// --- MissingNumberVisualizer Component (Template Applied) ---
const MissingNumberVisualizer = () => {
    // --- State Variables ---
    const [arrayInput, setArrayInput] = useState("3, 0, 1");
    const [elements, setElements] = useState([]); // Input array visualization
    const [message, setMessage] = useState("");
    const [errorMessage, setErrorMessage] = useState("");
    const [isRunning, setIsRunning] = useState(false);
    const [xorResult, setXorResult] = useState(null); // Stores the running XOR value
    const [currentIndex, setCurrentIndex] = useState(null); // Index 'i' being processed
    const [finalResult, setFinalResult] = useState(null); // Stores the final missing number
    const stopRef = React.useRef(false);
    // Audio/Speech State
    const [isAudioEnabled, setIsAudioEnabled] = useState(true);
    const [isSpeechEnabled, setIsSpeechEnabled] = useState(true);

    // --- Web Audio API Setup ---
    const audioContextRef = useRef(null);
    const initAudioContext = useCallback(() => { /* ... (Template standard) ... */ if (!isAudioEnabled) return; if (audioContextRef.current === null && typeof window !== 'undefined' && (window.AudioContext || window.webkitAudioContext)) { try { audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { console.error("Web Audio API not supported.", e); setIsAudioEnabled(false); setMessage("Audio tones disabled: Not supported."); } } if (audioContextRef.current && audioContextRef.current.state === 'suspended') { audioContextRef.current.resume().catch(e => console.error("Audio resume failed", e)); } }, [isAudioEnabled]);
    const playTone = useCallback((frequency = 440, duration = 0.1, type = 'sine', volume = 0.3) => { /* ... (Template standard) ... */ if (!isAudioEnabled || !audioContextRef.current || audioContextRef.current.state !== 'running') return; try { const oscillator = audioContextRef.current.createOscillator(); const gainNode = audioContextRef.current.createGain(); oscillator.type = type; oscillator.frequency.setValueAtTime(frequency, audioContextRef.current.currentTime); gainNode.gain.setValueAtTime(volume, audioContextRef.current.currentTime); gainNode.gain.exponentialRampToValueAtTime(0.0001, audioContextRef.current.currentTime + duration); oscillator.connect(gainNode); gainNode.connect(audioContextRef.current.destination); oscillator.start(audioContextRef.current.currentTime); oscillator.stop(audioContextRef.current.currentTime + duration); } catch (e) { console.error("Error playing tone:", e); } }, [isAudioEnabled]);
    // Specific sounds
    const playXorSound = useCallback(() => playTone(700, 0.08, 'square', 0.2), [playTone]);
    const playIterateSound = useCallback(() => playTone(450, 0.05, 'triangle', 0.15), [playTone]);
    const playStartSound = useCallback(() => playTone(440, 0.1, 'sine', 0.3), [playTone]);
    const playEndSound = useCallback(() => playTone(950, 0.25, 'sine', 0.3), [playTone]);
    const playStopSound = useCallback(() => playTone(220, 0.15, 'square', 0.3), [playTone]);
    const playErrorSound = useCallback(() => playTone(150, 0.3, 'sawtooth', 0.3), [playTone]);

    // --- Web Speech API Setup (Promise-based - FIXED ERROR HANDLING) ---
    const speak = useCallback((text) => {
        return new Promise((resolve) => { // Always resolve
            if (!isSpeechEnabled || typeof window === 'undefined' || !window.speechSynthesis) {
                resolve(); // Resolve immediately if disabled or not supported
                return;
            }
            try {
                window.speechSynthesis.cancel(); // Cancel previous speech
                const utterance = new SpeechSynthesisUtterance(text);
                utterance.lang = 'en-US';
                utterance.rate = 1.0;
                utterance.pitch = 1.0;
                utterance.volume = 0.8;

                // Resolve the promise when speech ends
                utterance.onend = () => {
                    resolve();
                };

                // ALSO resolve the promise on error to prevent unhandled rejections
                utterance.onerror = (event) => {
                    console.error("Speech synthesis error:", event.error);
                    resolve(); // CHANGE: Resolve instead of reject
                };

                window.speechSynthesis.speak(utterance);

            } catch (e) {
                console.error("Error initiating speech synthesis:", e);
                resolve(); // Resolve if initiation fails
            }
        });
    }, [isSpeechEnabled]); // Dependency on isSpeechEnabled

    const cancelSpeech = useCallback(() => { if (typeof window !== 'undefined' && window.speechSynthesis) { window.speechSynthesis.cancel(); } }, []);

    // --- Reset Function ---
    const reset = useCallback((initial = false) => {
        stopRef.current = true; cancelSpeech(); setIsRunning(false);
        setXorResult(null); setCurrentIndex(null); setFinalResult(null);
        setErrorMessage("");
        try {
            const nums = parseArrayInput(arrayInput, true);
            // Basic validation could be added here (e.g., check range, distinctness)
            setElements(nums.map((val, i) => ({ id: i, value: val, state: 'default', index: i, pointers: [] })));
            setMessage(initial ? "" : "Enter array containing n distinct numbers from [0, n].");
        } catch (e) {
            setElements([]); setErrorMessage(`Input Error: ${e.message}`); setMessage("");
            if (!initial) playErrorSound();
        }
    }, [arrayInput, cancelSpeech, parseArrayInput, playErrorSound]);

    // --- Effects ---
    useEffect(() => { reset(true); return () => { stopRef.current = true; cancelSpeech(); if (audioContextRef.current) { audioContextRef.current.close().catch(e => console.error("Error closing AudioContext:", e)); audioContextRef.current = null; } }; }, [reset, cancelSpeech]);
    useEffect(() => { const handler = setTimeout(() => { reset(true); }, 500); return () => clearTimeout(handler); }, [arrayInput, reset]);

    // --- Visualization Logic (XOR Method - Using Promise Speak) ---
    const runVisualization = async () => {
        initAudioContext(); cancelSpeech(); reset(false); await sleep(50);

        let nums;
        try {
            if (errorMessage) { setIsRunning(false); return; }
            nums = elements.map(el => el.value);
            // Add validation for distinct nums in range [0, n] if desired
            if (nums.length === 0 ) { throw new Error("Array cannot be empty."); }
        } catch (e) { setErrorMessage(`Input Error: ${e.message}`); setIsRunning(false); playErrorSound(); return; }

        stopRef.current = false; setIsRunning(true);
        setMessage("Starting Missing Number search (XOR Method)..."); playStartSound();
        await speak("Starting search using XOR.");
        if (stopRef.current) { setIsRunning(false); return; }

        const n = nums.length;
        let missing = n; // Initialize with n
        setXorResult(missing);
        setMessage(`Initialize missing = n = ${n}.`);
        await speak(`Initialize missing result to ${n}.`);
        if (stopRef.current) { setIsRunning(false); return; }
        await sleep(1200); // Pause after init speak

        for (let i = 0; i < n; i++) {
            if (stopRef.current) break;
            setCurrentIndex(i); playIterateSound();

            // Highlight current index and element
            setElements(prev => prev.map((el, idx) => ({
                ...el,
                state: idx === i ? 'highlight-checking' : 'default',
                pointers: idx === i ? ['i'] : []
            })));
            setMessage(`Processing index i = ${i} and nums[${i}] = ${nums[i]}. Current missing = ${missing}.`);
            await speak(`Processing index ${i}, value ${nums[i]}. Current missing value is ${missing}.`);
            if (stopRef.current) break;
            await sleep(1000); // Pause after speak

            // Perform XOR with index
            let oldMissing = missing;
            missing ^= i;
            setXorResult(missing);
            setMessage(`XOR with index: ${oldMissing} ^ ${i} = ${missing}.`);
            playXorSound();
            await speak(`XOR missing with index ${i}. Result is ${missing}.`);
            if (stopRef.current) break;
            await sleep(1200); // Pause after speak

            // Perform XOR with value
            oldMissing = missing;
            missing ^= nums[i];
            setXorResult(missing);
            setMessage(`XOR with value: ${oldMissing} ^ ${nums[i]} = ${missing}.`);
            playXorSound();
            await speak(`XOR result with value ${nums[i]}. Result is ${missing}.`);
            if (stopRef.current) break;
            await sleep(1200); // Pause after speak

            // Reset highlight
            setElements(prev => prev.map((el, idx) => ({ ...el, state: 'default', pointers: [] })));
            await sleep(400); // Shorter pause before next iteration
        }

        // Final State
        if (stopRef.current) {
            setMessage("Visualization stopped by user."); speak("Visualization stopped."); playStopSound();
        } else {
            setFinalResult(missing);
            setMessage(`Finished XOR loop. The missing number is ${missing}.`);
            playEndSound();
            await speak(`Finished loop. The missing number is ${missing}.`);
        }
        setIsRunning(false); setCurrentIndex(null); stopRef.current = false;
    };

    const stopVisualization = () => {
        stopRef.current = true; cancelSpeech(); setMessage("Stopping visualization...");
    };

    const toggleAudio = () => { /* ... (Template standard) ... */ const newState = !isAudioEnabled; setIsAudioEnabled(newState); if (newState) { initAudioContext(); playTone(500, 0.05, 'sine', 0.2); } else { playTone(300, 0.05, 'square', 0.2); if (audioContextRef.current && audioContextRef.current.state === 'running') { audioContextRef.current.suspend().catch(e => console.error("Audio suspend failed", e)); } } };
    const toggleSpeech = () => { /* ... (Template standard) ... */ const newState = !isSpeechEnabled; if (newState && (typeof window === 'undefined' || !window.speechSynthesis)) { setMessage("Speech synthesis not supported."); return; } setIsSpeechEnabled(newState); if (!newState) { cancelSpeech(); } else { speak("Speech enabled."); } };

    // --- Render ---
    return (
        <>
            <BaseVisualizer
                problemSummary={
                    <>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                            <Typography variant="h4" component="h1">Missing Number</Typography>
                            <Chip label="Easy" color="success" size="small" variant="filled" />
                        </Box>
                        <Typography variant="body1" component="div" sx={{ mb: 2 }}>
                            Given an array <code>nums</code> containing <code>n</code> distinct numbers in the range <code>[0, n]</code>, return <em>the only number in the range that is missing from the array</em>.
                        </Typography>
                        <Typography variant="h6" component="h3" sx={{ mt: 2, mb: 1 }}>Examples:</Typography>
                        <Box sx={{ bgcolor: 'action.hover', p: 1.5, borderRadius: 1, fontFamily: 'monospace', mb: 2, fontSize: '0.875rem' }}>
                            <strong>Input:</strong> nums = [3,0,1]<br/><strong>Output:</strong> 2<br/><strong>Explanation:</strong> n = 3 since there are 3 numbers, so the range is [0,3]. 2 is the missing number.<br/><br/>
                            <strong>Input:</strong> nums = [0,1]<br/><strong>Output:</strong> 2<br/><strong>Explanation:</strong> n = 2 since there are 2 numbers, so the range is [0,2]. 2 is the missing number.<br/><br/>
                            <strong>Input:</strong> nums = [9,6,4,2,3,5,7,0,1]<br/><strong>Output:</strong> 8<br/><strong>Explanation:</strong> n = 9 since there are 9 numbers, so the range is [0,9]. 8 is the missing number.
                        </Box>
                        <Typography variant="h6" component="h3" sx={{ mt: 2, mb: 1 }}>Constraints:</Typography>
                        <Box component="ul" sx={{ pl: 2, mb: 2 }}>
                            <li><code>n == nums.length</code></li>
                            <li><code>1 &lt;= n &lt;= 10<sup>4</sup></code></li>
                            <li><code>0 &lt;= nums[i] &lt;= n</code></li>
                            <li>All the numbers of <code>nums</code> are <strong>unique</strong>.</li>
                        </Box>
                        <Divider sx={{ my: 3 }} />
                        <Typography variant="h6" sx={{ mt: 3, mb: 1 }}>Runnable Solution Code Examples (XOR Method)</Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>Copy/paste these into the compiler below.</Typography>
                        <Typography variant="subtitle2" sx={{ mb: 0.5 }}>JavaScript:</Typography><SolutionCodeDisplay codeString={missingNumberSolutionCodeJS} />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>Python:</Typography><SolutionCodeDisplay codeString={missingNumberSolutionCodePython} />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>Java:</Typography><SolutionCodeDisplay codeString={missingNumberSolutionCodeJava} />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>C++:</Typography><SolutionCodeDisplay codeString={missingNumberSolutionCodeCPP} />
                        <Divider sx={{ my: 3 }} />
                        <Typography variant="subtitle1" gutterBottom>Algorithm Analysis (XOR Method)</Typography>
                        <Typography variant="body2" color="text.secondary"><strong>Time Complexity:</strong> <code>O(N)</code>. We iterate through the array once.</Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}><strong>Space Complexity:</strong> <code>O(1)</code>. Constant extra space is used for the 'missing' variable.</Typography>
                    </>
                }
                controls={
                    <>
                        <Typography variant="subtitle1" sx={{ textAlign: 'center', fontWeight: 'bold', p: 0.75, mb: 2.5, borderRadius: '4px', color: 'common.white', background: 'linear-gradient(45deg, #00ACC1 30%, #4DD0E1 90%)', boxShadow: 1 }}>Algorithm Visualizer</Typography>
                        <Grid container spacing={1.5} alignItems="center" mb={2}>
                            <Grid item xs={12} sm={8} md={7}><TextField fullWidth id="mn-array-input" label="Input Array (comma-separated, distinct [0,n])" variant="outlined" size="small" value={arrayInput} onChange={(e) => setArrayInput(e.target.value)} placeholder="e.g., 3, 0, 1" disabled={isRunning} /></Grid>
                            <Grid item xs={4} sm={2} md={1.5}><Tooltip title={isRunning ? "Stop Visualization" : "Run Visualization"}><span><Button fullWidth variant="contained" sx={{ height: '40px' }} startIcon={isRunning ? <CircularProgress size={20} color="inherit" /> : <HelpOutlineIcon />} onClick={isRunning ? stopVisualization : runVisualization} color={isRunning ? "warning" : "primary"} disabled={isRunning && stopRef.current}>{isRunning ? 'Stop' : 'Run'}</Button></span></Tooltip></Grid>
                            <Grid item xs={4} sm={2} md={1.5}><Tooltip title={isAudioEnabled ? "Mute Tones" : "Unmute Tones"}><Button fullWidth variant="outlined" onClick={toggleAudio} sx={{ height: '40px', minWidth: 'auto', p: 1 }}>{isAudioEnabled ? <VolumeUpIcon /> : <VolumeOffIcon />}</Button></Tooltip></Grid>
                            <Grid item xs={4} sm={2} md={1.5}><Tooltip title={isSpeechEnabled ? "Disable Speech" : "Enable Speech"}><Button fullWidth variant="outlined" onClick={toggleSpeech} sx={{ height: '40px', minWidth: 'auto', p: 1 }}>{isSpeechEnabled ? <RecordVoiceOverIcon /> : <VoiceOverOffIcon />}</Button></Tooltip></Grid>
                            <Grid item xs={12} sm={12} md={1.5} sx={{ display: 'flex', justifyContent: { xs: 'center', md: 'flex-start' } }}><Button variant="outlined" startIcon={<ReplayIcon />} onClick={() => reset(false)} disabled={isRunning} sx={{ height: '40px' }}>Reset</Button></Grid>
                        </Grid>
                        {errorMessage && <Alert severity="error" sx={{ mt: 2 }}>{errorMessage}</Alert>}
                    </>
                }
                displayArea={
                    <>
                        {/* Input Array */}
                        <Box sx={{ width: '100%', mb: 3 }}>
                            <Typography variant="h6" gutterBottom align="center">Input Array (nums)</Typography>
                            <Box sx={{ display: 'flex', justifyContent: 'center', flexWrap: 'wrap', gap: 1, alignItems: 'flex-end', minHeight: '80px', position: 'relative', pt: 4, pb: 1, borderBottom: '1px dashed', borderColor: 'divider' }}>
                                {/* ASSUMPTION: ArrayElement handles 'highlight-checking' state */}
                                {elements.map(el => (<ArrayElement key={el.id} value={el.value} index={el.index} state={el.state} pointers={el.pointers} type="box" />))}
                                {elements.length === 0 && !errorMessage && <Typography variant="caption" color="text.secondary">Enter input array</Typography>}
                                {errorMessage && elements.length === 0 && <Typography variant="caption" color="error">Input Error</Typography>}
                            </Box>
                        </Box>

                        {/* XOR Result Display */}
                        <Box sx={{ width: '100%', mt: 2, textAlign: 'center' }}>
                            <Typography variant="overline" display="block" color="text.secondary">Running XOR Result ('missing')</Typography>
                            <Chip label={xorResult ?? '-'} color="secondary" variant="filled" size="medium" sx={{ fontFamily: 'monospace', px: 2 }}/>
                        </Box>

                        {/* Final Result Display */}
                        {finalResult !== null && !isRunning && (
                            <Alert icon={<CheckCircleOutlineIcon fontSize="inherit" />} severity="success" sx={{ mt: 3, justifyContent: 'center', textAlign: 'center' }}>
                                <Typography variant="h6">Missing Number Found: {finalResult}</Typography>
                            </Alert>
                        )}
                    </>
                }
                message={message}
            />
            {/* Render Imported Online Compiler */}
            <Container maxWidth="xl" sx={{ mt: 4, mb: 4 }}>
                <OnlineCompiler />
            </Container>
        </>
    );
};

export default MissingNumberVisualizer;


