// --- Trie Node Class (Helper - Reuse from TrieVisualizer) ---
class TrieNode {
    constructor(char = null) {
        this.char = char;
        this.children = {};
        this.isEndOfWord = false;
        this.id = Math.random().toString(36).substring(2, 15);
        this.x = 0; this.y = 0; this.parentId = null;
    }
}

// --- Calculate Trie Positions (Reuse - From TrieVisualizer) ---
const calculateTriePositions = (root) => {
    if (!root) return { nodes: [], nodeMap: {}, height: 0 }; const nodes = []; const nodeMap = {}; let maxLevel = 0; const baseHorizontalSpacing = 80;
    const traverse = (node, level, x, parentId) => { if (!node) return; maxLevel = Math.max(maxLevel, level); node.y = level * LEVEL_SPACING; node.x = x; node.parentId = parentId; nodes.push(node); nodeMap[node.id] = node; const children = Object.values(node.children); const numChildren = children.length; if (numChildren === 0) return; const childrenTotalWidth = (numChildren - 1) * (baseHorizontalSpacing / Math.pow(1.5, level + 1)); let startX = x - childrenTotalWidth / 2; const childSpacing = baseHorizontalSpacing / Math.pow(1.5, level + 1); children.sort((a, b) => (a.char || '').localeCompare(b.char || '')); children.forEach((child, index) => { const childX = startX + index * childSpacing; traverse(child, level + 1, childX, node.id); }); };
    traverse(root, 0, 0, null);
    if (nodes.length > 0) { let minX = Infinity, maxX = -Infinity; nodes.forEach(n => { minX = Math.min(minX, n.x); maxX = Math.max(maxX, n.x); }); const treeWidth = maxX - minX; const centeringOffset = -minX - (treeWidth / 2); nodes.forEach(n => { n.x += centeringOffset; }); }
    const topPadding = NODE_RADIUS + 10; nodes.forEach(n => { n.y += topPadding; });
    return { nodes, nodeMap, height: (maxLevel * LEVEL_SPACING) + topPadding };
};


