const DecodeWaysVisualizer = () => {
    // --- State Variables ---
    const [sInput, setSInput] = useState("226"); // Input string of digits
    const [stringChars, setStringChars] = useState([]); // Input string visualization { id, value, state, index }
    const [dpElements, setDpElements] = useState([]); // DP array visualization { id, value, state, index }
    const [message, setMessage] = useState(""); // Status message for BaseVisualizer
    const [errorMessage, setErrorMessage] = useState(""); // Internal error state, used for logic checks
    const [isRunning, setIsRunning] = useState(false); // Visualization running flag
    const [finalResult, setFinalResult] = useState(null); // Stores the final count for BaseVisualizer result prop
    const [currentIndexI, setCurrentIndexI] = useState(null); // Current index 'i' being processed in DP array
    const [oneDigitHighlight, setOneDigitHighlight] = useState(null); // Index of single digit being checked in input string
    const [twoDigitsHighlight, setTwoDigitsHighlight] = useState([]); // Indices [i-2, i-1] of two digits being checked in input string
    const stopRef = useRef(false); // Ref to signal stopping the visualization

    // --- Audio/Speech State ---
    const [isAudioEnabled, setIsAudioEnabled] = useState(true);
    const [isSpeechEnabled, setIsSpeechEnabled] = useState(true);

    // --- Web Audio/Speech API Setup (Standard Boilerplate) ---
    const audioContextRef = useRef(null);
    // Initializes or resumes the Audio Context
    const initAudioContext = useCallback(() => {
        if (!isAudioEnabled) return;
        if (audioContextRef.current === null && typeof window !== 'undefined' && (window.AudioContext || window.webkitAudioContext)) {
            try {
                audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)();
            } catch (e) {
                console.error("Web Audio API not supported.", e);
                setIsAudioEnabled(false);
                setMessage("Audio tones disabled: Not supported.");
            }
        }
        if (audioContextRef.current && audioContextRef.current.state === 'suspended') {
            audioContextRef.current.resume().catch(e => console.error("Audio resume failed", e));
        }
    }, [isAudioEnabled]);
    // Plays a tone with specified parameters
    const playTone = useCallback((frequency = 440, duration = 0.1, type = 'sine', volume = 0.3) => {
        if (!isAudioEnabled || !audioContextRef.current || audioContextRef.current.state !== 'running') return;
        try {
            const oscillator = audioContextRef.current.createOscillator();
            const gainNode = audioContextRef.current.createGain();
            oscillator.type = type;
            oscillator.frequency.setValueAtTime(frequency, audioContextRef.current.currentTime);
            gainNode.gain.setValueAtTime(volume, audioContextRef.current.currentTime);
            gainNode.gain.exponentialRampToValueAtTime(0.0001, audioContextRef.current.currentTime + duration);
            oscillator.connect(gainNode);
            gainNode.connect(audioContextRef.current.destination);
            oscillator.start(audioContextRef.current.currentTime);
            oscillator.stop(audioContextRef.current.currentTime + duration);
        } catch (e) {
            console.error("Error playing tone:", e);
        }
    }, [isAudioEnabled]);
    // Specific sounds for different actions
    const playLoopSound = useCallback(() => playTone(350, 0.05, 'triangle', 0.15), [playTone]);
    const playCheckSound = useCallback(() => playTone(500, 0.07, 'sine', 0.18), [playTone]);
    const playReadDpSound = useCallback(() => playTone(600, 0.07, 'square', 0.2), [playTone]);
    const playValidSound = useCallback(() => playTone(800, 0.08, 'sine', 0.2), [playTone]);
    const playInvalidSound = useCallback(() => playTone(250, 0.1, 'sawtooth', 0.2), [playTone]);
    const playWriteDpSound = useCallback(() => playTone(900, 0.1, 'sine', 0.25), [playTone]);
    const playStartSound = useCallback(() => playTone(440, 0.1, 'sine', 0.3), [playTone]);
    const playEndSound = useCallback(() => playTone(1100, 0.2, 'sine', 0.3), [playTone]);
    const playStopSound = useCallback(() => playTone(220, 0.15, 'square', 0.3), [playTone]);
    const playErrorSound = useCallback(() => playTone(150, 0.3, 'sawtooth', 0.3), [playTone]);
    // Speaks text using browser's speech synthesis
    const speak = useCallback((text) => {
        return new Promise((resolve) => {
            if (!isSpeechEnabled || typeof window === 'undefined' || !window.speechSynthesis) {
                resolve(); return;
            }
            try {
                window.speechSynthesis.cancel();
                const utterance = new SpeechSynthesisUtterance(text);
                utterance.lang = 'en-US';
                utterance.rate = 1.0;
                utterance.pitch = 1.0;
                utterance.volume = 0.8;
                utterance.onend = () => resolve();
                utterance.onerror = (event) => { console.error("Speech synthesis error:", event.error); resolve(); };
                window.speechSynthesis.speak(utterance);
            } catch (e) {
                console.error("Error initiating speech synthesis:", e); resolve();
            }
        });
    }, [isSpeechEnabled]);
    // Cancels ongoing speech
    const cancelSpeech = useCallback(() => {
        if (typeof window !== 'undefined' && window.speechSynthesis) {
            window.speechSynthesis.cancel();
        }
    }, []);

    // --- Input Parsing and Validation ---
    // Parses the input string, ensuring it contains only digits.
    const parseAndValidateInput = (s) => {
        if (!s || s.length === 0) {
            throw new Error("Input string cannot be empty.");
        }
        if (!/^\d+$/.test(s)) { // Regular expression to check for digits only
            throw new Error("Input string must contain only digits ('0'-'9').");
        }
        // Note: Leading zeros are allowed by constraints, the algorithm handles their validity.
        return s;
    };

    // --- Reset Function ---
    // Resets the visualization state, parses input, and prepares for a new run.
    const reset = useCallback((initial = false) => {
        stopRef.current = true; // Signal any ongoing visualization to stop
        cancelSpeech(); // Stop any speech
        setIsRunning(false); // Set running state to false
        setStringChars([]); // Clear input string display
        setDpElements([]); // Clear DP array display
        setFinalResult(null); // Clear final result
        setErrorMessage(""); // Clear internal error state
        setMessage(""); // Clear main message state for BaseVisualizer
        setCurrentIndexI(null); // Clear current index indicator
        setOneDigitHighlight(null); // Clear digit highlights
        setTwoDigitsHighlight([]);

        try {
            const s = parseAndValidateInput(sInput); // Validate and parse input
            const n = s.length;

            // Initialize the display for the input string 's'
            setStringChars(s.split('').map((char, i) => ({
                id: `s-${i}`, value: char, state: 'default', index: i
            })));

            // Initialize the DP array and its visualization (size n+1)
            const initialDp = new Array(n + 1).fill(0);
            initialDp[0] = 1; // Base case: 1 way to decode an empty string

            // Calculate dp[1] based on the first character s[0]
            if (n >= 1 && s[0] !== '0') {
                 initialDp[1] = 1; // If s[0] is 1-9, there's 1 way
            } // If s[0] is '0' or n=0, dp[1] remains 0

            // Set the state for the DP array display
            setDpElements(initialDp.map((val, i) => ({
                id: `dp-${i}`,
                value: val, // Initial value (0, 1, or 0)
                // Mark base cases as 'final' visually
                state: (i === 0 || (i === 1 && initialDp[1] === 1)) ? 'highlight-final' : 'default',
                index: i // Index corresponds to prefix length
            })));

            setMessage(initial ? "Enter a string of digits." : "Ready. Click Run.");

        } catch (e) {
            // Handle errors during input parsing
            setStringChars([]);
            setDpElements([]);
            setErrorMessage(e.message); // Set internal error state
            setMessage(`Input Error: ${e.message}`); // Set main message for display in BaseVisualizer
            if (!initial) playErrorSound(); // Play error sound if not the initial load
        }
    }, [sInput, cancelSpeech, playErrorSound]); // Dependencies for useCallback

    // --- Effects ---
    // Effect for initial setup on mount and cleanup on unmount
    useEffect(() => {
        reset(true); // Perform initial reset
        return () => { // Cleanup function
            stopRef.current = true;
            cancelSpeech();
            if (audioContextRef.current) {
                audioContextRef.current.close().catch(e => console.error("Error closing AudioContext:", e));
                audioContextRef.current = null;
            }
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []); // Empty array ensures this runs only once

    // Effect to automatically reset (debounced) when input changes
    useEffect(() => {
        const handler = setTimeout(() => {
            reset(true); // Use reset(true) to avoid showing errors while typing
        }, 500); // 500ms delay
        return () => clearTimeout(handler); // Clear timeout if input changes again
    }, [sInput, reset]); // Rerun if sInput or reset function changes


    // --- Visualization Logic ---
    // Main async function to run the step-by-step visualization
    const runVisualization = async () => {
        initAudioContext(); // Ensure audio context is ready
        cancelSpeech(); // Stop previous speech
        reset(false); // Reset state and validate input
        await sleep(50); // Allow UI to update

        // Check internal error state set by reset
        if (errorMessage) {
            setIsRunning(false);
            return;
        }

        let s; // Parsed input string
        try {
             s = parseAndValidateInput(sInput); // Parse again for safety
        } catch (e) {
             // Should be caught by reset, but handle defensively
             setErrorMessage(`Input Error: ${e.message}`);
             setMessage(`Input Error: ${e.message}`); // Update message for BaseVisualizer
             setIsRunning(false);
             playErrorSound();
             return;
        }

        // Handle edge case: starts with '0' explicitly (although algorithm handles it)
        if (s[0] === '0') {
             setMessage("Cannot decode: String starts with '0'. Result is 0.");
             await speak("String starts with 0. Result is 0.");
             setFinalResult(0);
             // Highlight dp[n] as fail state
             setDpElements(prev => prev.map((el, idx) => ({
                 ...el,
                 state: idx === s.length ? 'highlight-final-result-fail' : el.state
             })));
             setIsRunning(false);
             playEndSound(); // Play end sound
             return;
        }

        stopRef.current = false; // Reset stop flag
        setIsRunning(true); // Set running state
        setMessage("Starting Decode Ways calculation...");
        playStartSound();
        await speak(`Calculating ways to decode string ${s}.`);
        if (stopRef.current) { setIsRunning(false); return; } // Check stop flag after async

        const n = s.length;
        let currentStringChars = stringChars.map(el => ({...el})); // Get current state
        // Get DP array state after reset (includes base cases dp[0], dp[1])
        let currentDpElements = dpElements.map(el => ({...el}));
        let dp = currentDpElements.map(el => el.value); // Algorithm's internal DP array

        // --- Visualize Base Cases ---
        setMessage("Base case: dp[0] = 1 (for empty string).");
        await speak("Base case: dp of 0 is 1.");
        await sleep(1000);
        if (stopRef.current) { setIsRunning(false); return; }
        if (n >= 1) {
            // Visualize dp[1] which was calculated in reset
            setMessage(`Base case: dp[1] = ${dp[1]} (for decoding '${s[0]}').`);
            await speak(`Base case: dp of 1 is ${dp[1]}.`);
            // Ensure dp[1] is marked final visually
            currentDpElements[1].state = 'highlight-final';
            setDpElements([...currentDpElements]);
            await sleep(1000);
            if (stopRef.current) { setIsRunning(false); return; }
        }


        // --- DP Calculation Loop ---
        // Start from i = 2, as dp[0] and dp[1] are base cases
        for (let i = 2; i <= n; i++) {
            if (stopRef.current) break; // Check stop flag
            setCurrentIndexI(i); // Set current DP index for UI
            playLoopSound();
            setMessage(`Calculating ways for prefix ending at index i=${i}. Target: dp[${i}].`);
            await speak(`Calculating for index ${i}. Target dp of ${i}.`);

            // Highlight target dp[i] in the DP array display
            currentDpElements = currentDpElements.map((el, idx) => ({
                ...el,
                state: idx === i ? 'highlight-current-dp' // Highlight target cell
                       : (idx < i) ? 'highlight-final' // Mark previously computed as final
                       : 'default'
            }));
            setDpElements([...currentDpElements]);
            await sleep(800);
            if (stopRef.current) break;

            let waysFromOneDigit = 0; // Ways added from single-digit decoding
            let waysFromTwoDigits = 0; // Ways added from two-digit decoding
            dp[i] = 0; // Initialize dp[i] for this iteration

            // --- Check 1: Single Digit Decoding (s[i-1]) ---
            const oneDigitChar = s[i - 1];
            const oneDigitVal = parseInt(oneDigitChar);
            setOneDigitHighlight(i - 1); // Highlight the single digit in the input string display
            setMessage(`Checking 1-digit decode: s[${i-1}] = '${oneDigitChar}'.`);
            await speak(`Checking single digit ${oneDigitChar}.`);

            // Highlight the corresponding digit and the DP dependency (dp[i-1])
            currentStringChars = currentStringChars.map((el, idx) => ({...el, state: idx === i - 1 ? 'highlight-substring' : 'default'}));
            currentDpElements = currentDpElements.map((el, idx) => ({
                ...el,
                state: idx === i ? 'highlight-current-dp' // Keep target highlighted
                       : idx === i - 1 ? 'highlight-dp-dependency' // Highlight dp[i-1]
                       : (idx < i - 1) ? 'highlight-final' // Keep previous final states
                       : 'default'
            }));
            setStringChars([...currentStringChars]);
            setDpElements([...currentDpElements]);
            playCheckSound();
            await sleep(1200);
            if (stopRef.current) break;

            // Check if the single digit is valid (1-9)
            if (oneDigitVal >= 1 && oneDigitVal <= 9) {
                waysFromOneDigit = dp[i - 1]; // Get ways from the previous DP state
                dp[i] += waysFromOneDigit; // Add these ways to dp[i]
                setMessage(`Valid 1-digit ('${oneDigitChar}'). Add ways from dp[${i-1}] = ${waysFromOneDigit}. Current dp[${i}] = ${dp[i]}.`);
                await speak(`Digit ${oneDigitChar} is valid. Add ${waysFromOneDigit} ways from dp of ${i-1}. Current dp of ${i} is ${dp[i]}.`);
                playValidSound();
                playReadDpSound();
                // Update UI temporarily to show the addition result
                currentDpElements[i] = {...currentDpElements[i], value: dp[i], state: 'highlight-update'};
                setDpElements([...currentDpElements]);
                await sleep(1500);
            } else {
                // Digit is '0', invalid single-digit decoding
                setMessage(`Invalid 1-digit decode ('${oneDigitChar}' is '0'). No ways added from dp[${i-1}].`);
                await speak(`Digit ${oneDigitChar} is invalid.`);
                playInvalidSound();
                await sleep(1200);
            }
            if (stopRef.current) break;
            setOneDigitHighlight(null); // Clear single digit highlight in string


            // --- Check 2: Two Digit Decoding (s[i-2]s[i-1]) ---
            const twoDigitChars = s.substring(i - 2, i);
            const twoDigitVal = parseInt(twoDigitChars);
            setTwoDigitsHighlight([i - 2, i - 1]); // Highlight the two digits in the input string
            setMessage(`Checking 2-digit decode: s[${i-2}]s[${i-1}] = '${twoDigitChars}'.`);
            await speak(`Checking two digits ${twoDigitChars}.`);

            // Highlight the corresponding digits and the DP dependency (dp[i-2])
            currentStringChars = currentStringChars.map((el, idx) => ({...el, state: (idx === i - 1 || idx === i - 2) ? 'highlight-substring' : 'default'}));
            // Reset dp highlights except target, highlight dp[i-2]
            currentDpElements = currentDpElements.map((el, idx) => ({
                ...el,
                state: idx === i ? (el.state === 'highlight-update' ? 'highlight-update' : 'highlight-current-dp') // Keep target state
                       : idx === i - 2 ? 'highlight-dp-dependency' // Highlight dp[i-2]
                       : (idx < i) ? 'highlight-final' // Keep previous final states
                       : 'default'
            }));
            setStringChars([...currentStringChars]);
            setDpElements([...currentDpElements]);
            playCheckSound();
            await sleep(1200);
            if (stopRef.current) break;

            // Check if the two digits form a valid number (10-26)
            if (twoDigitVal >= 10 && twoDigitVal <= 26) {
                waysFromTwoDigits = dp[i - 2]; // Get ways from two steps back
                dp[i] += waysFromTwoDigits; // Add these ways to dp[i]
                setMessage(`Valid 2-digit ('${twoDigitChars}'=${twoDigitVal}). Add ways from dp[${i-2}] = ${waysFromTwoDigits}. Current dp[${i}] = ${dp[i]}.`);
                await speak(`Digits ${twoDigitChars} are valid. Add ${waysFromTwoDigits} ways from dp of ${i-2}. Current dp of ${i} is ${dp[i]}.`);
                playValidSound();
                playReadDpSound();
                // Update UI to show the result of the addition
                currentDpElements[i] = {...currentDpElements[i], value: dp[i], state: 'highlight-update'};
                setDpElements([...currentDpElements]);
                await sleep(1500);
            } else {
                // Two digits are not valid (e.g., '06', '27', '30')
                setMessage(`Invalid 2-digit decode ('${twoDigitChars}' is ${twoDigitVal}). No ways added from dp[${i-2}].`);
                await speak(`Digits ${twoDigitChars} are invalid.`);
                playInvalidSound();
                await sleep(1200);
            }
             if (stopRef.current) break;
             setTwoDigitsHighlight([]); // Clear two digit highlight in string


            // --- Finalize Update for dp[i] ---
            setMessage(`Final ways for dp[${i}] = ${dp[i]}.`);
            await speak(`Final ways for dp of ${i} is ${dp[i]}.`);
            playWriteDpSound();

            // Update UI state for dp[i] and mark as final for this step
            currentDpElements = currentDpElements.map((el, idx) => ({
                ...el,
                value: idx === i ? dp[i] : el.value, // Ensure final value is set
                state: idx <= i ? 'highlight-final' : 'default' // Mark up to index i as final
            }));
            setDpElements([...currentDpElements]);
            // Clear highlights before next iteration
            setStringChars(prev => prev.map(c => ({...c, state: 'default'})));
            setCurrentIndexI(null); // Clear current DP index indicator
            await sleep(800); // Pause before next iteration

        } // End DP loop

        // --- Final State ---
        if (stopRef.current) {
             // Handle stop condition
             setMessage("Visualization stopped by user.");
             speak("Visualization stopped.");
             playStopSound();
        } else {
            // Handle normal completion
            const finalAnswer = dp[n]; // Result is in the last DP cell
            setFinalResult(finalAnswer); // Set final result state for BaseVisualizer prop
            setMessage(`Finished calculation. Total ways to decode: ${finalAnswer}.`);
            playEndSound();
            await speak(`Finished. Total ways to decode is ${finalAnswer}.`);

            // Highlight the final result cell dp[n]
            setDpElements(prev => prev.map((el, idx) => ({
                ...el,
                state: idx === n ? 'highlight-final-result-success' : 'highlight-final'
            })));
            // Mark entire input string as processed/final
            setStringChars(prev => prev.map(c => ({...c, state: 'highlight-final'})));
        }

        // Reset running state and flags
        setIsRunning(false);
        stopRef.current = false;
        setCurrentIndexI(null);
        setOneDigitHighlight(null);
        setTwoDigitsHighlight([]);
    };

    // --- Control Functions ---
    // Stops the visualization loop
    const stopVisualization = () => {
        stopRef.current = true;
        cancelSpeech();
        setMessage("Stopping visualization...");
    };
    // Toggles audio effects
    const toggleAudio = () => {
        const newState = !isAudioEnabled;
        setIsAudioEnabled(newState);
        if (newState) {
            initAudioContext();
            setTimeout(() => playTone(500, 0.05, 'sine', 0.2), 50); // Play sound on unmute
        } else {
            playTone(300, 0.05, 'square', 0.2); // Play sound on mute
            if (audioContextRef.current && audioContextRef.current.state === 'running') {
                audioContextRef.current.suspend().catch(e => console.error("Audio context suspend failed", e));
            }
        }
    };
    // Toggles speech synthesis
    const toggleSpeech = () => {
        const newState = !isSpeechEnabled;
        if (newState && (typeof window === 'undefined' || !window.speechSynthesis)) {
            setErrorMessage("Speech synthesis not supported by your browser."); // Use internal state
            setMessage("Speech synthesis not supported by your browser."); // Set message for display
            setTimeout(() => { setErrorMessage(""); setMessage(""); }, 3000);
            return;
        }
        setIsSpeechEnabled(newState);
        if (!newState) {
            cancelSpeech();
        } else {
            speak("Speech enabled.");
        }
    };

    // --- Render ---
    // Format the final result string for the BaseVisualizer prop
    const formattedResult = finalResult !== null ? `Final Result: ${finalResult} Ways` : null;

    return (
        <>
            {/* Use BaseVisualizer with adapted props */}
            <BaseVisualizer
                // Content for the problem description area
                problemSummary={
                    <>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                            <Typography variant="h4" component="h1">Decode Ways</Typography>
                            <Chip label="Medium" color="warning" size="small" variant="filled" />
                        </Box>
                        <Typography variant="body1" component="div" sx={{ mb: 2 }}>
                        A message containing letters from A-Z can be encoded into numbers using the following mapping: 'A' -"1", 'B' - "2", ..., 'Z' -"26".
                            <br/>To <strong>decode</strong> an encoded message, all the digits must be grouped then mapped back into letters using the reverse mapping. There may be multiple ways. For example, "11106" can be mapped into:
                            <ul>
                                <li>"AAJF" with the grouping (1 1 10 6)</li>
                                <li>"KJF" with the grouping (11 10 6)</li>
                            </ul>
                            Note that the grouping (1 11 06) is invalid because "06" cannot be mapped into 'F' since "6" is different from "06".
                            <br/><br/>Given a string <code>s</code> containing only digits, return <em>the <strong>number</strong> of ways to decode it</em>.
                        </Typography>
                        <Typography variant="h6" component="h3" sx={{ mt: 2, mb: 1 }}>Examples:</Typography>
                        <Box sx={{ bgcolor: 'action.hover', p: 1.5, borderRadius: 1, fontFamily: 'monospace', mb: 2, fontSize: '0.875rem' }}>
                            <strong>Input:</strong> s = "12"<br/><strong>Output:</strong> 2<br/><strong>Explanation:</strong> "12" could be decoded as "AB" (1 2) or "L" (12).<br/><br/>
                            <strong>Input:</strong> s = "226"<br/><strong>Output:</strong> 3<br/><strong>Explanation:</strong> "226" could be decoded as "BBF" (2 2 6), "BZ" (2 26), or "VF" (22 6).<br/><br/>
                            <strong>Input:</strong> s = "06"<br/><strong>Output:</strong> 0<br/><strong>Explanation:</strong> "06" cannot be mapped to "F" because of the leading zero ("6" is different from "06").
                        </Box>
                        <Typography variant="h6" component="h3" sx={{ mt: 2, mb: 1 }}>Constraints:</Typography>
                        <Box component="ul" sx={{ pl: 2, mb: 2 }}>
                             <li><code>1 &lt;= s.length &lt;= 100</code></li>
                             <li><code>s</code> contains only digits and may contain leading zero(s).</li>
                        </Box>
                        <Divider sx={{ my: 3 }} />
                        <Typography variant="h6" sx={{ mt: 3, mb: 1 }}>Runnable Solution Code Examples (Dynamic Programming)</Typography>
                        {/* Code Displays */}
                        <Typography variant="subtitle2" sx={{ mb: 0.5 }}>JavaScript:</Typography><SolutionCodeDisplay codeString={decodeWaysSolutionCodeJS} language="javascript"/>
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>Python:</Typography><SolutionCodeDisplay codeString={decodeWaysSolutionCodePython} language="python" />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>Java:</Typography><SolutionCodeDisplay codeString={decodeWaysSolutionCodeJava} language="java"/>
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>C++:</Typography><SolutionCodeDisplay codeString={decodeWaysSolutionCodeCPP} language="cpp"/>
                        <Divider sx={{ my: 3 }} />
                        <Typography variant="subtitle1" gutterBottom>Algorithm Analysis (DP)</Typography>
                        <Typography variant="body2" color="text.secondary"><strong>Time Complexity:</strong> <code>O(N)</code> - We iterate through the string once.</Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}><strong>Space Complexity:</strong> <code>O(N)</code> - For the DP array. Can be optimized to O(1).</Typography>
                    </>
                }
                // Content for the controls area (input field, buttons)
                controls={
                     <>
                        <Typography variant="subtitle1" sx={{ textAlign: 'center', fontWeight: 'bold', p: 0.75, mb: 2.5, borderRadius: '4px', color: 'common.white', background: 'linear-gradient(45deg, #26A69A 30%, #4DB6AC 90%)', boxShadow: 1 }}>
                             Decode Ways Visualizer Controls
                        </Typography>
                        <Grid container spacing={1.5} alignItems="center" mb={2}>
                            {/* Input Field */}
                            <Grid item xs={12} sm={8} md={6}>
                                <TextField fullWidth id="dw-s-input" label="Encoded String s (digits only)" variant="outlined" size="small" value={sInput} onChange={(e) => setSInput(e.target.value)} placeholder="e.g., 123123" disabled={isRunning} />
                            </Grid>
                            {/* Control Buttons */}
                            <Grid item xs={4} sm={2} md={1.5} sx={{ display: 'flex' }}> <Tooltip title={isRunning ? "Stop Visualization" : "Run Visualization"}><span><Button fullWidth variant="contained" sx={{ height: '40px' }} startIcon={isRunning && !stopRef.current ? <CircularProgress size={20} color="inherit" /> : <PlayArrowIcon />} onClick={isRunning ? stopVisualization : runVisualization} color={isRunning ? "warning" : "primary"} disabled={isRunning && stopRef.current}>{isRunning && !stopRef.current ? 'Running' : (isRunning && stopRef.current ? 'Stopping' : 'Run')}</Button></span></Tooltip> </Grid>
                            <Grid item xs={4} sm={2} md={1.5} sx={{ display: 'flex' }}> <Tooltip title="Reset Visualization and Input"><span><Button fullWidth variant="outlined" startIcon={<ReplayIcon />} onClick={() => reset(false)} disabled={isRunning} sx={{ height: '40px' }}>Reset</Button></span></Tooltip> </Grid>
                            <Grid item xs={4} sm={2} md={1.5} sx={{ display: 'flex' }}> <Tooltip title={isAudioEnabled ? "Mute Tones" : "Unmute Tones"}><Button fullWidth variant="outlined" onClick={toggleAudio} sx={{ height: '40px', minWidth: 'auto', p: 1 }}>{isAudioEnabled ? <VolumeUpIcon /> : <VolumeOffIcon />}</Button></Tooltip> </Grid>
                            <Grid item xs={4} sm={2} md={1.5} sx={{ display: 'flex' }}> <Tooltip title={isSpeechEnabled ? "Disable Speech" : "Enable Speech"}><Button fullWidth variant="outlined" onClick={toggleSpeech} sx={{ height: '40px', minWidth: 'auto', p: 1 }}>{isSpeechEnabled ? <RecordVoiceOverIcon /> : <VoiceOverOffIcon />}</Button></Tooltip> </Grid>
                         </Grid>
                         {/* Error Alert removed from here - errors displayed via message prop in BaseVisualizer */}
                    </>
                }
                // Content for the main visualization display area
                displayArea={
                    <>
                         {/* Input String Display */}
                         <Box sx={{ mb: 3 }}>
                             <Typography variant="subtitle1" gutterBottom align="center">Input String (s)</Typography>
                             <Box sx={{ display: 'flex', justifyContent: 'center', flexWrap: 'wrap', gap: 0.5, alignItems: 'center', minHeight: '40px', p:1, border: '1px solid', borderColor: 'divider', borderRadius: 1 }}>
                                 {stringChars.length > 0 ? stringChars.map(char => (
                                     // Use Chip to display each digit
                                     <Chip
                                         key={char.id}
                                         label={char.value}
                                         size="small"
                                         sx={{
                                             minWidth: '20px',
                                             fontWeight: 'medium',
                                             fontFamily: 'monospace',
                                             // Dynamic styling based on current checks
                                             bgcolor: char.index === oneDigitHighlight || twoDigitsHighlight.includes(char.index) ? 'warning.light' : (char.state === 'highlight-final' ? 'grey.300' : 'background.paper'),
                                             border: char.index === oneDigitHighlight || twoDigitsHighlight.includes(char.index) ? 1.5 : 0,
                                             borderColor: 'warning.main',
                                             transition: 'background-color 0.3s ease, border 0.3s ease',
                                         }}
                                     />
                                 )) : ( !errorMessage && <Typography variant="caption" color="text.secondary">Enter input string above</Typography> )}
                             </Box>
                         </Box>

                         {/* DP Array Display */}
                         <Typography variant="subtitle1" gutterBottom align="center">DP Array (dp[i]: Ways to decode prefix s[0...i-1])</Typography>
                         <Box sx={{ display: 'flex', justifyContent: 'center', flexWrap: 'wrap', gap: 1, alignItems: 'flex-end', minHeight: '60px', position: 'relative', pt: 4, pb: 1, border: '1px dashed', borderColor: 'divider', borderRadius: 1 }}>
                              {dpElements.length > 0 ? dpElements.map(el => (
                                  // Use ArrayElement component for DP values
                                  <ArrayElement
                                      key={el.id}
                                      value={el.value} // Number of ways
                                      index={el.index} // Corresponds to prefix length i
                                      state={el.state} // Highlighting state: current, dependency, update, final, success/fail
                                      type="box"
                                      showValue={true}
                                      showIndex={true}
                                  />
                              )) : ( !errorMessage && <Typography variant="caption" color="text.secondary">Enter inputs and click Run</Typography> )}
                              {/* Show message if DP array is empty due to input error */}
                              {errorMessage && dpElements.length === 0 && <Typography variant="caption" color="error">Input Error</Typography>}
                         </Box>

                         {/* Current Index Indicator */}
                         <Box sx={{ mt: 2, textAlign: 'center', fontFamily: 'monospace', fontSize: '0.8rem', p:1, bgcolor:'action.hover', borderRadius: 1, minHeight: '40px' }}>
                             <Typography variant="overline" display="block" color="text.secondary">Current DP Index (i)</Typography>
                             <Chip label={currentIndexI ?? 'idle'} color={currentIndexI !== null ? "primary": "default"} size="small" variant={currentIndexI !== null ? "filled" : "outlined"}/>
                         </Box>

                        {/* Final Result Alert removed - handled by BaseVisualizer 'result' prop */}
                    </>
                }
                // Pass message and formatted result to BaseVisualizer
                message={message}
                result={formattedResult}
            />
            {/* Online Compiler Section */}
            <Container maxWidth="xl" sx={{ mt: 4, mb: 4 }}>
                 {/* <Typography variant="h5" component="h2" gutterBottom>Test with Online Compiler</Typography> */}
                 <OnlineCompiler />
            </Container>
        </>
    );
};

export default DecodeWaysVisualizer;
