    const [errorMessage, setErrorMessage] = useState(""); // Keep for internal logic
    const [isRunning, setIsRunning] = useState(false);
    const [finalResult, setFinalResult] = useState(null); // Indicate completion
    const [currentCell, setCurrentCell] = useState(null); // {row, col} being visited
    const [direction, setDirection] = useState(0); // 0: R, 1: D, 2: L, 3: U
    const stopRef = useRef(false);
    // Audio/Speech State
    const [isAudioEnabled, setIsAudioEnabled] = useState(true);
    const [isSpeechEnabled, setIsSpeechEnabled] = useState(true);

    // --- Web Audio/Speech API Setup (Standard Boilerplate) ---
    const audioContextRef = useRef(null);
    const initAudioContext = useCallback(() => { /* ... (standard) ... */ if (!isAudioEnabled) return; if (audioContextRef.current === null && typeof window !== 'undefined' && (window.AudioContext || window.webkitAudioContext)) { try { audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { console.error("Web Audio API not supported.", e); setIsAudioEnabled(false); setMessage("Audio tones disabled: Not supported."); } } if (audioContextRef.current && audioContextRef.current.state === 'suspended') { audioContextRef.current.resume().catch(e => console.error("Audio resume failed", e)); } }, [isAudioEnabled]);
    const playTone = useCallback((frequency = 440, duration = 0.1, type = 'sine', volume = 0.3) => { /* ... (standard) ... */ if (!isAudioEnabled || !audioContextRef.current || audioContextRef.current.state !== 'running') return; try { const oscillator = audioContextRef.current.createOscillator(); const gainNode = audioContextRef.current.createGain(); oscillator.type = type; oscillator.frequency.setValueAtTime(frequency, audioContextRef.current.currentTime); gainNode.gain.setValueAtTime(volume, audioContextRef.current.currentTime); gainNode.gain.exponentialRampToValueAtTime(0.0001, audioContextRef.current.currentTime + duration); oscillator.connect(gainNode); gainNode.connect(audioContextRef.current.destination); oscillator.start(audioContextRef.current.currentTime); oscillator.stop(audioContextRef.current.currentTime + duration); } catch (e) { console.error("Error playing tone:", e); } }, [isAudioEnabled]);
    const playVisitSound = useCallback(() => playTone(400 + direction * 100, 0.06, 'sine', 0.18), [playTone, direction]); // Vary pitch by direction
    const playChangeDirectionSound = useCallback(() => playTone(700, 0.1, 'square', 0.2), [playTone]);
    const playStartSound = useCallback(() => playTone(440, 0.1, 'sine', 0.3), [playTone]);
    const playEndSound = useCallback(() => playTone(1100, 0.2, 'sine', 0.3), [playTone]);
    const playStopSound = useCallback(() => playTone(220, 0.15, 'square', 0.3), [playTone]);
    const playErrorSound = useCallback(() => playTone(150, 0.3, 'sawtooth', 0.3), [playTone]);
    const speak = useCallback((text) => { /* ... (standard) ... */ return new Promise((resolve) => { if (!isSpeechEnabled || typeof window === 'undefined' || !window.speechSynthesis) { resolve(); return; } try { window.speechSynthesis.cancel(); const utterance = new SpeechSynthesisUtterance(text); utterance.lang = 'en-US'; utterance.rate = 1.1; utterance.pitch = 1.0; utterance.volume = 0.8; utterance.onend = () => resolve(); utterance.onerror = (event) => { console.error("Speech synthesis error:", event.error); resolve(); }; window.speechSynthesis.speak(utterance); } catch (e) { console.error("Error initiating speech synthesis:", e); resolve(); } }); }, [isSpeechEnabled]);
    const cancelSpeech = useCallback(() => { /* ... (standard) ... */ if (typeof window !== 'undefined' && window.speechSynthesis) { window.speechSynthesis.cancel(); } }, []);

    // --- Input Parsing and Validation ---
    const parseAndValidateInput = (matrixStr) => {
        // (Same parsing logic as SetMatrixZeroesVisualizer)
        if (!matrixStr.trim()) throw new Error("Matrix input cannot be empty.");
        const rows = matrixStr.split(';');
        if (rows.length === 0) throw new Error("Matrix input cannot be empty.");
        const matrix = rows.map(rowStr => {
            if (!rowStr.trim()) throw new Error("Matrix row cannot be empty (check for extra semicolons).");
            return rowStr.split(',')
                         .map(numStr => numStr.trim())
                         .filter(numStr => numStr.length > 0)
                         .map(numStr => parseInt(numStr, 10));
        });
        const colLength = matrix[0].length;
        if (colLength === 0) throw new Error("Matrix row cannot be empty (check for commas).");
        for (let r = 0; r < matrix.length; r++) {
            if (matrix[r].length !== colLength) throw new Error(`Row ${r+1} has inconsistent length.`);
            if (matrix[r].some(isNaN)) throw new Error(`Row ${r+1} contains non-integer values.`);
        }
        return matrix;
    };

    // --- Reset Function ---
    const reset = useCallback((initial = false) => {
        stopRef.current = true;
        cancelSpeech();
        setIsRunning(false);
        setGridElements([]);
        setSpiralOutput([]);
        setFinalResult(null);
        setErrorMessage("");
        setMessage("");
        setCurrentCell(null);
        setDirection(0); // Reset direction

        try {
            const matrix = parseAndValidateInput(matrixInput);
            const R = matrix.length;
            const C = matrix[0].length;

            // Initialize grid elements for visualization
            const initialGrid = [];
            for (let i = 0; i < R; i++) {
                const row = [];
                for (let j = 0; j < C; j++) {
                    row.push({
                        id: `cell-${i}-${j}`,
                        value: matrix[i][j],
                        state: 'default', // States: default, current, visited
                        row: i,
                        col: j
                    });
                }
                initialGrid.push(row);
            }
            setGridElements(initialGrid);
            setMessage(initial ? "Enter matrix (rows separated by ';', values by ',')." : "Ready. Click Run.");

        } catch (e) {
            setGridElements([]);
            setSpiralOutput([]);
            setErrorMessage(e.message); // Set internal error state
            setMessage(`Input Error: ${e.message}`); // Set message for display
            if (!initial) playErrorSound();
        }
    }, [matrixInput, cancelSpeech, playErrorSound]);

    // --- Effects ---
    useEffect(() => {
        reset(true); // Initial reset
        return () => { /* ... (standard cleanup) ... */ stopRef.current = true; cancelSpeech(); if (audioContextRef.current) { audioContextRef.current.close().catch(e => console.error("Error closing AudioContext:", e)); audioContextRef.current = null; } };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    useEffect(() => { // Debounced reset on input change
        const handler = setTimeout(() => {
            reset(true);
        }, 500);
        return () => clearTimeout(handler);
    }, [matrixInput, reset]);


    // --- Visualization Logic (Spiral Traversal) ---
    const runVisualization = async () => {
        initAudioContext();
        cancelSpeech();
        reset(false); // Reset and validate
        await sleep(50);

        if (errorMessage) { // Check internal error state
            setIsRunning(false);
            return;
        }

        let matrix; // Use for logic if needed, though gridElements has values
        try {
             matrix = parseAndValidateInput(matrixInput);
        } catch (e) {
             setErrorMessage(`Input Error: ${e.message}`);
             setMessage(`Input Error: ${e.message}`);
             setIsRunning(false);
             playErrorSound();
             return;
        }

        const R = matrix.length;
        const C = matrix[0].length;
        if (R === 0 || C === 0) {
             setMessage("Empty matrix provided.");
             setIsRunning(false);
             return;
        }

        stopRef.current = false;
        setIsRunning(true);
        setFinalResult(null);
        setSpiralOutput([]); // Clear previous output
        playStartSound();
        await speak(`Starting Spiral Matrix traversal for ${R} by ${C} matrix.`);
        if (stopRef.current) { setIsRunning(false); return; }

        let currentGridElements = gridElements.map(row => row.map(cell => ({...cell, state: 'default'}))); // Deep copy for UI state
        let result = [];
        let top = 0, bottom = R - 1;
        let left = 0, right = C - 1;
        let dir = 0; // 0: R, 1: D, 2: L, 3: U
        setDirection(dir);

        const updateCellState = (r, c, newState) => {
             if (r >= 0 && r < R && c >= 0 && c < C) {
                 currentGridElements[r][c].state = newState;
             }
        };

        const syncUI = async (delay = 300) => {
             setGridElements([...currentGridElements.map(row => [...row])]);
             setSpiralOutput([...result]); // Update output display
             await sleep(delay);
             if (stopRef.current) throw new Error("Stopped"); // Throw error to break out
        };

        const directions = ["Right", "Down", "Left", "Up"];
        const dirIcons = [<ArrowForwardIcon fontSize="small"/>, <ArrowDownwardIcon fontSize="small"/>, <ArrowBackIcon fontSize="small"/>, <ArrowUpwardIcon fontSize="small"/>];

        try {
            while (top <= bottom && left <= right) {
                setMessage(`Direction: ${directions[dir]}`);
                await speak(`Going ${directions[dir]}.`);
                setDirection(dir); // Update state for sound pitch
                await syncUI(100);

                if (dir === 0) { // Traverse Right
                    for (let j = left; j <= right; j++) {
                        setCurrentCell({ row: top, col: j });
                        updateCellState(top, j, 'current');
                        await syncUI(250);
                        playVisitSound();
                        result.push(matrix[top][j]);
                        updateCellState(top, j, 'visited');
                    }
                    top++;
                } else if (dir === 1) { // Traverse Down
                    for (let i = top; i <= bottom; i++) {
                        setCurrentCell({ row: i, col: right });
                        updateCellState(i, right, 'current');
                        await syncUI(250);
                         playVisitSound();
                        result.push(matrix[i][right]);
                        updateCellState(i, right, 'visited');
                    }
                    right--;
                } else if (dir === 2) { // Traverse Left
                    for (let j = right; j >= left; j--) {
                        setCurrentCell({ row: bottom, col: j });
                        updateCellState(bottom, j, 'current');
                        await syncUI(250);
                         playVisitSound();
                        result.push(matrix[bottom][j]);
                        updateCellState(bottom, j, 'visited');
                    }
                    bottom--;
                } else if (dir === 3) { // Traverse Up
                    for (let i = bottom; i >= top; i--) {
                        setCurrentCell({ row: i, col: left });
                        updateCellState(i, left, 'current');
                        await syncUI(250);
                         playVisitSound();
                        result.push(matrix[i][left]);
                        updateCellState(i, left, 'visited');
                    }
                    left++;
                }
                setCurrentCell(null); // Clear current cell highlight
                dir = (dir + 1) % 4; // Change direction
                if (top <= bottom && left <= right) { // Only play sound if more steps remain
                     playChangeDirectionSound();
                     await sleep(300); // Pause after changing direction
                }
            } // End while loop

            // Final state
            setMessage("Finished Spiral Matrix traversal.");
            await speak("Finished.");
            playEndSound();
            setFinalResult("Completed"); // Indicate completion
            // Mark all as visited (or final)
            currentGridElements = currentGridElements.map(row => row.map(cell => ({
                 ...cell,
                 state: 'visited' // Use visited state as final
             })));
            await syncUI(100);


        } catch (error) {
            if (error.message === "Stopped") {
                setMessage("Visualization stopped by user.");
                speak("Visualization stopped.");
                playStopSound();
            } else {
                console.error("Visualization error:", error);
                setErrorMessage("An unexpected error occurred during visualization.");
                setMessage("An unexpected error occurred.");
            }
        } finally {
            setIsRunning(false);
            stopRef.current = false;
            setCurrentCell(null);
        }
    };

    // --- Control Functions ---
    const stopVisualization = () => { /* ... (standard) ... */ stopRef.current = true; cancelSpeech(); setMessage("Stopping visualization..."); };
    const toggleAudio = () => { /* ... (standard) ... */ const newState = !isAudioEnabled; setIsAudioEnabled(newState); if (newState) { initAudioContext(); setTimeout(() => playTone(500, 0.05, 'sine', 0.2), 50); } else { playTone(300, 0.05, 'square', 0.2); if (audioContextRef.current && audioContextRef.current.state === 'running') { audioContextRef.current.suspend().catch(e => console.error("Audio context suspend failed", e)); } } };
    const toggleSpeech = () => { /* ... (standard) ... */ const newState = !isSpeechEnabled; if (newState && (typeof window === 'undefined' || !window.speechSynthesis)) { setErrorMessage("Speech synthesis not supported by your browser."); setMessage("Speech synthesis not supported by your browser."); setTimeout(() => { setErrorMessage(""); setMessage(""); }, 3000); return; } setIsSpeechEnabled(newState); if (!newState) { cancelSpeech(); } else { speak("Speech enabled."); } };

    // --- Render ---
    // Format the final result string for the BaseVisualizer prop
    const formattedResult = finalResult === "Completed" ? "Result: Traversal Complete" : null;

    // Get grid dimensions for rendering
    const gridRows = gridElements.length;
    const gridCols = gridRows > 0 ? gridElements[0].length : 0;
    const directionIcons = [<ArrowForwardIcon fontSize="small"/>, <ArrowDownwardIcon fontSize="small"/>, <ArrowBackIcon fontSize="small"/>, <ArrowUpwardIcon fontSize="small"/>];


