// --- Tree Node Class (Helper) ---
class TreeNode {
    constructor(val, left = null, right = null) {
        this.val = val;
        this.left = left;
        this.right = right;
        // For visualization: unique id, position
        this.id = Math.random().toString(36).substring(2, 15); // Simple unique ID
        this.x = 0;
        this.y = 0;
        this.parentId = null;
    }
}

// --- Tree Parsing Function ---
// Input: LeetCode style array string like "[3,9,20,null,null,15,7]"
// Output: Root TreeNode or null
const parseTreeString = (str) => {
    str = str.trim();
    if (!str.startsWith('[') || !str.endsWith(']')) {
        // Allow single number input for single-node tree
        const num = parseInt(str, 10);
        if (!isNaN(num)) {
            return new TreeNode(num);
        }
        throw new Error("Invalid input format. Must be like '[1,2,null,3]' or a single number.");
    }
    str = str.substring(1, str.length - 1); // Remove brackets
    if (!str) {
        return null; // Empty tree
    }
    const values = str.split(',').map(v => v.trim());
    if (values.length === 0 || values[0] === 'null') {
        return null;
    }

    const rootVal = parseInt(values[0], 10);
     if (isNaN(rootVal)) {
         throw new Error(`Invalid root value: ${values[0]}`);
     }
    const root = new TreeNode(rootVal);
    const queue = [root];
    let i = 1;

    while (queue.length > 0 && i < values.length) {
        const currentNode = queue.shift();

        // Process left child
        if (i < values.length) {
            if (values[i] !== 'null') {
                const leftVal = parseInt(values[i], 10);
                 if (isNaN(leftVal)) throw new Error(`Invalid node value: ${values[i]}`);
                currentNode.left = new TreeNode(leftVal);
                currentNode.left.parentId = currentNode.id; // Link parent
                queue.push(currentNode.left);
            }
            i++;
        }

        // Process right child
        if (i < values.length) {
            if (values[i] !== 'null') {
                const rightVal = parseInt(values[i], 10);
                 if (isNaN(rightVal)) throw new Error(`Invalid node value: ${values[i]}`);
                currentNode.right = new TreeNode(rightVal);
                 currentNode.right.parentId = currentNode.id; // Link parent
                queue.push(currentNode.right);
            }
            i++;
        }
    }
    return root;
};

// --- Function to calculate node positions for rendering ---
// Uses a simple approach, may overlap for complex trees.
const calculateNodePositions = (root) => {
    if (!root) return { nodes: [], nodeMap: {}, height: 0 };

    const nodes = [];
    const nodeMap = {}; // To easily access nodes by ID
    let maxLevel = 0;
    const levelSpacing = 80; // Vertical distance between levels
    const baseHorizontalSpacing = 200; // Initial horizontal spread

    const traverse = (node, level, x, parentId) => {
        if (!node) return;

        maxLevel = Math.max(maxLevel, level);
        node.y = level * levelSpacing;
        node.x = x; // Assign calculated x
        node.parentId = parentId; // Assign parentId passed down

        nodes.push(node);
        nodeMap[node.id] = node;

        // Calculate horizontal spread for children, reducing it at deeper levels
        const childrenHorizontalSpread = baseHorizontalSpacing / Math.pow(1.8, level + 1); // Adjust 1.8 factor as needed

        traverse(node.left, level + 1, x - childrenHorizontalSpread, node.id);
        traverse(node.right, level + 1, x + childrenHorizontalSpread, node.id);
    };

    // Start traversal from root
    traverse(root, 0, 0, null); // Root is at level 0, x=0 initially

    // --- Post-processing: Adjust for overlaps and center ---

    // 1. Adjust X to prevent simple overlaps within the same level (basic)
    const nodesByLevel = {};
    nodes.forEach(node => {
        if (!nodesByLevel[node.y]) nodesByLevel[node.y] = [];
        nodesByLevel[node.y].push(node);
    });

    Object.values(nodesByLevel).forEach(levelNodes => {
        levelNodes.sort((a, b) => a.x - b.x); // Sort nodes by x position
        for (let i = 1; i < levelNodes.length; i++) {
            const node1 = levelNodes[i - 1];
            const node2 = levelNodes[i];
            const minGap = 40; // Minimum horizontal gap between nodes (nodeRadius * 2 + buffer)
            const currentGap = node2.x - node1.x;
            if (currentGap < minGap) {
                // Shift node2 and potentially its subtree rightward
                const shift = minGap - currentGap;
                // Basic shift - does not propagate to children correctly in this simple model
                // A full layout algorithm (like Reingold-Tilford) is needed for perfect results
                 // For this simple version, we just shift the node itself
                 node2.x += shift;
                 // A better approach would involve shifting subtrees, which is complex.
                 // We'll accept potential overlaps in complex trees with this basic method.
            }
        }
    });


    // 2. Center the tree horizontally based on final min/max X
    if (nodes.length > 0) {
        let minX = Infinity;
        let maxX = -Infinity;
        nodes.forEach(n => {
            minX = Math.min(minX, n.x);
            maxX = Math.max(maxX, n.x);
        });
        const width = maxX - minX;
        const offsetX = -minX - (width / 2); // Calculate offset to center the tree
         nodes.forEach(n => {
             n.x += offsetX;
         });
    }

    return { nodes, nodeMap, height: (maxLevel + 1) * levelSpacing };
};


