/**
 * Calculates the maximum depth of a binary tree using recursion (DFS).
 * Time: O(N), where N is the number of nodes (visits each node once).
 * Space: O(H) in the average case (recursion stack height), O(N) in the worst case (skewed tree).
 * @param {TreeNode} root The root of the binary tree.
 * @return {number} The maximum depth.
 */
const maxDepth = function(root) {
    if (!root) {
        return 0; // Base case: empty tree or leaf's child
    }

    // Recursively find the depth of left and right subtrees
    const leftDepth = maxDepth(root.left);
    const rightDepth = maxDepth(root.right);

    // The depth of the current node is 1 + maximum of its children's depths
    return Math.max(leftDepth, rightDepth) + 1;
};

// BFS Approach (Level Order Traversal)
// Time: O(N), Space: O(W), where W is the maximum width of the tree
const maxDepthBFS = function(root) {
    if (!root) return 0;
    let queue = [root];
    let depth = 0;
    while (queue.length > 0) {
        depth++;
        let levelSize = queue.length;
        for (let i = 0; i < levelSize; i++) {
            let node = queue.shift();
            if (node.left) queue.push(node.left);
            if (node.right) queue.push(node.right);
        }
    }
    return depth;
};
