const productExceptSelfSolutionCodeCPP = `
#include <vector>
#include <numeric> // Not used in optimal solution, but could be for printing
#include <iostream>

// Helper to print vector (optional)
template<typename T>
std::ostream& operator<<(std::ostream& os, const std::vector<T>& vec) {
    os << "[";
    for (size_t i = 0; i < vec.size(); ++i) {
        os << vec[i] << (i == vec.size() - 1 ? "" : ", ");
    }
    os << "]";
    return os;
}

class Solution {
public:
    /**
     * Calculates the product of all elements except self for each element in a vector.
     * O(n) time, O(1) extra space (output vector doesn't count), no division.
     * @param nums The input vector of integers.
     * @return A vector where answer[i] is the product of all elements except nums[i].
     */
    std::vector<int> productExceptSelf(const std::vector<int>& nums) {
        int n = nums.size();
        std::vector<int> answer(n);

        // 1. Calculate prefix products (left-to-right)
        answer[0] = 1;
        for (int i = 1; i < n; ++i) {
            answer[i] = nums[i - 1] * answer[i - 1];
        }

        // 2. Calculate suffix products (right-to-left) and multiply
        int suffixProduct = 1;
        for (int i = n - 1; i >= 0; --i) {
            answer[i] = answer[i] * suffixProduct;
            suffixProduct *= nums[i];
        }

        return answer;
    }
};

// Example Usage:
int main() {
    Solution sol;
    std::vector<int> nums1 = {1, 2, 3, 4};
    std::vector<int> result1 = sol.productExceptSelf(nums1);
    std::cout << "Input: " << nums1 << ", Output: " << result1 << std::endl; // Output: [24, 12, 8, 6]

    std::vector<int> nums2 = {-1, 1, 0, -3, 3};
    std::vector<int> result2 = sol.productExceptSelf(nums2);
    std::cout << "Input: " << nums2 << ", Output: " << result2 << std::endl; // Output: [0, 0, 9, 0, 0]

    return 0;
}
`;
