// --- Solution Code Strings (Climbing Stairs) ---
const climbingStairsSolutionCodeJS = `
/**
 * Calculates the number of distinct ways to climb to the top of n stairs,
 * taking either 1 or 2 steps at a time.
 * Uses dynamic programming.
 * @param {number} n - The total number of stairs (positive integer).
 * @returns {number} The number of distinct ways to climb.
 */
const climbStairs = function(n) {
    if (n <= 0) return 0;
    if (n === 1) return 1;
    if (n === 2) return 2;

    // dp[i] will store the number of ways to reach step i
    const dp = new Array(n + 1);

    // Base cases
    dp[0] = 0; // Not used, but helps align indices
    dp[1] = 1; // 1 way to reach step 1 (1 step)
    dp[2] = 2; // 2 ways to reach step 2 (1+1 or 2 steps)

    // Fill the dp table
    for (let i = 3; i <= n; i++) {
        // Ways to reach step i = ways to reach (i-1) + ways to reach (i-2)
        dp[i] = dp[i - 1] + dp[i - 2];
    }

    return dp[n];

    // Space Optimization (using only last two values):
    // let oneStepBefore = 2;
    // let twoStepsBefore = 1;
    // for (let i = 3; i <= n; i++) {
    //     const currentWays = oneStepBefore + twoStepsBefore;
    //     twoStepsBefore = oneStepBefore;
    //     oneStepBefore = currentWays;
    // }
    // return oneStepBefore;
};

// Example Usage:
console.log(\`Ways to climb 2 stairs: \${climbStairs(2)}\`); // Output: 2
console.log(\`Ways to climb 3 stairs: \${climbStairs(3)}\`); // Output: 3
console.log(\`Ways to climb 5 stairs: \${climbStairs(5)}\`); // Output: 8
`;

