// --- ClimbingStairsVisualizer Component (Template Applied) ---
const ClimbingStairsVisualizer = () => {
    // --- State Variables ---
    const [nInput, setNInput] = useState("5"); // Input 'n' stairs
    const [dpElements, setDpElements] = useState([]); // Stores the DP array visualization
    const [message, setMessage] = useState("");
    const [errorMessage, setErrorMessage] = useState("");
    const [isRunning, setIsRunning] = useState(false);
    const [finalResult, setFinalResult] = useState(null);
    const stopRef = React.useRef(false);
    // Audio/Speech State
    const [isAudioEnabled, setIsAudioEnabled] = useState(true);
    const [isSpeechEnabled, setIsSpeechEnabled] = useState(true);

    // --- Web Audio API Setup ---
    const audioContextRef = useRef(null);
    const initAudioContext = useCallback(() => { /* ... (Template standard) ... */ if (!isAudioEnabled) return; if (audioContextRef.current === null && typeof window !== 'undefined' && (window.AudioContext || window.webkitAudioContext)) { try { audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { console.error("Web Audio API not supported.", e); setIsAudioEnabled(false); setMessage("Audio tones disabled: Not supported."); } } if (audioContextRef.current && audioContextRef.current.state === 'suspended') { audioContextRef.current.resume().catch(e => console.error("Audio resume failed", e)); } }, [isAudioEnabled]);
    const playTone = useCallback((frequency = 440, duration = 0.1, type = 'sine', volume = 0.3) => { /* ... (Template standard) ... */ if (!isAudioEnabled || !audioContextRef.current || audioContextRef.current.state !== 'running') return; try { const oscillator = audioContextRef.current.createOscillator(); const gainNode = audioContextRef.current.createGain(); oscillator.type = type; oscillator.frequency.setValueAtTime(frequency, audioContextRef.current.currentTime); gainNode.gain.setValueAtTime(volume, audioContextRef.current.currentTime); gainNode.gain.exponentialRampToValueAtTime(0.0001, audioContextRef.current.currentTime + duration); oscillator.connect(gainNode); gainNode.connect(audioContextRef.current.destination); oscillator.start(audioContextRef.current.currentTime); oscillator.stop(audioContextRef.current.currentTime + duration); } catch (e) { console.error("Error playing tone:", e); } }, [isAudioEnabled]);
    // Specific sounds
    const playBaseCaseSound = useCallback(() => playTone(300, 0.1, 'square', 0.2), [playTone]);
    const playReadDpSound = useCallback(() => playTone(600, 0.07, 'square', 0.2), [playTone]);
    const playWriteDpSound = useCallback(() => playTone(900, 0.1, 'sine', 0.25), [playTone]);
    const playStartSound = useCallback(() => playTone(440, 0.1, 'sine', 0.3), [playTone]);
    const playEndSound = useCallback(() => playTone(1100, 0.2, 'sine', 0.3), [playTone]);
    const playStopSound = useCallback(() => playTone(220, 0.15, 'square', 0.3), [playTone]);
    const playErrorSound = useCallback(() => playTone(150, 0.3, 'sawtooth', 0.3), [playTone]);

    // --- Web Speech API Setup (Promise-based) ---
    const speak = useCallback((text) => {
        return new Promise((resolve) => { // Always resolve
            if (!isSpeechEnabled || typeof window === 'undefined' || !window.speechSynthesis) { resolve(); return; }
            try {
                window.speechSynthesis.cancel(); const utterance = new SpeechSynthesisUtterance(text);
                utterance.lang = 'en-US'; utterance.rate = 1.0; utterance.pitch = 1.0; utterance.volume = 0.8;
                utterance.onend = () => { resolve(); };
                utterance.onerror = (event) => { console.error("Speech synthesis error:", event.error); resolve(); };
                window.speechSynthesis.speak(utterance);
            } catch (e) { console.error("Error initiating speech synthesis:", e); resolve(); }
        });
    }, [isSpeechEnabled]);

    const cancelSpeech = useCallback(() => { if (typeof window !== 'undefined' && window.speechSynthesis) { window.speechSynthesis.cancel(); } }, []);

    // --- Reset Function ---
    const reset = useCallback((initial = false) => {
        stopRef.current = true; cancelSpeech(); setIsRunning(false);
        setDpElements([]); setFinalResult(null); setErrorMessage("");
        try {
            const n = parseNumberInput(nInput);
            if (n < 1 && !initial) throw new Error("Number of stairs (n) must be at least 1.");
            if (n > 45 && !initial) console.warn("Warning: Result might exceed standard integer limits for n > 45."); // Fibonacci grows fast
            // Initialize DP array for display (size n+1, index 0 unused visually perhaps)
             const initialDp = Array(n + 1).fill('?'); // Use '?' for uncalculated
             setDpElements(initialDp.map((val, i) => ({ id: `dp-${i}`, value: val, state: 'default', index: i, pointers: [] })));

            setMessage(initial ? "" : "Enter number of stairs (n >= 1).");
        } catch (e) {
            setDpElements([]); setErrorMessage(`Input Error: ${e.message}`); setMessage("");
            if (!initial) playErrorSound();
        }
    }, [nInput, cancelSpeech, parseNumberInput, playErrorSound]); // Added parseNumberInput dependency

    // --- Effects ---
    useEffect(() => { reset(true); return () => { stopRef.current = true; cancelSpeech(); if (audioContextRef.current) { audioContextRef.current.close().catch(e => console.error("Error closing AudioContext:", e)); audioContextRef.current = null; } }; }, [reset, cancelSpeech]);
    useEffect(() => { const handler = setTimeout(() => { reset(true); }, 500); return () => clearTimeout(handler); }, [nInput, reset]);

    // --- Visualization Logic ---
    const runVisualization = async () => {
        initAudioContext(); cancelSpeech(); reset(false); await sleep(50);

        let n;
        try {
            if (errorMessage) { setIsRunning(false); return; }
            n = parseNumberInput(nInput);
            if (n < 1) throw new Error("n must be at least 1.");
        } catch (e) { setErrorMessage(`Input Error: ${e.message}`); setIsRunning(false); playErrorSound(); return; }

        stopRef.current = false; setIsRunning(true);
        setMessage("Starting Climbing Stairs calculation..."); playStartSound();
        await speak(`Calculating ways to climb ${n} stairs.`);
        if (stopRef.current) { setIsRunning(false); return; }

        const dp = new Array(n + 1); // Algorithm's internal DP array
        let currentDpElements = dpElements.map(el => ({...el})); // Mutable copy for UI updates

        // --- Base Cases ---
        if (n >= 1) {
            dp[1] = 1;
            currentDpElements[1] = { ...currentDpElements[1], value: 1, state: 'highlight-final' };
            setDpElements([...currentDpElements]);
            setMessage("Base Case: dp[1] = 1 way (take 1 step).");
            playBaseCaseSound(); await speak("Base case: 1 way to reach step 1.");
            await sleep(1200); if (stopRef.current) { setIsRunning(false); return; }
        }
        if (n >= 2) {
            dp[2] = 2;
            currentDpElements[2] = { ...currentDpElements[2], value: 2, state: 'highlight-final' };
            setDpElements([...currentDpElements]);
            setMessage("Base Case: dp[2] = 2 ways (1+1 or 2 steps).");
            playBaseCaseSound(); await speak("Base case: 2 ways to reach step 2.");
            await sleep(1200); if (stopRef.current) { setIsRunning(false); return; }
        }

        // --- DP Calculation ---
        for (let i = 3; i <= n; i++) {
            if (stopRef.current) break;

            // Highlight dependencies
            const idx1 = i - 1;
            const idx2 = i - 2;
            currentDpElements = currentDpElements.map((el, idx) => ({
                ...el,
                state: idx === i ? 'highlight-current-dp' : (idx === idx1 || idx === idx2 ? 'highlight-dp-dependency' : (idx < i ? 'highlight-final' : 'default')),
                pointers: idx === i ? ['i'] : (idx === idx1 ? ['i-1'] : (idx === idx2 ? ['i-2'] : []))
            }));
            setDpElements([...currentDpElements]);
            setMessage(`Calculating dp[${i}]: Need dp[${idx1}] and dp[${idx2}].`);
            playReadDpSound(); await speak(`Calculating ways for step ${i}. Looking at step ${idx1} and step ${idx2}.`);
            await sleep(1500); if (stopRef.current) break;

            // Calculate result
            dp[i] = dp[idx1] + dp[idx2];
            setMessage(`Calculate dp[${i}] = dp[${idx1}] (${dp[idx1]}) + dp[${idx2}] (${dp[idx2]}) = ${dp[i]}.`);
            playWriteDpSound(); await speak(`Ways for step ${i} equals ${dp[idx1]} plus ${dp[idx2]}, which is ${dp[i]}.`);

            // Update UI
            currentDpElements[i] = { ...currentDpElements[i], value: dp[i], state: 'highlight-final', pointers: ['i'] };
             // Reset dependency highlights
             if (idx1 >= 0) currentDpElements[idx1] = { ...currentDpElements[idx1], state: 'highlight-final', pointers: [] };
             if (idx2 >= 0) currentDpElements[idx2] = { ...currentDpElements[idx2], state: 'highlight-final', pointers: [] };
            setDpElements([...currentDpElements]);
            await sleep(1500); if (stopRef.current) break; // Pause after calculation

             // Clear 'i' pointer for next iteration
             currentDpElements[i] = { ...currentDpElements[i], pointers: [] };
             setDpElements([...currentDpElements]);
             await sleep(300);

        }

        // Final State
        if (stopRef.current) {
            setMessage("Visualization stopped by user."); speak("Visualization stopped."); playStopSound();
        } else {
            const finalAnswer = dp[n];
            setFinalResult(finalAnswer);
            setMessage(`Finished. Total ways to climb ${n} stairs: ${finalAnswer}.`);
            playEndSound(); await speak(`Finished. There are ${finalAnswer} ways.`);
            // Ensure final state highlights the result
             setDpElements(prev => prev.map((el, idx) => ({ ...el, state: idx === n ? 'highlight-final-result' : 'highlight-final', pointers: idx === n ? ['Result'] : [] })));
        }
        setIsRunning(false); stopRef.current = false;
    };

    const stopVisualization = () => {
        stopRef.current = true; cancelSpeech(); setMessage("Stopping visualization...");
    };

    const toggleAudio = () => { /* ... (Template standard) ... */ const newState = !isAudioEnabled; setIsAudioEnabled(newState); if (newState) { initAudioContext(); playTone(500, 0.05, 'sine', 0.2); } else { playTone(300, 0.05, 'square', 0.2); if (audioContextRef.current && audioContextRef.current.state === 'running') { audioContextRef.current.suspend().catch(e => console.error("Audio suspend failed", e)); } } };
    const toggleSpeech = () => { /* ... (Template standard) ... */ const newState = !isSpeechEnabled; if (newState && (typeof window === 'undefined' || !window.speechSynthesis)) { setMessage("Speech synthesis not supported."); return; } setIsSpeechEnabled(newState); if (!newState) { cancelSpeech(); } else { speak("Speech enabled."); } };

    // --- Render ---
    return (
        <>
            <BaseVisualizer
                problemSummary={
                    <>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                            <Typography variant="h4" component="h1">Climbing Stairs</Typography>
                            <Chip label="Easy" color="success" size="small" variant="filled" />
                        </Box>
                        <Typography variant="body1" component="div" sx={{ mb: 2 }}>
                            You are climbing a staircase. It takes <code>n</code> steps to reach the top.
                            <br/><br/>Each time you can either climb <strong>1</strong> or <strong>2</strong> steps. In how many distinct ways can you climb to the top?
                        </Typography>
                        <Typography variant="h6" component="h3" sx={{ mt: 2, mb: 1 }}>Examples:</Typography>
                        <Box sx={{ bgcolor: 'action.hover', p: 1.5, borderRadius: 1, fontFamily: 'monospace', mb: 2, fontSize: '0.875rem' }}>
                            <strong>Input:</strong> n = 2<br/><strong>Output:</strong> 2<br/><strong>Explanation:</strong> 1. 1 step + 1 step<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2. 2 steps<br/><br/>
                            <strong>Input:</strong> n = 3<br/><strong>Output:</strong> 3<br/><strong>Explanation:</strong> 1. 1 step + 1 step + 1 step<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2. 1 step + 2 steps<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;3. 2 steps + 1 step
                        </Box>
                        <Typography variant="h6" component="h3" sx={{ mt: 2, mb: 1 }}>Constraints:</Typography>
                        <Box component="ul" sx={{ pl: 2, mb: 2 }}>
                            <li><code>1 &lt;= n &lt;= 45</code></li>
                        </Box>
                        <Divider sx={{ my: 3 }} />
                        <Typography variant="h6" sx={{ mt: 3, mb: 1 }}>Runnable Solution Code Examples (Dynamic Programming)</Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>Copy/paste these into the compiler below.</Typography>
                        <Typography variant="subtitle2" sx={{ mb: 0.5 }}>JavaScript:</Typography><SolutionCodeDisplay codeString={climbingStairsSolutionCodeJS} />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>Python:</Typography><SolutionCodeDisplay codeString={climbingStairsSolutionCodePython} />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>Java:</Typography><SolutionCodeDisplay codeString={climbingStairsSolutionCodeJava} />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>C++:</Typography><SolutionCodeDisplay codeString={climbingStairsSolutionCodeCPP} />
                        <Divider sx={{ my: 3 }} />
                        <Typography variant="subtitle1" gutterBottom>Algorithm Analysis (Dynamic Programming)</Typography>
                        <Typography variant="body2" color="text.secondary"><strong>Time Complexity:</strong> <code>O(N)</code>. We iterate from 1 to N once.</Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}><strong>Space Complexity:</strong> <code>O(N)</code> for the DP array. Can be optimized to <code>O(1)</code> by only storing the last two values.</Typography>
                    </>
                }
                controls={
                    <>
                        <Typography variant="subtitle1" sx={{ textAlign: 'center', fontWeight: 'bold', p: 0.75, mb: 2.5, borderRadius: '4px', color: 'common.white', background: 'linear-gradient(45deg, #66BB6A 30%, #81C784 90%)', boxShadow: 1 }}>Algorithm Visualizer</Typography>
                        <Grid container spacing={1.5} alignItems="center" mb={2}>
                            <Grid item xs={12} sm={6} md={6}><TextField fullWidth id="cs-input-n" label="Number of Stairs (n >= 1)" type="number" variant="outlined" size="small" value={nInput} onChange={(e) => setNInput(e.target.value)} placeholder="e.g., 5" disabled={isRunning} inputProps={{ min: 1 }} /></Grid>
                            <Grid item xs={4} sm={2} md={1.5}><Tooltip title={isRunning ? "Stop Visualization" : "Run Visualization"}><span><Button fullWidth variant="contained" sx={{ height: '40px' }} startIcon={isRunning ? <CircularProgress size={20} color="inherit" /> : <StairsIcon />} onClick={isRunning ? stopVisualization : runVisualization} color={isRunning ? "warning" : "primary"} disabled={isRunning && stopRef.current}>{isRunning ? 'Stop' : 'Run'}</Button></span></Tooltip></Grid>
                            <Grid item xs={4} sm={2} md={1.5}><Tooltip title={isAudioEnabled ? "Mute Tones" : "Unmute Tones"}><Button fullWidth variant="outlined" onClick={toggleAudio} sx={{ height: '40px', minWidth: 'auto', p: 1 }}>{isAudioEnabled ? <VolumeUpIcon /> : <VolumeOffIcon />}</Button></Tooltip></Grid>
                            <Grid item xs={4} sm={2} md={1.5}><Tooltip title={isSpeechEnabled ? "Disable Speech" : "Enable Speech"}><Button fullWidth variant="outlined" onClick={toggleSpeech} sx={{ height: '40px', minWidth: 'auto', p: 1 }}>{isSpeechEnabled ? <RecordVoiceOverIcon /> : <VoiceOverOffIcon />}</Button></Tooltip></Grid>
                            <Grid item xs={12} sm={12} md={1.5} sx={{ display: 'flex', justifyContent: { xs: 'center', md: 'flex-start' } }}><Button variant="outlined" startIcon={<ReplayIcon />} onClick={() => reset(false)} disabled={isRunning} sx={{ height: '40px' }}>Reset</Button></Grid>
                        </Grid>
                        {errorMessage && <Alert severity="error" sx={{ mt: 2 }}>{errorMessage}</Alert>}
                    </>
                }
                displayArea={
                    <>
                        <Typography variant="h6" gutterBottom align="center">DP Array (Ways to reach step i)</Typography>
                        <Box sx={{ display: 'flex', justifyContent: 'center', flexWrap: 'wrap', gap: 1, alignItems: 'flex-end', minHeight: '60px', position: 'relative', pt: 4, pb: 1, border: '1px dashed', borderColor: 'divider', borderRadius: 1 }}>
                             {/* ASSUMPTION: ArrayElement handles states like 'highlight-current-dp', 'highlight-dp-dependency', 'highlight-final', 'highlight-final-result' */}
                             {dpElements.map(el => (<ArrayElement key={el.id} value={el.value} index={el.index} state={el.state} pointers={el.pointers} type="box" showValue={true} showIndex={true} />))}
                             {dpElements.length === 0 && !errorMessage && <Typography variant="caption" color="text.secondary">Enter n to visualize DP array</Typography>}
                             {errorMessage && dpElements.length === 0 && <Typography variant="caption" color="error">Input Error</Typography>}
                        </Box>

                        {/* Final Result Indication */}
                        {finalResult !== null && !isRunning && !errorMessage && (
                            <Alert icon={<CheckCircleOutlineIcon fontSize="inherit" />} severity="success" sx={{ mt: 3, justifyContent: 'center', textAlign: 'center' }}>
                                <Typography variant="h6">Total Distinct Ways: {finalResult}</Typography>
                            </Alert>
                        )}
                    </>
                }
                message={message}
            />
            {/* Render Imported Online Compiler */}
            <Container maxWidth="xl" sx={{ mt: 4, mb: 4 }}>
                <OnlineCompiler />
            </Container>
        </>
    );
};

export default ClimbingStairsVisualizer;
