const solutionCodeJS = `
/**
 * Finds the minimum number of intervals to remove to make the rest non-overlapping.
 * Greedy approach: Sort by end times.
 * Time: O(N log N) for sorting, Space: O(1) or O(N) depending on sort implementation.
 * @param {number[][]} intervals - List of intervals.
 * @return {number} Minimum number of intervals to remove.
 */
const eraseOverlapIntervals = function(intervals) {
    if (!intervals || intervals.length === 0) {
        return 0;
    }

    // 1. Sort intervals by their end times
    intervals.sort((a, b) => a[1] - b[1]);

    let removals = 0;
    let lastEndTime = intervals[0][1]; // End time of the first non-overlapping interval found

    // 2. Iterate starting from the second interval
    for (let i = 1; i < intervals.length; i++) {
        const currentStart = intervals[i][0];
        const currentEnd = intervals[i][1]; // Not strictly needed for logic, but good for understanding

        // Check for overlap: current interval starts BEFORE the last one ended
        if (currentStart < lastEndTime) {
            // Overlap exists, we need to remove this current interval
            // We keep the one that finished earlier (which is lastEndTime due to sorting)
            removals++;
        } else {
            // No overlap, this interval can be kept.
            // Update the last end time to the current interval's end time.
            lastEndTime = currentEnd;
        }
    }

    return removals;
};
`;
