const solutionCodeJava = `
import java.util.Arrays;
import java.util.Comparator;

class Solution {
    /**
     * Finds the minimum number of intervals to remove to make the rest non-overlapping.
     * Greedy approach: Sort by end times.
     * Time: O(N log N), Space: O(1) or O(N).
     * @param intervals List of intervals.
     * @return Minimum number of intervals to remove.
     */
    public int eraseOverlapIntervals(int[][] intervals) {
        if (intervals == null || intervals.length == 0) {
            return 0;
        }

        // 1. Sort by end time
        Arrays.sort(intervals, Comparator.comparingInt(a -> a[1]));
        // Or: Arrays.sort(intervals, (a, b) -> Integer.compare(a[1], b[1]));

        int removals = 0;
        int lastEndTime = intervals[0][1];

        // 2. Iterate from the second interval
        for (int i = 1; i < intervals.length; i++) {
            int currentStart = intervals[i][0];
            int currentEnd = intervals[i][1]; // For clarity

            // Check for overlap
            if (currentStart < lastEndTime) {
                // Overlap, increment removal count
                removals++;
            } else {
                // No overlap, update last end time
                lastEndTime = currentEnd;
            }
        }

        return removals;
    }
}
`;
const solutionCodeCPP = `
#include <vector>
#include <algorithm> // For std::sort

using namespace std;

class Solution {
public:
    /**
     * Finds the minimum number of intervals to remove to make the rest non-overlapping.
     * Greedy approach: Sort by end times.
     * Time: O(N log N), Space: O(1) or O(N).
     * @param intervals List of intervals.
     * @return Minimum number of intervals to remove.
     */
    int eraseOverlapIntervals(vector<vector<int>>& intervals) {
        if (intervals.empty()) {
            return 0;
        }

        // 1. Sort by end time
        sort(intervals.begin(), intervals.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[1] < b[1];
        });

        int removals = 0;
        int lastEndTime = intervals[0][1];

        // 2. Iterate from the second interval
        for (int i = 1; i < intervals.size(); ++i) {
            int currentStart = intervals[i][0];
            int currentEnd = intervals[i][1]; // For clarity

            // Check for overlap
            if (currentStart < lastEndTime) {
                // Overlap, increment removal count
                removals++;
            } else {
                // No overlap, update last end time
                lastEndTime = currentEnd;
            }
        }

        return removals;
    }
};
`;

