    const [currentProcessingIndex, setCurrentProcessingIndex] = useState(-1); // Index in sortedIntervals being processed
    const [lastKeptIndex, setLastKeptIndex] = useState(-1); // Index of the last interval kept
    const [lastEndTime, setLastEndTime] = useState(-Infinity); // End time of the last kept interval
    const [removalCount, setRemovalCount] = useState(0);

    // Standard State
    const [message, setMessage] = useState(`Enter intervals to find minimum removals for non-overlap.`);
