// --- Simple Heap Implementations (for Visualization) ---
// In a real scenario, use efficient library implementations.
// These use sorting for simplicity, which is not efficient O(N log N).
class MaxHeap {
    constructor() { this.heap = []; }
    add(val) { this.heap.push(val); this.heap.sort((a, b) => b - a); } // Keep sorted descending
    peek() { return this.heap.length > 0 ? this.heap[0] : null; }
    poll() { return this.heap.length > 0 ? this.heap.shift() : null; } // Remove max
    size() { return this.heap.length; }
    getElements() { return [...this.heap]; }
}
class MinHeap {
    constructor() { this.heap = []; }
    add(val) { this.heap.push(val); this.heap.sort((a, b) => a - b); } // Keep sorted ascending
    peek() { return this.heap.length > 0 ? this.heap[0] : null; }
    poll() { return this.heap.length > 0 ? this.heap.shift() : null; } // Remove min
    size() { return this.heap.length; }
    getElements() { return [...this.heap]; }
}


