// Uses two heaps: a Max-Heap for the lower half and a Min-Heap for the upper half.
// This allows O(1) access to the middle elements for median calculation.
// Adding a number takes O(log N) time. Finding the median takes O(1) time.
// Space: O(N) to store the numbers.

// Note: JavaScript doesn't have built-in Heaps/PriorityQueues.
// You'd typically use a library or implement them manually.
// The code below simulates the logic using arrays and sorting (inefficient).

class MedianFinder {
    constructor() {
        // Max-heap for the lower half (stores smaller numbers, largest of them at top)
        this.lowerHalfMaxHeap = []; // Simulate with array, keep sorted descending
        // Min-heap for the upper half (stores larger numbers, smallest of them at top)
        this.upperHalfMinHeap = []; // Simulate with array, keep sorted ascending
    }

    /**
     * Adds a number into the data structure. O(log N) with real heaps.
     * @param {number} num
     * @return {void}
     */
    addNum(num) {
        // 1. Add to max-heap (lower half) by default
        this.lowerHalfMaxHeap.push(num);
        this.lowerHalfMaxHeap.sort((a, b) => b - a); // Keep sorted descending

        // 2. Balance: Move largest from lower half to upper half
        // Ensure largest element of lower half <= smallest element of upper half
        if (this.lowerHalfMaxHeap.length > 0 && this.upperHalfMinHeap.length > 0 &&
            this.lowerHalfMaxHeap[0] > this.upperHalfMinHeap[0])
        {
            const maxOfLower = this.lowerHalfMaxHeap.shift(); // Remove max
            this.upperHalfMinHeap.push(maxOfLower);
            this.upperHalfMinHeap.sort((a, b) => a - b); // Keep sorted ascending
        }

        // 3. Rebalance sizes: Ensure heaps differ by at most 1
        // If lower half is too big
        if (this.lowerHalfMaxHeap.length > this.upperHalfMinHeap.length + 1) {
             const maxOfLower = this.lowerHalfMaxHeap.shift(); // Remove max
             this.upperHalfMinHeap.push(maxOfLower);
             this.upperHalfMinHeap.sort((a, b) => a - b);
        }
        // If upper half is too big
        else if (this.upperHalfMinHeap.length > this.lowerHalfMaxHeap.length) {
             const minOfUpper = this.upperHalfMinHeap.shift(); // Remove min
             this.lowerHalfMaxHeap.push(minOfUpper);
             this.lowerHalfMaxHeap.sort((a, b) => b - a);
        }
    }

    /**
     * Returns the median of current data stream. O(1).
     * @return {number}
     */
    findMedian() {
        const lowerSize = this.lowerHalfMaxHeap.length;
        const upperSize = this.upperHalfMinHeap.length;

        if (lowerSize > upperSize) {
            // Odd number of elements, median is top of lower half (max-heap)
            return this.lowerHalfMaxHeap[0];
        } else if (upperSize > lowerSize) {
             // Should not happen with the rebalancing logic above, but included for completeness
             return this.upperHalfMinHeap[0];
        } else { // lowerSize === upperSize
            // Even number of elements, median is average of tops of both heaps
            if (lowerSize === 0) return 0; // Or throw error for empty stream
            return (this.lowerHalfMaxHeap[0] + this.upperHalfMinHeap[0]) / 2.0;
        }
    }
}

