const LEVEL_SPACING = 65; // Less vertical space

// --- Trie Node Class (Helper) ---
class TrieNode {
    constructor(char = null) { // Store character for visualization
        this.char = char;
        this.children = {}; // Map<char, TrieNode>
        this.isEndOfWord = false;
        // Visualization properties
        this.id = Math.random().toString(36).substring(2, 15);
        this.x = 0;
        this.y = 0;
        this.parentId = null;
    }
}

// --- Function to calculate Trie node positions ---
// Basic hierarchical layout, might overlap significantly with wide Tries.
const calculateTriePositions = (root) => {
    if (!root) return { nodes: [], nodeMap: {}, height: 0 };

    const nodes = [];
    const nodeMap = {};
    let maxLevel = 0;
    const baseHorizontalSpacing = 80; // Adjust as needed

    const traverse = (node, level, x, parentId) => {
        if (!node) return;

        maxLevel = Math.max(maxLevel, level);
        node.y = level * LEVEL_SPACING;
        node.x = x;
        node.parentId = parentId;

        nodes.push(node);
        nodeMap[node.id] = node;

        const children = Object.values(node.children);
        const numChildren = children.length;
        if (numChildren === 0) return;

        // Distribute children horizontally
        const childrenTotalWidth = (numChildren - 1) * (baseHorizontalSpacing / Math.pow(1.5, level + 1));
        let startX = x - childrenTotalWidth / 2;
        const childSpacing = baseHorizontalSpacing / Math.pow(1.5, level + 1); // Spacing between children

        // Sort children alphabetically for consistent layout
        children.sort((a, b) => (a.char || '').localeCompare(b.char || ''));

        children.forEach((child, index) => {
            const childX = startX + index * childSpacing;
            traverse(child, level + 1, childX, node.id);
        });
    };

    traverse(root, 0, 0, null); // Start from root

    // Center the tree horizontally
    if (nodes.length > 0) {
        let minX = Infinity, maxX = -Infinity;
        nodes.forEach(n => { minX = Math.min(minX, n.x); maxX = Math.max(maxX, n.x); });
        const treeWidth = maxX - minX;
        const centeringOffset = -minX - (treeWidth / 2);
        nodes.forEach(n => { n.x += centeringOffset; });
    }

     // Add a top padding for rendering
     const topPadding = NODE_RADIUS + 10;
     nodes.forEach(n => {
         n.y += topPadding;
     });

    return { nodes, nodeMap, height: (maxLevel * LEVEL_SPACING) + topPadding };
};


