const pacificAtlanticSolutionCodeJS = `
/**
 * Finds cells in a height map from which water can flow to both Pacific and Atlantic oceans.
 * Uses Depth First Search (DFS) starting from ocean borders.
 * Time: O(M*N), Space: O(M*N) for visited sets and recursion stack.
 * @param {number[][]} heights - The m x n grid of heights.
 * @returns {number[][]} A list of [row, col] coordinates reachable by both oceans.
 */
const pacificAtlantic = function(heights) {
    if (!heights || heights.length === 0 || heights[0].length === 0) {
        return [];
    }
    const R = heights.length;
    const C = heights[0].length;
    const pacificReachable = new Array(R).fill(0).map(() => new Array(C).fill(false));
    const atlanticReachable = new Array(R).fill(0).map(() => new Array(C).fill(false));
    const result = [];

    const dfs = (r, c, visited, prevHeight) => {
        // Check bounds, already visited, or water cannot flow uphill
        if (r < 0 || r >= R || c < 0 || c >= C || visited[r][c] || heights[r][c] < prevHeight) {
            return;
        }
        visited[r][c] = true; // Mark as reachable from this ocean

        // Explore neighbors
        dfs(r + 1, c, visited, heights[r][c]); // Down
        dfs(r - 1, c, visited, heights[r][c]); // Up
        dfs(r, c + 1, visited, heights[r][c]); // Right
        dfs(r, c - 1, visited, heights[r][c]); // Left
    };

    // Start DFS from Pacific border cells (top and left)
    for (let r = 0; r < R; r++) {
        dfs(r, 0, pacificReachable, -1); // Left border
    }
    for (let c = 0; c < C; c++) {
        dfs(0, c, pacificReachable, -1); // Top border
    }

    // Start DFS from Atlantic border cells (bottom and right)
    for (let r = 0; r < R; r++) {
        dfs(r, C - 1, atlanticReachable, -1); // Right border
    }
    for (let c = 0; c < C; c++) {
        dfs(R - 1, c, atlanticReachable, -1); // Bottom border
    }

    // Find cells reachable by both oceans
    for (let r = 0; r < R; r++) {
        for (let c = 0; c < C; c++) {
            if (pacificReachable[r][c] && atlanticReachable[r][c]) {
                result.push([r, c]);
            }
        }
    }

    return result;
};

// Example Usage:
const heights1 = [[1,2,2,3,5],[3,2,3,4,4],[2,4,5,3,1],[6,7,1,4,5],[5,1,1,2,4]];
console.log(pacificAtlantic(heights1));
// Output: [[0,4],[1,3],[1,4],[2,2],[3,0],[3,1],[3,3],[3,4],[4,0]] (order may vary)

const heights2 = [[1]];
console.log(pacificAtlantic(heights2)); // Output: [[0,0]]
`;

const pacificAtlanticSolutionCodePython = `
from typing import List, Set, Tuple

class Solution:
    """
    Finds cells reachable by both Pacific and Atlantic oceans using DFS.
    Time: O(M*N), Space: O(M*N).
    """
    def pacificAtlantic(self, heights: List[List[int]]) -> List[List[int]]:
        if not heights or not heights[0]:
            return []

        R, C = len(heights), len(heights[0])
        pacific_reachable: Set[Tuple[int, int]] = set()
        atlantic_reachable: Set[Tuple[int, int]] = set()

        def dfs(r: int, c: int, visited: Set[Tuple[int, int]], prev_height: int):
            # Check bounds, visited status, and height condition
            if (r < 0 or r >= R or c < 0 or c >= C or
                    (r, c) in visited or heights[r][c] < prev_height):
                return

            visited.add((r, c))
            current_height = heights[r][c]
            # Explore neighbors
            dfs(r + 1, c, visited, current_height)
            dfs(r - 1, c, visited, current_height)
            dfs(r, c + 1, visited, current_height)
            dfs(r, c - 1, visited, current_height)

        # Start DFS from Pacific borders (top and left)
        for r in range(R):
            dfs(r, 0, pacific_reachable, -1) # Left edge
        for c in range(C):
            dfs(0, c, pacific_reachable, -1) # Top edge

        # Start DFS from Atlantic borders (bottom and right)
        for r in range(R):
            dfs(r, C - 1, atlantic_reachable, -1) # Right edge
        for c in range(C):
            dfs(R - 1, c, atlantic_reachable, -1) # Bottom edge

        # Find intersection
        result = []
        for r in range(R):
            for c in range(C):
                if (r, c) in pacific_reachable and (r, c) in atlantic_reachable:
                    result.append([r, c])

        return result

# Example Usage:
if __name__ == "__main__":
    sol = Solution()
    heights1 = [[1,2,2,3,5],[3,2,3,4,4],[2,4,5,3,1],[6,7,1,4,5],[5,1,1,2,4]]
    print(f"pacificAtlantic(heights1) = {sol.pacificAtlantic(heights1)}")
    # Output: [[0, 4], [1, 3], [1, 4], [2, 2], [3, 0], [3, 1], [3, 3], [3, 4], [4, 0]] (order may vary)

    heights2 = [[1]]
    print(f"pacificAtlantic(heights2) = {sol.pacificAtlantic(heights2)}") # Output: [[0, 0]]
`;

const pacificAtlanticSolutionCodeJava = `
import java.util.ArrayList;
import java.util.List;
import java.util.HashSet;
import java.util.Set;

class Solution {
    private int R, C;
    private int[][] heights;
    private boolean[][] pacificReachable;
    private boolean[][] atlanticReachable;
    private int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}}; // R, L, D, U

    /**
     * Finds cells reachable by both Pacific and Atlantic oceans using DFS.
     * Time: O(M*N), Space: O(M*N).
     * @param heights The m x n grid of heights.
     * @return A list of [row, col] coordinates reachable by both oceans.
     */
    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        List<List<Integer>> result = new ArrayList<>();
        if (heights == null || heights.length == 0 || heights[0].length == 0) {
            return result;
        }

        this.R = heights.length;
        this.C = heights[0].length;
        this.heights = heights;
        this.pacificReachable = new boolean[R][C];
        this.atlanticReachable = new boolean[R][C];

        // Start DFS from Pacific borders
        for (int r = 0; r < R; r++) {
            dfs(r, 0, pacificReachable, -1); // Left
        }
        for (int c = 0; c < C; c++) {
            dfs(0, c, pacificReachable, -1); // Top
        }

        // Start DFS from Atlantic borders
        for (int r = 0; r < R; r++) {
            dfs(r, C - 1, atlanticReachable, -1); // Right
        }
        for (int c = 0; c < C; c++) {
            dfs(R - 1, c, atlanticReachable, -1); // Bottom
        }

        // Collect results
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                if (pacificReachable[r][c] && atlanticReachable[r][c]) {
                    List<Integer> cell = new ArrayList<>();
                    cell.add(r);
                    cell.add(c);
                    result.add(cell);
                }
            }
        }
        return result;
    }

    private void dfs(int r, int c, boolean[][] visited, int prevHeight) {
        // Check bounds, visited, and height condition
        if (r < 0 || r >= R || c < 0 || c >= C || visited[r][c] || heights[r][c] < prevHeight) {
            return;
        }
        visited[r][c] = true;
        int currentHeight = heights[r][c];

        // Explore neighbors
        for (int[] dir : directions) {
            dfs(r + dir[0], c + dir[1], visited, currentHeight);
        }
    }

    // Example Usage:
    public static void main(String[] args) {
        Solution sol = new Solution();
        int[][] heights1 = {{1,2,2,3,5},{3,2,3,4,4},{2,4,5,3,1},{6,7,1,4,5},{5,1,1,2,4}};
        System.out.println("pacificAtlantic(heights1) = " + sol.pacificAtlantic(heights1));
        // Output: [[0, 4], [1, 3], [1, 4], [2, 2], [3, 0], [3, 1], [3, 3], [3, 4], [4, 0]]

        int[][] heights2 = {{1}};
        System.out.println("pacificAtlantic(heights2) = " + sol.pacificAtlantic(heights2)); // Output: [[0, 0]]
    }
}
`;

const pacificAtlanticSolutionCodeCPP = `
#include <vector>
#include <set> // Can use set or boolean vector for visited
#include <iostream>

class Solution {
private:
    int R, C;
    std::vector<std::vector<int>> heights;
    std::vector<std::vector<bool>> pacificReachable;
    std::vector<std::vector<bool>> atlanticReachable;
    int dr[4] = {1, -1, 0, 0}; // Down, Up, Right, Left
    int dc[4] = {0, 0, 1, -1};

    void dfs(int r, int c, std::vector<std::vector<bool>>& visited, int prevHeight) {
        if (r < 0 || r >= R || c < 0 || c >= C || visited[r][c] || heights[r][c] < prevHeight) {
            return;
        }
        visited[r][c] = true;
        int currentHeight = heights[r][c];
        for (int i = 0; i < 4; ++i) {
            dfs(r + dr[i], c + dc[i], visited, currentHeight);
        }
    }

public:
    /**
     * Finds cells reachable by both Pacific and Atlantic oceans using DFS.
     * Time: O(M*N), Space: O(M*N).
     * @param heights_in The m x n grid of heights.
     * @return A vector of {row, col} coordinates reachable by both oceans.
     */
    std::vector<std::vector<int>> pacificAtlantic(const std::vector<std::vector<int>>& heights_in) {
        std::vector<std::vector<int>> result;
        if (heights_in.empty() || heights_in[0].empty()) {
            return result;
        }

        heights = heights_in; // Copy or store reference
        R = heights.size();
        C = heights[0].size();
        pacificReachable.assign(R, std::vector<bool>(C, false));
        atlanticReachable.assign(R, std::vector<bool>(C, false));

        // Start DFS from Pacific borders
        for (int r = 0; r < R; ++r) dfs(r, 0, pacificReachable, -1);
        for (int c = 0; c < C; ++c) dfs(0, c, pacificReachable, -1);

        // Start DFS from Atlantic borders
        for (int r = 0; r < R; ++r) dfs(r, C - 1, atlanticReachable, -1);
        for (int c = 0; c < C; ++c) dfs(R - 1, c, atlanticReachable, -1);

        // Collect results
        for (int r = 0; r < R; ++r) {
            for (int c = 0; c < C; ++c) {
                if (pacificReachable[r][c] && atlanticReachable[r][c]) {
                    result.push_back({r, c});
                }
            }
        }
        return result;
    }
};

// Example Usage (Helper to print vector of vectors):
void printResult(const std::vector<std::vector<int>>& res) {
    std::cout << "[";
    for (size_t i = 0; i < res.size(); ++i) {
        std::cout << "[" << res[i][0] << "," << res[i][1] << "]" << (i == res.size() - 1 ? "" : ",");
    }
    std::cout << "]" << std::endl;
}

int main() {
    Solution sol;
    std::vector<std::vector<int>> heights1 = {{1,2,2,3,5},{3,2,3,4,4},{2,4,5,3,1},{6,7,1,4,5},{5,1,1,2,4}};
    std::cout << "pacificAtlantic(heights1) = "; printResult(sol.pacificAtlantic(heights1));
    // Output: [[0,4],[1,3],[1,4],[2,2],[3,0],[3,1],[3,3],[3,4],[4,0]] (order may vary)

    std::vector<std::vector<int>> heights2 = {{1}};
     std::cout << "pacificAtlantic(heights2) = "; printResult(sol.pacificAtlantic(heights2)); // Output: [[0,0]]
    return 0;
}
`;
