            visited[r][c] = true; // Mark visited for this ocean's DFS run
            const currentHeight = heights[r][c];
            const stateSuffix = ocean; // 'pacific' or 'atlantic'
            const currentStateSuffix = `current-${ocean.charAt(0)}`; // 'current-p' or 'current-a'

