const combinationSum4SolutionCodeCPP = `
#include <vector>
#include <iostream>

// Helper to print vector (optional)
template<typename T>
std::ostream& operator<<(std::ostream& os, const std::vector<T>& vec) {
    os << "[";
    for (size_t i = 0; i < vec.size(); ++i) {
        os << vec[i] << (i == vec.size() - 1 ? "" : ", ");
    }
    os << "]";
    return os;
}

class Solution {
public:
    /**
     * Calculates the number of possible combinations that add up to target.
     * Uses dynamic programming.
     * @param nums Vector of distinct positive integers.
     * @param target The target sum.
     * @return The number of combinations.
     */
    int combinationSum4(const std::vector<int>& nums, int target) {
        if (target < 0) return 0;

        // dp[i] = number of combinations summing to i
        // Use unsigned int or double for dp array to avoid intermediate overflow
        // before casting back to int, as constraints guarantee final answer fits.
        std::vector<unsigned int> dp(target + 1, 0);
        dp[0] = 1; // Base case

        for (int i = 1; i <= target; ++i) {
            for (int num : nums) {
                if (i - num >= 0) {
                    // Check for potential overflow before adding
                    // if (dp[i] > UINT_MAX - dp[i - num]) {
                         // Handle overflow if needed, though constraints might prevent final overflow
                    // } else {
                         dp[i] += dp[i - num];
                    // }
                }
            }
        }

        // Final result is guaranteed to fit in a 32-bit signed integer
        return (int)dp[target];
    }
};

// Example Usage:
int main() {
    Solution sol;
    std::vector<int> nums1 = {1, 2, 3};
    int target1 = 4;
    std::cout << "combinationSum4({1, 2, 3}, 4) = " << sol.combinationSum4(nums1, target1) << std::endl; // Output: 7

    std::vector<int> nums2 = {9};
    int target2 = 3;
    std::cout << "combinationSum4({9}, 3) = " << sol.combinationSum4(nums2, target2) << std::endl; // Output: 0

    return 0;
}
`;
