const houseRobber2SolutionCodeJS = `
/**
 * Helper function for standard House Robber problem on a linear array.
 * Uses O(N) time and O(1) space.
 * @param {number[]} nums - Subarray of house values.
 * @returns {number} Max amount robbed from this subarray.
 */
const robLinear = function(nums) {
    let rob1 = 0; // Max amount robbing house i-2
    let rob2 = 0; // Max amount robbing house i-1

    // [rob1, rob2, n, n+1, ...]
    for (const n of nums) {
        // Max amount considering house n is max(rob1 + n, rob2)
        const temp = Math.max(rob1 + n, rob2);
        rob1 = rob2; // Update rob1 to previous rob2
        rob2 = temp; // Update rob2 to the new max
    }
    return rob2; // Final max amount
};

/**
 * Calculates the maximum amount robbed from non-adjacent houses arranged in a circle.
 * Uses O(N) time and O(1) space (within the helper).
 * @param {number[]} nums - Array representing money in each house.
 * @returns {number} The maximum amount that can be robbed.
 */
const rob = function(nums) {
    const n = nums.length;
    if (n === 0) return 0;
    if (n === 1) return nums[0]; // Only one house, rob it

    // Handle the circular constraint by breaking it into two linear problems:
    // 1. Rob houses from index 0 to n-2 (exclude last house)
    const max1 = robLinear(nums.slice(0, n - 1));
    // 2. Rob houses from index 1 to n-1 (exclude first house)
    const max2 = robLinear(nums.slice(1, n));

    // The result is the maximum of the two cases
    return Math.max(max1, max2);
};

// Example Usage:
console.log(rob([2, 3, 2]));       // Output: 3 (rob house at index 1)
console.log(rob([1, 2, 3, 1]));    // Output: 4 (rob 1 + 3 from second subproblem)
console.log(rob([1, 2, 1, 1]));    // Output: 3 (rob 1 + 1 from first, or 2 + 1 from second)
console.log(rob([0]));             // Output: 0
`;

const houseRobber2SolutionCodePython = `
from typing import List

class Solution:
    """ Helper for linear House Robber - O(N) time, O(1) space """
    def _rob_linear(self, nums: List[int]) -> int:
        rob1, rob2 = 0, 0
        # [rob1, rob2, n, n+1, ...]
        for n in nums:
            # Max considering house n = max(rob1 + n, rob2)
            temp = max(rob1 + n, rob2)
            rob1 = rob2
            rob2 = temp
        return rob2

    """
    Calculates max amount robbed from non-adjacent houses in a circle.
    Uses O(N) time and O(1) space (within helper).
    """
    def rob(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0
        # Handle edge case n=1 separately as slicing might yield empty lists
        if n == 1:
            return nums[0]

        # Case 1: Exclude last house (nums[0] to nums[n-2])
        max1 = self._rob_linear(nums[:-1])
        # Case 2: Exclude first house (nums[1] to nums[n-1])
        max2 = self._rob_linear(nums[1:])

        return max(max1, max2)

# Example Usage:
if __name__ == "__main__":
    sol = Solution()
    print(f"rob([2, 3, 2]) = {sol.rob([2, 3, 2])}")       # Output: 3
    print(f"rob([1, 2, 3, 1]) = {sol.rob([1, 2, 3, 1])}")    # Output: 4
    print(f"rob([1, 2, 1, 1]) = {sol.rob([1, 2, 1, 1])}")    # Output: 3
    print(f"rob([0]) = {sol.rob([0])}")             # Output: 0
`;

const houseRobber2SolutionCodeJava = `
import java.lang.Math;
import java.util.Arrays;

class Solution {
    /** Helper for linear House Robber - O(N) time, O(1) space */
    private int robLinear(int[] nums) {
        int rob1 = 0; // Max amount ending at i-2
        int rob2 = 0; // Max amount ending at i-1

        // [rob1, rob2, n, n+1, ...]
        for (int n : nums) {
            int temp = Math.max(rob1 + n, rob2);
            rob1 = rob2;
            rob2 = temp;
        }
        return rob2;
    }

    /**
     * Calculates max amount robbed from non-adjacent houses in a circle.
     * Uses O(N) time and O(1) space (within helper).
     * @param nums Array representing money in each house.
     * @return The maximum amount that can be robbed.
     */
    public int rob(int[] nums) {
        int n = nums.length;
        if (n == 0) return 0;
        if (n == 1) return nums[0];

        // Case 1: Exclude last house (0 to n-2)
        // Create subarray manually or use Arrays.copyOfRange
        int[] nums1 = Arrays.copyOfRange(nums, 0, n - 1);
        int max1 = robLinear(nums1);

        // Case 2: Exclude first house (1 to n-1)
        int[] nums2 = Arrays.copyOfRange(nums, 1, n);
        int max2 = robLinear(nums2);

        return Math.max(max1, max2);
    }

    // Example Usage:
    public static void main(String[] args) {
        Solution sol = new Solution();
        int[] nums1 = {2, 3, 2};
        System.out.println("rob([2, 3, 2]) = " + sol.rob(nums1));       // Output: 3
        int[] nums2 = {1, 2, 3, 1};
        System.out.println("rob([1, 2, 3, 1]) = " + sol.rob(nums2));    // Output: 4
        int[] nums3 = {1, 2, 1, 1};
        System.out.println("rob([1, 2, 1, 1]) = " + sol.rob(nums3));    // Output: 3
        int[] nums4 = {0};
        System.out.println("rob([0]) = " + sol.rob(nums4));             // Output: 0
    }
}
`;

const houseRobber2SolutionCodeCPP = `
#include <vector>
#include <algorithm> // For std::max
#include <iostream>

class Solution {
private:
    /** Helper for linear House Robber - O(N) time, O(1) space */
    int robLinear(const std::vector<int>& nums) {
        int rob1 = 0; // Max amount ending at i-2
        int rob2 = 0; // Max amount ending at i-1

        // [rob1, rob2, n, n+1, ...]
        for (int n : nums) {
            int temp = std::max(rob1 + n, rob2);
            rob1 = rob2;
            rob2 = temp;
        }
        return rob2;
    }

public:
    /**
     * Calculates max amount robbed from non-adjacent houses in a circle.
     * Uses O(N) time and O(1) space (within helper).
     * @param nums Vector representing money in each house.
     * @return The maximum amount that can be robbed.
     */
    int rob(const std::vector<int>& nums) {
        int n = nums.size();
        if (n == 0) return 0;
        if (n == 1) return nums[0];

        // Case 1: Exclude last house (0 to n-2)
        // Create subarray using iterators
        std::vector<int> nums1(nums.begin(), nums.end() - 1);
        int max1 = robLinear(nums1);

        // Case 2: Exclude first house (1 to n-1)
        std::vector<int> nums2(nums.begin() + 1, nums.end());
        int max2 = robLinear(nums2);

        return std::max(max1, max2);
    }
};

// Example Usage:
int main() {
    Solution sol;
    std::vector<int> nums1 = {2, 3, 2};
    std::cout << "rob({2, 3, 2}) = " << sol.rob(nums1) << std::endl;       // Output: 3
    std::vector<int> nums2 = {1, 2, 3, 1};
    std::cout << "rob({1, 2, 3, 1}) = " << sol.rob(nums2) << std::endl;    // Output: 4
    std::vector<int> nums3 = {1, 2, 1, 1};
    std::cout << "rob({1, 2, 1, 1}) = " << sol.rob(nums3) << std::endl;    // Output: 3
     std::vector<int> nums4 = {0};
    std::cout << "rob({0}) = " << sol.rob(nums4) << std::endl;             // Output: 0
    return 0;
}
`;
