                 await speak(`Sorted key is ${sortedKey}.`);
                 playSortKeySound();
                 await syncUI(i, sortedKey);

                 // Add to map
                 if (!currentAnagramMap[sortedKey]) {
                     currentAnagramMap[sortedKey] = [];
                     setMessage(`Key "${sortedKey}" not in map. Creating new group.`);
                     await speak(`Creating new group for key ${sortedKey}.`);
                 } else {
                     setMessage(`Key "${sortedKey}" found in map. Adding to existing group.`);
                     await speak(`Adding to existing group for key ${sortedKey}.`);
                 }
                 currentAnagramMap[sortedKey].push(currentStr);
                 playGroupAddSound();
