const houseRobberSolutionCodeJS = `
/**
 * Calculates the maximum amount robbed from non-adjacent houses.
 * Uses O(N) time and O(1) space dynamic programming.
 * @param {number[]} nums - Array representing money in each house.
 * @returns {number} The maximum amount that can be robbed.
 */
const rob = function(nums) {
    let rob1 = 0; // Max amount ending at house i-2
    let rob2 = 0; // Max amount ending at house i-1

    // Iterate through houses. For each house n:
    // rob1 represents max amount if we *don't* rob house n-1
    // rob2 represents max amount if we *don't* rob house n
    // The new max (rob2 for the next iteration) is either:
    // - Robbing house n: rob1 + n (since we couldn't rob n-1)
    // - Not robbing house n: rob2 (max amount up to n-1)
    // [rob1, rob2, n, n+1, ...]
    for (const n of nums) {
        const temp = Math.max(rob1 + n, rob2);
        rob1 = rob2; // Update rob1 (max up to i-2 for next iter)
        rob2 = temp; // Update rob2 (max up to i-1 for next iter)
    }
    // After the loop, rob2 holds the max amount for the whole array
    return rob2;
};

// Example Usage:
console.log(rob([1, 2, 3, 1]));    // Output: 4 (1 + 3)
console.log(rob([2, 7, 9, 3, 1])); // Output: 12 (2 + 9 + 1)
console.log(rob([2, 1, 1, 2]));    // Output: 4 (2 + 2)
`;

const houseRobberSolutionCodePython = `
from typing import List

class Solution:
    """
    Calculates max amount robbed from non-adjacent houses.
    Uses O(N) time and O(1) space DP.
    """
    def rob(self, nums: List[int]) -> int:
        # rob1: max money that can be robbed ending at house i-2
        # rob2: max money that can be robbed ending at house i-1
        rob1, rob2 = 0, 0

        # Iterate through the houses
        # For house n at index i:
        # temp = max amount ending at house i
        #      = max(rob house i (rob1 + n), don't rob house i (rob2))
        # [rob1, rob2, n, n+1, ...]
        for n in nums:
            temp = max(rob1 + n, rob2)
            rob1 = rob2  # Update rob1 for the next iteration (becomes previous rob2)
            rob2 = temp  # Update rob2 for the next iteration (becomes current max)

        # rob2 holds the final maximum amount
        return rob2

# Example Usage:
if __name__ == "__main__":
    sol = Solution()
    print(f"rob([1, 2, 3, 1]) = {sol.rob([1, 2, 3, 1])}")    # Output: 4
    print(f"rob([2, 7, 9, 3, 1]) = {sol.rob([2, 7, 9, 3, 1])}") # Output: 12
    print(f"rob([2, 1, 1, 2]) = {sol.rob([2, 1, 1, 2])}")    # Output: 4
`;

const houseRobberSolutionCodeJava = `
import java.lang.Math;

class Solution {
    /**
     * Calculates max amount robbed from non-adjacent houses.
     * Uses O(N) time and O(1) space DP.
     * @param nums Array representing money in each house.
     * @return The maximum amount that can be robbed.
     */
    public int rob(int[] nums) {
        int rob1 = 0; // Max amount ending two steps back
        int rob2 = 0; // Max amount ending one step back

        // [rob1, rob2, n, n+1, ...]
        for (int n : nums) {
            // Max amount including house n is rob1 + n
            // Max amount excluding house n is rob2
            int temp = Math.max(rob1 + n, rob2);
            rob1 = rob2; // Update rob1 for next step
            rob2 = temp; // Update rob2 for next step
        }
        // rob2 holds the overall maximum after iterating through all houses
        return rob2;
    }

    // Example Usage:
    public static void main(String[] args) {
        Solution sol = new Solution();
        int[] nums1 = {1, 2, 3, 1};
        System.out.println("rob([1, 2, 3, 1]) = " + sol.rob(nums1));    // Output: 4
        int[] nums2 = {2, 7, 9, 3, 1};
        System.out.println("rob([2, 7, 9, 3, 1]) = " + sol.rob(nums2)); // Output: 12
        int[] nums3 = {2, 1, 1, 2};
        System.out.println("rob([2, 1, 1, 2]) = " + sol.rob(nums3));    // Output: 4
    }
}
`;

const houseRobberSolutionCodeCPP = `
#include <vector>
#include <algorithm> // For std::max
#include <iostream>

class Solution {
public:
    /**
     * Calculates max amount robbed from non-adjacent houses.
     * Uses O(N) time and O(1) space DP.
     * @param nums Vector representing money in each house.
     * @return The maximum amount that can be robbed.
     */
    int rob(const std::vector<int>& nums) {
        int rob1 = 0; // Max amount ending at i-2
        int rob2 = 0; // Max amount ending at i-1

        // [rob1, rob2, n, n+1, ...]
        for (int n : nums) {
            // Max amount considering house n = max(rob1 + n, rob2)
            int temp = std::max(rob1 + n, rob2);
            rob1 = rob2; // Update rob1 for the next iteration
            rob2 = temp; // Update rob2 for the next iteration
        }
        // rob2 contains the final max amount
        return rob2;
    }
};

// Example Usage:
int main() {
    Solution sol;
    std::vector<int> nums1 = {1, 2, 3, 1};
    std::cout << "rob({1, 2, 3, 1}) = " << sol.rob(nums1) << std::endl;    // Output: 4
    std::vector<int> nums2 = {2, 7, 9, 3, 1};
    std::cout << "rob({2, 7, 9, 3, 1}) = " << sol.rob(nums2) << std::endl; // Output: 12
    std::vector<int> nums3 = {2, 1, 1, 2};
    std::cout << "rob({2, 1, 1, 2}) = " << sol.rob(nums3) << std::endl;    // Output: 4
    return 0;
}
`;
