const coinChangeSolutionCodeJS = `
/**
 * Finds the fewest number of coins needed to make up a given amount.
 * If the amount cannot be made up, returns -1.
 * Uses dynamic programming.
 * @param {number[]} coins - An array of coin denominations.
 * @param {number} amount - The target amount.
 * @returns {number} The fewest number of coins, or -1 if impossible.
 */
const coinChange = function(coins, amount) {
    if (amount < 0) return -1;
    if (amount === 0) return 0;

    // dp[i] = fewest coins to make amount i
    // Initialize with a value larger than any possible result (e.g., amount + 1)
    const dp = new Array(amount + 1).fill(amount + 1);
    dp[0] = 0; // Base case: 0 coins to make amount 0

    // Iterate through amounts from 1 to amount
    for (let i = 1; i <= amount; i++) {
        // Iterate through each coin denomination
        for (const coin of coins) {
            if (i - coin >= 0) {
                // If we can use this coin, check if it leads to a better solution
                dp[i] = Math.min(dp[i], dp[i - coin] + 1);
            }
        }
    }

    // If dp[amount] is still the initial large value, it means it's impossible
    return dp[amount] > amount ? -1 : dp[amount];
};

// Example Usage:
const coins1 = [1, 2, 5];
const amount1 = 11;
console.log(\`Coins: \${coins1}, Amount: \${amount1}, Fewest Coins: \${coinChange(coins1, amount1)}\`); // Output: 3 (5 + 5 + 1)

const coins2 = [2];
const amount2 = 3;
console.log(\`Coins: \${coins2}, Amount: \${amount2}, Fewest Coins: \${coinChange(coins2, amount2)}\`); // Output: -1
`;

const coinChangeSolutionCodePython = `
from typing import List
import math

class Solution:
    """
    Finds the fewest number of coins needed to make up a given amount.
    Uses dynamic programming.
    """
    def coinChange(self, coins: List[int], amount: int) -> int:
        """
        Args:
            coins: A list of coin denominations.
            amount: The target amount.

        Returns:
            The fewest number of coins, or -1 if impossible.
        """
        if amount < 0:
            return -1
        if amount == 0:
            return 0

        # dp[i] = fewest coins for amount i
        # Initialize with infinity (or amount + 1 as a large enough number)
        dp = [float('inf')] * (amount + 1)
        dp[0] = 0 # Base case

        for i in range(1, amount + 1):
            for coin in coins:
                if i - coin >= 0:
                    # Check if using this coin gives a better result
                    # Ensure dp[i-coin] is reachable (not infinity)
                    if dp[i - coin] != float('inf'):
                         dp[i] = min(dp[i], dp[i - coin] + 1)

        return dp[amount] if dp[amount] != float('inf') else -1

# Example Usage:
if __name__ == "__main__":
    sol = Solution()
    coins1 = [1, 2, 5]
    amount1 = 11
    print(f"Coins: {coins1}, Amount: {amount1}, Fewest Coins: {sol.coinChange(coins1, amount1)}") # Output: 3

    coins2 = [2]
    amount2 = 3
    print(f"Coins: {coins2}, Amount: {amount2}, Fewest Coins: {sol.coinChange(coins2, amount2)}") # Output: -1
`;

const coinChangeSolutionCodeJava = `
import java.util.Arrays;

class Solution {
    /**
     * Finds the fewest number of coins needed to make up a given amount.
     * Uses dynamic programming.
     * @param coins An array of coin denominations.
     * @param amount The target amount.
     * @return The fewest number of coins, or -1 if impossible.
     */
    public int coinChange(int[] coins, int amount) {
        if (amount < 0) return -1;
        if (amount == 0) return 0;

        // dp[i] = fewest coins for amount i
        // Initialize with amount + 1 (a value larger than any possible answer)
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, amount + 1);
        dp[0] = 0; // Base case

        for (int i = 1; i <= amount; i++) {
            for (int coin : coins) {
                if (i - coin >= 0) {
                    // Check if dp[i - coin] is reachable
                    if (dp[i - coin] != amount + 1) {
                         dp[i] = Math.min(dp[i], dp[i - coin] + 1);
                    }
                }
            }
        }

        return dp[amount] > amount ? -1 : dp[amount];
    }

    // Example Usage:
    public static void main(String[] args) {
        Solution sol = new Solution();
        int[] coins1 = {1, 2, 5};
        int amount1 = 11;
        System.out.println("Coins: " + Arrays.toString(coins1) + ", Amount: " + amount1 +
                           ", Fewest Coins: " + sol.coinChange(coins1, amount1)); // Output: 3

        int[] coins2 = {2};
        int amount2 = 3;
        System.out.println("Coins: " + Arrays.toString(coins2) + ", Amount: " + amount2 +
                           ", Fewest Coins: " + sol.coinChange(coins2, amount2)); // Output: -1
    }
}
`;

const coinChangeSolutionCodeCPP = `
#include <vector>
#include <algorithm> // For std::min
#include <iostream>

// Helper to print vector (optional)
template<typename T>
std::ostream& operator<<(std::ostream& os, const std::vector<T>& vec) {
    os << "[";
    for (size_t i = 0; i < vec.size(); ++i) {
        os << vec[i] << (i == vec.size() - 1 ? "" : ", ");
    }
    os << "]";
    return os;
}


class Solution {
public:
    /**
     * Finds the fewest number of coins needed to make up a given amount.
     * Uses dynamic programming.
     * @param coins A vector of coin denominations.
     * @param amount The target amount.
     * @return The fewest number of coins, or -1 if impossible.
     */
    int coinChange(const std::vector<int>& coins, int amount) {
        if (amount < 0) return -1;
        if (amount == 0) return 0;

        // dp[i] = fewest coins for amount i
        // Initialize with amount + 1 (a value larger than any possible answer)
        // Using vector<int> instead of vector<long long> as result fits in int
        std::vector<int> dp(amount + 1, amount + 1);
        dp[0] = 0; // Base case

        for (int i = 1; i <= amount; ++i) {
            for (int coin : coins) {
                if (i - coin >= 0) {
                    // Check if dp[i - coin] is reachable (not amount + 1)
                    if (dp[i - coin] != amount + 1) {
                        dp[i] = std::min(dp[i], dp[i - coin] + 1);
                    }
                }
            }
        }

        return dp[amount] > amount ? -1 : dp[amount];
    }
};

// Example Usage:
int main() {
    Solution sol;
    std::vector<int> coins1 = {1, 2, 5};
    int amount1 = 11;
    std::cout << "Coins: " << coins1 << ", Amount: " << amount1
              << ", Fewest Coins: " << sol.coinChange(coins1, amount1) << std::endl; // Output: 3

    std::vector<int> coins2 = {2};
    int amount2 = 3;
     std::cout << "Coins: " << coins2 << ", Amount: " << amount2
              << ", Fewest Coins: " << sol.coinChange(coins2, amount2) << std::endl; // Output: -1

    return 0;
}
`;
