import React from 'react';
import { Box, Card, CardContent, Typography, Chip, Paper } from '@mui/material'; // Added Paper
import { useTheme } from '@mui/material/styles'; // To access theme for conditional styling

// Base component structure for visualizations using MUI
const BaseVisualizer = ({ children, problemSummary, controls, displayArea, message, result }) => {
    const theme = useTheme(); // Access the current theme

    // Determine a subtle background color based on the theme mode for certain sections
    // This provides a slight distinction from the main paper background without being too stark.
    const subtleBgColor = theme.palette.mode === 'light' ? theme.palette.grey[50] : theme.palette.grey[800]; // Darker grey for dark mode
    // Alternatively, for even more integration with paper, you could use:
    // const subtleBgColor = theme.palette.mode === 'light' ? theme.palette.grey[50] : theme.palette.action.hover;


    return (
        <Box sx={{ p: { xs: 1, sm: 2 } }}> {/* Main padding for the whole visualizer */}

            {/* Problem Summary Card: Uses the theme's paper background by default */}
            {problemSummary && (
                <Card variant="outlined" sx={{ mb: 2 /*, bgcolor: 'background.paper' // Default for Card */ }}>
                    <CardContent>
                        {problemSummary}
                    </CardContent>
                </Card>
            )}

            {/* Controls Card: Uses the theme's paper background by default */}
            {controls && (
                <Card variant="outlined" sx={{ mb: 2 }}>
                    <CardContent>
                        {controls}
                    </CardContent>
                </Card>
            )}

            {/* Display Area Card */}
            <Card variant="outlined" sx={{ mb: 2, minHeight: 200, display: 'flex', flexDirection: 'column' }}>
                <CardContent sx={{
                    flexGrow: 1,
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    justifyContent: 'center',
                    p: { xs: 1, sm: 2 }
                }}>
                    {displayArea}
                </CardContent>

                {/* Footer for Message and Result */}
                {(message || result !== undefined) && (
                    <Box sx={{
                        borderTop: 1,
                        borderColor: 'divider',
                        p: 2,
                        mt: 'auto', // Pushes to the bottom of the card
                        textAlign: 'center',
                        bgcolor: subtleBgColor, // Use theme-aware subtle background
                    }}>
       
<amp-ad width="100vw" height="320"
     type="adsense"
     data-ad-client="ca-pub-6960770161475250"
     data-ad-slot="5404827739"
     data-auto-format="rspv"
     data-full-width="">
  <div overflow=""></div>
</amp-ad>
                        {/* Display Message */}
                        {message && (
                            <Typography
                                variant="body2"
                                color="text.secondary"
                                sx={{ minHeight: '1.5rem', mb: result !== undefined && result !== null ? 1 : 0 }}
                            >
                                {message}
                            </Typography>
                        )}

                        {/* Display Result */}
                        {result !== undefined && result !== null && (
                            // Check if result is a string and matches specific patterns for Chip styling
                            typeof result === 'string' && (
                                result.toLowerCase().startsWith('result: true') ||
                                result.toLowerCase().startsWith('result: false') ||
                                result.toLowerCase().includes('found') || // More generic "found"
                                result.toLowerCase().includes('not found')
                            ) ? (
                                <Chip
                                    label={result}
                                    color={
                                        result.toLowerCase().includes('true') || result.toLowerCase().includes('target found') ? 'success' :
                                        (result.toLowerCase().includes('false') || result.toLowerCase().includes('not found') ? 'error' : 'default')
                                    }
                                    size="medium"
                                    sx={{ fontWeight: 500 }} // Ensure chip text is readable
                                />
                            ) : (
                                // Display other results as H6 or another appropriate variant
                                <Typography variant="h6" component="div" color="text.primary">
                                    {typeof result === 'object' ? JSON.stringify(result) : result.toString()}
                                </Typography>
                            )
                        )}
                    </Box>
                )}
            </Card>

            {/* Children prop can be used for additional custom sections if needed */}
            {children}
        </Box>
    );
};

export default BaseVisualizer;
