import React, { useState } from 'react';
import { Box, Button, Accordion, AccordionSummary, AccordionDetails, Typography, useTheme, Tooltip, Fade } from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';

/**
 * A component to display a collapsible section with solution code and a copy button.
 * @param {object} props - Component props
 * @param {string} props.codeString - The solution code to display.
 * @param {string} [props.title="Solution Code"] - The title for the accordion header.
 */
const SolutionCodeDisplay = ({ codeString, title = "Solution Code" }) => {
    // Access the MUI theme for consistent styling
    const theme = useTheme();
    // State to manage the visibility of the "Copied!" tooltip
    const [copySuccess, setCopySuccess] = useState(false);

    /**
     * Handles copying the code string to the clipboard using the Clipboard API.
     * Shows a "Copied!" tooltip on success.
     */
    const handleCopy = async () => {
        try {
            // Use the Clipboard API to write the code string
            await navigator.clipboard.writeText(codeString);
            // Show success tooltip
            setCopySuccess(true);
            // Hide tooltip after 2 seconds
            setTimeout(() => setCopySuccess(false), 2000);
        } catch (err) {
            console.error('Failed to copy code: ', err);
            // Optionally, implement user feedback for copy failure
        }
    };

    // Define theme-aware styles
    const accordionSummaryBgColor = theme.palette.mode === 'light' ? theme.palette.grey[100] : theme.palette.grey[800];
    const codeBlockBgColor = theme.palette.mode === 'light' ? theme.palette.grey[50] : '#282c34'; // Keep existing dark for dark mode
    const codeBlockColor = theme.palette.mode === 'light' ? theme.palette.text.primary : '#abb2bf'; // Keep existing light text for dark mode

    return (
        // Accordion component to make the code block collapsible
        <Accordion sx={{
            mt: 2, // Margin top
            boxShadow: 'none', // Remove default shadow for a flatter look
            border: `1px solid ${theme.palette.divider}`, // Use theme's divider color
            '&:before': { display: 'none' } // Remove MUI's default top border line on Accordion
        }}>
            {/* Header of the Accordion */}
            <AccordionSummary
                expandIcon={<ExpandMoreIcon sx={{ color: theme.palette.text.secondary }} />} // Themed icon color
                aria-controls="solution-content" // Accessibility control
                id="solution-header" // Accessibility ID
                sx={{
                    bgcolor: accordionSummaryBgColor, // Theme-aware background
                    minHeight: '48px', // Ensure consistent height
                    '& .MuiAccordionSummary-content': { // Target content for margin
                        margin: '12px 0',
                    }
                }}
            >
                <Typography variant="subtitle1" sx={{ fontWeight: 500, color: theme.palette.text.primary }}>{title}</Typography>
            </AccordionSummary>
            {/* Content of the Accordion (Code block and button) */}
            <AccordionDetails sx={{ p: 0, position: 'relative', bgcolor: codeBlockBgColor /* Apply base bg for details */ }}>
                {/* Tooltip to show "Copied!" message */}
                <Tooltip
                    title="Copied!"
                    open={copySuccess}
                    disableFocusListener // Don't show on focus
                    disableHoverListener // Don't show on hover
                    disableTouchListener // Don't show on touch
                    placement="top" // Position tooltip above the button
                    arrow // Add arrow to tooltip
                    TransitionComponent={Fade} // Use fade transition
                >
                    {/* Copy Button */}
                    <Button
                        size="small"
                        variant="outlined"
                        startIcon={<ContentCopyIcon fontSize="inherit" />} // Copy icon
                        onClick={handleCopy}
                        sx={{
                            position: 'absolute', // Position absolutely within AccordionDetails
                            top: theme.spacing(1), // Spacing from top using theme
                            right: theme.spacing(1), // Spacing from right using theme
                            zIndex: 1, // Ensure button is above the code block
                            textTransform: 'none', // Prevent uppercase text
                            fontSize: '0.75rem', // Smaller font size
                            // Theme-aware button styling
                            borderColor: theme.palette.divider,
                            color: theme.palette.text.secondary,
                            bgcolor: theme.palette.background.paper, // Use paper background for button
                            '&:hover': {
                                bgcolor: theme.palette.action.hover, // Standard MUI hover effect
                                borderColor: theme.palette.action.active, // Slightly darker border on hover
                            }
                        }}
                    >
                        Copy
                    </Button>
                </Tooltip>
                {/* Code Block */}
                <Box
                    component="pre" // Use <pre> for preformatted text
                    sx={{
                        bgcolor: codeBlockBgColor, // Theme-aware background
                        color: codeBlockColor,     // Theme-aware text color
                        p: theme.spacing(2),       // Padding inside the block using theme
                        pt: theme.spacing(5),      // Extra padding top to avoid overlap with the copy button
                        m: 0,                      // Remove default margin from <pre>
                        borderRadius: '0 0 4px 4px', // Round bottom corners to match Accordion
                        overflowX: 'auto',         // Allow horizontal scrolling for long lines
                        fontSize: '0.8rem',        // Slightly smaller font size for code
                        fontFamily: 'monospace',   // Use a monospace font
                        whiteSpace: 'pre-wrap',    // Wrap long lines
                        wordBreak: 'break-all',    // Break long words/identifiers
                    }}
                >
                    <code> {/* Use <code> for semantic correctness */}
                        {codeString}
                    </code>
                </Box>
            </AccordionDetails>
        </Accordion>
    );
};

export default SolutionCodeDisplay;
