const listNodeDefinitionJS = `
/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 * this.val = (val===undefined ? 0 : val)
 * this.next = (next===undefined ? null : next)
 * }
 */`;

// --- Solution Code Strings ---
const solutionCodeJS = `
${listNodeDefinitionJS}
/**
 * Merges two sorted linked lists into one sorted linked list.
 * Time: O(N + M), Space: O(1) (iterative, modifies pointers) or O(N+M) for new list creation if required.
 * @param {ListNode} list1 The head of the first sorted list.
 * @param {ListNode} list2 The head of the second sorted list.
 * @return {ListNode} The head of the merged sorted linked list.
 */
const mergeTwoLists = function(list1, list2) {
    // Create a dummy node to serve as the start of the merged list
    const dummy = new ListNode(-1);
    let current = dummy; // Pointer to the last node in the merged list

    while (list1 !== null && list2 !== null) {
        if (list1.val <= list2.val) {
            current.next = list1; // Link the smaller node
            list1 = list1.next;   // Move the pointer of list1 forward
        } else {
            current.next = list2; // Link the smaller node
            list2 = list2.next;   // Move the pointer of list2 forward
        }
        current = current.next; // Move the current pointer of the merged list forward
    }

    // If one list is exhausted, append the remainder of the other list
    if (list1 !== null) {
        current.next = list1;
    } else {
        current.next = list2;
    }

    return dummy.next; // The merged list starts after the dummy node
};
`;
