// --- Component ---
const MergeTwoSortedListsVisualizer = () => {
    // --- State Variables ---
    const [list1Input, setList1Input] = useState("[1,2,4]");
    const [list2Input, setList2Input] = useState("[1,3,4]");

    // Node structure: { id: string (e.g., 'l1-0', 'l2-1'), value: number, nextId: string | null, state: 'default' | 'processing' | 'merged' }
    const [list1Nodes, setList1Nodes] = useState([]);
    const [list2Nodes, setList2Nodes] = useState([]);
    const [mergedNodes, setMergedNodes] = useState([]); // Stores the structure being built
    // Pointer structure: { l1: string | null, l2: string | null, currentMerged: string | null } (values are node ids)
    const [pointers, setPointers] = useState({ l1: null, l2: null, currentMerged: null });
    const DUMMY_ID = 'dummy-head'; // Special ID for the dummy node

    // Standard State
    const [message, setMessage] = useState(`Enter two sorted lists (e.g., [1,2,4] and [1,3,4]).`);
    const [errorMessage, setErrorMessage] = useState("");
    const [isRunning, setIsRunning] = useState(false);
    const [finalResult, setFinalResult] = useState(null); // Stores the final merged list structure (array of values)
    const stopRef = useRef(false);
    const [isAudioEnabled, setIsAudioEnabled] = useState(true);
    const [isSpeechEnabled, setIsSpeechEnabled] = useState(true);

    // --- Audio/Speech API Setup (Standard Boilerplate) ---
    const audioContextRef = useRef(null);
    const initAudioContext = useCallback(() => { /* ... (standard code) ... */ if (!isAudioEnabled) return; if (audioContextRef.current === null && typeof window !== 'undefined' && (window.AudioContext || window.webkitAudioContext)) { try { audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { console.error("Web Audio API not supported.", e); setIsAudioEnabled(false); setMessage("Audio tones disabled: Not supported."); } } if (audioContextRef.current && audioContextRef.current.state === 'suspended') { audioContextRef.current.resume().catch(e => console.error("Audio resume failed", e)); } }, [isAudioEnabled]);
    const playTone = useCallback((frequency = 440, duration = 0.1, type = 'sine', volume = 0.3) => { /* ... (standard code) ... */ if (!isAudioEnabled || !audioContextRef.current || audioContextRef.current.state !== 'running') return; try { const oscillator = audioContextRef.current.createOscillator(); const gainNode = audioContextRef.current.createGain(); oscillator.type = type; oscillator.frequency.setValueAtTime(frequency, audioContextRef.current.currentTime); gainNode.gain.setValueAtTime(volume, audioContextRef.current.currentTime); gainNode.gain.exponentialRampToValueAtTime(0.0001, audioContextRef.current.currentTime + duration); oscillator.connect(gainNode); gainNode.connect(audioContextRef.current.destination); oscillator.start(audioContextRef.current.currentTime); oscillator.stop(audioContextRef.current.currentTime + duration); } catch (e) { console.error("Error playing tone:", e); } }, [isAudioEnabled]);
    const playCompareSound = useCallback(() => playTone(500, 0.07, 'square', 0.18), [playTone]);
    const playLinkSound = useCallback(() => playTone(750, 0.1, 'sine', 0.2), [playTone]);
    const playAdvancePointerSound = useCallback(() => playTone(600, 0.08, 'triangle', 0.15), [playTone]);
    const playAppendRestSound = useCallback(() => playTone(850, 0.12, 'sawtooth', 0.22), [playTone]);
    const playStartSound = useCallback(() => playTone(440, 0.1, 'sine', 0.3), [playTone]);
    const playEndSound = useCallback(() => playTone(1100, 0.2, 'sine', 0.3), [playTone]);
    const playStopSound = useCallback(() => playTone(220, 0.15, 'square', 0.3), [playTone]);
    const playErrorSound = useCallback(() => playTone(150, 0.3, 'sawtooth', 0.3), [playTone]);
    const speak = useCallback((text) => { /* ... (standard code) ... */ return new Promise((resolve) => { if (!isSpeechEnabled || typeof window === 'undefined' || !window.speechSynthesis) { resolve(); return; } try { window.speechSynthesis.cancel(); const utterance = new SpeechSynthesisUtterance(text); utterance.lang = 'en-US'; utterance.rate = 1.1; utterance.pitch = 1.0; utterance.volume = 0.8; utterance.onend = () => resolve(); utterance.onerror = (event) => { console.error("Speech synthesis error:", event.error); resolve(); }; window.speechSynthesis.speak(utterance); } catch (e) { console.error("Error initiating speech synthesis:", e); resolve(); } }); }, [isSpeechEnabled]);
    const cancelSpeech = useCallback(() => { /* ... (standard code) ... */ if (typeof window !== 'undefined' && window.speechSynthesis) { window.speechSynthesis.cancel(); } }, []);

    // --- Input Parsing and Validation ---
    const parseList = (input, listPrefix) => {
        const rawInput = JSON.parse(input.trim());
        if (!Array.isArray(rawInput)) {
            throw new Error(`Input for ${listPrefix} must be an array (e.g., [1,2,4]).`);
        }
        if (!rawInput.every(n => typeof n === 'number' || typeof n === 'string')) {
            throw new Error(`List ${listPrefix} array must contain numbers or strings.`);
        }
        // Check if sorted (optional but good practice)
        for (let i = 0; i < rawInput.length - 1; i++) {
            if (rawInput[i] > rawInput[i+1]) {
                 throw new Error(`List ${listPrefix} must be sorted.`);
            }
        }

        return rawInput.map((value, index) => ({
            id: `${listPrefix}-${index}`, // Unique ID like 'l1-0', 'l2-1'
            value: value,
            nextId: index < rawInput.length - 1 ? `${listPrefix}-${index + 1}` : null,
            state: 'default',
        }));
    }

    const parseAndValidateInput = useCallback(() => {
        setMessage("");
        setErrorMessage("");
        try {
            const nodes1 = parseList(list1Input, 'l1');
            const nodes2 = parseList(list2Input, 'l2');

            setList1Nodes(nodes1);
            setList2Nodes(nodes2);

            // Initialize merged list with dummy node
            const dummyNode = { id: DUMMY_ID, value: 'D', nextId: null, state: 'default' };
            setMergedNodes([dummyNode]);

            // Initialize pointers
            setPointers({
                l1: nodes1.length > 0 ? nodes1[0].id : null,
                l2: nodes2.length > 0 ? nodes2[0].id : null,
                currentMerged: DUMMY_ID,
            });
            setFinalResult(null);

            return { head1Id: nodes1.length > 0 ? nodes1[0].id : null, head2Id: nodes2.length > 0 ? nodes2[0].id : null };

        } catch (e) {
            console.error("Input Parsing Error:", e);
            const errorMsg = `Input Error: ${e.message || "Invalid format."}`;
            setErrorMessage(errorMsg);
            setMessage(errorMsg);
            setList1Nodes([]);
            setList2Nodes([]);
            setMergedNodes([]);
            setPointers({ l1: null, l2: null, currentMerged: null });
            playErrorSound();
            return null; // Indicate failure
        }
    }, [list1Input, list2Input, playErrorSound]);

    // --- Reset Function ---
    const reset = useCallback((isInitial = false) => {
        stopRef.current = true;
        cancelSpeech();
        setIsRunning(false);
        setFinalResult(null);
        setMessage("");
        setErrorMessage("");

        const parseResult = parseAndValidateInput();

        if (parseResult === null && !isInitial) {
            // Error handled
        } else if (parseResult !== null) {
            setMessage(isInitial ? `Enter two sorted lists.` : "Ready. Click Run.");
        } else {
             setMessage(`Enter two sorted lists. Check format.`);
            setList1Nodes([]);
            setList2Nodes([]);
            setMergedNodes([]);
             setPointers({ l1: null, l2: null, currentMerged: null });
        }
    }, [parseAndValidateInput, cancelSpeech]);

    // --- Effects ---
    useEffect(() => { reset(true); return () => { stopRef.current = true; cancelSpeech(); if (audioContextRef.current) { audioContextRef.current.close().catch(e => console.error("Error closing AudioContext:", e)); audioContextRef.current = null; } }; /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, []);
    useEffect(() => { const handler = setTimeout(() => { if (!isRunning) { reset(true); } }, 500); return () => clearTimeout(handler); }, [list1Input, list2Input, reset, isRunning]);


    // --- Visualization Logic ---
    const runVisualization = async () => {
        initAudioContext();
        cancelSpeech();
        reset(false);
        await sleep(50);

        if (errorMessage) { setIsRunning(false); return; }

        const parseResult = parseAndValidateInput(); // Re-parse to get initial state
        if (!parseResult) { setIsRunning(false); return; }

        stopRef.current = false;
        setIsRunning(true);
        setFinalResult(null);
        playStartSound();
        await speak(`Starting Merge Two Sorted Lists visualization.`);
        if (stopRef.current) { setIsRunning(false); return; }

        // --- Algorithm State ---
        let currentL1Nodes = JSON.parse(JSON.stringify(list1Nodes));
        let currentL2Nodes = JSON.parse(JSON.stringify(list2Nodes));
        let currentMerged = JSON.parse(JSON.stringify(mergedNodes)); // Starts with dummy
        let currentPointers = { ...pointers }; // Starts with heads and dummy

        // --- Helper ---
        const syncUI = async (delay = 800) => {
            // Update states from current working copies
            setList1Nodes([...currentL1Nodes]);
            setList2Nodes([...currentL2Nodes]);
            setMergedNodes([...currentMerged]);
            setPointers({ ...currentPointers });
            await sleep(delay);
            if (stopRef.current) throw new Error("Stopped");
        };

        const getNode = (id) => {
             if (!id) return null;
             if (id === DUMMY_ID) return currentMerged.find(n => n.id === DUMMY_ID);
             const prefix = id.split('-')[0];
             const list = prefix === 'l1' ? currentL1Nodes : currentL2Nodes;
             return list.find(n => n.id === id);
        }

         const updateNodeState = (id, newState) => {
            const node = getNode(id);
            if (node) node.state = newState;
        };

        const linkMerged = (targetNodeId) => {
             const currentMergedNode = getNode(currentPointers.currentMerged);
             if (currentMergedNode) {
                 currentMergedNode.nextId = targetNodeId;
                 updateNodeState(targetNodeId, 'merged'); // Mark node in original list as merged
             }
             // Add the node to the merged list display (or update if already there)
             const targetNode = getNode(targetNodeId);
             if (targetNode) {
                 const existingIndex = currentMerged.findIndex(n => n.id === targetNodeId);
                 const nodeToAdd = { ...targetNode, nextId: null }; // Reset nextId for merged display
                 if (existingIndex === -1) {
                    currentMerged.push(nodeToAdd);
                 } else {
                    currentMerged[existingIndex] = nodeToAdd; // Update if somehow added before linking
                 }
             }
        }

        // --- Main Loop ---
        try {
            setMessage("Initializing dummy node and pointers.");
            await syncUI(1000);

            while (currentPointers.l1 !== null && currentPointers.l2 !== null) {
                const node1 = getNode(currentPointers.l1);
                const node2 = getNode(currentPointers.l2);
                if (!node1 || !node2) break; // Safety check

                 updateNodeState(currentPointers.l1, 'processing');
                 updateNodeState(currentPointers.l2, 'processing');
                 setMessage(`Comparing List1 (${node1.value}) and List2 (${node2.value}).`);
                 await speak(`Comparing ${node1.value} and ${node2.value}.`);
                 playCompareSound();
                 await syncUI(900);

                if (node1.value <= node2.value) {
                    setMessage(`List1 (${node1.value}) <= List2 (${node2.value}). Linking List1 node.`);
                    await speak(`Linking node ${node1.value} from list 1.`);
                    linkMerged(currentPointers.l1);
                    playLinkSound();
                    await syncUI();

                    // Advance currentMerged pointer
                    currentPointers.currentMerged = currentPointers.l1;

                     // Advance l1 pointer
                    const nextL1Id = node1.nextId;
                    setMessage(`Advancing List1 pointer to next (ID: ${nextL1Id ?? 'null'}).`);
                    await speak(`Advance list 1 pointer.`);
                    currentPointers.l1 = nextL1Id;
                    playAdvancePointerSound();
                    await syncUI();

                } else {
                     setMessage(`List2 (${node2.value}) < List1 (${node1.value}). Linking List2 node.`);
                     await speak(`Linking node ${node2.value} from list 2.`);
                     linkMerged(currentPointers.l2);
                     playLinkSound();
                     await syncUI();

                     // Advance currentMerged pointer
                     currentPointers.currentMerged = currentPointers.l2;

                     // Advance l2 pointer
                     const nextL2Id = node2.nextId;
                     setMessage(`Advancing List2 pointer to next (ID: ${nextL2Id ?? 'null'}).`);
                     await speak(`Advance list 2 pointer.`);
                     currentPointers.l2 = nextL2Id;
                     playAdvancePointerSound();
                     await syncUI();
                }
                 // Reset processing states
                 updateNodeState(node1.id, node1.state === 'processing' ? 'default' : node1.state); // Keep 'merged' state
                 updateNodeState(node2.id, node2.state === 'processing' ? 'default' : node2.state);

                 if (stopRef.current) break;
            } // End while loop

            if (stopRef.current) throw new Error("Stopped");

            // Append remaining list
            const remainingListId = currentPointers.l1 !== null ? currentPointers.l1 : currentPointers.l2;
            const remainingListName = currentPointers.l1 !== null ? 'List1' : 'List2';

            if (remainingListId !== null) {
                 setMessage(`Appending remaining nodes from ${remainingListName}.`);
                 await speak(`Appending remaining nodes from ${remainingListName}.`);
                 const currentMergedNode = getNode(currentPointers.currentMerged);
                 if (currentMergedNode) {
                     currentMergedNode.nextId = remainingListId; // Link the rest
                 }
                 playAppendRestSound();

                 // Add remaining nodes to merged display and mark as merged in original
                  let tempPtr = remainingListId;
                  while(tempPtr !== null) {
                      const node = getNode(tempPtr);
                      if (!node) break;
                      const existingIndex = currentMerged.findIndex(n => n.id === tempPtr);
                      const nodeToAdd = { ...node, nextId: null }; // Reset next for display
                      if (existingIndex === -1) currentMerged.push(nodeToAdd);
                      else currentMerged[existingIndex] = nodeToAdd;
                      updateNodeState(tempPtr, 'merged');
                      tempPtr = node.nextId;
                      if (stopRef.current) throw new Error("Stopped");
                  }
                 await syncUI(1000);
            } else {
                 setMessage("Both lists exhausted.");
                 await speak("Both lists exhausted.");
                 await syncUI(500);
            }


            // --- Final State ---
             if (stopRef.current) {
                setMessage("Visualization stopped by user.");
                speak("Visualization stopped.");
                playStopSound();
            } else {
                // Extract final list values from mergedNodes, skipping dummy
                const finalValues = [];
                let currentId = currentMerged.find(n => n.id === DUMMY_ID)?.nextId;
                const visited = new Set(); // Prevent infinite loops in case of error
                while(currentId !== null && !visited.has(currentId)) {
                    visited.add(currentId);
                    const node = currentMerged.find(n => n.id === currentId); // Find in the built merged list
                    if (node) {
                        finalValues.push(node.value);
                        currentId = getNode(currentId)?.nextId; // Get next from the *original* node structure link
                    } else {
                         currentId = null; // Should not happen
                    }
                }

                setMessage(`Finished Merging. Final list created.`);
                await speak(`Finished merging.`);
                playEndSound();
                setFinalResult(finalValues);
                // Final UI sync to show completed state
                 setPointers({ l1: null, l2: null, currentMerged: null }); // Clear pointers
                 // Ensure all nodes in merged list have 'merged' state visually
                 currentMerged.forEach(node => { if(node.id !== DUMMY_ID) node.state = 'merged'});
                 // Also ensure remaining nodes in original lists are marked merged
                 currentL1Nodes.forEach(node => { if(node.state === 'default') node.state = 'merged'});
                 currentL2Nodes.forEach(node => { if(node.state === 'default') node.state = 'merged'});

                await syncUI(100);
            }

        } catch (error) {
            if (error.message === "Stopped") {
                setMessage("Visualization stopped by user.");
                playStopSound();
            } else {
                console.error("Visualization error:", error);
                setErrorMessage("An unexpected error occurred during visualization.");
                setMessage("An unexpected error occurred.");
                playErrorSound();
            }
        } finally {
            setIsRunning(false);
            stopRef.current = false;
        }
    };

    // --- Control Functions (Standard Boilerplate) ---
     const stopVisualization = () => { stopRef.current = true; cancelSpeech(); setMessage("Stopping visualization..."); };
     const toggleAudio = () => { const newState = !isAudioEnabled; setIsAudioEnabled(newState); if (newState) { initAudioContext(); setTimeout(() => playTone(500, 0.05, 'sine', 0.2), 50); } else { playTone(300, 0.05, 'square', 0.2); if (audioContextRef.current && audioContextRef.current.state === 'running') { audioContextRef.current.suspend().catch(e => console.error("Audio context suspend failed", e)); } } };
     const toggleSpeech = () => { const newState = !isSpeechEnabled; if (newState && (typeof window === 'undefined' || !window.speechSynthesis)) { const msg = "Speech synthesis not supported by your browser."; setErrorMessage(msg); setMessage(msg); setTimeout(() => { if (errorMessage === msg) { setErrorMessage(""); setMessage(""); } }, 3000); return; } setIsSpeechEnabled(newState); if (!newState) { cancelSpeech(); } else { speak("Speech enabled."); } };

    // --- Render ---
    const formattedResult = finalResult !== null ? `Result: ${JSON.stringify(finalResult)}` : null;

    // --- Helper for Node Appearance ---
    const getNodeAppearance = (state) => {
        switch (state) {
            case 'processing': return { bgcolor: 'info.light', color: 'info.contrastText', border: '2px solid', borderColor: 'info.dark' };
            case 'merged': return { bgcolor: 'success.light', color: 'success.contrastText', border: '1px solid', borderColor: 'success.dark' };
            default: return { bgcolor: 'grey.100', color: 'text.secondary', border: '1px solid', borderColor: 'grey.300' };
        }
    };

    // --- Helper to render a list ---
    const renderList = (nodesToRender, listIdPrefix, pointerId, pointerIcon, pointerColor) => (
         <Paper variant="outlined" sx={{ p: 1.5, mb: 1, display: 'flex', flexWrap: 'wrap', gap: '15px', alignItems: 'center', minHeight: '60px' }}>
            {nodesToRender.length > 0 ? nodesToRender.map((node, index) => {
                const appearance = getNodeAppearance(node.state);
                const isPointer = node.id === pointerId;
                return (
                    <React.Fragment key={node.id}>
                        <Tooltip title={`ID: ${node.id}, Value: ${node.value}, Next ID: ${node.nextId ?? 'null'}`}>
                             <Chip
                                icon={isPointer ? pointerIcon : null}
                                label={String(node.value)}
                                size="medium"
                                sx={{
                                    ...appearance,
                                    minWidth: 45,
                                    fontWeight: isPointer ? 'bold' : 'normal',
                                    transform: isPointer ? 'scale(1.1)' : 'scale(1.0)',
                                    boxShadow: isPointer ? 3 : 1,
                                    transition: 'all 0.3s ease',
                                    zIndex: 1,
                                }}
                                color={isPointer ? pointerColor : "default"}
                                variant={isPointer ? "filled" : "outlined"}
                            />
                        </Tooltip>
                        {node.nextId !== null && (
                             <ArrowForwardIcon sx={{ color: 'action.disabled', mx: -1 }} />
                        )}
                        {node.nextId === null && index === nodesToRender.length - 1 && (
                            <Typography variant="caption" sx={{ ml: 1, color: 'text.secondary' }}>null</Typography>
                        )}
                    </React.Fragment>
                );
            }) : (
                 <Typography variant="caption" color="text.secondary" align="center" sx={{width: '100%'}}>{errorMessage ? "Invalid Input" : "List is empty..."}</Typography>
            )}
        </Paper>
    );


    return (
        <>
            <BaseVisualizer
                problemSummary={
                    <>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                            <Typography variant="h4" component="h1">{`#${LEETCODE_NUMBER}. ${PROBLEM_TITLE}`}</Typography>
                            <Chip label={PROBLEM_DIFFICULTY} color={DIFFICULTY_COLOR} size="small" variant="filled" />
                        </Box>
                        <Typography variant="body1" component="div" sx={{ mb: 2 }}>
                           You are given the heads of two sorted linked lists <code>list1</code> and <code>list2</code>.
                           <br/><br/>
                           Merge the two lists into one <strong>sorted</strong> list. The list should be made by splicing together the nodes of the first two lists.
                           <br/><br/>
                           Return the head of the merged linked list.
                           <br/><br/>
                           {/* Including ListNode definition for context */}
                           <Typography variant="caption" component="pre" sx={{ bgcolor: 'action.hover', p: 1, borderRadius: 1, display: 'block' }}>
                               <code>{listNodeDefinitionJS}</code>
                           </Typography>
                        </Typography>
                        <Typography variant="h6" component="h3" sx={{ mt: 2, mb: 1 }}>Example:</Typography>
                        <Box sx={{ bgcolor: 'action.hover', p: 1.5, borderRadius: 1, fontFamily: 'monospace', mb: 2, fontSize: '0.875rem' }}>
                            <strong>Input:</strong> list1 = [1,2,4], list2 = [1,3,4]<br/>
                            <strong>Output:</strong> [1,1,2,3,4,4]
                            <br/><br/>
                            <strong>Input:</strong> list1 = [], list2 = []<br/>
                            <strong>Output:</strong> []
                             <br/><br/>
                             <strong>Input:</strong> list1 = [], list2 = [0]<br/>
                            <strong>Output:</strong> [0]
                        </Box>
                        <Typography variant="h6" component="h3" sx={{ mt: 2, mb: 1 }}>Constraints:</Typography>
                        <Box component="ul" sx={{ pl: 2, mb: 2 }}>
                             <li>The number of nodes in both lists is in the range <code>[0, 50]</code>.</li>
                             <li><code>-100 &lt;= Node.val &lt;= 100</code></li>
                             <li>Both <code>list1</code> and <code>list2</code> are sorted in <strong>non-decreasing</strong> order.</li>
                        </Box>
                         <Divider sx={{ my: 3 }} />
                        <Typography variant="h6" sx={{ mb: 1 }}>Runnable Solution Code Examples (Iterative)</Typography>
                        <Typography variant="subtitle2" sx={{ mb: 0.5 }}>JavaScript:</Typography><SolutionCodeDisplay codeString={solutionCodeJS} language="javascript" />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>Python:</Typography><SolutionCodeDisplay codeString={solutionCodePython} language="python" />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>Java:</Typography><SolutionCodeDisplay codeString={solutionCodeJava} language="java" />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>C++:</Typography><SolutionCodeDisplay codeString={solutionCodeCPP} language="cpp" />
                        <Divider sx={{ my: 3 }} />
                        <Typography variant="subtitle1" gutterBottom>Algorithm Analysis (Iterative)</Typography>
                        <Typography variant="body2" color="text.secondary"><strong>Time Complexity:</strong> <code>O(N + M)</code> - Where N and M are the lengths of list1 and list2. We iterate through each node once.</Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}><strong>Space Complexity:</strong> <code>O(1)</code> - We only use a few extra pointers and modify the existing lists' pointers.</Typography>
                    </>
                }
                controls={
                    <>
                         <Typography variant="subtitle1" sx={{ textAlign: 'center', fontWeight: 'bold', p: 0.75, mb: 2.5, borderRadius: '4px', color: 'common.white', background: 'linear-gradient(45deg, #03A9F4 30%, #4FC3F7 90%)', boxShadow: 1 }}> {/* Example Styling */}
                             {PROBLEM_TITLE} Visualizer Controls
                         </Typography>
                         <MuiGrid container spacing={1.5} alignItems="flex-start" mb={2}>
                            {/* Input Fields */}
                            <MuiGrid item xs={12} md={6}>
                                <TextField
                                    fullWidth
                                    id="list1-input"
                                    label="List 1 Values (e.g., [1,2,4])"
                                    variant="outlined"
                                    size="small"
                                    value={list1Input}
                                    onChange={(e) => setList1Input(e.target.value)}
                                    placeholder="[1,2,4]"
                                    disabled={isRunning}
                                    error={!!errorMessage && errorMessage.includes("List l1")}
                                    InputProps={{ sx: { fontFamily: 'monospace' } }}
                                />
                            </MuiGrid>
                             <MuiGrid item xs={12} md={6}>
                                <TextField
                                    fullWidth
                                    id="list2-input"
                                    label="List 2 Values (e.g., [1,3,4])"
                                    variant="outlined"
                                    size="small"
                                    value={list2Input}
                                    onChange={(e) => setList2Input(e.target.value)}
                                    placeholder="[1,3,4]"
                                    disabled={isRunning}
                                    error={!!errorMessage && errorMessage.includes("List l2")}
                                    InputProps={{ sx: { fontFamily: 'monospace' } }}
                                />
                            </MuiGrid>
                             {/* Control Buttons */}
                             <MuiGrid item xs={12} container spacing={1} alignItems="center" justifyContent="center" mt={1}>
                                 <MuiGrid item xs={4} sm={3} md={2} sx={{ display: 'flex' }}> <Tooltip title={isRunning ? "Stop Visualization" : "Run Visualization"}><span><Button fullWidth variant="contained" sx={{ height: '40px' }} startIcon={isRunning && !stopRef.current ? <CircularProgress size={20} color="inherit" /> : <PlayArrowIcon />} onClick={isRunning ? stopVisualization : runVisualization} color={isRunning ? "warning" : "primary"} disabled={isRunning && stopRef.current}>{isRunning && !stopRef.current ? 'Running' : (isRunning && stopRef.current ? 'Stopping' : 'Run')}</Button></span></Tooltip> </MuiGrid>
                                 <MuiGrid item xs={4} sm={3} md={2} sx={{ display: 'flex' }}> <Tooltip title="Reset Visualization and Input"><span><Button fullWidth variant="outlined" startIcon={<ReplayIcon />} onClick={() => reset(false)} disabled={isRunning} sx={{ height: '40px' }}>Reset</Button></span></Tooltip> </MuiGrid>
                                 <MuiGrid item xs={2} sm={1.5} md={1} sx={{ display: 'flex' }}> <Tooltip title={isAudioEnabled ? "Mute Tones" : "Unmute Tones"}><Button fullWidth variant="outlined" onClick={toggleAudio} sx={{ height: '40px', minWidth: 'auto', p: 1 }}>{isAudioEnabled ? <VolumeUpIcon /> : <VolumeOffIcon />}</Button></Tooltip> </MuiGrid>
                                 <MuiGrid item xs={2} sm={1.5} md={1} sx={{ display: 'flex' }}> <Tooltip title={isSpeechEnabled ? "Disable Speech" : "Enable Speech"}><Button fullWidth variant="outlined" onClick={toggleSpeech} sx={{ height: '40px', minWidth: 'auto', p: 1 }}>{isSpeechEnabled ? <RecordVoiceOverIcon /> : <VoiceOverOffIcon />}</Button></Tooltip> </MuiGrid>
                             </MuiGrid>
                         </MuiGrid>
                    </>
                }
                displayArea={
                    <>
                        <Typography variant="subtitle1" gutterBottom align="center">{PROBLEM_TITLE} Visualization</Typography>

                         {/* Input Lists */}
                         <Typography variant="overline" display="block">List 1:</Typography>
                         {renderList(list1Nodes, 'l1', pointers.l1, <AccountTreeIcon fontSize="small"/>, 'primary')}

                          <Typography variant="overline" display="block" sx={{mt: 2}}>List 2:</Typography>
                         {renderList(list2Nodes, 'l2', pointers.l2, <AccountTreeIcon fontSize="small"/>, 'secondary')}


                         {/* Merged List */}
                         <Divider sx={{my: 3}}/>
                         <Typography variant="overline" display="block">Merged List:</Typography>
                         <Paper variant="outlined" sx={{ p: 1.5, mb: 1, display: 'flex', flexWrap: 'wrap', gap: '15px', alignItems: 'center', minHeight: '60px', bgcolor: 'action.selected' }}>
                             {mergedNodes.length > 0 ? mergedNodes.map((node, index) => {
                                 const isPointer = node.id === pointers.currentMerged;
                                 // Skip rendering the dummy node value, but show it if it's the current pointer
                                 const displayValue = node.id === DUMMY_ID ? 'Dummy' : String(node.value);
                                 const isDummy = node.id === DUMMY_ID;

                                 return (
                                     <React.Fragment key={node.id}>
                                         <Tooltip title={`ID: ${node.id}, Value: ${node.value}, Next ID: ${node.nextId ?? 'null'}`}>
                                              <Chip
                                                 icon={isPointer ? <PlaylistAddIcon fontSize="small"/> : null}
                                                 label={displayValue}
                                                 size="medium"
                                                 sx={{
                                                     // Special style for dummy
                                                     ...(isDummy && { bgcolor: 'grey.300', fontStyle: 'italic'}),
                                                     // Standard styles
                                                     ...(!isDummy && getNodeAppearance(node.state)), // Apply merged style
                                                     minWidth: 45,
                                                     fontWeight: isPointer ? 'bold' : 'normal',
                                                     transform: isPointer ? 'scale(1.1)' : 'scale(1.0)',
                                                     boxShadow: isPointer ? 3 : 1,
                                                     transition: 'all 0.3s ease',
                                                     zIndex: 1,
                                                 }}
                                                 color={isPointer ? "success" : "default"}
                                                 variant={isPointer ? "filled" : "outlined"}
                                             />
                                         </Tooltip>
                                         {node.nextId !== null && (
                                              <ArrowForwardIcon sx={{ color: 'action.active', mx: -1 }} />
                                         )}
                                         {node.nextId === null && index === mergedNodes.length - 1 && !isDummy && (
                                             <Typography variant="caption" sx={{ ml: 1, color: 'text.secondary' }}>null</Typography>
                                         )}
                                     </React.Fragment>
                                 );
                             }) : (
                                  <Typography variant="caption" color="text.secondary" align="center" sx={{width: '100%'}}>Merged list appears here...</Typography>
                             )}
                         </Paper>

                         {/* Final Result Display */}
                         {finalResult !== null && (
                             <Box sx={{ display: 'flex', justifyContent: 'center', mt: 2 }}>
                                 <TextField
                                     label="Final Merged List (Values)"
                                     value={JSON.stringify(finalResult)}
                                     multiline
                                     fullWidth
                                     InputProps={{ readOnly: true, sx: { fontFamily: 'monospace' } }}
                                     variant="filled"
                                     color="success"
                                     focused
                                 />
                             </Box>
                         )}
                    </>
                }
                message={message}
                result={null} // Don't use BaseVisualizer result, show in displayArea
            />
            {/* Online Compiler Section */}
            <Container maxWidth="xl" sx={{ mt: 4, mb: 4 }}>
                 <Typography variant="h5" component="h2" gutterBottom>Test with Online Compiler</Typography>
                 <OnlineCompiler />
            </Container>
        </>
    );
};

export default MergeTwoSortedListsVisualizer;
