const solutionCodeJava = `
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;

class Solution {
    /**
     * Merges overlapping intervals in a list.
     * Time: O(N log N), Space: O(N).
     * @param intervals List of intervals.
     * @return List of merged intervals.
     */
    public int[][] merge(int[][] intervals) {
        if (intervals == null || intervals.length == 0) {
            return new int[0][];
        }

        // 1. Sort by start time
        Arrays.sort(intervals, Comparator.comparingInt(a -> a[0]));
        // Or: Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));


        List<int[]> merged = new ArrayList<>();
        merged.add(intervals[0]);

        // 2. Iterate and merge
        for (int i = 1; i < intervals.length; i++) {
            int[] currentInterval = intervals[i];
            int[] lastMerged = merged.get(merged.size() - 1);

            // Check for overlap
            if (currentInterval[0] <= lastMerged[1]) {
                // Merge: update end of last merged interval
                lastMerged[1] = Math.max(lastMerged[1], currentInterval[1]);
            } else {
                // No overlap: add current interval
                merged.add(currentInterval);
            }
        }

        return merged.toArray(new int[merged.size()][]);
    }
}
`;
const solutionCodeCPP = `
#include <vector>
#include <algorithm> // For std::sort, std::min, std::max

using namespace std;

class Solution {
public:
    /**
     * Merges overlapping intervals in a list.
     * Time: O(N log N), Space: O(N).
     * @param intervals List of intervals.
     * @return List of merged intervals.
     */
    vector<vector<int>> merge(vector<vector<int>>& intervals) {
        if (intervals.empty()) {
            return {};
        }

        // 1. Sort by start time
        sort(intervals.begin(), intervals.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[0] < b[0];
        });

        vector<vector<int>> merged;
        merged.push_back(intervals[0]);

        // 2. Iterate and merge
        for (int i = 1; i < intervals.size(); ++i) {
            vector<int>& currentInterval = intervals[i];
            vector<int>& lastMerged = merged.back(); // Reference to the last element

            // Check for overlap
            if (currentInterval[0] <= lastMerged[1]) {
                // Merge: update end of last merged interval
                lastMerged[1] = max(lastMerged[1], currentInterval[1]);
            } else {
                // No overlap: add current interval
                merged.push_back(currentInterval);
            }
        }

        return merged;
    }
};
`;

