                setMessage(`Finished Reordering List.`);
                await speak(`Finished reordering.`);
                playEndSound();
                setFinalResult(finalValues);
                // Final UI sync
                 setPointers({ slow: null, fast: null, prev: null, current: null, first: null, second: null }); // Clear pointers
                 currentNodes.forEach(node => node.state = 'merged'); // Mark all as merged
                await syncUI(3, 100);
