const solutionCodeJS = `
/**
 * Determines if the input string containing just '(', ')', '{', '}', '[' and ']' is valid.
 * An input string is valid if:
 * 1. Open brackets must be closed by the same type of brackets.
 * 2. Open brackets must be closed in the correct order.
 * 3. Every close bracket has a corresponding open bracket of the same type.
 * Uses a stack.
 * Time: O(N), Space: O(N) in worst case (all opening brackets).
 * @param {string} s The input string.
 * @return {boolean} True if the string is valid, false otherwise.
 */
const isValid = function(s) {
    const stack = [];
    const map = {
        ')': '(',
        '}': '{',
        ']': '['
    };

    for (let i = 0; i < s.length; i++) {
        const char = s[i];

        if (char === '(' || char === '{' || char === '[') {
            // If it's an opening bracket, push onto the stack
            stack.push(char);
        } else if (char === ')' || char === '}' || char === ']') {
            // If it's a closing bracket
            if (stack.length === 0) {
                // Stack is empty, no matching opening bracket
                return false;
            }
            // Pop the top element and check if it matches the current closing bracket
            const lastOpen = stack.pop();
            if (map[char] !== lastOpen) {
                // Mismatched brackets
                return false;
            }
        }
        // Ignore any other characters if the problem allowed them
    }

    // If the stack is empty at the end, all brackets were matched correctly
    return stack.length === 0;
};
`;
