const solutionCodeJava = `
import java.util.Stack;
import java.util.HashMap;
import java.util.Map;

class Solution {
    /**
     * Determines if the input string containing just '(', ')', '{', '}', '[' and ']' is valid.
     * Time: O(N), Space: O(N).
     * @param s The input string.
     * @return True if the string is valid, false otherwise.
     */
    public boolean isValid(String s) {
        Stack<Character> stack = new Stack<>();
        Map<Character, Character> map = new HashMap<>();
        map.put(')', '(');
        map.put('}', '{');
        map.put(']', '[');

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);

            if (map.containsValue(c)) { // It's an opening bracket
                stack.push(c);
            } else if (map.containsKey(c)) { // It's a closing bracket
                if (stack.isEmpty()) {
                    return false; // No matching opening bracket
                }
                char topElement = stack.pop();
                if (map.get(c) != topElement) {
                    return false; // Mismatched brackets
                }
            }
            // Ignore other characters if necessary
        }

        // Stack must be empty at the end for a valid string
        return stack.isEmpty();
    }
}
`;
const solutionCodeCPP = `
#include <string>
#include <stack>
#include <unordered_map>

using namespace std;

class Solution {
public:
    /**
     * Determines if the input string containing just '(', ')', '{', '}', '[' and ']' is valid.
     * Time: O(N), Space: O(N).
     * @param s The input string.
     * @return True if the string is valid, false otherwise.
     */
    bool isValid(string s) {
        stack<char> charStack;
        unordered_map<char, char> map = {
            {')', '('},
            {'}', '{'},
            {']', '['}
        };

        for (char c : s) {
            if (c == '(' || c == '{' || c == '[') {
                // Opening bracket, push onto stack
                charStack.push(c);
            } else if (c == ')' || c == '}' || c == ']') {
                // Closing bracket
                if (charStack.empty()) {
                    return false; // No matching open bracket
                }
                char topElement = charStack.top();
                charStack.pop();
                if (map[c] != topElement) {
                    return false; // Mismatched brackets
                }
            }
            // Ignore other chars if needed
        }

        // Stack must be empty for valid string
        return charStack.empty();
    }
};
`;

