// --- Min-Heap Implementation (Simple for Visualization) ---
// Note: A production-ready heap would be more robust.
class MinHeap {
    constructor(capacity) {
        this.heap = []; // Stores [value, frequency] pairs
        this.capacity = capacity;
    }

    // Basic comparison function (min-heap based on frequency)
    compare(a, b) {
        return a[1] - b[1]; // Compare frequencies
    }

    // Add element, maintaining heap property and capacity
    add(element) { // element is [value, frequency]
        this.heap.push(element);
        this.heap.sort(this.compare); // Simple sort for visualization (inefficient for real heap)
        if (this.heap.length > this.capacity) {
            this.heap.shift(); // Remove the smallest frequency element
        }
    }

    // Get the heap elements (sorted by frequency for this simple version)
    getElements() {
        // For visualization, return sorted. Real heap extract would be different.
        return this.heap.sort(this.compare);
    }

     // Get just the values from the heap
     getValues() {
        return this.heap.map(item => item[0]);
    }
}


// --- Array Parsing Function (Reuse) ---
const parseArrayString = (str, arrayName) => {
    str = str.trim();
    if (str.startsWith('[') && str.endsWith(']')) { str = str.substring(1, str.length - 1); }
    if (!str) return [];
    const parts = str.split(',').map(v => v.trim());
    const numbers = parts.map(part => { const num = parseInt(part, 10); if (isNaN(num)) { throw new Error(`Invalid non-numeric value '${part}' found in ${arrayName} input.`); } return num; });
    return numbers;
};

