const solutionCodePython = `
import collections
import heapq
from typing import List

class Solution:
    """
    Finds the k most frequent elements using HashMap and Min-Heap.
    Time: O(N log K), Space: O(N + K).
    """
    def topKFrequent(self, nums: List[int], k: int) -> List[int]:
        # 1. Count frequencies
        # Use collections.Counter for convenience
        if not nums:
            return []
        count = collections.Counter(nums)

        # 2. Use a min-heap of size k
        # Python's heapq implements a min-heap. We store (frequency, value) tuples.
        min_heap = []
        for value, frequency in count.items():
            heapq.heappush(min_heap, (frequency, value))
            # If heap size exceeds k, pop the smallest frequency element
            if len(min_heap) > k:
                heapq.heappop(min_heap)

        # 3. Extract the values (which are the second element of the tuples)
        # The heap now contains the k elements with the highest frequencies.
        result = [value for frequency, value in min_heap]
        return result

    """
    Alternative using Bucket Sort (potentially O(N) on average)
    Time: O(N), Space: O(N)
    """
    def topKFrequentBucketSort(self, nums: List[int], k: int) -> List[int]:
        count = collections.Counter(nums)
        # Bucket index is frequency, value is list of numbers with that frequency
        # Size needs to be len(nums) + 1 because frequency can go up to N
        buckets = [[] for _ in range(len(nums) + 1)]

        for num, freq in count.items():
            buckets[freq].append(num)

        result = []
        # Iterate buckets from highest frequency down
        for i in range(len(buckets) - 1, 0, -1):
            if buckets[i]:
                result.extend(buckets[i])
            if len(result) >= k:
                break # Found enough elements

        return result[:k] # Return only the top k

`;
const solutionCodeJava = `
import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.List;
import java.util.ArrayList;

class Solution {
    /**
     * Finds the k most frequent elements using HashMap and Min-Heap.
     * Time: O(N log K), Space: O(N + K).
     * @param nums Input array.
     * @param k Number of elements to return.
     * @return Array containing the k most frequent elements.
     */
    public int[] topKFrequent(int[] nums, int k) {
        // 1. Count frequencies
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : nums) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }

        // 2. Use a Min-Heap (PriorityQueue) of size k
        // The heap stores Map.Entry objects, comparing them by frequency (value).
        PriorityQueue<Map.Entry<Integer, Integer>> minHeap =
            new PriorityQueue<>(k, (a, b) -> a.getValue() - b.getValue()); // Min-heap based on frequency

        for (Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {
            minHeap.offer(entry);
            // If heap size exceeds k, remove the element with the smallest frequency
            if (minHeap.size() > k) {
                minHeap.poll();
            }
        }

        // 3. Extract the values (keys) from the heap
        int[] result = new int[k];
        int i = 0;
        while (!minHeap.isEmpty()) {
            result[i++] = minHeap.poll().getKey();
        }

        // The result array might be in ascending order of frequency,
        // the problem doesn't specify order, so this is fine.
        // If specific order needed, reverse or store differently.
        return result;
    }
}
`;
const solutionCodeCPP = `
#include <vector>
#include <unordered_map>
#include <queue> // For priority_queue
#include <map> // Can also use map if needed

class Solution {
public:
    /**
     * Finds the k most frequent elements using HashMap and Min-Heap.
     * Time: O(N log K), Space: O(N + K).
     */
    std::vector<int> topKFrequent(std::vector<int>& nums, int k) {
        // 1. Count frequencies
        std::unordered_map<int, int> freqMap;
        for (int num : nums) {
            freqMap[num]++;
        }

        // 2. Use a Min-Heap (priority_queue) of size k
        // Store pairs of {frequency, value}. Use std::greater for min-heap.
        using Pair = std::pair<int, int>;
        std::priority_queue<Pair, std::vector<Pair>, std::greater<Pair>> minHeap;

        for (auto const& [value, frequency] : freqMap) {
            minHeap.push({frequency, value});
            // If heap size exceeds k, pop the smallest frequency element
            if (minHeap.size() > k) {
                minHeap.pop();
            }
        }

        // 3. Extract the values from the heap
        std::vector<int> result;
        result.reserve(k); // Reserve space
        while (!minHeap.empty()) {
            result.push_back(minHeap.top().second); // Get the value (second element)
            minHeap.pop();
        }

        // Result will be in arbitrary order (or reverse freq order depending on extraction)
        // Reverse if needed, but problem doesn't require specific order.
        // std::reverse(result.begin(), result.end());
        return result;
    }
};
`;

