    const audioContextRef = useRef(null);
    const initAudioContext = useCallback(() => { /* ... (Template standard) ... */ if (!isAudioEnabled) return; if (audioContextRef.current === null && typeof window !== 'undefined' && (window.AudioContext || window.webkitAudioContext)) { try { audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { console.error("Web Audio API not supported.", e); setIsAudioEnabled(false); setMessage("Audio tones disabled: Not supported."); } } if (audioContextRef.current && audioContextRef.current.state === 'suspended') { audioContextRef.current.resume().catch(e => console.error("Audio resume failed", e)); } }, [isAudioEnabled]);
