const lisSolutionCodeJava = `
import java.util.Arrays;

class Solution {
    /**
     * Finds the length of the longest increasing subsequence using O(N^2) DP.
     * @param nums The input array of integers.
     * @return The length of the longest increasing subsequence.
     */
    public int lengthOfLIS(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0;
        }

        int n = nums.length;
        // dp[i] = length of LIS ending at index i
        int[] dp = new int[n];
        Arrays.fill(dp, 1); // Each element itself is an LIS of length 1
        int maxLength = 1;

        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (nums[i] > nums[j]) {
                    dp[i] = Math.max(dp[i], dp[j] + 1);
                }
            }
            maxLength = Math.max(maxLength, dp[i]);
        }

        return maxLength;
    }

    // Example Usage:
    public static void main(String[] args) {
        Solution sol = new Solution();
        int[] nums1 = {10, 9, 2, 5, 3, 7, 101, 18};
        System.out.println("Input: " + Arrays.toString(nums1) +
                           ", LIS Length: " + sol.lengthOfLIS(nums1)); // Output: 4

        int[] nums2 = {0, 1, 0, 3, 2, 3};
        System.out.println("Input: " + Arrays.toString(nums2) +
                           ", LIS Length: " + sol.lengthOfLIS(nums2)); // Output: 4

        int[] nums3 = {7, 7, 7, 7, 7, 7, 7};
        System.out.println("Input: " + Arrays.toString(nums3) +
                           ", LIS Length: " + sol.lengthOfLIS(nums3)); // Output: 1
    }
}
`;

const lisSolutionCodeCPP = `
#include <vector>
#include <algorithm> // For std::max
#include <iostream>

// Helper to print vector (optional)
template<typename T>
std::ostream& operator<<(std::ostream& os, const std::vector<T>& vec) {
    os << "[";
    for (size_t i = 0; i < vec.size(); ++i) {
        os << vec[i] << (i == vec.size() - 1 ? "" : ", ");
    }
    os << "]";
    return os;
}

class Solution {
public:
    /**
     * Finds the length of the longest increasing subsequence using O(N^2) DP.
     * @param nums The input vector of integers.
     * @return The length of the longest increasing subsequence.
     */
    int lengthOfLIS(const std::vector<int>& nums) {
        if (nums.empty()) {
            return 0;
        }

        int n = nums.size();
        // dp[i] = length of LIS ending at index i
        std::vector<int> dp(n, 1); // Initialize all LIS lengths to 1
        int maxLength = 1;

        for (int i = 1; i < n; ++i) {
            for (int j = 0; j < i; ++j) {
                if (nums[i] > nums[j]) {
                    dp[i] = std::max(dp[i], dp[j] + 1);
                }
            }
            maxLength = std::max(maxLength, dp[i]);
        }

        return maxLength;
    }
};

// Example Usage:
int main() {
    Solution sol;
    std::vector<int> nums1 = {10, 9, 2, 5, 3, 7, 101, 18};
    std::cout << "Input: " << nums1 << ", LIS Length: " << sol.lengthOfLIS(nums1) << std::endl; // Output: 4

    std::vector<int> nums2 = {0, 1, 0, 3, 2, 3};
    std::cout << "Input: " << nums2 << ", LIS Length: " << sol.lengthOfLIS(nums2) << std::endl; // Output: 4

    std::vector<int> nums3 = {7, 7, 7, 7, 7, 7, 7};
    std::cout << "Input: " << nums3 << ", LIS Length: " << sol.lengthOfLIS(nums3) << std::endl; // Output: 1

    return 0;
}
`;
