// --- Tree Node Class (Helper - Can be shared or redefined) ---
class TreeNode {
    constructor(val, left = null, right = null) {
        this.val = val;
        this.left = left;
        this.right = right;
        this.id = Math.random().toString(36).substring(2, 15); // Unique ID for visualization
        this.x = 0;
        this.y = 0;
        this.parentId = null;
    }
}

// --- Tree Parsing Function (Assume exists or copy from MaxDepth) ---
const parseTreeString = (str) => {
    str = str.trim();
    if (!str.startsWith('[') || !str.endsWith(']')) {
        throw new Error("Invalid input format. Must be like '[1,2,null,3]'.");
    }
    str = str.substring(1, str.length - 1);
    if (!str) return null;
    const values = str.split(',').map(v => v.trim());
    if (values.length === 0 || values[0] === 'null') return null;

    const root = new TreeNode(parseInt(values[0], 10));
    const queue = [root];
    let i = 1;
    while (queue.length > 0 && i < values.length) {
        const currentNode = queue.shift();
        if (i < values.length) {
            if (values[i] !== 'null') {
                const leftVal = parseInt(values[i], 10);
                currentNode.left = new TreeNode(leftVal);
                currentNode.left.parentId = currentNode.id;
                queue.push(currentNode.left);
            }
            i++;
        }
        if (i < values.length) {
            if (values[i] !== 'null') {
                const rightVal = parseInt(values[i], 10);
                currentNode.right = new TreeNode(rightVal);
                currentNode.right.parentId = currentNode.id;
                queue.push(currentNode.right);
            }
            i++;
        }
    }
    return root;
};


// --- Function to calculate node positions (Assume exists or copy from MaxDepth) ---
// Returns { nodes, nodeMap, height }
const calculateNodePositions = (root) => {
    if (!root) return { nodes: [], nodeMap: {}, height: 0 };
    const nodes = [];
    const nodeMap = {};
    let maxLevel = 0;
    const traverse = (node, level, index, parentX, parentY) => {
        if (!node) return;
        maxLevel = Math.max(maxLevel, level);
        node.y = level * 80;
        const horizontalSpread = 150 / (level + 1);
        if (parentX === null) {
            node.x = 0;
        } else {
            const parentNode = nodeMap[node.parentId]; // Need nodeMap populated during traversal
             if (!parentNode) { // Should not happen if called correctly
                 node.x = 0;
             } else {
                 const isLeftChild = parentNode.left?.id === node.id;
                 node.x = parentX + (isLeftChild ? -horizontalSpread : horizontalSpread);
             }
        }
        nodes.push(node);
        nodeMap[node.id] = node; // Add to map *before* traversing children
        traverse(node.left, level + 1, index * 2, node.x, node.y);
        traverse(node.right, level + 1, index * 2 + 1, node.x, node.y);
    };

    traverse(root, 0, 0, null, null);

     // Center the tree horizontally
     if (nodes.length > 0) {
        let minX = Infinity, maxX = -Infinity;
        nodes.forEach(n => { minX = Math.min(minX, n.x); maxX = Math.max(maxX, n.x); });
        const width = maxX - minX;
        const offsetX = -minX - (width / 2);
        nodes.forEach(n => { n.x += offsetX; });
    }

    return { nodes, nodeMap, height: (maxLevel + 1) * 80 };
};


// --- Solution Code Strings ---
const solutionCodeJS = `
/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 * this.val = (val===undefined ? 0 : val)
 * this.left = (left===undefined ? null : left)
 * this.right = (right===undefined ? null : right)
 * }
 */
/**
 * Checks if two binary trees are structurally identical and have the same node values.
 * Uses recursion (DFS).
 * Time: O(min(N, M)), where N and M are the number of nodes in tree p and q.
 * We traverse both trees concurrently, stopping at the first difference or null node.
 * Space: O(min(H_p, H_q)) avg (recursion stack), O(min(N, M)) worst case (skewed trees).
 * @param {TreeNode} p The root of the first tree.
 * @param {TreeNode} q The root of the second tree.
 * @return {boolean} True if the trees are the same, false otherwise.
 */
const isSameTree = function(p, q) {
    // Base case 1: Both nodes are null, they are the same.
    if (!p && !q) {
        return true;
    }
    // Base case 2: One node is null, but the other isn't, they are different.
    if (!p || !q) {
        return false;
    }
    // Base case 3: Node values are different, they are different.
    if (p.val !== q.val) {
        return false;
    }

    // Recursively check left and right subtrees.
    // Both must be the same for the current nodes to be considered the same.
    return isSameTree(p.left, q.left) && isSameTree(p.right, q.right);
};
`;
