             // Backtrack visually after successful left comparison
             setCurrentNodeIdP(nodeP.id);
             setCurrentNodeIdQ(nodeQ.id);
             setComparisonStatus('value_match'); // Back to parent match state
             setMessage(`Left subtrees match. Comparing right children of P=${nodeP.val}, Q=${nodeQ.val}.`);
