// --- Solution Code Strings (Longest Common Subsequence - DP) ---
const lcsSolutionCodeJS = `
/**
 * Finds the length of the longest common subsequence between two strings.
 * Uses O(M*N) dynamic programming.
 * @param {string} text1
 * @param {string} text2
 * @returns {number} The length of the LCS.
 */
const longestCommonSubsequence = function(text1, text2) {
    const m = text1.length;
    const n = text2.length;

    // dp[i][j] = length of LCS of text1[0...i-1] and text2[0...j-1]
    // Initialize (m+1) x (n+1) DP table with zeros
    const dp = Array(m + 1).fill(0).map(() => Array(n + 1).fill(0));

    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            // If characters match
            if (text1[i - 1] === text2[j - 1]) {
                dp[i][j] = 1 + dp[i - 1][j - 1];
            } else {
                // If characters don't match, take max from top or left cell
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }

    // The bottom-right cell contains the length of the LCS for the full strings
    return dp[m][n];
};

// Example Usage:
console.log("LCS('abcde', 'ace') =", longestCommonSubsequence('abcde', 'ace')); // Output: 3
console.log("LCS('abc', 'abc') =", longestCommonSubsequence('abc', 'abc'));     // Output: 3
console.log("LCS('abc', 'def') =", longestCommonSubsequence('abc', 'def'));     // Output: 0
`;

const lcsSolutionCodePython = `
class Solution:
    """
    Finds the length of the longest common subsequence between two strings using DP.
    """
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        """
        Args:
            text1: The first string.
            text2: The second string.

        Returns:
            The length of the longest common subsequence.
        """
        m = len(text1)
        n = len(text2)

        # dp[i][j] = length of LCS of text1[:i] and text2[:j]
        # Initialize (m+1) x (n+1) DP table with zeros
        dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

        for i in range(1, m + 1):
            for j in range(1, n + 1):
                # If characters match
                if text1[i - 1] == text2[j - 1]:
                    dp[i][j] = 1 + dp[i - 1][j - 1]
                else:
                    # If characters don't match, take max
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        return dp[m][n]

# Example Usage:
if __name__ == "__main__":
    sol = Solution()
    print(f"LCS('abcde', 'ace') = {sol.longestCommonSubsequence('abcde', 'ace')}") # Output: 3
    print(f"LCS('abc', 'abc') = {sol.longestCommonSubsequence('abc', 'abc')}")     # Output: 3
    print(f"LCS('abc', 'def') = {sol.longestCommonSubsequence('abc', 'def')}")     # Output: 0
`;

const lcsSolutionCodeJava = `
import java.util.Arrays;

class Solution {
    /**
     * Finds the length of the longest common subsequence between two strings using DP.
     * @param text1 The first string.
     * @param text2 The second string.
     * @return The length of the LCS.
     */
    public int longestCommonSubsequence(String text1, String text2) {
        int m = text1.length();
        int n = text2.length();

        // dp[i][j] = length of LCS of text1[0...i-1] and text2[0...j-1]
        int[][] dp = new int[m + 1][n + 1];
        // Java initializes int arrays to 0 by default

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                // If characters match
                if (text1.charAt(i - 1) == text2.charAt(j - 1)) {
                    dp[i][j] = 1 + dp[i - 1][j - 1];
                } else {
                    // If characters don't match, take max
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        return dp[m][n];
    }

    // Example Usage:
    public static void main(String[] args) {
        Solution sol = new Solution();
        System.out.println("LCS('abcde', 'ace') = " + sol.longestCommonSubsequence("abcde", "ace")); // Output: 3
        System.out.println("LCS('abc', 'abc') = " + sol.longestCommonSubsequence("abc", "abc"));     // Output: 3
        System.out.println("LCS('abc', 'def') = " + sol.longestCommonSubsequence("abc", "def"));     // Output: 0
    }
}
`;

const lcsSolutionCodeCPP = `
#include <string>
#include <vector>
#include <algorithm> // For std::max
#include <iostream>

class Solution {
public:
    /**
     * Finds the length of the longest common subsequence between two strings using DP.
     * @param text1 The first string.
     * @param text2 The second string.
     * @return The length of the LCS.
     */
    int longestCommonSubsequence(std::string text1, std::string text2) {
        int m = text1.length();
        int n = text2.length();

        // dp[i][j] = length of LCS of text1[0...i-1] and text2[0...j-1]
        // Initialize (m+1) x (n+1) DP table with zeros
        std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));

        for (int i = 1; i <= m; ++i) {
            for (int j = 1; j <= n; ++j) {
                // If characters match
                if (text1[i - 1] == text2[j - 1]) {
                    dp[i][j] = 1 + dp[i - 1][j - 1];
                } else {
                    // If characters don't match, take max
                    dp[i][j] = std::max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        return dp[m][n];
    }
};

// Example Usage:
int main() {
    Solution sol;
    std::cout << "LCS('abcde', 'ace') = " << sol.longestCommonSubsequence("abcde", "ace") << std::endl; // Output: 3
    std::cout << "LCS('abc', 'abc') = " << sol.longestCommonSubsequence("abc", "abc") << std::endl;     // Output: 3
    std::cout << "LCS('abc', 'def') = " << sol.longestCommonSubsequence("abc", "def") << std::endl;     // Output: 0
    return 0;
}
`;
