const solutionCodeJS = `
/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 * this.val = (val===undefined ? 0 : val)
 * this.left = (left===undefined ? null : left)
 * this.right = (right===undefined ? null : right)
 * }
 */
/**
 * Checks if a binary tree is a valid Binary Search Tree (BST).
 * A BST is valid if:
 * - The left subtree of a node contains only nodes with keys less than the node's key.
 * - The right subtree of a node contains only nodes with keys greater than the node's key.
 * - Both the left and right subtrees must also be binary search trees.
 *
 * Uses recursion with range validation (min/max).
 * Time: O(N), visits each node once.
 * Space: O(H) avg (recursion stack), O(N) worst case.
 * @param {TreeNode} root The root of the binary tree.
 * @return {boolean} True if the tree is a valid BST, false otherwise.
 */
const isValidBST = function(root) {
    // Helper function with min and max range constraints
    function validate(node, min, max) {
        // Base case: An empty tree (or subtree) is a valid BST
        if (!node) {
            return true;
        }

        // Check current node's value against the valid range
        if (node.val <= min || node.val >= max) {
            return false; // Violation found
        }

        // Recursively validate the left and right subtrees
        // Left child must be less than current node's value (new max)
        // Right child must be greater than current node's value (new min)
        return validate(node.left, min, node.val) &&
               validate(node.right, node.val, max);
    }

    // Start the validation with initial range (-Infinity, +Infinity)
    return validate(root, -Infinity, Infinity);
};

// Alternative: Inorder Traversal Check
// Time: O(N), Space: O(H) avg, O(N) worst
const isValidBSTInorder = function(root) {
    let prevVal = -Infinity;
    let isValid = true;

    function inorder(node) {
        if (!node || !isValid) { // Stop if already invalid or null node
            return;
        }

        inorder(node.left);

        // Check inorder property: current value must be > previous value
        if (node.val <= prevVal) {
            isValid = false;
            return; // Stop early
        }
        prevVal = node.val; // Update previous value

        inorder(node.right);
    }

    inorder(root);
    return isValid;
};
`;
