// --- Data Structure (Min-Heap) ---
// Basic MinHeap implementation for visualization purposes
class MinHeap {
    constructor() {
        this.heap = []; // Store { value: number, listId: number, nodeId: string }
    }
    _getParentIndex(i) { return Math.floor((i - 1) / 2); }
    _getLeftChildIndex(i) { return 2 * i + 1; }
    _getRightChildIndex(i) { return 2 * i + 2; }
    _swap(i, j) { [this.heap[i], this.heap[j]] = [this.heap[j], this.heap[i]]; }
    _siftUp(index) {
        let parentIndex = this._getParentIndex(index);
        while (index > 0 && this.heap[index].value < this.heap[parentIndex].value) {
            this._swap(index, parentIndex);
            index = parentIndex;
            parentIndex = this._getParentIndex(index);
        }
    }
    _siftDown(index) {
        let smallestIndex = index;
        const leftIndex = this._getLeftChildIndex(index);
        const rightIndex = this._getRightChildIndex(index);
        const size = this.heap.length;
        if (leftIndex < size && this.heap[leftIndex].value < this.heap[smallestIndex].value) {
            smallestIndex = leftIndex;
        }
        if (rightIndex < size && this.heap[rightIndex].value < this.heap[smallestIndex].value) {
            smallestIndex = rightIndex;
        }
        if (smallestIndex !== index) {
            this._swap(index, smallestIndex);
            this._siftDown(smallestIndex);
        }
    }
    insert(node) { // node = { value, listId, nodeId }
        this.heap.push(node);
        this._siftUp(this.heap.length - 1);
    }
    extractMin() {
        if (this.heap.length === 0) return null;
        if (this.heap.length === 1) return this.heap.pop();
        const min = this.heap[0];
        this.heap[0] = this.heap.pop();
        this._siftDown(0);
        return min;
    }
    peek() { return this.heap.length > 0 ? this.heap[0] : null; }
    isEmpty() { return this.heap.length === 0; }
    getHeapState() { return [...this.heap]; } // Return copy for display
}


