/**
 * Merges k sorted linked lists into one sorted linked list using a Min Heap.
 * Time: O(N log k), where N is the total number of nodes and k is the number of lists.
 * Space: O(k) for the priority queue.
 * @param {ListNode[]} lists Array of k sorted linked list heads.
 * @return {ListNode} The head of the merged sorted linked list.
 */
const mergeKLists = function(lists) {
    if (!lists || lists.length === 0) {
        return null;
    }

    const pq = new MinPriorityQueue();

    // 1. Add the head of each non-empty list to the min-heap
    for (const head of lists) {
        if (head) {
            pq.enqueue({ node: head });
        }
    }

    const dummy = new ListNode(-1);
    let current = dummy;

    // 2. Extract min, add to result, add next from same list to heap
    while (!pq.isEmpty()) {
        const { node: smallestNode } = pq.dequeue(); // Get the node with the smallest value

        current.next = smallestNode; // Link it to the merged list
        current = current.next;      // Move the current pointer

        // If the extracted node has a next node, add it to the heap
        if (smallestNode.next) {
            pq.enqueue({ node: smallestNode.next });
        }
    }

    return dummy.next;
};
