
import React, { useState, useEffect } from 'react';
import {
    Grid, TextField, Button, Box, Typography, CircularProgress, Alert, Tooltip, Select, MenuItem, InputLabel, FormControl, Paper, Stack 
} from '@mui/material';

import { Editor } from "@monaco-editor/react"; 
import { useTheme, useMediaQuery } from "@mui/material"; 


import CodeIcon from '@mui/icons-material/Code'; 
import PlayArrowIcon from '@mui/icons-material/PlayArrow'; 
import InputIcon from '@mui/icons-material/Input'; 
import OutputIcon from '@mui/icons-material/Output'; 
import NotesIcon from '@mui/icons-material/Notes'; 
import Brightness4Icon from '@mui/icons-material/Brightness4'; 
import Brightness7Icon from '@mui/icons-material/Brightness7'; 
import IconButton from '@mui/material/IconButton';

const RAPIDAPI_KEY_PLACEHOLDER = "1bd042778fmshd4b16d97e812af0p1395bejsn19af4753d4d1"; 
const RAPIDAPI_HOST = "code-compiler.p.rapidapi.com";
const RAPIDAPI_URL = "https://code-compiler.p.rapidapi.com/v2";


const defaultCodeSnippets = {
    '4': `import java.util.*; \npublic class Progman {\n\tpublic static void main(String[] args) {\n\t\t// Write your Java code here\n\t\tSystem.out.println("Hello from Java!");\n\t}\n}`, // Java
    '5': `# Write your Python code here\nprint("Hello from Python!")`, 
    '7': `#include <iostream>\nusing namespace std;\nint main() {\n\t// Write your C++ code here\n\tcout << "Hello from C++!";\n\treturn 0;\n}`, // C++
    '6': `#include <stdio.h>\nint main() {\n\t// Write your C code here\n\tprintf("Hello from C!");\n\treturn 0;\n}` // C
};


const languageIdToMonacoLang = {
    '4': 'java',
    '5': 'python',
    '7': 'cpp',
    '6': 'c',
};

export const OnlineCompiler = () => {
    // State
    const [languageId, setLanguageId] = useState(localStorage.getItem('compiler_language_Id') || '5');
    const [inputCode, setInputCode] = useState('');
    const [userInput, setUserInput] = useState('');
    const [output, setOutput] = useState('');
    const [loading, setLoading] = useState(false);
    const [apiError, setApiError] = useState('');

    // Theme and responsiveness hooks
    const muiTheme = useTheme();
    const isMobile = useMediaQuery(muiTheme.breakpoints.down("sm"));

    // --- NEW: State for editor theme ---
    const [editorThemeMode, setEditorThemeMode] = useState(muiTheme.palette.mode); // Initialize based on MUI theme

    // --- NEW: Monaco editor theme based on state ---
    const editorTheme = editorThemeMode === 'dark' ? 'vs-dark' : 'light';
    
    useEffect(() => {
        const savedCode = localStorage.getItem(`compiler_input_${languageId}`);
        setInputCode(defaultCodeSnippets[languageId] || '');
    }, [languageId]);

    // Handlers
    const handleEditorChange = (value) => {
        const currentCode = value || '';
        setInputCode(currentCode);
        localStorage.setItem(`compiler_input_${languageId}`, currentCode);
    };
    const handleUserInputChange = (event) => { setUserInput(event.target.value); };
    const handleLanguageChange = (event) => {
        const newLangId = event.target.value;
        if (newLangId === '#') return;
        setLanguageId(newLangId);
        localStorage.setItem('compiler_language_Id', newLangId);
        // Reset code to default when language changes
        setInputCode(defaultCodeSnippets[newLangId] || '');
        localStorage.removeItem(`compiler_input_${languageId}`); // Clear old language code
    };

    // --- NEW: Handler to toggle editor theme ---
    const toggleEditorTheme = () => {
        setEditorThemeMode((prevMode) => (prevMode === 'dark' ? 'light' : 'dark'));
    };


    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!inputCode || languageId === '#') {
            setApiError("Please select a language and write some code."); return;
        }

        if (RAPIDAPI_KEY_PLACEHOLDER === "YOUR_RAPIDAPI_KEY" || !RAPIDAPI_KEY_PLACEHOLDER) {
             setApiError("API Key not configured. Please replace the placeholder in the code.");
             setOutput("API Key not configured. Execution aborted."); return;
        }

        setLoading(true); setOutput("Running code..."); setApiError('');
        const data = new URLSearchParams();
        data.append("LanguageChoice", languageId);
        data.append("Program", inputCode);
        data.append("Input", userInput || "");

        const options = {
            method: 'POST',
            headers: {
                'x-rapidapi-key': RAPIDAPI_KEY_PLACEHOLDER, // Use the placeholder
                'x-rapidapi-host': RAPIDAPI_HOST,
                'Content-Type': 'application/x-www-form-urlencoded',
            },
            body: data,
        };

        try {
            const response = await fetch(RAPIDAPI_URL, options);
            const jsonResponse = await response.json();

            if (!response.ok) {
                 // Attempt to parse error message more robustly
                 let errorMsg = `HTTP error! Status: ${response.status} ${response.statusText}`;
                 if (jsonResponse) {
                     errorMsg = jsonResponse.Errors || jsonResponse.message || JSON.stringify(jsonResponse); // Use Errors, message, or stringify
                 }
                 // Check for HTML response which often indicates gateway errors or misconfigurations
                 if (response.headers.get("content-type")?.includes("text/html")) {
                     errorMsg = `API Gateway Error: Status ${response.status}. Check RapidAPI dashboard or network configuration. Response might be HTML.`;
                 }
                 throw new Error(errorMsg);
            }

            // Handle potential variations in successful response structure
            const resultOutput = jsonResponse.Result || jsonResponse.Output || ""; // Check 'Output' too
            const errorOutput = jsonResponse.Errors || ""; // Capture compilation/runtime errors from API

            if (errorOutput) {
                setOutput(`Execution Error:\n${errorOutput}`); // Show API errors clearly
            } else if (resultOutput) {
                setOutput(resultOutput);
            } else {
                 setOutput("Execution finished, but no output was produced."); // Handle cases with no output/error
            }

        } catch (error) {
            console.error("API Error:", error);
            // Display a user-friendly error message
            setApiError(`Error: ${error.message}`);
            setOutput(`Failed to execute code. ${error.message}`); // Show error in output too
        } finally {
            setLoading(false);
        }
    };

    // --- Render the Improved Compiler UI ---
    return (
        <Paper elevation={3} sx={{ p: { xs: 2, sm: 3 }, border: 1, borderColor: 'divider', borderRadius: 2 }}>
            {/* Title with Icon */}
            <Stack direction="row" spacing={1} alignItems="center" justifyContent="center" mb={3}>
                 <CodeIcon color="primary"/>
                 <Typography variant={isMobile ? "h6" : "h5"} component="h2" sx={{ fontWeight: 'medium' }}>
                    <b>
                    Compiler
                    </b>
                 </Typography>
            </Stack>

            {/* Controls: Language Select and Run Button */}
            <Stack
                direction={{ xs: 'column', sm: 'row' }}
                spacing={2}
                sx={{ mb: 3, justifyContent: 'center', alignItems: 'center' }}
            >
                 <FormControl variant="outlined" size="small" sx={{ minWidth: 180, width: { xs: '100%', sm: 'auto'} }}>
                    <InputLabel id="compiler-language-label">Language</InputLabel>
                    <Select
                        labelId="compiler-language-label"
                        id="compiler-language"
                        value={languageId}
                        onChange={handleLanguageChange}
                        label="Language"
                    >
                        <MenuItem value="#" disabled>Select Language</MenuItem>
                        <MenuItem value="4">Java</MenuItem>
                        <MenuItem value="5">Python</MenuItem>
                        <MenuItem value="7">C++</MenuItem>
                        <MenuItem value="6">C</MenuItem>
                    </Select>
                </FormControl>
                <Button
                    variant="contained"
                    color="primary"
                    size="medium"
                    onClick={handleSubmit}
                    disabled={loading || languageId === '#'}
                    startIcon={loading ? <CircularProgress size={20} color="inherit" /> : <PlayArrowIcon />}
                    sx={{ width: { xs: '100%', sm: 'auto'}, px: 3, py: 1.1 }}
                >
                    {loading ? 'Running...' : 'Run Code'}
                </Button>
            </Stack>

            {/* Main Grid Layout */}
            <Grid container spacing={3} sx={{ mt: 1 }}> {/* Reduced spacing slightly */}
                {/* Editor Section */}
                <Grid item xs={12} md={8} width="100%"> {/* Ensure full width on small, 2/3 on medium+ */}
                    <Paper elevation={2} sx={{ height: { xs: '55vh', sm: '60vh', md: '65vh' }, p: 2, borderRadius: 2, bgcolor: 'background.default', display: 'flex', flexDirection: 'column' }}>
                        {/* Editor Header with Title and Theme Toggle */}
                        <Stack direction="row" alignItems="center" justifyContent="space-between" spacing={1} mb={1.5}>
                            <Stack direction="row" alignItems="center" spacing={1}>
                                <NotesIcon color="action" />
                                <Typography variant="h6" sx={{ fontWeight: 600 }}>
                                    Code Editor
                                </Typography>
                            </Stack>
                            {/* --- NEW: Theme Toggle Button --- */}
                            <Tooltip title={`Switch to ${editorThemeMode === 'dark' ? 'Light' : 'Dark'} Mode`}>
                                <IconButton onClick={toggleEditorTheme} size="small">
                                    {editorThemeMode === 'dark' ? <Brightness7Icon /> : <Brightness4Icon />}
                                </IconButton>
                            </Tooltip>
                        </Stack>
                        {/* Monaco Editor Container */}
                        <Box sx={{ flex: 1, overflow: 'hidden', borderRadius: 1, border: '1px solid', borderColor: 'divider' }} > {/* Added border */}
                            <Editor
                                height="100%" // Fill the container
                                width="100%"
                                language={languageIdToMonacoLang[languageId] || 'plaintext'}
                                value={inputCode}
                                onChange={handleEditorChange}
                                theme={editorTheme} // Use the state-controlled theme
                                options={{
                                    selectOnLineNumbers: true,
                                    automaticLayout: true, // Important for resizing
                                    fontSize: isMobile ? 13 : 14,
                                    minimap: { enabled: !isMobile, scale: 0.8 },
                                    wordWrap: 'on',
                                    scrollBeyondLastLine: false,
                                    padding: { top: 10, bottom: 10 }, // Slightly reduced padding
                                    renderLineHighlight: 'gutter', // Highlight gutter instead of full line
                                    fontLigatures: true,
                                    smoothScrolling: true,
                                }}
                            />
                        </Box>
                    </Paper>
                </Grid>

                  {/* Input / Output Column */}

                  <Grid item xs={12} md={4} width="100%"> {/* Adjusted grid size back slightly if needed */}

<Box sx={{ height: '100%' }}>

    <Stack direction="row" spacing={2} sx={{ height: '100%' }}>

        {/* Input Section */}

        <Box sx={{ width: '50%' }}>
  <Stack spacing={1.5} mb={1.5} direction="row" alignItems="center">
    <InputIcon fontSize="small" color="action" /> {/* Icon Added */}
    <Typography variant="subtitle1" component="h3" sx={{ fontWeight: 'medium' }}>
      Input (stdin)
    </Typography>
  </Stack>

  <TextField
    placeholder="Enter standard input here..."
    multiline
    rows={isMobile ? 7 : 10}
    variant="outlined"
    fullWidth
    value={userInput}
    onChange={handleUserInputChange}
    sx={{
      height: '86%', // Allow TextField to attempt filling height
      '& .MuiOutlinedInput-root': {
        height: '100%', // Make root element fill height
        alignItems: 'flex-start', // Align text to top
        fontFamily: 'monospace',
        fontSize: '0.9rem',
        bgcolor: muiTheme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.05)' : 'rgba(0, 0, 0, 0.03)',
        '&:hover .MuiOutlinedInput-notchedOutline': { borderColor: 'primary.light' },
        '&.Mui-focused .MuiOutlinedInput-notchedOutline': { borderColor: 'primary.main' },
      },
      '& .MuiInputBase-inputMultiline': {
        height: '100% !important', // Force multiline input to take full height
        overflow: 'auto !important',
      },
      '& .MuiInputBase-input::placeholder': { color: muiTheme.palette.text.disabled, opacity: 1 },
    }}
  />
</Box>

{/* Output Section */}
<Box sx={{ width: '50%', display: 'flex', flexDirection: 'column' }}>
  <Stack spacing={1.5} mb={1.5} direction="row" alignItems="center">
    <OutputIcon fontSize="small" color="action" /> {/* Icon Added */}
    <Typography variant="subtitle1" component="h3" sx={{ fontWeight: 'medium' }}>
      Output
    </Typography>
  </Stack>

  {apiError && (
    <Alert severity="error" sx={{ mb: 1.5, flexShrink: 0, borderRadius: 1 }}>
      {apiError}
    </Alert>
  )}

  <Paper
    variant="outlined"
    sx={{
      p: 2,
      flexGrow: 1,
      minHeight: '180px',
      bgcolor: muiTheme.palette.background.paper,
      color: 'text.primary',
      borderColor: 'divider',
      borderRadius: 1,
      whiteSpace: 'pre-wrap',
      overflow: 'auto',
      fontFamily: 'monospace',
      fontSize: '0.875rem',
      lineHeight: 1.6,
    }}
  >
    {loading && output === 'Running code...' ? (
      // Show loading indicator + text when loading and message matches
      <Stack direction="row" spacing={1} alignItems="center" sx={{ color: 'text.secondary' }}>
        <CircularProgress size={16} color="inherit" />
        <Typography variant="body2">Running code...</Typography>
      </Stack>
    ) : (
      // Otherwise, show the actual output or the placeholder
      output || <Typography variant="body2" sx={{ color: 'text.disabled', fontStyle: 'italic' }}>Output will appear here...</Typography>
    )}
  </Paper>
</Box>
</Stack>
</Box>
</Grid>
</Grid>
</Paper>


            )};