const containerMostWaterSolutionCodePython = `
from typing import List

class Solution:
    def maxArea(self, height: List[int]) -> int:
        left = 0
        right = len(height) - 1
        max_area = 0

        while left < right:
            current_width = right - left
            current_height = min(height[left], height[right])
            current_area = current_width * current_height
            max_area = max(max_area, current_area)

            if height[left] < height[right]:
                left += 1
            else:
                right -= 1

        return max_area

# Main
if __name__ == "__main__":
    sol = Solution()
    input_h = [1,8,6,2,5,4,8,3,7]
    print(f"Input: {input_h}")
    print(f"Max Area: {sol.maxArea(input_h)}")
`;
// --- End Solution Code Strings ---


// --- ContainerMostWaterVisualizer Component (Template Base - Audio Restored & Fixed) ---
const ContainerMostWaterVisualizer = () => {
    // --- State Variables ---
    const [heightInput, setHeightInput] = useState("1, 8, 6, 2, 5, 4, 8, 3, 7");
    const [elements, setElements] = useState([]);
    const [message, setMessage] = useState("");
    const [errorMessage, setErrorMessage] = useState("");
    const [isRunning, setIsRunning] = useState(false);
    const [pointers, setPointers] = useState({ left: null, right: null });
    const [maxArea, setMaxArea] = useState(0);
    const [currentArea, setCurrentArea] = useState(0);
    const [maxHeightVal, setMaxHeightVal] = useState(1);
    const stopRef = React.useRef(false);
    const [isAudioEnabled, setIsAudioEnabled] = useState(true);
    const [isSpeechEnabled, setIsSpeechEnabled] = useState(true);

    // --- Web Audio API Setup ---
    const audioContextRef = useRef(null);
    const initAudioContext = useCallback(() => {
        if (!isAudioEnabled) return;
        if (audioContextRef.current === null && typeof window !== 'undefined' && (window.AudioContext || window.webkitAudioContext)) {
            try {
                audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)();
                // console.log("Debug Audio: NEW AudioContext created. State:", audioContextRef.current.state);
            } catch (e) {
                console.error("Web Audio API not supported.", e);
                setIsAudioEnabled(false);
                setMessage("Audio tones disabled: Not supported.");
            }
        }
        if (audioContextRef.current && audioContextRef.current.state === 'suspended') {
            // console.log("Debug Audio: Context is suspended, attempting resume...");
            audioContextRef.current.resume().catch(e => console.error("Audio resume failed", e));
        }
    }, [isAudioEnabled]); // Removed setMessage dependency

    const playTone = useCallback((frequency = 440, duration = 0.1, type = 'sine', volume = 0.3) => {
        if (!isAudioEnabled || !audioContextRef.current || audioContextRef.current.state !== 'running') {
            // console.log(`Debug Audio: playTone returning early. isAudioEnabled=${isAudioEnabled}, context=${audioContextRef.current ? audioContextRef.current.state : 'null'}`);
             return;
        }
        try {
            // console.log("Debug Audio: Attempting to play tone...");
            const oscillator = audioContextRef.current.createOscillator();
            const gainNode = audioContextRef.current.createGain();
            oscillator.type = type;
            oscillator.frequency.setValueAtTime(frequency, audioContextRef.current.currentTime);
            gainNode.gain.setValueAtTime(volume, audioContextRef.current.currentTime);
            gainNode.gain.exponentialRampToValueAtTime(0.0001, audioContextRef.current.currentTime + duration);
            oscillator.connect(gainNode);
            gainNode.connect(audioContextRef.current.destination);
            oscillator.start(audioContextRef.current.currentTime);
            oscillator.stop(audioContextRef.current.currentTime + duration);
        } catch (e) {
            console.error("Error playing tone:", e);
        }
    }, [isAudioEnabled]);

    // Specific sounds - Using actual playTone calls
    const playPointerMoveSound = useCallback(() => playTone(600, 0.05, 'triangle', 0.2), [playTone]);
    const playAreaCalcSound = useCallback(() => playTone(250, 0.03, 'square', 0.15), [playTone]);
    const playNewMaxAreaSound = useCallback(() => playTone(1000, 0.15, 'sine', 0.4), [playTone]);
    const playComparisonSound = useCallback(() => playTone(500, 0.06, 'sine', 0.15), [playTone]);
    const playStartSound = useCallback(() => playTone(440, 0.1, 'sine', 0.3), [playTone]);
    const playEndSound = useCallback(() => playTone(330, 0.2, 'sawtooth', 0.3), [playTone]);
    const playStopSound = useCallback(() => playTone(220, 0.15, 'square', 0.3), [playTone]);
    const playErrorSound = useCallback(() => playTone(150, 0.3, 'sawtooth', 0.3), [playTone]);

    // --- Web Speech API Setup (Promise-based - Error Handling Updated) ---
    const speak = useCallback((text) => {
        // Using actual speech synthesis
        return new Promise((resolve) => {
            if (!isSpeechEnabled || typeof window === 'undefined' || !window.speechSynthesis) {
                resolve();
                return;
            }
            try {
                window.speechSynthesis.cancel();
                const utterance = new SpeechSynthesisUtterance(text);
                utterance.lang = 'en-US';
                utterance.rate = 1.0;
                utterance.pitch = 1.0;
                utterance.volume = 0.8;
                utterance.onend = () => { resolve(); };
                utterance.onerror = (event) => {
                    console.error("Speech synthesis error:", event.error);
                    resolve(); // Resolve even on error
                };
                window.speechSynthesis.speak(utterance);
            } catch (e) {
                console.error("Error initiating speech synthesis:", e);
                resolve(); // Resolve if initiation fails
            }
        });
    }, [isSpeechEnabled]);

    const cancelSpeech = useCallback(() => { if (typeof window !== 'undefined' && window.speechSynthesis) { window.speechSynthesis.cancel(); } }, []);

    // --- Reset Function ---
    const reset = useCallback((initial = false) => {
        // console.log("Debug: Reset called. Initial:", initial);
        stopRef.current = true; cancelSpeech(); setIsRunning(false);
        setPointers({ left: null, right: null }); setMaxArea(0); setCurrentArea(0);
        setErrorMessage("");
        try {
            const heights = parseArrayInput(heightInput, true).map(h => Math.max(0, h));
            if (heights.some(h => h < 0)) throw new Error("Heights cannot be negative.");
            if (heights.length < 2 && !initial && heights.length !== 0) throw new Error("Need at least two heights.");
            const validHeights = heights.filter(h => typeof h === 'number' && !isNaN(h));
            setMaxHeightVal(validHeights.length > 0 ? Math.max(...validHeights, 1) : 1);
            setElements(heights.map((val, i) => ({ id: i, value: val, state: 'default', index: i, pointers: [] })));
            // console.log("Debug: Reset successful. Elements:", heights);
            setMessage(initial ? "" : "Enter heights array and run, or use default.");
        } catch (e) {
            setElements([]); setErrorMessage(`Input Error: ${e.message}`); setMessage("");
            // console.error("Debug: Reset failed:", e.message);
            if (!initial) playErrorSound();
        }
    }, [heightInput, cancelSpeech, parseArrayInput, playErrorSound]); // Added playErrorSound dependency

    // --- Effects ---
    useEffect(() => { reset(true); return () => { stopRef.current = true; cancelSpeech(); if (audioContextRef.current) { audioContextRef.current.close().catch(e => console.error("Error closing AudioContext:", e)); audioContextRef.current = null; } }; }, [reset, cancelSpeech]);
    useEffect(() => { const handler = setTimeout(() => { reset(true); }, 500); return () => clearTimeout(handler); }, [heightInput, reset]);

    // --- Visualization Logic (Audio Restored) ---
    const runVisualization = async () => {
        // console.log("Debug: runVisualization started");
        initAudioContext(); // Re-enabled audio init
        cancelSpeech();
        reset(false);
        await sleep(100);

        let heights;
        try {
            if (errorMessage) { setIsRunning(false); return; }
            heights = elements.map(el => el.value);
            if (heights.length < 2) { setErrorMessage("Need at least two heights."); setIsRunning(false); return; }
        } catch (e) { setErrorMessage(`Internal Error: ${e.message}`); setIsRunning(false); playErrorSound(); return; }

        stopRef.current = false; setIsRunning(true);
        setMessage("Starting Container With Most Water..."); playStartSound();
        await speak("Starting. Initializing left and right pointers.");
        if (stopRef.current) { setIsRunning(false); return; }

        let left = 0;
        let right = heights.length - 1;
        let currentMaxArea = 0;

        await sleep(500);

        while (left < right && !stopRef.current) {
            // console.log(`\nDebug: Loop Start - L=${left}, R=${right}`);

            // 1. Highlight pointers & Announce check
            setPointers({ left, right });
            setElements(prev => prev.map((el, idx) => ({ ...el, state: (idx === left || idx === right) ? 'highlight-active' : 'default', pointers: idx === left ? ['L'] : idx === right ? ['R'] : [] })));
            setMessage(`Checking L=${left}(H:${heights[left]}), R=${right}(H:${heights[right]})`);
            playComparisonSound();
            // console.log(`Debug: Checking L=${left}(${heights[left]}), R=${right}(${heights[right]})`);
            if (stopRef.current) break;
            await speak(`Checking left ${left}, right ${right}.`);
            if (stopRef.current) break;
            await sleep(800);

            // 2. Calculate area & Announce
            const h = Math.min(heights[left], heights[right]);
            const w = right - left;
            const area = h * w;
            setCurrentArea(area);
            setMessage(`Width=${w}, Height=${h}. Current Area = ${area}.`);
            playAreaCalcSound();
            // console.log(`Debug: Calculated Area = ${area} (w=${w}, h=${h})`);
            if (stopRef.current) break;
            await speak(`Current area is ${area}.`);
            if (stopRef.current) break;
            await sleep(800);

            // 3. Compare with max & Announce
            setMessage(`Compare Current Area (${area}) with Max Area (${currentMaxArea}).`);
            playComparisonSound();
            // console.log(`Debug: Comparing Area ${area} with Max ${currentMaxArea}`);
             if (stopRef.current) break;
            await speak(`Compare area ${area} with max ${currentMaxArea}.`);
            if (stopRef.current) break;
            await sleep(800);

            if (area > currentMaxArea) {
                 setElements(prev => prev.map((el, idx) => ({ ...el, state: (idx === left || idx === right) ? 'highlight-max-found' : 'default', pointers: idx === left ? ['L'] : idx === right ? ['R'] : [] })));
                currentMaxArea = area;
                setMaxArea(currentMaxArea);
                setMessage(`New Max Area Found: ${currentMaxArea}`);
                playNewMaxAreaSound();
                // console.log(`Debug: New Max Area = ${currentMaxArea}`);
                 if (stopRef.current) break;
                await speak(`New maximum area found: ${currentMaxArea}.`);
                if (stopRef.current) break;
                await sleep(1000);
            } else {
                 setMessage(`Current area (${area}) <= Max area (${currentMaxArea}). No update.`);
                 if (stopRef.current) break;
                 await speak(`No new max area.`);
                 if (stopRef.current) break;
                 await sleep(800);
            }
             if (stopRef.current) break;

            // 4. Decide which pointer to move & Announce
            let movedLeft = false;
            let messageMove = "";
            let speakMove = "";
            if (heights[left] < heights[right]) {
                messageMove = `H[L] (${heights[left]}) < H[R] (${heights[right]}). Move Left pointer -> ${left + 1}.`;
                speakMove = `Moving left pointer.`;
                movedLeft = true;
            } else {
                messageMove = `H[R] (${heights[right]}) <= H[L] (${heights[left]}). Move Right pointer -> ${right - 1}.`;
                speakMove = `Moving right pointer.`;
                movedLeft = false;
            }
            setMessage(messageMove);
            playPointerMoveSound();
            // console.log(`Debug: ${messageMove}`);
            if (stopRef.current) break;
            await speak(speakMove);
            if (stopRef.current) break;
            await sleep(500);

            // 5. Execute pointer move & Pause
            if (movedLeft) {
                left++;
            } else {
                right--;
            }
             // console.log(`Debug: Pointers moved to L=${left}, R=${right}`);
            setPointers({ left, right });
            setElements(prev => prev.map((el, idx) => ({ ...el, state: 'default', pointers: idx === left ? ['L'] : idx === right ? ['R'] : [] })));
            await sleep(1000);
            if (stopRef.current) break;
        }

        // Final State
        // console.log("Debug: Loop finished or stopped.");
        if (stopRef.current) {
            setMessage("Visualization stopped by user."); speak("Visualization stopped."); playStopSound();
            setElements(prev => prev.map(el => ({ ...el, state: 'default', pointers: [] })));
        } else {
            setMessage(`Finished. Maximum Area: ${currentMaxArea}.`);
            playEndSound();
            await speak(`Finished. Maximum area is ${currentMaxArea}.`);
            setElements(prev => prev.map(el => ({ ...el, state: 'default', pointers: [] })));
            setMaxArea(currentMaxArea);
        }
        setIsRunning(false); stopRef.current = false;
        // console.log("Debug: runVisualization ended");
    };

    const stopVisualization = () => {
        // console.log("Debug: stopVisualization called");
        stopRef.current = true; cancelSpeech(); setMessage("Stopping visualization...");
    };

    const toggleAudio = () => { /* ... (Template standard) ... */ const newState = !isAudioEnabled; setIsAudioEnabled(newState); if (newState) { initAudioContext(); playTone(500, 0.05, 'sine', 0.2); } else { playTone(300, 0.05, 'square', 0.2); if (audioContextRef.current && audioContextRef.current.state === 'running') { audioContextRef.current.suspend().catch(e => console.error("Audio suspend failed", e)); } } };
    const toggleSpeech = () => { /* ... (Template standard) ... */ const newState = !isSpeechEnabled; if (newState && (typeof window === 'undefined' || !window.speechSynthesis)) { setMessage("Speech synthesis not supported."); return; } setIsSpeechEnabled(newState); if (!newState) { cancelSpeech(); } else { speak("Speech enabled."); } };

    // --- Render ---
    return (
        <>
            <BaseVisualizer
                problemSummary={
                    <>
                       {/* ... (Problem Summary content remains the same) ... */}
                       <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                            <Typography variant="h4" component="h1">Container With Most Water</Typography>
                            <Chip label="Medium" color="warning" size="small" variant="filled" />
                        </Box>
                        <Typography variant="body1" component="div" sx={{ mb: 2 }}>
                            You are given an integer array <code>height</code> of length <code>n</code>. There are <code>n</code> vertical lines drawn such that the two endpoints of the <code>i</code>-th line are <code>(i, 0)</code> and <code>(i, height[i])</code>.
                            <br /><br />Find two lines that together with the x-axis form a container, such that the container contains the most water.
                            <br /><br />Return <em>the maximum amount of water a container can store</em>.
                            <br /><br /><strong>Notice:</strong> You may not slant the container.
                        </Typography>
                        <Typography variant="h6" component="h3" sx={{ mt: 2, mb: 1 }}>Example:</Typography>
                        <Box sx={{ bgcolor: 'action.hover', p: 1.5, borderRadius: 1, fontFamily: 'monospace', mb: 2, fontSize: '0.875rem' }}>
                            <strong>Input:</strong> height = [1,8,6,2,5,4,8,3,7]<br /><strong>Output:</strong> 49
                        </Box>
                        <Typography variant="h6" component="h3" sx={{ mt: 2, mb: 1 }}>Constraints:</Typography>
                        <Box component="ul" sx={{ pl: 2, mb: 2 }}>
                            <li><code>n == height.length</code></li><li><code>2 &lt;= n &lt;= 10<sup>5</sup></code></li><li><code>0 &lt;= height[i] &lt;= 10<sup>4</sup></code></li>
                        </Box>
                        <Divider sx={{ my: 3 }} />
                        <Typography variant="h6" sx={{ mt: 3, mb: 1 }}>Runnable Solution Code Examples (Two Pointers)</Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>Copy/paste these into the compiler below.</Typography>
                        <Typography variant="subtitle2" sx={{ mb: 0.5 }}>JavaScript:</Typography><SolutionCodeDisplay codeString={containerMostWaterSolutionCodeJS} />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>Python:</Typography><SolutionCodeDisplay codeString={containerMostWaterSolutionCodePython} />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>Java:</Typography><SolutionCodeDisplay codeString={containerMostWaterSolutionCodeJava} />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>C++:</Typography><SolutionCodeDisplay codeString={containerMostWaterSolutionCodeCPP} />
                        <Divider sx={{ my: 3 }} />
                        <Typography variant="subtitle1" gutterBottom>Algorithm Analysis (Two Pointers)</Typography>
                        <Typography variant="body2" color="text.secondary"><strong>Time Complexity:</strong> <code>O(N)</code>. Single pass with two pointers.</Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}><strong>Space Complexity:</strong> <code>O(1)</code>.</Typography>
                    </>
                }
                controls={
                     <>
                        <Typography variant="subtitle1" sx={{ textAlign: 'center', fontWeight: 'bold', p: 0.75, mb: 2.5, borderRadius: '4px', color: 'common.white', background: 'linear-gradient(45deg, #0D47A1 30%, #1976D2 90%)', boxShadow: 1 }}>Algorithm Visualizer</Typography>
                        <Grid container spacing={1.5} alignItems="center" mb={2}>
                            <Grid item xs={12} sm={6} md={6}><TextField fullWidth id="cmw-height-input" label="Heights (comma-separated, non-negative)" variant="outlined" size="small" value={heightInput} onChange={(e) => setHeightInput(e.target.value)} placeholder="e.g., 1, 8, 6, 2, 5, 4, 8, 3, 7" disabled={isRunning} /></Grid>
                            <Grid item xs={4} sm={2} md={1.5}><Tooltip title={isRunning ? "Stop Visualization" : "Run Visualization"}><span><Button fullWidth variant="contained" sx={{ height: '40px' }} startIcon={isRunning ? <CircularProgress size={20} color="inherit" /> : <WaterIcon />} onClick={isRunning ? stopVisualization : runVisualization} color={isRunning ? "warning" : "primary"} disabled={isRunning && stopRef.current}>{isRunning ? 'Stop' : 'Run'}</Button></span></Tooltip></Grid>
                            <Grid item xs={4} sm={2} md={1.5}><Tooltip title={isAudioEnabled ? "Mute Tones" : "Unmute Tones"}><Button fullWidth variant="outlined" onClick={toggleAudio} sx={{ height: '40px', minWidth: 'auto', p: 1 }}>{isAudioEnabled ? <VolumeUpIcon /> : <VolumeOffIcon />}</Button></Tooltip></Grid>
                            <Grid item xs={4} sm={2} md={1.5}><Tooltip title={isSpeechEnabled ? "Disable Speech" : "Enable Speech"}><Button fullWidth variant="outlined" onClick={toggleSpeech} sx={{ height: '40px', minWidth: 'auto', p: 1 }}>{isSpeechEnabled ? <RecordVoiceOverIcon /> : <VoiceOverOffIcon />}</Button></Tooltip></Grid>
                            <Grid item xs={12} sm={12} md={1.5} sx={{ display: 'flex', justifyContent: { xs: 'center', md: 'flex-start' } }}><Button variant="outlined" startIcon={<ReplayIcon />} onClick={() => reset(false)} disabled={isRunning} sx={{ height: '40px' }}>Reset</Button></Grid>
                        </Grid>
                        {errorMessage && <Alert severity="error" sx={{ mt: 2 }}>{errorMessage}</Alert>}
                     </>
                }
                displayArea={
                     <>
                         <Box sx={{ display: 'flex', justifyContent: 'space-around', flexWrap: 'wrap', gap: 2, width: '100%', mb: 3, textAlign: 'center' }}>
                             <Tooltip title="Area formed by current left and right pointers"><Box>
                                <Typography variant="overline" display="block" color="text.secondary">Current Area</Typography>
                                <Chip label={currentArea} color="info" variant="outlined" size="small"/>
                             </Box></Tooltip>
                              <Tooltip title="Maximum area found so far"><Box>
                                <Typography variant="overline" display="block" color="text.secondary">Max Area Found</Typography>
                                <Chip label={maxArea} color="primary" variant="filled" size="small"/>
                             </Box></Tooltip>
                         </Box>
                        <Typography variant="h6" gutterBottom align="center">Heights Array Visualization</Typography>
                        <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'flex-end', flexWrap: 'nowrap', overflowX: 'auto', minHeight: '180px', width: '100%', p: 2, border: '1px dashed', borderColor: 'divider', borderRadius: 1, position: 'relative', bgcolor: 'background.default' }}>
                             {/* Restored original states */}
                             {elements.map(el => (<ArrayElement key={el.id} value={el.value} index={el.index} state={el.state} pointers={el.pointers} type="bar" maxHeight={150} maxValue={maxHeightVal} showValue={true} /> ))}
                             {elements.length === 0 && !errorMessage && <Typography variant="caption" color="text.secondary">Enter valid heights to visualize.</Typography>}
                             {errorMessage && elements.length === 0 && <Typography variant="caption" color="error">Invalid input.</Typography>}
                        </Box>
                         {/* Final Result Indication */}
                         {maxArea > 0 && !isRunning && !errorMessage && elements.length > 0 && (
                             <Alert icon={<CheckCircleOutlineIcon fontSize="inherit" />} severity="success" sx={{ mt: 3, justifyContent: 'center', textAlign: 'center' }}>
                                 <Typography variant="h6">Final Max Area: {maxArea}</Typography>
                             </Alert>
                         )}
                    </>
                }
                message={message}
            />
            {/* Render Imported Online Compiler */}
            <Container maxWidth="xl" sx={{ mt: 4, mb: 4 }}>
                <OnlineCompiler />
            </Container>
        </>
    );
};

export default ContainerMostWaterVisualizer;
