const countingBitsSolutionCodeJS = `
/**
 * Counts the number of set bits for each number from 0 to n.
 * @param {number} n - The non-negative integer upper bound.
 * @returns {number[]} An array ans of length n + 1 such that ans[i] is the number of 1's in the binary representation of i.
 */
const countBits = function(n) {
    // Initialize dp array (or ans array) of size n + 1 with zeros
    const ans = new Array(n + 1).fill(0);

    // Iterate from 1 to n
    for (let i = 1; i <= n; i++) {
        // Dynamic Programming approach:
        // ans[i] = ans[i >> 1] + (i & 1);
        // ans[i >> 1] gives the count for the number with the last bit removed.
        // (i & 1) checks if the last bit of i is 1. If it is, add 1.
        ans[i] = ans[i >> 1] + (i % 2); // i % 2 is equivalent to i & 1 for non-negatives
    }

    return ans;
};

// Example Usage:
const n1 = 2;
console.log(\`Input: \${n1}, Output: \${countBits(n1)}\`); // Output: [0, 1, 1]

const n2 = 5;
console.log(\`Input: \${n2}, Output: \${countBits(n2)}\`); // Output: [0, 1, 1, 2, 1, 2]
`;

const countingBitsSolutionCodePython = `
from typing import List

class Solution:
    """
    Counts the number of set bits for each number from 0 to n using dynamic programming.
    """
    def countBits(self, n: int) -> List[int]:
        """
        Args:
            n: The non-negative integer upper bound.

        Returns:
            A list ans of length n + 1 where ans[i] is the Hamming weight of i.
        """
        # Initialize dp array of size n + 1
        ans = [0] * (n + 1)

        # Iterate from 1 to n
        for i in range(1, n + 1):
            # DP relation: count[i] = count[i // 2] + (i % 2)
            # i // 2 is integer division (equivalent to i >> 1)
            # i % 2 checks if the last bit is 1 (equivalent to i & 1)
            ans[i] = ans[i >> 1] + (i & 1)

        return ans

# Example Usage:
if __name__ == "__main__":
    sol = Solution()
    n1 = 2
    print(f"Input: {n1}, Output: {sol.countBits(n1)}") # Output: [0, 1, 1]

    n2 = 5
    print(f"Input: {n2}, Output: {sol.countBits(n2)}") # Output: [0, 1, 1, 2, 1, 2]
`;

const countingBitsSolutionCodeJava = `
import java.util.Arrays;

class Solution {
    /**
     * Counts the number of set bits for each number from 0 to n using dynamic programming.
     * @param n The non-negative integer upper bound.
     * @return An array ans of length n + 1 such that ans[i] is the number of 1's in the binary representation of i.
     */
    public int[] countBits(int n) {
        // Initialize dp array (ans) of size n + 1
        int[] ans = new int[n + 1];
        // ans[0] is already 0

        // Iterate from 1 to n
        for (int i = 1; i <= n; i++) {
            // DP relation: ans[i] = ans[i >> 1] + (i & 1);
            // i >> 1 is equivalent to i / 2 (integer division)
            // i & 1 checks if the last bit is 1
            ans[i] = ans[i >> 1] + (i & 1);
        }

        return ans;
    }

    // Example Usage:
    public static void main(String[] args) {
        Solution sol = new Solution();
        int n1 = 2;
        System.out.println("Input: " + n1 +
                           ", Output: " + Arrays.toString(sol.countBits(n1))); // Output: [0, 1, 1]

        int n2 = 5;
        System.out.println("Input: " + n2 +
                           ", Output: " + Arrays.toString(sol.countBits(n2))); // Output: [0, 1, 1, 2, 1, 2]
    }
}
`;

const countingBitsSolutionCodeCPP = `
#include <vector>
#include <iostream>

// Helper to print vector (optional)
template<typename T>
std::ostream& operator<<(std::ostream& os, const std::vector<T>& vec) {
    os << "[";
    for (size_t i = 0; i < vec.size(); ++i) {
        os << vec[i] << (i == vec.size() - 1 ? "" : ", ");
    }
    os << "]";
    return os;
}

class Solution {
public:
    /**
     * Counts the number of set bits for each number from 0 to n using dynamic programming.
     * @param n The non-negative integer upper bound.
     * @return A vector ans of length n + 1 such that ans[i] is the number of 1's in the binary representation of i.
     */
    std::vector<int> countBits(int n) {
        // Initialize dp vector (ans) of size n + 1 with zeros
        std::vector<int> ans(n + 1, 0);

        // Iterate from 1 to n
        for (int i = 1; i <= n; ++i) {
            // DP relation: ans[i] = ans[i >> 1] + (i & 1);
            // i >> 1 is right shift (divide by 2)
            // i & 1 checks the least significant bit
            ans[i] = ans[i >> 1] + (i & 1);
        }

        return ans;
    }
};

// Example Usage:
int main() {
    Solution sol;
    int n1 = 2;
    std::vector<int> result1 = sol.countBits(n1);
    std::cout << "Input: " << n1 << ", Output: " << result1 << std::endl; // Output: [0, 1, 1]

    int n2 = 5;
    std::vector<int> result2 = sol.countBits(n2);
    std::cout << "Input: " << n2 << ", Output: " << result2 << std::endl; // Output: [0, 1, 1, 2, 1, 2]

    return 0;
}
`;
