const solutionCodeJava = `
import java.util.ArrayList;
import java.util.List;

class Solution {
    /**
     * Inserts a new interval into a list of non-overlapping intervals, merging if necessary.
     * Assumes the initial list is sorted by start times.
     * Time: O(N), Space: O(N).
     * @param intervals Sorted list of non-overlapping intervals.
     * @param newInterval The interval to insert.
     * @return The list with the new interval inserted and merged.
     */
    public int[][] insert(int[][] intervals, int[] newInterval) {
        List<int[]> result = new ArrayList<>();
        int i = 0;
        int n = intervals.length;
        int newStart = newInterval[0];
        int newEnd = newInterval[1];

        // 1. Add intervals ending before newInterval starts
        while (i < n && intervals[i][1] < newStart) {
            result.add(intervals[i]);
            i++;
        }

        // 2. Merge overlapping intervals
        while (i < n && intervals[i][0] <= newEnd) {
            newStart = Math.min(newStart, intervals[i][0]);
            newEnd = Math.max(newEnd, intervals[i][1]);
            i++;
        }
        result.add(new int[]{newStart, newEnd}); // Add merged interval

        // 3. Add remaining intervals
        while (i < n) {
            result.add(intervals[i]);
            i++;
        }

        return result.toArray(new int[result.size()][]);
    }
}
`;
const solutionCodeCPP = `
#include <vector>
#include <algorithm> // For std::min and std::max

using namespace std;

class Solution {
public:
    /**
     * Inserts a new interval into a list of non-overlapping intervals, merging if necessary.
     * Assumes the initial list is sorted by start times.
     * Time: O(N), Space: O(N).
     * @param intervals Sorted list of non-overlapping intervals.
     * @param newInterval The interval to insert.
     * @return The list with the new interval inserted and merged.
     */
    vector<vector<int>> insert(vector<vector<int>>& intervals, vector<int>& newInterval) {
        vector<vector<int>> result;
        int i = 0;
        int n = intervals.size();
        int newStart = newInterval[0];
        int newEnd = newInterval[1];

        // 1. Add intervals ending before newInterval starts
        while (i < n && intervals[i][1] < newStart) {
            result.push_back(intervals[i]);
            i++;
        }

        // 2. Merge overlapping intervals
        while (i < n && intervals[i][0] <= newEnd) {
            newStart = min(newStart, intervals[i][0]);
            newEnd = max(newEnd, intervals[i][1]);
            i++;
        }
        result.push_back({newStart, newEnd}); // Add merged interval

        // 3. Add remaining intervals
        while (i < n) {
            result.push_back(intervals[i]);
            i++;
        }

        return result;
    }
};
`;

