// --- Trie Node Class (Helper - Stores word at end) ---
class TrieNode {
    constructor() {
        this.children = {};
        this.word = null; // Store the complete word at the end node
        // Add ID for potential Trie visualization (though focus is on grid)
        this.id = Math.random().toString(36).substring(2, 15);
    }
}

// --- Build Trie Function ---
const buildTrie = (words) => {
    const root = new TrieNode();
    for (const word of words) {
        let node = root;
        for (const char of word) {
            if (!node.children[char]) {
                node.children[char] = new TrieNode();
                 // Assign char to node for potential Trie visualization (optional)
                 // node.children[char].char = char;
                 // node.children[char].parentId = node.id;
            }
            node = node.children[char];
        }
        node.word = word; // Store the word itself
    }
    return root;
};

// --- Grid Parsing Function ---
// Input: String like '[["o","a","a","n"],["e","t","a","e"],["i","h","k","r"],["i","f","l","v"]]'
// Output: 2D array of characters or throws error
const parseGridString = (str) => {
    str = str.trim();
    if (!str.startsWith('[') || !str.endsWith(']')) {
        throw new Error("Invalid grid format. Must start/end with '[' and ']'.");
    }
    try {
        const grid = JSON.parse(str);
        if (!Array.isArray(grid)) throw new Error("Input is not an array.");
        if (grid.length === 0) return []; // Empty grid is valid
         // Check if it's a 2D array and rectangular
         if (!Array.isArray(grid[0])) throw new Error("Input is not a 2D array.");
        const cols = grid[0].length;
        if (!grid.every(row => Array.isArray(row) && row.length === cols && row.every(cell => typeof cell === 'string' && cell.length === 1))) {
             throw new Error("Grid must be a 2D array of single characters with consistent row lengths.");
        }
        // Validate characters (assuming lowercase letters based on constraints)
         const charRegex = /^[a-z]$/;
         for(let r=0; r<grid.length; r++){
             for(let c=0; c<grid[r].length; c++){
                 if(!charRegex.test(grid[r][c])){
                     throw new Error(`Invalid character '${grid[r][c]}' at [${r},${c}]. Only lowercase letters expected.`);
                 }
             }
         }
        return grid;
    } catch (e) {
        console.error("Grid Parsing JSON Error:", e);
        // Provide more specific error message if possible
        if (e instanceof SyntaxError) {
             throw new Error(`Invalid JSON format for grid: ${e.message}`);
        }
        throw new Error(`Invalid grid structure: ${e.message}`);
    }
};

// --- Words Parsing Function ---
// Input: String like '["oath","pea","eat","rain"]' or "oath,pea,eat,rain"
// Output: Array of strings or throws error
const parseWordsString = (str) => {
     str = str.trim();
     let words = [];
     try {
         if (str.startsWith('[') && str.endsWith(']')) {
             words = JSON.parse(str);
             if (!Array.isArray(words) || !words.every(w => typeof w === 'string')) {
                  throw new Error("Invalid JSON array of strings.");
             }
         } else {
             // Assume comma-separated if not JSON array
             words = str.split(',').map(w => w.trim()).filter(w => w.length > 0);
         }
          // Validate characters (assuming lowercase letters only based on constraints)
          const wordRegex = /^[a-z]*$/;
          for(const word of words){
              if(!wordRegex.test(word)){
                  throw new Error(`Word "${word}" contains invalid characters (only lowercase letters expected).`);
              }
          }
         // Remove duplicates using Set
         return [...new Set(words)];
     } catch (e) {
         console.error("Words Parsing Error:", e);
          if (e instanceof SyntaxError) {
             throw new Error(`Invalid JSON format for words: ${e.message}`);
         }
         throw new Error(`Invalid words format: ${e.message}`);
     }
};


