// --- Local Components ---
import BaseVisualizer from '../components/BaseVisualizer'; // Assuming this exists
import SolutionCodeDisplay from '../components/SolutionCodeDisplay'; // Assuming this exists
import { OnlineCompiler } from '../constants/onlineCompiler'; // Assuming this exists
import { sleep } from '../utils/helpers'; // Assuming this exists

// --- Problem Specific Constants ---
const LEETCODE_NUMBER = 206;
const PROBLEM_TITLE = "Reverse Linked List";
const PROBLEM_DIFFICULTY = "Easy";
const DIFFICULTY_COLOR = "success";

// --- Helper: ListNode Definition (for comments/docs) ---
const listNodeDefinitionJS = `
/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 * this.val = (val===undefined ? 0 : val)
 * this.next = (next===undefined ? null : next)
 * }
 */`;

// --- Solution Code Strings ---
const solutionCodeJS = `
${listNodeDefinitionJS}
/**
 * Reverses a singly linked list iteratively.
 * Time: O(N), Space: O(1)
 * @param {ListNode} head The head of the linked list.
 * @return {ListNode} The new head of the reversed linked list.
 */
const reverseList = function(head) {
    let prev = null;
    let current = head;
    let nextTemp = null;

    while (current !== null) {
        nextTemp = current.next; // Store next node
        current.next = prev;     // Reverse current node's pointer
        prev = current;          // Move prev pointer one step forward
        current = nextTemp;      // Move current pointer one step forward
    }

    return prev; // prev will be the new head
};
`;
const solutionCodePython = `
from typing import Optional

# Definition for singly-linked list.
class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    """
    Reverses a singly linked list iteratively.
    Time: O(N), Space: O(1)
    """
    def reverseList(self, head: Optional[ListNode]) -> Optional[ListNode]:
        prev = None
        current = head

        while current:
            next_temp = current.next  # Store next
            current.next = prev     # Reverse
            prev = current          # Advance prev
            current = next_temp     # Advance current

        return prev # New head
`;
const solutionCodeJava = `
/**
 * Definition for singly-linked list.
 * public class ListNode {
 * int val;
 * ListNode next;
 * ListNode() {}
 * ListNode(int val) { this.val = val; }
 * ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    /**
     * Reverses a singly linked list iteratively.
     * Time: O(N), Space: O(1)
     * @param head The head of the linked list.
     * @return The new head of the reversed linked list.
     */
    public ListNode reverseList(ListNode head) {
        ListNode prev = null;
        ListNode current = head;
        ListNode nextTemp = null;

        while (current != null) {
            nextTemp = current.next; // Store next
            current.next = prev;     // Reverse
            prev = current;          // Advance prev
            current = nextTemp;      // Advance current
        }

        return prev; // New head
    }
}
`;
const solutionCodeCPP = `
/**
 * Definition for singly-linked list.
 * struct ListNode {
 * int val;
 * ListNode *next;
 * ListNode() : val(0), next(nullptr) {}
 * ListNode(int x) : val(x), next(nullptr) {}
 * ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    /**
     * Reverses a singly linked list iteratively.
     * Time: O(N), Space: O(1)
     * @param head The head of the linked list.
     * @return The new head of the reversed linked list.
     */
    ListNode* reverseList(ListNode* head) {
        ListNode* prev = nullptr;
        ListNode* current = head;
        ListNode* nextTemp = nullptr;

        while (current != nullptr) {
            nextTemp = current->next; // Store next
            current->next = prev;     // Reverse
            prev = current;           // Advance prev
            current = nextTemp;       // Advance current
        }

        return prev; // New head
    }
};
`;

// --- Component ---
const ReverseLinkedListVisualizer = () => {
    // --- State Variables ---
    const [listInput, setListInput] = useState("[1,2,3,4,5]");
    // Node structure: { id: number, value: number, nextId: number | null, state: 'default' | 'processing' | 'reversed' }
    const [nodes, setNodes] = useState([]);
    // Pointer structure: { prev: number | null, current: number | null, nextTemp: number | null } (values are node ids)
    const [pointers, setPointers] = useState({ prev: null, current: null, nextTemp: null });

    // Standard State
    const [message, setMessage] = useState(`Enter list values (e.g., [1,2,3]).`);
    const [errorMessage, setErrorMessage] = useState("");
    const [isRunning, setIsRunning] = useState(false);
    const [finalResult, setFinalResult] = useState(null); // Stores the final head node value
    const stopRef = useRef(false);
    const [isAudioEnabled, setIsAudioEnabled] = useState(true);
    const [isSpeechEnabled, setIsSpeechEnabled] = useState(true);

    // --- Audio/Speech API Setup (Standard Boilerplate) ---
    const audioContextRef = useRef(null);
    const initAudioContext = useCallback(() => { /* ... (standard code) ... */ if (!isAudioEnabled) return; if (audioContextRef.current === null && typeof window !== 'undefined' && (window.AudioContext || window.webkitAudioContext)) { try { audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { console.error("Web Audio API not supported.", e); setIsAudioEnabled(false); setMessage("Audio tones disabled: Not supported."); } } if (audioContextRef.current && audioContextRef.current.state === 'suspended') { audioContextRef.current.resume().catch(e => console.error("Audio resume failed", e)); } }, [isAudioEnabled]);
    const playTone = useCallback((frequency = 440, duration = 0.1, type = 'sine', volume = 0.3) => { /* ... (standard code) ... */ if (!isAudioEnabled || !audioContextRef.current || audioContextRef.current.state !== 'running') return; try { const oscillator = audioContextRef.current.createOscillator(); const gainNode = audioContextRef.current.createGain(); oscillator.type = type; oscillator.frequency.setValueAtTime(frequency, audioContextRef.current.currentTime); gainNode.gain.setValueAtTime(volume, audioContextRef.current.currentTime); gainNode.gain.exponentialRampToValueAtTime(0.0001, audioContextRef.current.currentTime + duration); oscillator.connect(gainNode); gainNode.connect(audioContextRef.current.destination); oscillator.start(audioContextRef.current.currentTime); oscillator.stop(audioContextRef.current.currentTime + duration); } catch (e) { console.error("Error playing tone:", e); } }, [isAudioEnabled]);
    const playPointerMoveSound = useCallback(() => playTone(600, 0.07, 'square', 0.18), [playTone]);
    const playReverseSound = useCallback(() => playTone(800, 0.1, 'triangle', 0.2), [playTone]);
    const playStoreNextSound = useCallback(() => playTone(500, 0.06, 'sine', 0.15), [playTone]);
    const playStartSound = useCallback(() => playTone(440, 0.1, 'sine', 0.3), [playTone]);
    const playEndSound = useCallback(() => playTone(1100, 0.2, 'sine', 0.3), [playTone]);
    const playStopSound = useCallback(() => playTone(220, 0.15, 'square', 0.3), [playTone]);
    const playErrorSound = useCallback(() => playTone(150, 0.3, 'sawtooth', 0.3), [playTone]);
    const speak = useCallback((text) => { /* ... (standard code) ... */ return new Promise((resolve) => { if (!isSpeechEnabled || typeof window === 'undefined' || !window.speechSynthesis) { resolve(); return; } try { window.speechSynthesis.cancel(); const utterance = new SpeechSynthesisUtterance(text); utterance.lang = 'en-US'; utterance.rate = 1.1; utterance.pitch = 1.0; utterance.volume = 0.8; utterance.onend = () => resolve(); utterance.onerror = (event) => { console.error("Speech synthesis error:", event.error); resolve(); }; window.speechSynthesis.speak(utterance); } catch (e) { console.error("Error initiating speech synthesis:", e); resolve(); } }); }, [isSpeechEnabled]);
    const cancelSpeech = useCallback(() => { /* ... (standard code) ... */ if (typeof window !== 'undefined' && window.speechSynthesis) { window.speechSynthesis.cancel(); } }, []);

    // --- Input Parsing and Validation ---
    const parseAndValidateInput = useCallback(() => {
        setMessage("");
        setErrorMessage("");
        let nodeValues = [];
        try {
            const rawInput = JSON.parse(listInput.trim());
            if (!Array.isArray(rawInput)) {
                throw new Error("Input must be an array of values (e.g., [1,2,3]).");
            }
            if (!rawInput.every(n => typeof n === 'number' || typeof n === 'string')) { // Allow strings too
                 throw new Error("Array must contain numbers or strings.");
            }
            nodeValues = rawInput;

            // Create node structure for visualization
            const initialNodes = nodeValues.map((value, index) => ({
                id: index, // Use index as unique ID
                value: value,
                nextId: index < nodeValues.length - 1 ? index + 1 : null,
                state: 'default',
            }));

            setNodes(initialNodes);
            setPointers({ prev: null, current: initialNodes.length > 0 ? 0 : null, nextTemp: null }); // Start current at head (id 0)
            setFinalResult(null);

            return { headId: initialNodes.length > 0 ? 0 : null }; // Return the ID of the head node

        } catch (e) {
            console.error("Input Parsing Error:", e);
            const errorMsg = `Input Error: ${e.message || "Invalid format."}`;
            setErrorMessage(errorMsg);
            setMessage(errorMsg);
            setNodes([]);
            setPointers({ prev: null, current: null, nextTemp: null });
            playErrorSound();
            return null; // Indicate failure
        }
    }, [listInput, playErrorSound]);

    // --- Reset Function ---
    const reset = useCallback((isInitial = false) => {
        stopRef.current = true;
        cancelSpeech();
        setIsRunning(false);
        setFinalResult(null);
        setMessage("");
        setErrorMessage("");

        const parseResult = parseAndValidateInput();

        if (parseResult === null && !isInitial) {
            // Error handled by parseAndValidateInput
        } else if (parseResult !== null) {
            setMessage(isInitial ? `Enter list values (e.g., [1,2,3]).` : "Ready. Click Run.");
        } else {
            setMessage(`Enter list values. Check format.`);
            setNodes([]);
             setPointers({ prev: null, current: null, nextTemp: null });
        }
    }, [parseAndValidateInput, cancelSpeech]);

    // --- Effects ---
    useEffect(() => { reset(true); return () => { stopRef.current = true; cancelSpeech(); if (audioContextRef.current) { audioContextRef.current.close().catch(e => console.error("Error closing AudioContext:", e)); audioContextRef.current = null; } }; /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, []);
    useEffect(() => { const handler = setTimeout(() => { if (!isRunning) { reset(true); } }, 500); return () => clearTimeout(handler); }, [listInput, reset, isRunning]);

    // --- Visualization Logic ---
    const runVisualization = async () => {
        initAudioContext();
        cancelSpeech();
        reset(false); // Reset and validate
        await sleep(50);

        if (errorMessage || nodes.length === 0) {
            if (nodes.length === 0 && !errorMessage) setMessage("List is empty. Nothing to reverse.");
            setIsRunning(false);
            return;
        }

        const parseResult = parseAndValidateInput(); // Re-parse to get headId
        if (!parseResult) { setIsRunning(false); return; }
        // let { headId } = parseResult; // Not strictly needed if pointers state is set correctly

        stopRef.current = false;
        setIsRunning(true);
        setFinalResult(null);
        playStartSound();
        await speak(`Starting Reverse Linked List visualization.`);
        if (stopRef.current) { setIsRunning(false); return; }

        // --- Algorithm State ---
        let currentNodes = JSON.parse(JSON.stringify(nodes)); // Deep copy for manipulation
        let currentPointers = { prev: null, current: nodes.length > 0 ? 0 : null, nextTemp: null };

        // --- Helper ---
        const syncUI = async (delay = 700) => {
            setNodes([...currentNodes]);
            setPointers({ ...currentPointers });
            await sleep(delay);
            if (stopRef.current) throw new Error("Stopped");
        };

        const getNodeById = (id) => currentNodes.find(n => n.id === id);
        const updateNodeState = (id, newState) => {
            const node = getNodeById(id);
            if (node) node.state = newState;
        };
         const updateNodeNext = (id, nextId) => {
            const node = getNodeById(id);
            if (node) node.nextId = nextId;
        };

        // --- Main Loop ---
        try {
            setMessage("Initializing pointers: prev = null, current = head.");
            await syncUI(1000);

            while (currentPointers.current !== null) {
                const currentNodeId = currentPointers.current;
                const currentNode = getNodeById(currentNodeId);
                if (!currentNode) break; // Should not happen

                updateNodeState(currentNodeId, 'processing');
                setMessage(`Current node: ${currentNode.value} (ID: ${currentNodeId}).`);
                await speak(`Current node ${currentNode.value}.`);
                playPointerMoveSound();
                await syncUI(600);

                // 1. Store next
                currentPointers.nextTemp = currentNode.nextId;
                setMessage(`Store next node (ID: ${currentPointers.nextTemp ?? 'null'}) in nextTemp.`);
                await speak(`Store next node.`);
                playStoreNextSound();
                if (currentPointers.nextTemp !== null) updateNodeState(currentPointers.nextTemp, 'next'); // Highlight next
                await syncUI(800);
                if (currentPointers.nextTemp !== null) updateNodeState(currentPointers.nextTemp, 'default'); // Remove highlight

                // 2. Reverse current node's pointer
                setMessage(`Reverse current node's pointer: current.next = prev (ID: ${currentPointers.prev ?? 'null'}).`);
                await speak(`Reverse pointer.`);
                updateNodeNext(currentNodeId, currentPointers.prev);
                updateNodeState(currentNodeId, 'reversed'); // Mark as reversed visually
                playReverseSound();
                await syncUI(900);

                // 3. Move prev pointer forward
                setMessage(`Move prev pointer to current node (ID: ${currentNodeId}).`);
                await speak(`Move previous pointer.`);
                currentPointers.prev = currentNodeId;
                playPointerMoveSound();
                 await syncUI(700);

                // 4. Move current pointer forward
                setMessage(`Move current pointer to nextTemp (ID: ${currentPointers.nextTemp ?? 'null'}).`);
                await speak(`Move current pointer.`);
                currentPointers.current = currentPointers.nextTemp;
                 playPointerMoveSound();
                await syncUI(700);

                 if (stopRef.current) break;
            } // End while loop

            // --- Final State ---
             if (stopRef.current) {
                setMessage("Visualization stopped by user.");
                speak("Visualization stopped.");
                playStopSound();
            } else {
                const finalHeadNode = getNodeById(currentPointers.prev);
                const finalHeadValue = finalHeadNode ? finalHeadNode.value : 'null';
                setMessage(`Finished Reversing. New head node value: ${finalHeadValue}.`);
                await speak(`Finished. New head is ${finalHeadValue}.`);
                playEndSound();
                setFinalResult(finalHeadValue); // Set final answer
                // Mark all nodes as reversed (except potentially null head)
                currentNodes.forEach(node => node.state = 'reversed');
                await syncUI(100); // Final sync
            }

        } catch (error) {
            if (error.message === "Stopped") {
                setMessage("Visualization stopped by user.");
                playStopSound();
            } else {
                console.error("Visualization error:", error);
                setErrorMessage("An unexpected error occurred during visualization.");
                setMessage("An unexpected error occurred.");
                playErrorSound();
            }
        } finally {
            setIsRunning(false);
            stopRef.current = false;
        }
    };

    // --- Control Functions (Standard Boilerplate) ---
     const stopVisualization = () => { stopRef.current = true; cancelSpeech(); setMessage("Stopping visualization..."); };
     const toggleAudio = () => { const newState = !isAudioEnabled; setIsAudioEnabled(newState); if (newState) { initAudioContext(); setTimeout(() => playTone(500, 0.05, 'sine', 0.2), 50); } else { playTone(300, 0.05, 'square', 0.2); if (audioContextRef.current && audioContextRef.current.state === 'running') { audioContextRef.current.suspend().catch(e => console.error("Audio context suspend failed", e)); } } };
     const toggleSpeech = () => { const newState = !isSpeechEnabled; if (newState && (typeof window === 'undefined' || !window.speechSynthesis)) { const msg = "Speech synthesis not supported by your browser."; setErrorMessage(msg); setMessage(msg); setTimeout(() => { if (errorMessage === msg) { setErrorMessage(""); setMessage(""); } }, 3000); return; } setIsSpeechEnabled(newState); if (!newState) { cancelSpeech(); } else { speak("Speech enabled."); } };

    // --- Render ---
    const formattedResult = finalResult !== null ? `Result: New Head = ${finalResult}` : null;

    // --- Helper for Node Appearance ---
    const getNodeAppearance = (state) => {
        switch (state) {
            case 'processing': return { bgcolor: 'info.light', color: 'info.contrastText', border: '2px solid', borderColor: 'info.dark' };
            case 'reversed': return { bgcolor: 'success.light', color: 'success.contrastText', border: '1px solid', borderColor: 'success.dark' };
             case 'next': return { bgcolor: 'secondary.light', color: 'secondary.contrastText', border: '2px dashed', borderColor: 'secondary.dark' }; // Highlight for nextTemp
            default: return { bgcolor: 'grey.100', color: 'text.secondary', border: '1px solid', borderColor: 'grey.300' };
        }
    };

    // Helper to find node position for pointer placement
    const getNodePosition = (nodeId) => {
        const index = nodes.findIndex(n => n.id === nodeId);
        // Basic positioning logic, assuming horizontal layout
        // This would need refinement for a proper graphical layout library
        return {
            left: `${index * 100 + 50}px`, // Example positioning
            top: '10px', // Adjust as needed
        };
    };


    return (
        <>
            <BaseVisualizer
                problemSummary={
                    <>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                            <Typography variant="h4" component="h1">{`#${LEETCODE_NUMBER}. ${PROBLEM_TITLE}`}</Typography>
                            <Chip label={PROBLEM_DIFFICULTY} color={DIFFICULTY_COLOR} size="small" variant="filled" />
                        </Box>
                        <Typography variant="body1" component="div" sx={{ mb: 2 }}>
                           Given the <code>head</code> of a singly linked list, reverse the list, and return the reversed list.
                           <br/><br/>
                           {/* Including ListNode definition for context */}
                           <Typography variant="caption" component="pre" sx={{ bgcolor: 'action.hover', p: 1, borderRadius: 1, display: 'block' }}>
                               <code>{listNodeDefinitionJS}</code>
                           </Typography>
                        </Typography>
                        <Typography variant="h6" component="h3" sx={{ mt: 2, mb: 1 }}>Example:</Typography>
                        <Box sx={{ bgcolor: 'action.hover', p: 1.5, borderRadius: 1, fontFamily: 'monospace', mb: 2, fontSize: '0.875rem' }}>
                            <strong>Input:</strong> head = [1,2,3,4,5]<br/>
                            <strong>Output:</strong> [5,4,3,2,1]
                            <br/><br/>
                            <strong>Input:</strong> head = [1,2]<br/>
                            <strong>Output:</strong> [2,1]
                             <br/><br/>
                             <strong>Input:</strong> head = []<br/>
                            <strong>Output:</strong> []
                        </Box>
                        <Typography variant="h6" component="h3" sx={{ mt: 2, mb: 1 }}>Constraints:</Typography>
                        <Box component="ul" sx={{ pl: 2, mb: 2 }}>
                             <li>The number of nodes in the list is the range <code>[0, 5000]</code>.</li>
                             <li><code>-5000 &lt;= Node.val &lt;= 5000</code></li>
                        </Box>
                        <Divider sx={{ my: 3 }} />
                        <Typography variant="h6" sx={{ mb: 1 }}>Runnable Solution Code Examples (Iterative)</Typography>
                        <Typography variant="subtitle2" sx={{ mb: 0.5 }}>JavaScript:</Typography><SolutionCodeDisplay codeString={solutionCodeJS} language="javascript" />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>Python:</Typography><SolutionCodeDisplay codeString={solutionCodePython} language="python" />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>Java:</Typography><SolutionCodeDisplay codeString={solutionCodeJava} language="java" />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>C++:</Typography><SolutionCodeDisplay codeString={solutionCodeCPP} language="cpp" />
                        <Divider sx={{ my: 3 }} />
                        <Typography variant="subtitle1" gutterBottom>Algorithm Analysis (Iterative)</Typography>
                        <Typography variant="body2" color="text.secondary"><strong>Time Complexity:</strong> <code>O(N)</code> - We visit each node once.</Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}><strong>Space Complexity:</strong> <code>O(1)</code> - We only use a few extra pointers.</Typography>
                    </>
                }
                controls={
                    <>
                         <Typography variant="subtitle1" sx={{ textAlign: 'center', fontWeight: 'bold', p: 0.75, mb: 2.5, borderRadius: '4px', color: 'common.white', background: 'linear-gradient(45deg, #2196F3 30%, #64B5F6 90%)', boxShadow: 1 }}> {/* Example Styling */}
                             {PROBLEM_TITLE} Visualizer Controls
                         </Typography>
                         <MuiGrid container spacing={1.5} alignItems="center" mb={2}>
                            {/* Input Field */}
                            <MuiGrid item xs={12} md={8}>
                                <TextField
                                    fullWidth
                                    id="list-input"
                                    label="List Values (e.g., [1,2,3,4,5])"
                                    variant="outlined"
                                    size="small"
                                    value={listInput}
                                    onChange={(e) => setListInput(e.target.value)}
                                    placeholder="[1,2,3,4,5]"
                                    disabled={isRunning}
                                    error={!!errorMessage}
                                    InputProps={{ sx: { fontFamily: 'monospace' } }}
                                />
                            </MuiGrid>
                             {/* Control Buttons */}
                             <MuiGrid item xs={4} sm={2} md={1} sx={{ display: 'flex' }}> <Tooltip title={isRunning ? "Stop Visualization" : "Run Visualization"}><span><Button fullWidth variant="contained" sx={{ height: '40px' }} startIcon={isRunning && !stopRef.current ? <CircularProgress size={20} color="inherit" /> : <PlayArrowIcon />} onClick={isRunning ? stopVisualization : runVisualization} color={isRunning ? "warning" : "primary"} disabled={isRunning && stopRef.current}>{isRunning && !stopRef.current ? 'Running' : (isRunning && stopRef.current ? 'Stopping' : 'Run')}</Button></span></Tooltip> </MuiGrid>
                             <MuiGrid item xs={4} sm={2} md={1} sx={{ display: 'flex' }}> <Tooltip title="Reset Visualization and Input"><span><Button fullWidth variant="outlined" startIcon={<ReplayIcon />} onClick={() => reset(false)} disabled={isRunning} sx={{ height: '40px' }}>Reset</Button></span></Tooltip> </MuiGrid>
                             <MuiGrid item xs={4} sm={2} md={1} sx={{ display: 'flex' }}> <Tooltip title={isAudioEnabled ? "Mute Tones" : "Unmute Tones"}><Button fullWidth variant="outlined" onClick={toggleAudio} sx={{ height: '40px', minWidth: 'auto', p: 1 }}>{isAudioEnabled ? <VolumeUpIcon /> : <VolumeOffIcon />}</Button></Tooltip> </MuiGrid>
                             <MuiGrid item xs={4} sm={2} md={1} sx={{ display: 'flex' }}> <Tooltip title={isSpeechEnabled ? "Disable Speech" : "Enable Speech"}><Button fullWidth variant="outlined" onClick={toggleSpeech} sx={{ height: '40px', minWidth: 'auto', p: 1 }}>{isSpeechEnabled ? <RecordVoiceOverIcon /> : <VoiceOverOffIcon />}</Button></Tooltip> </MuiGrid>
                         </MuiGrid>
                    </>
                }
                displayArea={
                    <>
                        <Typography variant="subtitle1" gutterBottom align="center">{PROBLEM_TITLE} Visualization</Typography>

                        {/* Pointer Display */}
                        <Stack direction="row" spacing={2} justifyContent="center" mb={2} flexWrap="wrap">
                            <Chip label={`Prev: ${pointers.prev === null ? 'null' : nodes.find(n=>n.id===pointers.prev)?.value ?? '?' }`} variant="outlined" color="secondary" icon={<HelpOutlineIcon />} size="small"/>
                            <Chip label={`Current: ${pointers.current === null ? 'null' : nodes.find(n=>n.id===pointers.current)?.value ?? '?' }`} variant="filled" color="primary" icon={<InputIcon />} size="small"/>
                            <Chip label={`NextTemp: ${pointers.nextTemp === null ? 'null' : nodes.find(n=>n.id===pointers.nextTemp)?.value ?? '?' }`} variant="outlined" color="info" icon={<SwapHorizIcon />} size="small"/>
                        </Stack>

                        {/* Linked List Visualization */}
                        <Paper variant="outlined" sx={{ p: 2, mb: 2, display: 'flex', flexWrap: 'wrap', gap: '20px', alignItems: 'center', minHeight: '80px', position: 'relative' }}>
                             {nodes.length > 0 ? nodes.map((node, index) => {
                                const appearance = getNodeAppearance(node.state);
                                const isCurrent = node.id === pointers.current;
                                const isPrev = node.id === pointers.prev;
                                // const isNextTemp = node.id === pointers.nextTemp; // Less important to highlight directly on node

                                return (
                                    <React.Fragment key={node.id}>
                                        <Tooltip title={`Value: ${node.value}, State: ${node.state}, Next ID: ${node.nextId ?? 'null'}`}>
                                             <Chip
                                                // icon={isCurrent ? <InputIcon /> : (isPrev ? <HelpOutlineIcon /> : null)}
                                                label={String(node.value)}
                                                size="medium"
                                                sx={{
                                                    ...appearance,
                                                    minWidth: 50,
                                                    fontWeight: isCurrent || isPrev ? 'bold' : 'normal',
                                                    transform: isCurrent ? 'scale(1.1)' : 'scale(1.0)',
                                                    boxShadow: isCurrent ? 3 : 1,
                                                    transition: 'all 0.3s ease',
                                                    zIndex: 1, // Ensure chips are above arrows
                                                }}
                                            />
                                        </Tooltip>
                                        {/* Basic Arrow Representation */}
                                        {node.nextId !== null && (
                                             <ArrowForwardIcon sx={{
                                                 color: node.state === 'reversed' ? 'success.main' : 'action.disabled',
                                                 transform: node.state === 'reversed' ? 'rotate(180deg)' : 'rotate(0deg)', // Flip arrow if reversed
                                                 transition: 'transform 0.5s ease, color 0.5s ease',
                                                 mx: -1, // Adjust spacing
                                             }} />
                                        )}
                                         {node.nextId === null && index === nodes.length - 1 && (
                                            <Typography variant="caption" sx={{ ml: 1, color: 'text.secondary' }}>null</Typography>
                                        )}
                                    </React.Fragment>
                                );
                            }) : (
                                 <Typography variant="caption" color="text.secondary" align="center" sx={{width: '100%'}}>{errorMessage ? "Invalid Input" : "Enter list values..."}</Typography>
                            )}
                             {/* Pointer Indicators (Simplified) - Needs better positioning logic for accuracy */}
                             {/* <Box sx={{ position: 'absolute', ...getNodePosition(pointers.prev), color: 'secondary.main', fontSize: '0.8rem' }}>Prev</Box>
                             <Box sx={{ position: 'absolute', ...getNodePosition(pointers.current), color: 'primary.main', fontSize: '0.8rem', fontWeight: 'bold' }}>Current</Box> */}
                        </Paper>

                    </>
                }
                message={message}
                result={formattedResult}
            />
            {/* Online Compiler Section */}
            <Container maxWidth="xl" sx={{ mt: 4, mb: 4 }}>
                 <Typography variant="h5" component="h2" gutterBottom>Test with Online Compiler</Typography>
                 <OnlineCompiler />
            </Container>
        </>
    );
};

export default ReverseLinkedListVisualizer;
