import React from 'react';
import { Box, Chip, Typography, useTheme } from '@mui/material';

// Generic component to display array elements using MUI Box/Chip
const ArrayElement = ({ value, index, state = 'default', type = 'box', maxHeight = 150, maxValue = 100, pointers = [] }) => {
    const theme = useTheme(); // Access theme for transitions and palette

    // Map state strings to MUI sx styles
    const getStateStyles = (currentState) => {
        // Define base styles for default and dimmed states that adapt to the theme mode
        const defaultBgColor = theme.palette.mode === 'light' ? theme.palette.grey[200] : theme.palette.grey[700];
        const defaultBorderColor = theme.palette.mode === 'light' ? theme.palette.grey[400] : theme.palette.grey[600];
        const dimmedBgColor = theme.palette.mode === 'light' ? theme.palette.grey[300] : theme.palette.grey[600]; // A bit darker for dimmed in dark mode
        const searchSpaceBgColor = theme.palette.mode === 'light' ? theme.palette.grey[100] : theme.palette.grey[800];


        switch (currentState) {
            // General States
            case 'default': return {
                bgcolor: defaultBgColor,
                border: '1px solid',
                borderColor: defaultBorderColor,
                color: theme.palette.text.primary, // Ensure text color is from theme
                opacity: 1
            };
            case 'checking': return {
                bgcolor: theme.palette.warning.light, // Uses theme's warning.light
                border: '2px solid',
                borderColor: theme.palette.warning.main, // Uses theme's warning.main
                transform: 'scale(1.08)',
                filter: 'brightness(1.1)'
            };
            case 'highlight': return {
                bgcolor: theme.palette.primary.light,
                border: '2px solid',
                borderColor: theme.palette.primary.main,
                transform: 'scale(1.05)'
            };
            case 'found': return { // This 'found' is generic, specific 'highlight-found' or 'highlight-triplet-found' might be preferred
                bgcolor: theme.palette.success.light,
                border: '2px solid',
                borderColor: theme.palette.success.main,
                color: theme.palette.getContrastText(theme.palette.success.light), // Ensure contrast
                transform: 'scale(1.1)'
            };
            case 'sorted': return {
                bgcolor: theme.palette.info.light,
                border: '1px solid',
                borderColor: theme.palette.info.main
            };
            case 'pivot': return {
                bgcolor: theme.palette.secondary.light,
                border: '2px solid',
                borderColor: theme.palette.secondary.main,
                transform: 'scale(1.1)'
            };
            case 'swap': return {
                bgcolor: theme.palette.secondary.light,
                border: '2px solid',
                borderColor: theme.palette.secondary.dark,
                transform: 'scale(1.15)',
                transition: 'transform 0.3s ease!' // Keep specific transition if needed
            };
            case 'dimmed': return {
                bgcolor: dimmedBgColor,
                border: '1px solid',
                borderColor: defaultBorderColor, // Can use defaultBorderColor or theme.palette.divider
                opacity: 0.5,
                color: theme.palette.text.disabled // Use disabled text color for dimmed items
            };
            case 'result-array': return { // PES Result
                bgcolor: theme.palette.info.lighter, // This is a custom shade, ensure it's defined in both light/dark theme palettes
                border: '1px solid',
                borderColor: theme.palette.info.light,
                color: theme.palette.getContrastText(theme.palette.info.lighter)
            };
            case 'result-array-highlight-update': return { // PES Result Update
                bgcolor: theme.palette.info.light,
                border: '2px solid',
                borderColor: theme.palette.info.dark,
                transform: 'scale(1.1)'
            };
            case 'highlight-final': return { // PES Final Result
                bgcolor: theme.palette.success.main,
                border: '1px solid',
                borderColor: theme.palette.success.dark,
                color: theme.palette.success.contrastText // Already using contrastText
            };

            // Two Sum Specific
            case 'highlight-checking': return { // Same as 'checking', can be consolidated if identical
                bgcolor: theme.palette.warning.light,
                border: '2px solid',
                borderColor: theme.palette.warning.main,
                transform: 'scale(1.08)',
                filter: 'brightness(1.1)'
            };
            case 'highlight-i': return { // Lighter primary for non-found elements
                bgcolor: theme.palette.primary.lighter, // Custom shade, ensure defined in both themes
                border: '2px solid',
                borderColor: theme.palette.primary.light
            };
            case 'highlight-found': return { // Specific for Two Sum found pair
                bgcolor: theme.palette.success.main,
                border: '2px solid',
                borderColor: theme.palette.success.dark,
                color: theme.palette.success.contrastText,
                transform: 'scale(1.1)'
            };

            // Max Profit Specific
            case 'highlight-current': return { // Current day being checked
                bgcolor: theme.palette.warning.light,
                border: '2px solid',
                borderColor: theme.palette.warning.main,
                transform: 'scale(1.05)'
            };
            case 'highlight-min-price': return { // Bar color for min price day
                bgcolor: theme.palette.success.dark, // Or a specific theme color
                color: theme.palette.success.contrastText
            };
            case 'highlight-potential-profit': return { // Bar color for potential max profit day
                bgcolor: theme.palette.secondary.main, // Or a specific theme color
                color: theme.palette.secondary.contrastText
            };

            // Contains Duplicate Specific
            case 'highlight-current-cd': return {
                bgcolor: theme.palette.primary.lighter,
                border: '2px solid',
                borderColor: theme.palette.primary.main,
                transform: 'scale(1.05)'
            };
            case 'highlight-added': return { // Added to set
                bgcolor: theme.palette.success.light,
                border: '1px solid',
                borderColor: theme.palette.success.main,
                transform: 'scale(1.1)',
                transition: 'transform 0.3s ease!'
            };
            case 'highlight-duplicate-set': return { // Duplicate in set
                bgcolor: theme.palette.error.main,
                border: '2px solid',
                borderColor: theme.palette.error.dark,
                color: theme.palette.error.contrastText,
                transform: 'scale(1.1)'
            };
            case 'highlight-duplicate-found': return { // Duplicate in array
                bgcolor: theme.palette.error.light,
                border: '2px solid',
                borderColor: theme.palette.error.dark,
                color: theme.palette.getContrastText(theme.palette.error.light), // Ensure contrast
                transform: 'scale(1.1)'
            };

            // Product Except Self Specific
            case 'highlight-current-pes': return {
                bgcolor: theme.palette.secondary.lighter, // Custom shade
                border: '2px solid',
                borderColor: theme.palette.secondary.main,
                transform: 'scale(1.05)'
            };

            // Max Subarray Specific
            case 'highlight-current-msa': return {
                bgcolor: theme.palette.warning.light,
                border: '2px solid',
                borderColor: theme.palette.warning.main,
                transform: 'scale(1.08)',
                filter: 'brightness(1.1)'
            };
            case 'highlight-current-subarray': return {
                bgcolor: theme.palette.primary.lighter,
                border: '1px dashed',
                borderColor: theme.palette.primary.main,
                opacity: 0.8
            };
            case 'highlight-max-subarray': return {
                bgcolor: theme.palette.success.light,
                border: '2px solid',
                borderColor: theme.palette.success.main
            };

            // Find Min / Search Rotated Specific
            case 'highlight-search-space': return {
                bgcolor: searchSpaceBgColor,
                border: '1px solid',
                borderColor: defaultBorderColor, // Or theme.palette.divider
                opacity: 1,
                color: theme.palette.text.primary
            };
            case 'dimmed-fmr': return { // Similar to 'dimmed'
                bgcolor: dimmedBgColor,
                border: '1px solid',
                borderColor: defaultBorderColor,
                opacity: 0.4, // Slightly more dimmed
                color: theme.palette.text.disabled
            };
            case 'highlight-final-min': return {
                bgcolor: theme.palette.success.main,
                border: '2px solid',
                borderColor: theme.palette.success.dark,
                color: theme.palette.success.contrastText,
                transform: 'scale(1.1)'
            };
            case 'highlight-target-found': return { // Search Rotated
                bgcolor: theme.palette.success.main,
                border: '2px solid',
                borderColor: theme.palette.success.dark,
                color: theme.palette.success.contrastText,
                transform: 'scale(1.1)'
            };

            // 3Sum Specific
            case 'highlight-i-3sum': return {
                bgcolor: theme.palette.secondary.light,
                border: '2px solid',
                borderColor: theme.palette.secondary.main,
                transform: 'scale(1.05)'
            };
            case 'highlight-left-3sum': return {
                bgcolor: theme.palette.primary.lighter,
                border: '2px solid',
                borderColor: theme.palette.primary.main,
                transform: 'scale(1.05)'
            };
            case 'highlight-right-3sum': return {
                bgcolor: theme.palette.error.lighter, // Custom shade
                border: '2px solid',
                borderColor: theme.palette.error.main,
                transform: 'scale(1.05)'
            };
            case 'highlight-triplet-found': return {
                bgcolor: theme.palette.success.main,
                border: '2px solid',
                borderColor: theme.palette.success.dark,
                color: theme.palette.success.contrastText,
                transform: 'scale(1.1)'
            };

            // Container Most Water Specific
            case 'highlight-left-cmw': return {
                bgcolor: theme.palette.primary.light,
                border: '2px solid',
                borderColor: theme.palette.primary.main
            };
            case 'highlight-right-cmw': return {
                bgcolor: theme.palette.error.light,
                border: '2px solid',
                borderColor: theme.palette.error.main
            };
            case 'highlight-container': return { // Dim elements not part of current container
                opacity: 0.7,
                // Consider if a specific background/border is needed or if opacity is enough
            };

            default: return {
                bgcolor: defaultBgColor,
                border: '1px solid',
                borderColor: defaultBorderColor,
                color: theme.palette.text.primary,
                opacity: 1
            };
        }
    };

    // Map pointer names to MUI Chip styles
    // Chip component itself is theme-aware for its 'color' prop.
    const getPointerChip = (pointerName) => {
        let color = 'default';
        let label = pointerName;
        // This logic can remain largely the same as Chip's color prop handles theming.
        switch (pointerName.toLowerCase()) { // Standardize to lowercase for matching
            case 'left': color = 'primary'; break;
            case 'right': color = 'error'; break;
            case 'mid': color = 'success'; break;
            case 'i': color = 'warning'; break;
            case 'j': color = 'secondary'; break;
            case 'pivot': color = 'secondary'; break;
            case 'found': color = 'success'; label = 'Found'; break;
            case 'min': color = 'success'; label = 'Min'; break;
            case 'buy?': color = 'success'; label = 'Buy?'; break;
            case 'sell?': color = 'secondary'; label = 'Sell?'; break;
            case 'dup!': color = 'error'; label = 'Dup!'; break;
            case 'start': color = 'success'; label = 'Start'; break;
            case 'end': color = 'success'; label = 'End'; break;
            case 'target': color = 'info'; label = 'Target'; break; // Changed to info for variety
            case 'l': color = 'primary'; label = 'L'; break;
            case 'r': color = 'error'; label = 'R'; break;
            default: color = 'default'; break; // Ensure a default case
        }
        return <Chip label={label} color={color} size="small" sx={{ mx: 0.2, fontWeight: 500 }} />;
    };

    const stateStyle = getStateStyles(state); // Get current state style

    const commonSx = {
        minWidth: { xs: 40, sm: 45 },
        minHeight: { xs: 40, sm: 45 },
        m: { xs: 0.5, sm: 1 },
        p: 1,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        position: 'relative',
        borderRadius: '8px',
        boxShadow: theme.shadows[1], // Use theme shadows
        transition: theme.transitions.create(['background-color', 'transform', 'opacity', 'border-color', 'filter', 'color'], {
            duration: theme.transitions.duration.short,
        }),
        fontFamily: 'monospace',
        fontSize: '0.9rem',
        ...stateStyle, // Apply dynamic styles (includes bgcolor, border, color, etc.)
    };

    if (type === 'bar') {
        const safeValue = typeof value === 'number' ? value : 0;
        const safeMaxValue = Math.max(1, typeof maxValue === 'number' ? maxValue : 1);
        const barHeight = Math.max(5, (Math.abs(safeValue) / safeMaxValue) * maxHeight);

        // Theme-aware gradient for bars
        // The top color of the gradient will be lighter than the bar's main color
        const gradientTopColor = theme.palette.mode === 'light'
            ? theme.palette.augmentColor({ color: { main: stateStyle.bgcolor || theme.palette.grey[200] }, mainShade: 100, lightShade: 300 }).light // Lighter version of bgcolor
            : theme.palette.augmentColor({ color: { main: stateStyle.bgcolor || theme.palette.grey[700] }, mainShade: 600, darkShade: 400 }).dark; // Darker version for dark mode, but still lighter than main

        const barBackground = stateStyle.bgcolor
            ? `linear-gradient(to top, ${stateStyle.bgcolor}, ${gradientTopColor} 200%)`
            : `linear-gradient(to top, ${theme.palette.grey[400]}, ${theme.palette.grey[100]} 300%)`; // Fallback if bgcolor isn't set by state

        return (
            <Box sx={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                position: 'relative',
                mx: { xs: 0.5, sm: 1 },
                mb: 4, // Space for pointers below
                height: maxHeight + 30, // Total height including space for value text on top
                justifyContent: 'flex-end',
                width: { xs: 30, sm: 40 },
            }} title={`Index: ${index}, Value: ${value}`}>
                {pointers.length > 0 && (
                    <Box sx={{ position: 'absolute', bottom: -28, display: 'flex', flexWrap: 'wrap', justifyContent: 'center', gap: 0.5 }}>
                        {pointers.map((p, idx) => <React.Fragment key={idx}>{getPointerChip(p)}</React.Fragment>)}
                    </Box>
                )}
                <Typography variant="caption" sx={{ position: 'absolute', top: -20, color: 'text.secondary', userSelect: 'none' }}>
                    {value}
                </Typography>
                <Box sx={{
                    width: '100%',
                    height: `${barHeight}px`,
                    background: barBackground,
                    borderRadius: '4px 4px 0 0',
                    transition: theme.transitions.create(['height', 'background', 'transform', 'border', 'border-color'], {
                        duration: theme.transitions.duration.short,
                    }),
                    transform: stateStyle.transform || 'none',
                    border: stateStyle.border || `1px solid ${theme.palette.divider}`, // Default border
                    borderColor: stateStyle.borderColor || theme.palette.divider,
                    boxShadow: theme.shadows[1],
                }} />
                <Typography variant="caption" sx={{ mt: 0.5, color: 'text.secondary', userSelect: 'none' }}>
                    {index}
                </Typography>
            </Box>
        );
    }

    // Default: Box type
    return (
        <Box sx={commonSx} title={`Index: ${index}, Value: ${value}`}>
            {pointers.length > 0 && (
                <Box sx={{ position: 'absolute', top: -28, display: 'flex', flexWrap: 'wrap', justifyContent: 'center', gap: 0.5 }}>
                    {pointers.map((p, idx) => <React.Fragment key={idx}>{getPointerChip(p)}</React.Fragment>)}
                </Box>
            )}
            {value}
            {index !== null && index !== undefined && (
                <Typography variant="caption" sx={{ position: 'absolute', bottom: -20, color: 'text.secondary', userSelect: 'none' }}>
                    {index}
                </Typography>
            )}
        </Box>
    );
};

export default ArrayElement;
