// --- Solution Code Strings (Jump Game - Greedy O(N)) ---
const jumpGameSolutionCodeJS = `
/**
 * Determines if you can reach the last index starting from the first index.
 * Each element nums[i] is the maximum jump length from that position.
 * Uses O(N) time and O(1) space greedy approach.
 * @param {number[]} nums - Array of non-negative integers (jump lengths).
 * @returns {boolean} True if the last index is reachable, false otherwise.
 */
const canJump = function(nums) {
    let maxReachable = 0; // The farthest index reachable so far
    const n = nums.length;

    for (let i = 0; i < n; i++) {
        // If the current index 'i' is beyond the farthest we could reach,
        // then it's impossible to proceed further.
        if (i > maxReachable) {
            return false;
        }
        // Update the farthest reachable index based on the jump from current index 'i'
        maxReachable = Math.max(maxReachable, i + nums[i]);

        // Optimization: If we can already reach or exceed the last index, return true
        if (maxReachable >= n - 1) {
            return true;
        }
    }
    // If the loop completes, it means we reached the end (or could have)
    // This line is technically redundant due to the optimization check inside the loop
    // but confirms reachability if the loop finishes exactly at n-1.
    return true;
};

// Example Usage:
console.log(canJump([2, 3, 1, 1, 4])); // Output: true
console.log(canJump([3, 2, 1, 0, 4])); // Output: false
console.log(canJump([0]));            // Output: true
console.log(canJump([2, 0]));          // Output: true
`;

