const jumpGameSolutionCodeCPP = `
#include <vector>
#include <algorithm> // For std::max
#include <iostream>

class Solution {
public:
    /**
     * Determines if the last index is reachable via jumps.
     * Uses O(N) time and O(1) space greedy approach.
     * @param nums Vector of non-negative integers (jump lengths).
     * @return True if the last index is reachable, false otherwise.
     */
    bool canJump(const std::vector<int>& nums) {
        int maxReachable = 0; // Farthest index reachable so far
        int n = nums.size();

        for (int i = 0; i < n; ++i) {
            // If current index 'i' is beyond our current reach
            if (i > maxReachable) {
                return false;
            }
            // Update the farthest reachable index
            maxReachable = std::max(maxReachable, i + nums[i]);

            // Optimization: If we can reach the end, return true
            if (maxReachable >= n - 1) {
                return true;
            }
        }
        // If loop completes, the end was reachable
        return true;
    }
};

// Example Usage:
int main() {
    Solution sol;
    std::vector<int> nums1 = {2, 3, 1, 1, 4};
    std::cout << std::boolalpha << "canJump({2, 3, 1, 1, 4}) = " << sol.canJump(nums1) << std::endl; // Output: true
    std::vector<int> nums2 = {3, 2, 1, 0, 4};
    std::cout << std::boolalpha << "canJump({3, 2, 1, 0, 4}) = " << sol.canJump(nums2) << std::endl; // Output: false
    std::vector<int> nums3 = {0};
    std::cout << std::boolalpha << "canJump({0}) = " << sol.canJump(nums3) << std::endl;            // Output: true
    std::vector<int> nums4 = {2, 0};
    std::cout << std::boolalpha << "canJump({2, 0}) = " << sol.canJump(nums4) << std::endl;          // Output: true
    return 0;
}
`;
