    const playCheckSound = useCallback(() => playTone(500, 0.07, 'sine', 0.18), [playTone]);
    const playUpdateReachSound = useCallback(() => playTone(700, 0.1, 'square', 0.2), [playTone]);
    const playSuccessSound = useCallback(() => playTone(1100, 0.2, 'sine', 0.3), [playTone]);
