                 if (!fastNextNode) break;

                  // Check if fast.next.next exists
                 const fastNextNextId = fastNextNode.nextId;
                 if (fastNextNextId === null) {
                     // Move fast one last step before breaking
                     currentPointers.fast = fastNextId;
                     setMessage(`Fast pointer moves to node ${fastNextNode.value}. Reached end (next is null).`);
                     await speak(`Fast pointer moves. Reached end.`);
                     playFastMoveSound();
                     await syncUI();
                     break; // Fast reached end
                 }

                 // Move slow pointer
                 const slowNode = getNodeById(currentPointers.slow);
                 const nextSlowId = slowNode ? slowNode.nextId : null;
                 currentPointers.slow = nextSlowId;
                 const nextSlowNode = getNodeById(nextSlowId);
                 setMessage(`Move slow pointer to node ${nextSlowNode?.value ?? 'null'}.`);
                 await speak(`Move slow pointer.`);
                 playSlowMoveSound();
                 await syncUI(600);
