                 // Move fast pointer
                 currentPointers.fast = fastNextNextId;
                 const nextFastNode = getNodeById(fastNextNextId);
                 setMessage(`Move fast pointer two steps to node ${nextFastNode?.value ?? 'null'}.`);
                 await speak(`Move fast pointer.`);
                 playFastMoveSound();
                 await syncUI(600);
