const NODE_RADIUS = 18;
const LEVEL_SPACING = 80;

// --- Tree Node Class (Helper) ---
class TreeNode {
    constructor(val, left = null, right = null) {
        this.val = val;
        this.left = left;
        this.right = right;
        // For visualization: unique id, position
        this.id = Math.random().toString(36).substring(2, 15); // Simple unique ID
        this.x = 0;
        this.y = 0;
        this.parentId = null;
    }
}

// --- Tree Parsing Function (Reuse - From MaxDepth) ---
const parseTreeString = (str) => {
    str = str.trim();
    if (!str.startsWith('[') || !str.endsWith(']')) {
        const num = parseInt(str, 10);
        if (!isNaN(num)) return new TreeNode(num);
        throw new Error("Invalid format. Use array like '[1,2,null,3]' or single number.");
    }
    str = str.substring(1, str.length - 1);
    if (!str) return null;
    const values = str.split(',').map(v => v.trim());
    if (values.length === 0 || values[0] === 'null') return null;
    const rootVal = parseInt(values[0], 10);
    if (isNaN(rootVal)) throw new Error(`Invalid root value: ${values[0]}`);
    const root = new TreeNode(rootVal);
    const queue = [root];
    let i = 1;
    while (queue.length > 0 && i < values.length) {
        const currentNode = queue.shift();
        // Process left child
        if (i < values.length) {
            if (values[i] !== 'null') {
                const leftVal = parseInt(values[i], 10);
                 if (isNaN(leftVal)) throw new Error(`Invalid node value: ${values[i]}`);
                currentNode.left = new TreeNode(leftVal);
                currentNode.left.parentId = currentNode.id;
                queue.push(currentNode.left);
            } i++;
        }
        // Process right child
        if (i < values.length) {
            if (values[i] !== 'null') {
                const rightVal = parseInt(values[i], 10);
                 if (isNaN(rightVal)) throw new Error(`Invalid node value: ${values[i]}`);
                currentNode.right = new TreeNode(rightVal);
                 currentNode.right.parentId = currentNode.id;
                queue.push(currentNode.right);
            } i++;
        }
    } return root;
};

// --- Calculate Node Positions (Reuse - From MaxDepth with responsiveness improvements) ---
const calculateNodePositions = (root) => {
    if (!root) return { nodes: [], nodeMap: {}, height: 0 };
    const nodes = [];
    const nodeMap = {};
    let maxLevel = 0;
    const baseHorizontalSpacing = 150; // Reduced for better fit
    const traverse = (node, level, x, parentId) => {
        if (!node) return;
        maxLevel = Math.max(maxLevel, level);
        node.y = level * LEVEL_SPACING;
        node.x = x;
        node.parentId = parentId;
        nodes.push(node);
        nodeMap[node.id] = node;
        const childrenHorizontalSpread = baseHorizontalSpacing / Math.pow(1.8, level + 1);
        traverse(node.left, level + 1, x - childrenHorizontalSpread, node.id);
        traverse(node.right, level + 1, x + childrenHorizontalSpread, node.id);
    };
    traverse(root, 0, 0, null);
    // Basic overlap adjustment
    const nodesByLevel = {};
    nodes.forEach(node => { if (!nodesByLevel[node.y]) nodesByLevel[node.y] = []; nodesByLevel[node.y].push(node); });
    Object.values(nodesByLevel).forEach(levelNodes => {
        levelNodes.sort((a, b) => a.x - b.x);
        for (let i = 1; i < levelNodes.length; i++) {
            const node1 = levelNodes[i - 1], node2 = levelNodes[i];
            const minGap = NODE_RADIUS * 2 + 10;
            const currentGap = node2.x - node1.x;
            if (currentGap < minGap) node2.x += (minGap - currentGap);
        }
    });
    // Centering
    if (nodes.length > 0) {
        let minX = Infinity, maxX = -Infinity;
        nodes.forEach(n => { minX = Math.min(minX, n.x); maxX = Math.max(maxX, n.x); });
        const treeWidth = maxX - minX;
        const centeringOffset = -minX - (treeWidth / 2);
        nodes.forEach(n => { n.x += centeringOffset; });
    }
    // Top padding
    const topPadding = NODE_RADIUS + 10;
    nodes.forEach(n => { n.y += topPadding; });
    return { nodes, nodeMap, height: (maxLevel * LEVEL_SPACING) + topPadding };
};

// --- Solution Code Strings ---
const solutionCodeJS = `
/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 * this.val = (val===undefined ? 0 : val)
 * this.left = (left===undefined ? null : left)
 * this.right = (right===undefined ? null : right)
 * }
 */
/**
 * Finds the maximum path sum in a binary tree.
 * A path is defined as any sequence of nodes from some starting node to any node
 * in the tree along the parent-child connections. The path must contain at least
 * one node and does not need to go through the root.
 *
 * Time: O(N), visits each node once.
 * Space: O(H) avg (recursion stack), O(N) worst case.
 * @param {TreeNode} root The root of the binary tree.
 * @return {number} The maximum path sum.
 */
const maxPathSum = function(root) {
    let maxSum = -Infinity; // Initialize with a very small number

    // Helper function: Calculates the max path sum *starting* from the current node
    // and going downwards (only left or right, not both split).
    // It also updates the overall maxSum considering paths that might split at the current node.
    function maxGain(node) {
        if (!node) {
            return 0; // Gain from a null node is 0
        }

        // Recursively get the maximum gain from left and right subtrees
        // Ignore paths with negative sums (better to not include them)
        const leftGain = Math.max(maxGain(node.left), 0);
        const rightGain = Math.max(maxGain(node.right), 0);

        // Calculate the maximum path sum that *includes* the current node as the highest point
        // This path might split (go left and right)
        const currentPathSum = node.val + leftGain + rightGain;

        // Update the overall maximum path sum found so far
        maxSum = Math.max(maxSum, currentPathSum);

        // Return the maximum gain *downwards* from this node
        // The path cannot split when returning upwards, so choose the better side.
        return node.val + Math.max(leftGain, rightGain);
    }

    maxGain(root); // Start the recursion
    // If the tree was empty or all nodes were negative, maxSum might remain -Infinity.
    // The problem statement implies the path must contain at least one node.
    // If the tree has nodes, the result must be at least the value of the largest node.
    // However, the standard LeetCode solution returns maxSum directly.
    // If the tree is guaranteed to have at least one node, this is fine.
    // If the tree can be empty, the result might be ambiguous (0 or error?).
    // LeetCode test cases seem to handle this by expecting the calculated maxSum.
    return maxSum;
};
`;
