import { createTheme } from '@mui/material/styles';

// Define base properties that are common to both light and dark modes
const commonTypography = {
    fontFamily: '"Inter", "Roboto", "Helvetica", "Arial", sans-serif',
    h1: {
        fontSize: '2.5rem', // 40px
        fontWeight: 700,
        letterSpacing: '-0.02em',
    },
    h2: {
        fontSize: '1.75rem', // 28px
        fontWeight: 600,
    },
    h3: {
        fontSize: '1.15rem', // ~18px
        fontWeight: 600,
    },
    h4: {
        fontSize: '1.1rem', // ~17.6px
        fontWeight: 600,
    },
    subtitle1: {
        fontSize: '0.9rem', // ~14.4px
        opacity: 0.8,
    },
};

const commonTransitions = {
    duration: {
        shortest: 150,
        shorter: 200,
        short: 250,
        standard: 300,
        complex: 375,
        enteringScreen: 225,
        leavingScreen: 195,
    },
    easing: {
        easeInOut: 'cubic-bezier(0.4, 0, 0.2, 1)',
        easeOut: 'cubic-bezier(0.0, 0, 0.2, 1)',
        easeIn: 'cubic-bezier(0.4, 0, 1, 1)',
        sharp: 'cubic-bezier(0.4, 0, 0.6, 1)',
    },
};

const commonComponents = (mode) => ({
    MuiCard: {
        styleOverrides: {
            root: ({ theme }) => ({
                borderRadius: '12px',
                boxShadow: theme.shadows[mode === 'light' ? 2 : 3], // Subtle shadow for dark cards
                transition: theme.transitions.create(['box-shadow', 'transform', 'border-color', 'background-color'], {
                    duration: theme.transitions.duration.short,
                }),
                '&:hover': {
                    boxShadow: theme.shadows[mode === 'light' ? 6 : 7],
                    transform: 'translateY(-4px)',
                    borderColor: theme.palette.primary.light,
                },
                border: `1px solid ${theme.palette.divider}`, // Use divider for border
                overflow: 'hidden',
                backgroundColor: theme.palette.background.paper,
            }),
        },
    },
    MuiCardHeader: {
        styleOverrides: {
            root: ({theme}) => ({
                borderBottom: `1px solid ${theme.palette.divider}`,
            }),
            avatar: {
                fontSize: '1.8rem',
            }
        }
    },
    MuiButton: {
        styleOverrides: {
            root: {
                borderRadius: '8px',
                textTransform: 'none',
                fontWeight: 600,
            },
        },
    },
    MuiChip: {
        styleOverrides: {
            root: {
                fontWeight: 500,
            },
        },
    },
    MuiDialog: {
        styleOverrides: {
            paper: {
                borderRadius: '16px',
                maxWidth: '900px',
                width: '95%',
            }
        }
    },
    MuiAppBar: {
        styleOverrides: {
            root: ({ theme }) => ({
                // AppBar background is handled in App.js for dynamic gradient/solid color
            }),
        }
    },
    MuiDrawer: {
        styleOverrides: {
            paper: ({ theme }) => ({
                 backgroundColor: theme.palette.background.paper, // Ensure drawer uses paper bg
                 borderRight: `1px solid ${theme.palette.divider}`,
            }),
        }
    }
});

// Function to generate the theme based on mode
export const getAppTheme = (mode) => {
    const lightPalette = {
        primary: {
            main: '#6366F1',    // Indigo
            light: '#a5b4fc',
            lighter: '#e0e7ff', // For very subtle highlights or backgrounds
        },
        secondary: {
            main: '#EC4899',    // Pink
            light: '#f9a8d4',
            lighter: '#fce7f3',
        },
        success: { main: '#10b981', light: '#a7f3d0', dark: '#047857', contrastText: '#ffffff' },
        warning: { main: '#f59e0b', light: '#fde68a', dark: '#b45309', contrastText: '#000000' },
        error: { main: '#ef4444', light: '#fecaca', dark: '#b91c1c', contrastText: '#ffffff' },
        info: { main: '#3b82f6', light: '#bfdbfe', lighter: '#eff6ff', dark: '#1d4ed8', contrastText: '#ffffff' },
        background: {
            default: '#f8fafc',
            paper: '#ffffff',
        },
        text: {
            primary: 'rgba(0, 0, 0, 0.87)',
            secondary: 'rgba(0, 0, 0, 0.6)',
            disabled: 'rgba(0, 0, 0, 0.38)',
        },
        divider: 'rgba(0, 0, 0, 0.12)',
        action: { // Keep default action colors or customize for light mode
            active: 'rgba(0, 0, 0, 0.54)',
            hover: 'rgba(0, 0, 0, 0.04)',
            selected: 'rgba(0, 0, 0, 0.08)',
            disabled: 'rgba(0, 0, 0, 0.26)',
            disabledBackground: 'rgba(0, 0, 0, 0.12)',
        }
    };

    // NEW Dark Palette with a "gradient black" feel (deep dark colors)
    const darkPalette = {
        primary: { // Brighter Indigo for dark mode
            main: '#7C7FF5', // Original: #6366F1
            light: '#a5b4fc', // Can remain same or be adjusted
            lighter: '#c7d2fe', // Lighter for subtle highlights
            contrastText: '#ffffff',
        },
        secondary: { // Brighter Pink for dark mode
            main: '#F062A4', // Original: #EC4899
            light: '#f9a8d4',
            lighter: '#fbcfe8',
            contrastText: '#ffffff',
        },
        success: { main: '#22c55e', light: '#4ade80', dark: '#15803d', contrastText: '#ffffff' }, // Adjusted Green
        warning: { main: '#facc15', light: '#fde047', dark: '#ca8a04', contrastText: '#000000' }, // Adjusted Yellow/Amber
        error: { main: '#f43f5e', light: '#fb7185', dark: '#be123c', contrastText: '#ffffff' },   // Adjusted Red
        info: { main: '#38bdf8', light: '#7dd3fc', lighter: '#e0f2fe', dark: '#0ea5e9', contrastText: '#000000' },    // Adjusted Blue
        background: {
            default: '#0D1117', // Very dark charcoal, GitHub-like dark
            paper: '#161B22',   // Slightly lighter for surfaces, GitHub-like dark
        },
        text: {
            primary: '#E6EDF3',    // Light grey/off-white
            secondary: '#909DAB',  // Medium grey
            disabled: '#505A66',   // Darker grey for disabled
        },
        divider: 'rgba(255, 255, 255, 0.1)', // Lighter divider for dark mode
        action: { // Define action colors for dark mode for better visibility
            active: 'rgba(255, 255, 255, 0.7)',
            hover: 'rgba(255, 255, 255, 0.08)',
            selected: 'rgba(255, 255, 255, 0.16)',
            disabled: 'rgba(255, 255, 255, 0.3)',
            disabledBackground: 'rgba(255, 255, 255, 0.12)',
        }
    };

    return createTheme({
        palette: {
            mode: mode,
            ...(mode === 'light' ? lightPalette : darkPalette),
        },
        typography: commonTypography,
        transitions: commonTransitions,
        components: commonComponents(mode),
    });
};

const defaultTheme = getAppTheme('light');
export default defaultTheme;
