const maxSubarraySolutionCodeCPP = `
#include <vector>
#include <algorithm> // For std::max
#include <iostream>
#include <numeric>   // For std::accumulate (optional for printing)
#include <limits>   // For numeric_limits

// Helper to print vector (optional)
template<typename T>
std::ostream& operator<<(std::ostream& os, const std::vector<T>& vec) {
    os << "[";
    for (size_t i = 0; i < vec.size(); ++i) {
        os << vec[i] << (i == vec.size() - 1 ? "" : ", ");
    }
    os << "]";
    return os;
}

class Solution {
public:
    /**
     * Finds the maximum sum of a contiguous subarray using Kadane's Algorithm.
     * @param nums The input vector of integers.
     * @return The maximum subarray sum.
     */
    int maxSubArray(const std::vector<int>& nums) {
        if (nums.empty()) {
            return 0; // Or handle error
        }

        int maxSoFar = nums[0];
        int currentMax = nums[0];

        for (size_t i = 1; i < nums.size(); ++i) {
            int num = nums[i];
            // Extend current subarray or start new one
            currentMax = std::max(num, currentMax + num);
            // Update overall max
            maxSoFar = std::max(maxSoFar, currentMax);
        }

        return maxSoFar;
    }
};

// Example Usage:
int main() {
    Solution sol;
    std::vector<int> nums1 = {-2, 1, -3, 4, -1, 2, 1, -5, 4};
    std::cout << "Input: " << nums1 << ", Max Subarray Sum: " << sol.maxSubArray(nums1) << std::endl; // Output: 6

    std::vector<int> nums2 = {1};
    std::cout << "Input: " << nums2 << ", Max Subarray Sum: " << sol.maxSubArray(nums2) << std::endl; // Output: 1

    std::vector<int> nums3 = {5, 4, -1, 7, 8};
    std::cout << "Input: " << nums3 << ", Max Subarray Sum: " << sol.maxSubArray(nums3) << std::endl; // Output: 23

    return 0;
}
`;
