    const [currentMaxEndingHere, setCurrentMaxEndingHere] = useState(null);
    const [maxSoFar, setMaxSoFar] = useState(null);
    const [maxSubarrayIndices, setMaxSubarrayIndices] = useState({ start: -1, end: -1 });
