                 overallMax = Math.max(...nums);
                 const maxIndex = nums.indexOf(overallMax);
                 maxStart = maxIndex; maxEnd = maxIndex;
                 setMaxSoFar(overallMax); setMaxSubarrayIndices({ start: maxStart, end: maxEnd });
