const solutionCodeJS = `
/**
 * Checks if a string is a palindrome after cleaning it.
 * Cleans the string by converting to lowercase and removing non-alphanumeric chars.
 * Uses two pointers (left and right) moving towards the center.
 * Time: O(N), Space: O(N) for cleaned string (or O(1) if modified in-place/no extra storage).
 * @param {string} s The input string.
 * @return {boolean} True if the cleaned string is a palindrome, false otherwise.
 */
const isPalindrome = function(s) {
    // 1. Clean the string
    const cleaned = s.toLowerCase().replace(/[^a-z0-9]/g, '');

    // 2. Use two pointers
    let left = 0;
    let right = cleaned.length - 1;

    while (left < right) {
        if (cleaned[left] !== cleaned[right]) {
            return false; // Mismatch found
        }
        left++;
        right--;
    }

    return true; // All characters matched
};
`;
