const solutionCodeJS = `
/**
 * Finds the minimum window substring of s which contains all the characters in t.
 * Uses a sliding window approach with frequency maps.
 * Time: O(|S| + |T|), Space: O(|T|) or O(Alphabet Size).
 * @param {string} s The string to search within.
 * @param {string} t The string containing characters to find.
 * @return {string} The minimum window substring, or "" if no such window exists.
 */
const minWindow = function(s, t) {
    if (!s || !t || s.length < t.length) {
        return "";
    }

    const tFreqMap = new Map();
    for (const char of t) {
        tFreqMap.set(char, (tFreqMap.get(char) || 0) + 1);
    }

    let requiredChars = tFreqMap.size; // Number of unique characters required
    let formedChars = 0; // Number of unique characters formed in the current window

    const windowFreqMap = new Map(); // Frequency of characters in the current window
    let windowStart = 0;
    let minLength = Infinity;
    let minWindowStart = -1; // Starting index of the minimum window found

    for (let windowEnd = 0; windowEnd < s.length; windowEnd++) {
        const rightChar = s[windowEnd];

        // Add rightChar to the window map
        windowFreqMap.set(rightChar, (windowFreqMap.get(rightChar) || 0) + 1);

        // Check if this character is required and if its count now matches the required count
        if (tFreqMap.has(rightChar) && windowFreqMap.get(rightChar) === tFreqMap.get(rightChar)) {
            formedChars++;
        }

        // Try to shrink the window while the window is valid (contains all required chars)
        while (windowStart <= windowEnd && formedChars === requiredChars) {
            const currentLength = windowEnd - windowStart + 1;

            // Update minimum window found so far
            if (currentLength < minLength) {
                minLength = currentLength;
                minWindowStart = windowStart;
            }

            // Remove the left character from the window
            const leftChar = s[windowStart];
            windowFreqMap.set(leftChar, windowFreqMap.get(leftChar) - 1);

            // Check if removing the left character makes the window invalid
            if (tFreqMap.has(leftChar) && windowFreqMap.get(leftChar) < tFreqMap.get(leftChar)) {
                formedChars--;
            }

            // Move the window start forward
            windowStart++;
        }
    }

    return minLength === Infinity ? "" : s.substring(minWindowStart, minWindowStart + minLength);
};
`;
