const twoSumSolutionCodeJS = `
/**
 * Finds indices of two numbers in an array that add up to a specific target.
 * @param {number[]} nums - The input array of integers.
 * @param {number} target - The target sum.
 * @return {number[]} An array containing the indices of the two numbers, or empty if none found.
 */
var twoSum = function(nums, target) {
    // Create a hash map to store numbers encountered and their indices
    const map = new Map(); // { number: index }

    for (let i = 0; i < nums.length; i++) {
        const currentNum = nums[i];
        const complement = target - currentNum;

        // Check if the complement needed to reach the target exists in the map
        if (map.has(complement)) {
            // If found, return the index of the complement and the current index
            return [map.get(complement), i];
        }

        // If complement not found, store the current number and its index in the map
        // This allows subsequent numbers to find it as their complement
        map.set(currentNum, i);
    }

    // If the loop finishes without finding a pair (problem statement usually guarantees one)
    return []; // Or throw an error, depending on guarantees
};

// Example Usage:
const nums1 = [2, 7, 11, 15];
const target1 = 9;
console.log(\`Input: \${nums1}, Target: \${target1}, Indices: \${twoSum(nums1, target1)}\`); // Output: [0, 1]

const nums2 = [3, 2, 4];
const target2 = 6;
console.log(\`Input: \${nums2}, Target: \${target2}, Indices: \${twoSum(nums2, target2)}\`); // Output: [1, 2]
`;

const twoSumSolutionCodePython = `
from typing import List

class Solution:
    """
    Finds indices of two numbers in a list that add up to a specific target.
    Uses a hash map (dictionary in Python) for O(n) time complexity.
    """
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        """
        Args:
            nums: The input list of integers.
            target: The target sum.

        Returns:
            A list containing the indices of the two numbers.
        """
        num_map = {} # Dictionary to store num -> index

        for i, num in enumerate(nums):
            complement = target - num
            # Check if the complement exists in the map
            if complement in num_map:
                # Return the stored index of the complement and the current index
                return [num_map[complement], i]
            # Store the current number and its index if complement wasn't found
            num_map[num] = i

        # Should not be reached if one solution is guaranteed
        return []

# Example Usage:
if __name__ == "__main__":
    sol = Solution()
    nums1 = [2, 7, 11, 15]
    target1 = 9
    print(f"Input: {nums1}, Target: {target1}, Indices: {sol.twoSum(nums1, target1)}") # Output: [0, 1]

    nums2 = [3, 2, 4]
    target2 = 6
    print(f"Input: {nums2}, Target: {target2}, Indices: {sol.twoSum(nums2, target2)}") # Output: [1, 2]
`;

const twoSumSolutionCodeJava = `
import java.util.HashMap;
import java.util.Map;
import java.util.Arrays;

class Solution {
    /**
     * Finds indices of two numbers in an array that add up to a specific target.
     * Uses a HashMap for O(n) time complexity.
     * @param nums The input array of integers.
     * @param target The target sum.
     * @return An array containing the indices of the two numbers.
     * @throws IllegalArgumentException if no solution is found (or return empty array).
     */
    public int[] twoSum(int[] nums, int target) {
        if (nums == null || nums.length < 2) {
            throw new IllegalArgumentException("Input array must contain at least two numbers.");
        }

        Map<Integer, Integer> map = new HashMap<>(); // Stores number -> index

        for (int i = 0; i < nums.length; i++) {
            int currentNum = nums[i];
            int complement = target - currentNum;

            // Check if the complement exists in the map
            if (map.containsKey(complement)) {
                // Return the stored index of the complement and the current index
                return new int[]{map.get(complement), i};
            }

            // Store the current number and its index
            map.put(currentNum, i);
        }

        // Problem statement usually guarantees a solution, but handle the case anyway
        throw new IllegalArgumentException("No two sum solution found.");
        // Or return new int[]{}; depending on requirements
    }

    // Example Usage:
    public static void main(String[] args) {
        Solution sol = new Solution();
        int[] nums1 = {2, 7, 11, 15};
        int target1 = 9;
        System.out.println("Input: " + Arrays.toString(nums1) + ", Target: " + target1 +
                           ", Indices: " + Arrays.toString(sol.twoSum(nums1, target1))); // Output: [0, 1]

        int[] nums2 = {3, 2, 4};
        int target2 = 6;
        System.out.println("Input: " + Arrays.toString(nums2) + ", Target: " + target2 +
                           ", Indices: " + Arrays.toString(sol.twoSum(nums2, target2))); // Output: [1, 2]
    }
}
`;

const twoSumSolutionCodeCPP = `
#include <vector>
#include <unordered_map>
#include <iostream>
#include <stdexcept> // For exceptions
#include <limits>    // For numeric_limits

// Helper to print vector (optional)
template<typename T>
std::ostream& operator<<(std::ostream& os, const std::vector<T>& vec) {
    os << "[";
    for (size_t i = 0; i < vec.size(); ++i) {
        os << vec[i] << (i == vec.size() - 1 ? "" : ", ");
    }
    os << "]";
    return os;
}

class Solution {
public:
    /**
     * Finds indices of two numbers in a vector that add up to a specific target.
     * Uses an unordered_map for O(n) average time complexity.
     * @param nums The input vector of integers.
     * @param target The target sum.
     * @return A vector containing the indices of the two numbers. Throws runtime_error if not found.
     */
    std::vector<int> twoSum(const std::vector<int>& nums, int target) {
        if (nums.size() < 2) {
             throw std::invalid_argument("Input vector must contain at least two numbers.");
        }
        std::unordered_map<int, int> map; // Stores number -> index

        for (int i = 0; i < nums.size(); ++i) {
            int currentNum = nums[i];
            // Use long long for complement calculation to avoid potential overflow
            long long complement_ll = (long long)target - currentNum;
            // Check if complement fits within int range before casting back
            if (complement_ll < std::numeric_limits<int>::min() || complement_ll > std::numeric_limits<int>::max()) {
                 continue; // Skip if complement is out of int range
            }
            int complement = (int)complement_ll;


            // Check if the complement exists in the map
            auto it = map.find(complement);
            if (it != map.end()) {
                // Found: return the stored index (it->second) and current index (i)
                return {it->second, i};
            }

            // Store the current number and its index
            map[currentNum] = i;
        }

        // Problem statement guarantees one solution, but throw if not found.
        throw std::runtime_error("No two sum solution found.");
        // return {}; // Alternative: return empty vector
    }
};

// Example Usage:
int main() {
    Solution sol;
    std::vector<int> nums1 = {2, 7, 11, 15};
    int target1 = 9;
    std::vector<int> result1 = sol.twoSum(nums1, target1);
    std::cout << "Input: " << nums1 << ", Target: " << target1
              << ", Indices: " << result1 << std::endl; // Output: [0, 1]

    std::vector<int> nums2 = {3, 2, 4};
    int target2 = 6;
    std::vector<int> result2 = sol.twoSum(nums2, target2);
    std::cout << "Input: " << nums2 << ", Target: " << target2
              << ", Indices: " << result2 << std::endl; // Output: [1, 2]

    return 0;
}
`;
