const maxProductSubarraySolutionCodeJava = `
import java.lang.Math;
import java.util.Arrays;

class Solution {
    /**
     * Finds the maximum product of a contiguous non-empty subarray.
     * @param nums The input array of integers.
     * @return The maximum product.
     */
    public int maxProduct(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0; // Or handle error based on constraints
        }

        int maxProductOverall = nums[0];
        int maxEndingHere = nums[0];
        int minEndingHere = nums[0]; // Track min due to negatives

        for (int i = 1; i < nums.length; i++) {
            int num = nums[i];

            // If num is negative, swap roles of max and min ending here
            if (num < 0) {
                int temp = maxEndingHere;
                maxEndingHere = minEndingHere;
                minEndingHere = temp;
            }

            // Update max and min ending at index i
            maxEndingHere = Math.max(num, num * maxEndingHere);
            minEndingHere = Math.min(num, num * minEndingHere);

            // Update the overall max product
            maxProductOverall = Math.max(maxProductOverall, maxEndingHere);
        }

        return maxProductOverall;
    }

    // Example Usage:
    public static void main(String[] args) {
        Solution sol = new Solution();
        int[] nums1 = {2, 3, -2, 4};
        System.out.println("Input: " + Arrays.toString(nums1) +
                           ", Max Product: " + sol.maxProduct(nums1)); // 6

        int[] nums2 = {-2, 0, -1};
        System.out.println("Input: " + Arrays.toString(nums2) +
                           ", Max Product: " + sol.maxProduct(nums2)); // 0

        int[] nums3 = {-2, 3, -4};
        System.out.println("Input: " + Arrays.toString(nums3) +
                           ", Max Product: " + sol.maxProduct(nums3)); // 24
    }
}
`;

const maxProductSubarraySolutionCodeCPP = `
#include <vector>
#include <algorithm> // For std::max, std::min, std::swap
#include <iostream>

// Helper to print vector (optional)
template<typename T>
std::ostream& operator<<(std::ostream& os, const std::vector<T>& vec) {
    os << "[";
    for (size_t i = 0; i < vec.size(); ++i) {
        os << vec[i] << (i == vec.size() - 1 ? "" : ", ");
    }
    os << "]";
    return os;
}

class Solution {
public:
    /**
     * Finds the maximum product of a contiguous non-empty subarray.
     * @param nums The input vector of integers.
     * @return The maximum product.
     */
    int maxProduct(const std::vector<int>& nums) {
        if (nums.empty()) {
            return 0; // Or handle error
        }

        int maxProductOverall = nums[0];
        int maxEndingHere = nums[0];
        int minEndingHere = nums[0]; // Track min due to negatives

        for (size_t i = 1; i < nums.size(); ++i) {
            int num = nums[i];

            // If num is negative, swap max and min ending here before calculation
            if (num < 0) {
                std::swap(maxEndingHere, minEndingHere);
            }

            // Update max and min ending at index i
            maxEndingHere = std::max(num, num * maxEndingHere);
            minEndingHere = std::min(num, num * minEndingHere);

            // Update the overall max product
            maxProductOverall = std::max(maxProductOverall, maxEndingHere);
        }

        return maxProductOverall;
    }
};

// Example Usage:
int main() {
    Solution sol;
    std::vector<int> nums1 = {2, 3, -2, 4};
    std::cout << "Input: " << nums1 << ", Max Product: " << sol.maxProduct(nums1) << std::endl; // 6

    std::vector<int> nums2 = {-2, 0, -1};
    std::cout << "Input: " << nums2 << ", Max Product: " << sol.maxProduct(nums2) << std::endl; // 0

    std::vector<int> nums3 = {-2, 3, -4};
    std::cout << "Input: " << nums3 << ", Max Product: " << sol.maxProduct(nums3) << std::endl; // 24

    return 0;
}
`;
