const containsDuplicateSolutionCodeJS = `
/**
 * Checks if an array contains duplicate values using a HashSet.
 * @param {number[]} nums - The input array of numbers.
 * @returns {boolean} True if a duplicate exists, false otherwise.
 */
const containsDuplicate = function(nums) {
    const seen = new Set();
    for (let i = 0; i < nums.length; i++) {
        const num = nums[i];
        if (seen.has(num)) {
            return true; // Duplicate found
        }
        seen.add(num);
    }
    return false; // No duplicates found
};

// Example Usage:
const nums1 = [1, 2, 3, 1];
console.log(\`Input: \${nums1}, Contains Duplicate: \${containsDuplicate(nums1)}\`); // true

const nums2 = [1, 2, 3, 4];
console.log(\`Input: \${nums2}, Contains Duplicate: \${containsDuplicate(nums2)}\`); // false
`;

const containsDuplicateSolutionCodePython = `
from typing import List

class Solution:
    """
    Checks if a list contains duplicate values using a HashSet.
    """
    def containsDuplicate(self, nums: List[int]) -> bool:
        """
        Args:
            nums: The input list of integers.

        Returns:
            True if a duplicate exists, False otherwise.
        """
        seen = set()
        for num in nums:
            if num in seen:
                return True  # Duplicate found
            seen.add(num)
        return False # No duplicates found

# Example Usage:
if __name__ == "__main__":
    sol = Solution()
    nums1 = [1, 2, 3, 1]
    print(f"Input: {nums1}, Contains Duplicate: {sol.containsDuplicate(nums1)}") # true

    nums2 = [1, 2, 3, 4]
    print(f"Input: {nums2}, Contains Duplicate: {sol.containsDuplicate(nums2)}") # false
`;

const containsDuplicateSolutionCodeJava = `
import java.util.HashSet;
import java.util.Set;
import java.util.Arrays;

class Solution {
    /**
     * Checks if an array contains duplicate values using a HashSet.
     * @param nums The input array of integers.
     * @return True if a duplicate exists, false otherwise.
     */
    public boolean containsDuplicate(int[] nums) {
        Set<Integer> seen = new HashSet<>();
        for (int num : nums) {
            // .add() returns false if the element is already present
            if (!seen.add(num)) {
                return true; // Duplicate found
            }
        }
        return false; // No duplicates found
    }

    // Example Usage:
    public static void main(String[] args) {
        Solution sol = new Solution();
        int[] nums1 = {1, 2, 3, 1};
        System.out.println("Input: " + Arrays.toString(nums1) +
                           ", Contains Duplicate: " + sol.containsDuplicate(nums1)); // true

        int[] nums2 = {1, 2, 3, 4};
        System.out.println("Input: " + Arrays.toString(nums2) +
                           ", Contains Duplicate: " + sol.containsDuplicate(nums2)); // false
    }
}
`;

const containsDuplicateSolutionCodeCPP = `
#include <vector>
#include <unordered_set>
#include <iostream>

// Helper to print vector (optional)
template<typename T>
std::ostream& operator<<(std::ostream& os, const std::vector<T>& vec) {
    os << "[";
    for (size_t i = 0; i < vec.size(); ++i) {
        os << vec[i] << (i == vec.size() - 1 ? "" : ", ");
    }
    os << "]";
    return os;
}

class Solution {
public:
    /**
     * Checks if a vector contains duplicate values using an unordered_set.
     * @param nums The input vector of integers.
     * @return True if a duplicate exists, false otherwise.
     */
    bool containsDuplicate(const std::vector<int>& nums) {
        std::unordered_set<int> seen;
        for (int num : nums) {
            // .insert() returns a pair, the second element is bool (true if inserted, false if already existed)
            if (!seen.insert(num).second) {
                return true; // Duplicate found (insertion failed because it was already there)
            }
        }
        return false; // No duplicates found
    }
};

// Example Usage:
int main() {
    Solution sol;
    std::vector<int> nums1 = {1, 2, 3, 1};
    std::cout << "Input: " << nums1 << ", Contains Duplicate: "
              << std::boolalpha << sol.containsDuplicate(nums1) << std::endl; // true

    std::vector<int> nums2 = {1, 2, 3, 4};
    std::cout << "Input: " << nums2 << ", Contains Duplicate: "
              << std::boolalpha << sol.containsDuplicate(nums2) << std::endl; // false

    return 0;
}
`;
