const solutionCodeJS = `
/**
 * Counts how many palindromic substrings are in a string.
 * Uses the "Expand Around Center" approach.
 * Time: O(N^2), Space: O(1)
 * @param {string} s The input string.
 * @return {number} The total number of palindromic substrings.
 */
const countSubstrings = function(s) {
    if (!s || s.length === 0) return 0;

    let count = 0;

    // Helper function to expand around a center and count palindromes
    const expandAndCount = (left, right) => {
        while (left >= 0 && right < s.length && s[left] === s[right]) {
            // Found a palindrome, increment count
            count++;
            left--;  // Expand outwards
            right++;
        }
    };

    for (let i = 0; i < s.length; i++) {
        // Expand around single character center (odd length palindromes)
        // Includes the single character itself as a palindrome
        expandAndCount(i, i);

        // Expand around space between characters (even length palindromes)
        expandAndCount(i, i + 1);
    }

    return count;
};
`;
const solutionCodePython = `
class Solution:
    """
    Counts how many palindromic substrings are in a string.
    Uses the "Expand Around Center" approach.
    Time: O(N^2), Space: O(1)
    """
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        if n == 0:
            return 0

        count = 0

        def expand_and_count(left, right):
            nonlocal count
            while left >= 0 and right < n and s[left] == s[right]:
                count += 1 # Found a palindrome
                left -= 1
                right += 1

        for i in range(n):
            # Odd length palindromes (center is i)
            expand_and_count(i, i)
            # Even length palindromes (center is between i and i+1)
            expand_and_count(i, i + 1)

        return count
`;
const solutionCodeJava = `
class Solution {
    private int count = 0;

    /**
     * Counts how many palindromic substrings are in a string.
     * Uses the "Expand Around Center" approach.
     * Time: O(N^2), Space: O(1)
     * @param s The input string.
     * @return The total number of palindromic substrings.
     */
    public int countSubstrings(String s) {
        if (s == null || s.length() == 0) return 0;

        count = 0; // Reset count if object is reused

        for (int i = 0; i < s.length(); i++) {
            // Odd length palindromes
            expandAndCount(s, i, i);
            // Even length palindromes
            expandAndCount(s, i, i + 1);
        }
        return count;
    }

    private void expandAndCount(String s, int left, int right) {
        while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
            count++; // Increment count for each valid palindrome found
            left--;
            right++;
        }
    }
}
`;
const solutionCodeCPP = `
#include <string>
#include <vector>

using namespace std;

class Solution {
private:
    int count = 0;

    void expandAndCount(const string& s, int left, int right) {
        while (left >= 0 && right < s.length() && s[left] == s[right]) {
            count++; // Increment count for each palindrome found
            left--;
            right++;
        }
    }

public:
    /**
     * Counts how many palindromic substrings are in a string.
     * Uses the "Expand Around Center" approach.
     * Time: O(N^2), Space: O(1)
     * @param s The input string.
     * @return The total number of palindromic substrings.
     */
    int countSubstrings(string s) {
        if (s.empty()) return 0;

        count = 0; // Reset count

        for (int i = 0; i < s.length(); ++i) {
            // Odd length palindromes
            expandAndCount(s, i, i);
            // Even length palindromes
            expandAndCount(s, i, i + 1);
        }
        return count;
    }
};
`;

