const solutionCodeJS = `
/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 * this.val = (val===undefined ? 0 : val)
 * this.left = (left===undefined ? null : left)
 * this.right = (right===undefined ? null : right)
 * }
 */
/**
 * Finds the kth smallest element in a Binary Search Tree (BST).
 * Uses iterative Inorder Traversal with a stack.
 * Time: O(H + k), where H is the height. In worst case (skewed tree, k=N), O(N).
 * Space: O(H) for the stack, O(N) in worst case.
 *
 * @param {TreeNode} root The root of the BST.
 * @param {number} k The desired rank (1-indexed).
 * @return {number} The value of the kth smallest element.
 */
const kthSmallest = function(root, k) {
    const stack = [];
    let count = 0;
    let currentNode = root;

    while (currentNode || stack.length > 0) {
        // Go left as far as possible
        while (currentNode) {
            stack.push(currentNode);
            currentNode = currentNode.left;
        }

        // Process the node at the top of the stack (next smallest)
        currentNode = stack.pop();
        count++;

        // If this is the kth node, return its value
        if (count === k) {
            return currentNode.val;
        }

        // Move to the right subtree
        currentNode = currentNode.right;
    }

    // Should not be reached if k is valid (1 <= k <= total nodes)
    return -1; // Or throw error
};

// Recursive Inorder Approach
// Time: O(N) in worst case (if k is large), Space: O(H) avg, O(N) worst
const kthSmallestRecursive = function(root, k) {
    let count = 0;
    let result = -1;

    function inorder(node) {
        if (!node || count >= k) { // Stop if node is null or k already found
            return;
        }

        // Traverse left
        inorder(node.left);

        // Process current node
        count++;
        if (count === k) {
            result = node.val;
            return; // Found the kth element, stop recursion
        }

        // Traverse right
        inorder(node.right);
    }

    inorder(root);
    return result;
};
`;
