/**
 * Finds the length of the longest substring without repeating characters.
 * Uses a sliding window approach with a Map or Set.
 * Time: O(N), Space: O(min(M, N)) where M is the size of the character set.
 * @param {string} s The input string.
 * @return {number} The length of the longest substring without repeating characters.
 */
const lengthOfLongestSubstring = function(s) {
    if (!s) return 0;

    let maxLength = 0;
    let windowStart = 0;
    const charIndexMap = new Map(); // Stores the last seen index of each character

    for (let windowEnd = 0; windowEnd < s.length; windowEnd++) {
        const rightChar = s[windowEnd];

        // If the character is already in the map and its index is within the current window
        if (charIndexMap.has(rightChar) && charIndexMap.get(rightChar) >= windowStart) {
            // Shrink the window from the left
            windowStart = charIndexMap.get(rightChar) + 1;
        }

        // Update the character's last seen index
        charIndexMap.set(rightChar, windowEnd);

        // Update the maximum length found so far
        maxLength = Math.max(maxLength, windowEnd - windowStart + 1);
    }

    return maxLength;
};

