/**
 * Builds a binary tree from preorder and inorder traversal arrays.
 * Time: O(N), where N is the number of nodes (due to map lookup and single pass).
 * Space: O(N) for the map and recursion stack (O(H) avg, O(N) worst).
 * @param {number[]} preorder
 * @param {number[]} inorder
 * @return {TreeNode}
 */
const buildTree = function(preorder, inorder) {
    if (!preorder || preorder.length === 0 || !inorder || inorder.length === 0) {
        return null;
    }

    // Create a map for quick inorder index lookup
    const inorderMap = new Map();
    for (let i = 0; i < inorder.length; i++) {
        inorderMap.set(inorder[i], i);
    }

    let preorderIndex = 0; // Keep track of the current root in preorder

    // Recursive helper function
    function build(inorderStart, inorderEnd) {
        // Base case: If the range is invalid, return null
        if (inorderStart > inorderEnd) {
            return null;
        }

        // The current root value is the next element in preorder
        const rootVal = preorder[preorderIndex++];
        const root = new TreeNode(rootVal);

        // Find the root's index in the current inorder subarray range
        const inorderRootIndex = inorderMap.get(rootVal);

        // Recursively build the left subtree
        // Left subtree uses inorder elements from inorderStart to inorderRootIndex - 1
        root.left = build(inorderStart, inorderRootIndex - 1);

        // Recursively build the right subtree
        // Right subtree uses inorder elements from inorderRootIndex + 1 to inorderEnd
        root.right = build(inorderRootIndex + 1, inorderEnd);

        return root;
    }

    return build(0, inorder.length - 1);
};
