const solutionCodeCPP = `
#include <vector>
#include <unordered_map>
#include <stdexcept> // For potential errors

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 * int val;
 * TreeNode *left;
 * TreeNode *right;
 * TreeNode() : val(0), left(nullptr), right(nullptr) {}
 * TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 * TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
private:
    int preorderIndex;
    std::unordered_map<int, int> inorderMap;

    /**
     * Recursive helper to build the tree.
     */
    TreeNode* build(const std::vector<int>& preorder, int inorderStart, int inorderEnd) {
        // Base case
        if (inorderStart > inorderEnd) {
            return nullptr;
        }

        // Get root value from preorder and advance index
        int rootVal = preorder[preorderIndex++];
        TreeNode* root = new TreeNode(rootVal);

        // Find root's index in inorder
        // Check if the value exists in the map (important for error handling)
        if (inorderMap.find(rootVal) == inorderMap.end()) {
             // Handle error: value in preorder not found in inorder
             // Depending on constraints, could throw, or return nullptr, etc.
             // For LeetCode, constraints usually guarantee validity.
             delete root; // Clean up allocated node
             throw std::runtime_error("Value from preorder not found in inorder map.");
        }
        int inorderRootIndex = inorderMap[rootVal];

        // Recursively build subtrees
        root->left = build(preorder, inorderStart, inorderRootIndex - 1);
        root->right = build(preorder, inorderRootIndex + 1, inorderEnd);

        return root;
    }

public:
    /**
     * Builds a binary tree from preorder and inorder traversal arrays.
     * Time: O(N), Space: O(N).
     */
    TreeNode* buildTree(const std::vector<int>& preorder, const std::vector<int>& inorder) {
        if (preorder.empty() || inorder.empty() || preorder.size() != inorder.size()) {
            return nullptr; // Basic validation
        }

        preorderIndex = 0;
        inorderMap.clear(); // Clear map for potential multiple calls
        for (int i = 0; i < inorder.size(); ++i) {
             // Check for duplicates in inorder, which would make the map ambiguous
             if (inorderMap.count(inorder[i])) {
                 // Handle error: duplicate value in inorder
                 throw std::runtime_error("Duplicate value found in inorder traversal.");
             }
            inorderMap[inorder[i]] = i;
        }

        // Consider adding a check here to ensure all preorder values are in the map
        // before starting recursion, although the check inside build handles it too.

        return build(preorder, 0, inorder.size() - 1);
    }
};
`;

