// --- Solution Code Strings (Unique Paths - DP) ---
const uniquePathsSolutionCodeJS = `
/**
 * Calculates the number of unique paths from top-left to bottom-right in an m x n grid.
 * Robot can only move down or right.
 * Uses O(m * n) time and O(m * n) space dynamic programming (can be optimized to O(min(m, n))).
 * @param {number} m - Number of rows.
 * @param {number} n - Number of columns.
 * @returns {number} The number of unique paths.
 */
const uniquePaths = function(m, n) {
    if (m <= 0 || n <= 0) return 0;

    // dp[i][j] = number of ways to reach cell (i, j)
    // Dimensions are m x n (rows x columns)
    const dp = Array(m).fill(0).map(() => Array(n).fill(0));

    // Base cases: First row (only move right)
    for (let j = 0; j < n; j++) {
        dp[0][j] = 1;
    }
    // Base cases: First column (only move down)
    for (let i = 0; i < m; i++) {
        dp[i][0] = 1;
    }

    // Fill the rest of the grid
    for (let i = 1; i < m; i++) {
        for (let j = 1; j < n; j++) {
            // Ways to reach (i, j) = ways from top + ways from left
            dp[i][j] = dp[i - 1][j] + dp[i][j - 1];
        }
    }

    // Result is in the bottom-right cell
    return dp[m - 1][n - 1];
};

// Example Usage:
console.log(uniquePaths(3, 7)); // Output: 28
console.log(uniquePaths(3, 2)); // Output: 3
console.log(uniquePaths(1, 1)); // Output: 1
`;

const uniquePathsSolutionCodePython = `
class Solution:
    """
    Calculates the number of unique paths in an m x n grid (down or right moves).
    Uses O(m * n) time and O(m * n) space DP (can be optimized).
    """
    def uniquePaths(self, m: int, n: int) -> int:
        if m <= 0 or n <= 0:
            return 0

        # dp[i][j] = number of ways to reach cell (row i, col j)
        dp = [[0] * n for _ in range(m)]

        # Base cases: Initialize first row and first column to 1
        for j in range(n):
            dp[0][j] = 1
        for i in range(m):
            dp[i][0] = 1

        # Fill the grid using the recurrence relation
        for i in range(1, m):
            for j in range(1, n):
                # Paths to (i, j) = paths from (i-1, j) + paths from (i, j-1)
                dp[i][j] = dp[i-1][j] + dp[i][j-1]

        # Result is at the bottom-right corner
        return dp[m-1][n-1]

# Example Usage:
if __name__ == "__main__":
    sol = Solution()
    print(f"uniquePaths(3, 7) = {sol.uniquePaths(3, 7)}") # Output: 28
    print(f"uniquePaths(3, 2) = {sol.uniquePaths(3, 2)}") # Output: 3
    print(f"uniquePaths(1, 1) = {sol.uniquePaths(1, 1)}") # Output: 1
`;

const uniquePathsSolutionCodeJava = `
class Solution {
    /**
     * Calculates the number of unique paths in an m x n grid (down or right moves).
     * Uses O(m * n) time and O(m * n) space DP.
     * @param m Number of rows.
     * @param n Number of columns.
     * @return The number of unique paths.
     */
    public int uniquePaths(int m, int n) {
        if (m <= 0 || n <= 0) return 0;

        // dp[i][j] = number of ways to reach cell (i, j)
        int[][] dp = new int[m][n];

        // Base cases: Fill first row and first column with 1s
        for (int j = 0; j < n; j++) {
            dp[0][j] = 1;
        }
        for (int i = 0; i < m; i++) {
            dp[i][0] = 1;
        }

        // Fill the rest of the DP table
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]; // Sum of paths from top and left
            }
        }

        // The result is at the bottom-right cell
        return dp[m - 1][n - 1];
    }

    // Example Usage:
    public static void main(String[] args) {
        Solution sol = new Solution();
        System.out.println("uniquePaths(3, 7) = " + sol.uniquePaths(3, 7)); // Output: 28
        System.out.println("uniquePaths(3, 2) = " + sol.uniquePaths(3, 2)); // Output: 3
        System.out.println("uniquePaths(1, 1) = " + sol.uniquePaths(1, 1)); // Output: 1
    }
}
`;

const uniquePathsSolutionCodeCPP = `
#include <vector>
#include <iostream>

class Solution {
public:
    /**
     * Calculates the number of unique paths in an m x n grid (down or right moves).
     * Uses O(m * n) time and O(m * n) space DP.
     * @param m Number of rows.
     * @param n Number of columns.
     * @return The number of unique paths.
     */
    int uniquePaths(int m, int n) {
        if (m <= 0 || n <= 0) return 0;

        // dp[i][j] = number of ways to reach cell (i, j)
        // Initialize grid with 0s
        std::vector<std::vector<int>> dp(m, std::vector<int>(n, 0));

        // Base cases: Fill first row and column with 1s
        for (int j = 0; j < n; ++j) {
            dp[0][j] = 1;
        }
        for (int i = 0; i < m; ++i) {
            dp[i][0] = 1;
        }

        // Fill the rest of the grid
        for (int i = 1; i < m; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]; // Paths from top + paths from left
            }
        }

        // Result is in the bottom-right cell
        return dp[m - 1][n - 1];
    }
};

// Example Usage:
int main() {
    Solution sol;
    std::cout << "uniquePaths(3, 7) = " << sol.uniquePaths(3, 7) << std::endl; // Output: 28
    std::cout << "uniquePaths(3, 2) = " << sol.uniquePaths(3, 2) << std::endl; // Output: 3
    std::cout << "uniquePaths(1, 1) = " << sol.uniquePaths(1, 1) << std::endl; // Output: 1
    return 0;
}
`;
