                 await sleep(1200);
                 if (stopRef.current) break outerLoop;

                 // Calculate dp[i][j]
                 dp[i][j] = fromTop + fromLeft;
                 setMessage(`Calculating dp[${i}][${j}] = dp[${i-1}][${j}] + dp[${i}][${j-1}] = ${fromTop} + ${fromLeft} = ${dp[i][j]}.`);
