// Helper function to parse comma-separated numbers from input string
export const parseArrayInput = (input, allowEmpty = false) => {
    if (!input && allowEmpty) return [];
    if (!input) throw new Error("Input cannot be empty.");
    const arr = input.split(',')
        .map(s => s.trim())
        .filter(s => s !== '')
        .map(numStr => {
            const num = Number(numStr);
            if (isNaN(num)) {
                throw new Error(`Invalid number '${numStr}' in input.`);
            }
            return num;
        });
    if (!allowEmpty && arr.length === 0) throw new Error("Input array cannot be empty.");
    return arr;
};

// Helper function to parse a single number input
export const parseNumberInput = (input) => {
    const num = Number(input);
    if (isNaN(num)) {
        throw new Error(`Invalid number '${input}'.`);
    }
    return num;
};

// Helper function to create a delay
export const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));
