const solutionCodeJS = `
/**
 * Finds the length of the longest substring containing the same letter you can get
 * after performing at most k character replacements.
 * Uses a sliding window approach.
 * Time: O(N), Space: O(M) or O(1) if fixed alphabet size (e.g., 26).
 * @param {string} s The input string.
 * @param {number} k The maximum number of replacements allowed.
 * @return {number} The length of the longest valid substring.
 */
const characterReplacement = function(s, k) {
    let maxLength = 0;
    let windowStart = 0;
    let maxFrequency = 0; // Max frequency of a single character in the current window
    const charFrequencyMap = new Map(); // Map<char, count>

    for (let windowEnd = 0; windowEnd < s.length; windowEnd++) {
        const rightChar = s[windowEnd];
        // Increment frequency of the right character
        charFrequencyMap.set(rightChar, (charFrequencyMap.get(rightChar) || 0) + 1);
        // Update the max frequency seen in the current window
        maxFrequency = Math.max(maxFrequency, charFrequencyMap.get(rightChar));

        // Calculate the number of characters that need replacement in the current window
        // windowLength = windowEnd - windowStart + 1
        // replacementsNeeded = windowLength - maxFrequency
        const windowLength = windowEnd - windowStart + 1;

        // Check if the current window is invalid (needs more replacements than k)
        if (windowLength - maxFrequency > k) {
            // Shrink the window from the left
            const leftChar = s[windowStart];
            charFrequencyMap.set(leftChar, charFrequencyMap.get(leftChar) - 1);
            // Note: We don't need to recalculate maxFrequency precisely when shrinking.
            // The window only expands the maxLength when a *new* maxFrequency allows it.
            // If we remove the maxFrequency char, the condition (windowLength - maxFrequency > k)
            // will remain true or become true until the window shrinks enough.
            windowStart++;
        }

        // Update the maximum length found so far
        // The window length is only a candidate for maxLength when it's valid
        maxLength = Math.max(maxLength, windowEnd - windowStart + 1);
    }

    return maxLength;
};
`;
const solutionCodePython = `
from collections import defaultdict

class Solution:
    """
    Finds the length of the longest substring with repeating characters after k replacements.
    Time: O(N), Space: O(M) or O(1).
    """
    def characterReplacement(self, s: str, k: int) -> int:
        max_length = 0
        window_start = 0
        max_frequency = 0 # Max frequency of a single char in the window
        char_frequency = defaultdict(int)

        for window_end in range(len(s)):
            right_char = s[window_end]
            char_frequency[right_char] += 1
            max_frequency = max(max_frequency, char_frequency[right_char])

            # Current window length
            window_length = window_end - window_start + 1

            # Check if replacements needed exceed k
            replacements_needed = window_length - max_frequency
            if replacements_needed > k:
                # Shrink window
                left_char = s[window_start]
                char_frequency[left_char] -= 1
                # No need to precisely update max_frequency here when shrinking
                window_start += 1
                # Recalculate window_length for max_length update below (optional but clearer)
                # window_length = window_end - window_start + 1

            # Max length is the max valid window size seen so far
            max_length = max(max_length, window_end - window_start + 1) # window_length)

        return max_length
`;
const solutionCodeJava = `
import java.util.HashMap;
import java.util.Map;

class Solution {
    /**
     * Finds the length of the longest substring with repeating characters after k replacements.
     * Time: O(N), Space: O(M) or O(1).
     * @param s The input string.
     * @param k The maximum number of replacements.
     * @return The length of the longest valid substring.
     */
    public int characterReplacement(String s, int k) {
        int n = s.length();
        int maxLength = 0;
        int windowStart = 0;
        int maxFrequency = 0; // Max frequency of a single char in window
        Map<Character, Integer> charFrequencyMap = new HashMap<>();

        for (int windowEnd = 0; windowEnd < n; windowEnd++) {
            char rightChar = s.charAt(windowEnd);
            charFrequencyMap.put(rightChar, charFrequencyMap.getOrDefault(rightChar, 0) + 1);
            maxFrequency = Math.max(maxFrequency, charFrequencyMap.get(rightChar));

            int windowLength = windowEnd - windowStart + 1;

            // Check if the window needs too many replacements
            if (windowLength - maxFrequency > k) {
                // Shrink the window
                char leftChar = s.charAt(windowStart);
                charFrequencyMap.put(leftChar, charFrequencyMap.get(leftChar) - 1);
                // No need to update maxFrequency precisely when shrinking
                windowStart++;
                 // windowLength = windowEnd - windowStart + 1; // Recalculate if using below
            }

            // The maximum length is the size of the largest valid window found
            maxLength = Math.max(maxLength, windowEnd - windowStart + 1); // windowLength);
        }

        return maxLength;
    }
}
`;
const solutionCodeCPP = `
#include <string>
#include <unordered_map>
#include <algorithm> // For std::max

using namespace std;

class Solution {
public:
    /**
     * Finds the length of the longest substring with repeating characters after k replacements.
     * Time: O(N), Space: O(M) or O(1).
     * @param s The input string.
     * @param k The maximum number of replacements.
     * @return The length of the longest valid substring.
     */
    int characterReplacement(string s, int k) {
        int n = s.length();
        int maxLength = 0;
        int windowStart = 0;
        int maxFrequency = 0; // Max frequency in window
        unordered_map<char, int> charFrequencyMap;

        for (int windowEnd = 0; windowEnd < n; ++windowEnd) {
            char rightChar = s[windowEnd];
            charFrequencyMap[rightChar]++;
            maxFrequency = max(maxFrequency, charFrequencyMap[rightChar]);

            int windowLength = windowEnd - windowStart + 1;

            // Check if window is invalid
            if (windowLength - maxFrequency > k) {
                // Shrink window
                char leftChar = s[windowStart];
                charFrequencyMap[leftChar]--;
                // No need to update maxFrequency precisely when shrinking
                windowStart++;
                // windowLength = windowEnd - windowStart + 1; // If using below
            }

            // Update max length (size of largest valid window)
            maxLength = max(maxLength, windowEnd - windowStart + 1); // windowLength);
        }

        return maxLength;
    }
};
`;

