const wordBreakSolutionCodeJS = `
/**
 * Determines if a string can be segmented into a space-separated sequence
 * of one or more dictionary words using Dynamic Programming.
 * @param {string} s - The input string.
 * @param {string[]} wordDict - An array of dictionary words.
 * @returns {boolean} True if s can be segmented, false otherwise.
 */
const wordBreak = function(s, wordDict) {
    const n = s.length;
    // Use a Set for O(1) average time complexity lookups
    const wordSet = new Set(wordDict);

    // dp[i] = true if the prefix s[0...i-1] can be segmented
    const dp = new Array(n + 1).fill(false);
    dp[0] = true; // Base case: an empty string can always be segmented

    // Outer loop: Iterate through all possible end points (i) of substrings
    // i represents the length of the prefix being checked (s[0...i-1])
    for (let i = 1; i <= n; i++) {
        // Inner loop: Iterate through all possible start points (j) of the last word
        // j represents the end of a previously segmentable prefix (s[0...j-1])
        for (let j = 0; j < i; j++) {
            // Check two conditions:
            // 1. dp[j] is true: The prefix s[0...j-1] was already found to be segmentable.
            // 2. The substring s[j...i-1] is present in the dictionary.
            const sub = s.substring(j, i);
            if (dp[j] && wordSet.has(sub)) {
                // If both conditions are met, then the prefix s[0...i-1] is segmentable.
                dp[i] = true;
                // Optimization: Once we find one way to segment s[0...i-1],
                // we can break the inner loop and move to the next i.
                break;
            }
        }
    }

    // The final answer is whether the entire string s (prefix s[0...n-1]) can be segmented.
    return dp[n];
};

// Example Usage:
console.log(wordBreak("leetcode", ["leet", "code"])); // Output: true
console.log(wordBreak("applepenapple", ["apple", "pen"])); // Output: true
console.log(wordBreak("catsandog", ["cats", "dog", "sand", "and", "cat"])); // Output: false
`;

const wordBreakSolutionCodePython = `
from typing import List

class Solution:
    """
    Determines if a string can be segmented into dictionary words using DP.
    """
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        """
        Args:
            s: The input string.
            wordDict: A list of dictionary words.

        Returns:
            True if s can be segmented, False otherwise.
        """
        n = len(s)
        # Use a set for efficient O(1) average lookup. Creation takes O(L).
        word_set = set(wordDict)

        # dp[i] will be True if the prefix s[:i] (s[0...i-1]) can be segmented.
        dp = [False] * (n + 1)
        dp[0] = True # Base case: empty string prefix is always segmentable.

        # O(n^2 * k) where k is avg substring creation/lookup,
        # or O(n^3) if slicing is O(n). Set lookup is O(1) avg.
        # Outer loop: Iterate through possible lengths 'i' of prefixes.
        for i in range(1, n + 1):
            # Inner loop: Iterate through possible split points 'j'.
            for j in range(i):
                # Check if dp[j] is True (prefix s[:j] is segmentable)
                # AND if the substring s[j:i] is in the dictionary.
                substring = s[j:i]
                if dp[j] and substring in word_set:
                    # If yes, mark dp[i] as True and break the inner loop (optimization).
                    dp[i] = True
                    break

        # The result is stored in dp[n], indicating if the whole string s[:n] is segmentable.
        return dp[n]

# Example Usage:
if __name__ == "__main__":
    sol = Solution()
    print(f"wordBreak('leetcode', ['leet', 'code']) = {sol.wordBreak('leetcode', ['leet', 'code'])}") # Output: True
    print(f"wordBreak('applepenapple', ['apple', 'pen']) = {sol.wordBreak('applepenapple', ['apple', 'pen'])}") # Output: True
    print(f"wordBreak('catsandog', ['cats', 'dog', 'sand', 'and', 'cat']) = {sol.wordBreak('catsandog', ['cats', 'dog', 'sand', 'and', 'cat'])}") # Output: False
`;

const wordBreakSolutionCodeJava = `
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.Arrays;

class Solution {
    /**
     * Determines if a string can be segmented into dictionary words using DP.
     * Time: O(n^3) due to substring creation inside nested loops (n^2 loops * O(n) substring).
     * Space: O(n + L) for dp array and HashSet, L = total length of words in dict.
     * @param s The input string.
     * @param wordDict A list of dictionary words.
     * @return True if s can be segmented, false otherwise.
     */
    public boolean wordBreak(String s, List<String> wordDict) {
        int n = s.length();
        // Use HashSet for O(1) average time contains() check. Creation is O(L).
        Set<String> wordSet = new HashSet<>(wordDict);

        // dp[i] = true if s.substring(0, i) can be segmented
        boolean[] dp = new boolean[n + 1];
        dp[0] = true; // Base case: empty string

        // Outer loop iterates from 1 to n (length of prefix)
        for (int i = 1; i <= n; i++) {
            // Inner loop iterates from 0 to i-1 (potential split point)
            for (int j = 0; j < i; j++) {
                // Check if dp[j] is true (prefix s[0...j-1] is segmentable)
                if (dp[j]) {
                    // Extract substring s[j...i-1]
                    String sub = s.substring(j, i);
                    // Check if this substring is in the dictionary
                    if (wordSet.contains(sub)) {
                        // If both conditions met, mark dp[i] as true
                        dp[i] = true;
                        break; // Optimization: move to the next i
                    }
                }
            }
        }

        // Final result for the entire string s[0...n-1]
        return dp[n];
    }

    // Example Usage:
    public static void main(String[] args) {
        Solution sol = new Solution();
        List<String> dict1 = Arrays.asList("leet", "code");
        System.out.println("wordBreak('leetcode', [\"leet\", \"code\"]) = " + sol.wordBreak("leetcode", dict1)); // Output: true

        List<String> dict2 = Arrays.asList("apple", "pen");
        System.out.println("wordBreak('applepenapple', [\"apple\", \"pen\"]) = " + sol.wordBreak("applepenapple", dict2)); // Output: true

        List<String> dict3 = Arrays.asList("cats", "dog", "sand", "and", "cat");
        System.out.println("wordBreak('catsandog', [\"cats\", \"dog\", \"sand\", \"and\", \"cat\"]) = " + sol.wordBreak("catsandog", dict3)); // Output: false
    }
}
`;

const wordBreakSolutionCodeCPP = `
#include <string>
#include <vector>
#include <unordered_set>
#include <iostream>
#include <vector> // Include vector for dp array

class Solution {
public:
    /**
     * Determines if a string can be segmented into dictionary words using DP.
     * Time: O(n^3) in worst case (n^2 loops * O(n) substr). Can be O(n^2) with string views.
     * Space: O(n + L) for dp vector and unordered_set.
     * @param s The input string.
     * @param wordDict A vector of dictionary words.
     * @return True if s can be segmented, false otherwise.
     */
    bool wordBreak(std::string s, const std::vector<std::string>& wordDict) {
        int n = s.length();
        // Use unordered_set for O(1) average time lookup. Creation O(L).
        std::unordered_set<std::string> wordSet(wordDict.begin(), wordDict.end());

        // dp[i] = true if s.substr(0, i) can be segmented
        std::vector<bool> dp(n + 1, false);
        dp[0] = true; // Base case

        // Outer loop: iterates length i from 1 to n
        for (int i = 1; i <= n; ++i) {
            // Inner loop: iterates potential split point j from 0 to i-1
            for (int j = 0; j < i; ++j) {
                // Check if dp[j] is true (prefix s[0...j-1] is segmentable)
                if (dp[j]) {
                    // Extract substring s[j...i-1] which has length i - j
                    std::string sub = s.substr(j, i - j);
                    // Check if substring exists in the dictionary set
                    if (wordSet.count(sub)) { // .count() is O(1) avg for unordered_set
                        dp[i] = true; // Mark current prefix length as segmentable
                        break; // Optimization: move to next i
                    }
                }
            }
        }

        // Final result for the whole string s[0...n-1]
        return dp[n];
    }
};

// Example Usage:
// #include <vector> // Already included above
// #include <string> // Already included above
// #include <iostream> // Already included above
// #include <iomanip> // For std::boolalpha

int main() {
    Solution sol;
    std::vector<std::string> dict1 = {"leet", "code"};
    std::cout << "wordBreak('leetcode', {'leet', 'code'}) = "
              << std::boolalpha << sol.wordBreak("leetcode", dict1) << std::endl; // Output: true

    std::vector<std::string> dict2 = {"apple", "pen"};
    std::cout << "wordBreak('applepenapple', {'apple', 'pen'}) = "
              << std::boolalpha << sol.wordBreak("applepenapple", dict2) << std::endl; // Output: true

    std::vector<std::string> dict3 = {"cats", "dog", "sand", "and", "cat"};
    std::cout << "wordBreak('catsandog', {'cats', 'dog', 'sand', 'and', 'cat'}) = "
              << std::boolalpha << sol.wordBreak("catsandog", dict3) << std::endl; // Output: false

    return 0;
}
`;


const WordBreakVisualizer = () => {
    const [sInput, setSInput] = useState("leetcode");
    const [dictInput, setDictInput] = useState("leet, code");
    const [dpElements, setDpElements] = useState([]);
    const [stringChars, setStringChars] = useState([]);
    const [message, setMessage] = useState("");
    const [errorMessage, setErrorMessage] = useState("");
    const [isRunning, setIsRunning] = useState(false);
    const [finalResult, setFinalResult] = useState(null);
    const [currentIndexI, setCurrentIndexI] = useState(null);
    const [currentIndexJ, setCurrentIndexJ] = useState(null);
    const [currentSubstring, setCurrentSubstring] = useState("");
    const [substringFound, setSubstringFound] = useState(false);
    const stopRef = useRef(false);

    const [isAudioEnabled, setIsAudioEnabled] = useState(true);
    const [isSpeechEnabled, setIsSpeechEnabled] = useState(true);

    const audioContextRef = useRef(null);

    const initAudioContext = useCallback(() => {
        if (!isAudioEnabled) return;
        if (audioContextRef.current === null && typeof window !== 'undefined' && (window.AudioContext || window.webkitAudioContext)) {
            try {
                audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)();
            } catch (e) {
                console.error("Web Audio API not supported or context creation failed.", e);
                setIsAudioEnabled(false);
                setMessage("Audio tones disabled: Not supported by browser.");
            }
        }
        if (audioContextRef.current && audioContextRef.current.state === 'suspended') {
            audioContextRef.current.resume().catch(e => console.error("Audio context resume failed", e));
        }
    }, [isAudioEnabled]);

    const playTone = useCallback((frequency = 440, duration = 0.1, type = 'sine', volume = 0.3) => {
        if (!isAudioEnabled || !audioContextRef.current || audioContextRef.current.state !== 'running') return;
        try {
            const oscillator = audioContextRef.current.createOscillator();
            const gainNode = audioContextRef.current.createGain();

            oscillator.type = type;
            oscillator.frequency.setValueAtTime(frequency, audioContextRef.current.currentTime);

            gainNode.gain.setValueAtTime(volume, audioContextRef.current.currentTime);
            gainNode.gain.exponentialRampToValueAtTime(0.0001, audioContextRef.current.currentTime + duration);

            oscillator.connect(gainNode);
            gainNode.connect(audioContextRef.current.destination);

            oscillator.start(audioContextRef.current.currentTime);
            oscillator.stop(audioContextRef.current.currentTime + duration);
        } catch (e) {
            console.error("Error playing tone:", e);
        }
    }, [isAudioEnabled]);

    const playOuterLoopSound = useCallback(() => playTone(300, 0.05, 'triangle', 0.15), [playTone]);
    const playInnerLoopSound = useCallback(() => playTone(450, 0.05, 'sine', 0.15), [playTone]);
    const playCheckDpSound = useCallback(() => playTone(600, 0.07, 'square', 0.2), [playTone]);
    const playCheckDictSound = useCallback(() => playTone(750, 0.08, 'sawtooth', 0.18), [playTone]);
    const playFoundWordSound = useCallback(() => playTone(1000, 0.1, 'sine', 0.25), [playTone]);
    const playStartSound = useCallback(() => playTone(440, 0.1, 'sine', 0.3), [playTone]);
    const playEndSound = useCallback((success) => playTone(success ? 1100 : 250, 0.2, success ? 'sine' : 'sawtooth', 0.3), [playTone]);
    const playStopSound = useCallback(() => playTone(220, 0.15, 'square', 0.3), [playTone]);
    const playErrorSound = useCallback(() => playTone(150, 0.3, 'sawtooth', 0.3), [playTone]);

    const speak = useCallback((text) => {
        return new Promise((resolve) => {
            if (!isSpeechEnabled || typeof window === 'undefined' || !window.speechSynthesis) {
                resolve();
                return;
            }
            try {
                window.speechSynthesis.cancel();
                const utterance = new SpeechSynthesisUtterance(text);
                utterance.lang = 'en-US';
                utterance.rate = 1.0;
                utterance.pitch = 1.0;
                utterance.volume = 0.8;

                utterance.onend = () => {
                    resolve();
                };
                utterance.onerror = (event) => {
                    console.error("Speech synthesis error:", event.error);
                    resolve();
                };

                window.speechSynthesis.speak(utterance);
            } catch (e) {
                console.error("Error initiating speech synthesis:", e);
                resolve();
            }
        });
    }, [isSpeechEnabled]);

    const cancelSpeech = useCallback(() => {
        if (typeof window !== 'undefined' && window.speechSynthesis) {
            window.speechSynthesis.cancel();
        }
    }, []);

    // *** UPDATED reset function ***
    const reset = useCallback((initial = false) => {
        stopRef.current = true;
        cancelSpeech();
        setIsRunning(false);
        setDpElements([]);
        setStringChars([]);
        setFinalResult(null);
        setErrorMessage("");
        setCurrentIndexI(null);
        setCurrentIndexJ(null);
        setCurrentSubstring("");
        setSubstringFound(false);

        try {
            const s = sInput;
            if (!initial && s.trim().length === 0) {
                throw new Error("Input string cannot be empty.");
            }

            // *** FIX: Parse dictionary input directly ***
            const wordDict = dictInput
                               .split(',') // Split by comma
                               .map(word => word.trim()) // Trim whitespace
                               .filter(word => word.length > 0); // Remove empty strings

            if (!initial && wordDict.length === 0) {
                 throw new Error("Word dictionary cannot be empty or contain only invalid entries.");
            }

            const n = s.length;
            const initialDp = Array(n + 1).fill(false);
            initialDp[0] = true;
            setDpElements(initialDp.map((val, i) => ({
                id: `dp-${i}`,
                value: val ? 'T' : 'F',
                state: i === 0 ? 'highlight-final' : 'default',
                index: i
            })));

            setStringChars(s.split('').map((char, i) => ({
                id: `s-${i}`,
                value: char,
                state: 'default',
                index: i
            })));

            setMessage(initial ? "Enter string and dictionary, then click Run." : "Ready. Click Run to visualize.");

        } catch (e) {
            setDpElements([]);
            setStringChars([]);
            setErrorMessage(`Input Error: ${e.message}`);
            setMessage("");
            if (!initial) {
                 playErrorSound();
            }
        }
    // Removed parseArrayInput from dependencies, added dictInput
    }, [sInput, dictInput, cancelSpeech, playErrorSound]);

    useEffect(() => {
        reset(true);
        return () => {
            stopRef.current = true;
            cancelSpeech();
            if (audioContextRef.current) {
                audioContextRef.current.close().catch(e => console.error("Error closing AudioContext:", e));
                audioContextRef.current = null;
            }
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []); // Keep reset out of this initial mount dependency array

    useEffect(() => {
        const handler = setTimeout(() => {
            reset(true);
        }, 500);

        return () => {
            clearTimeout(handler);
        };
    }, [sInput, dictInput, reset]); // reset is needed here as it depends on inputs


    // *** UPDATED runVisualization function ***
    const runVisualization = async () => {
        initAudioContext();
        cancelSpeech();
        reset(false); // Reset state and validate inputs using the updated reset logic
        await sleep(50);

        if (errorMessage) {
             setIsRunning(false);
             return;
        }

        let s = sInput.trim();
        let wordDict;
        let wordSet;
        try {
             // *** FIX: Parse dictionary input directly ***
             wordDict = dictInput
                        .split(',') // Split by comma
                        .map(word => word.trim()) // Trim whitespace
                        .filter(word => word.length > 0); // Remove empty strings

             // Validate lengths again after parsing/trimming
             if (s.length === 0) throw new Error("Input string cannot be empty.");
             if (wordDict.length === 0) throw new Error("Word dictionary cannot be empty.");
             wordSet = new Set(wordDict); // Use Set for efficient lookups
        } catch (e) {
             setErrorMessage(`Input Error: ${e.message}`);
             setIsRunning(false);
             playErrorSound();
             return;
        }

        stopRef.current = false;
        setIsRunning(true);
        setMessage("Starting Word Break calculation...");
        playStartSound();
        await speak(`Starting Word Break check for string '${s}'.`);
        if (stopRef.current) { setIsRunning(false); return; }

        const n = s.length;
        const dp = new Array(n + 1).fill(false);
        dp[0] = true;

        // Get UI elements based on the state set by reset()
        let currentDpElements = dpElements.map(el => ({...el}));

        setMessage("Base Case: dp[0] = true (empty prefix is always segmentable).");
        currentDpElements[0].state = 'highlight-final';
        setDpElements([...currentDpElements]);
        await speak("Base case: dp of zero is true.");
        if (stopRef.current) { setIsRunning(false); return; }
        await sleep(1200);

        outerLoop:
        for (let i = 1; i <= n; i++) {
             if (stopRef.current) break;
             setCurrentIndexI(i);
             playOuterLoopSound();
             setMessage(`Outer loop (i=${i}): Checking if prefix s[0...${i-1}] can be segmented. Target: dp[${i}].`);
             await speak(`Checking up to index ${i-1}. Target dp of ${i}.`);

             currentDpElements = currentDpElements.map((el, idx) => ({
                ...el,
                state: idx === i ? 'highlight-current-dp'
                       : (el.state.startsWith('highlight-final') || el.state === 'highlight-impossible') ? el.state
                       : 'default',
             }));
             setDpElements([...currentDpElements]);
             if (stopRef.current) break;
             await sleep(800);

             innerLoop:
             for (let j = 0; j < i; j++) {
                 if (stopRef.current) break outerLoop;
                 setCurrentIndexJ(j);
                 playInnerLoopSound();
                 const sub = s.substring(j, i);
                 setCurrentSubstring(sub);
                 setSubstringFound(false);

                 currentDpElements = currentDpElements.map((el, idx) => ({
                    ...el,
                    state: idx === i ? 'highlight-current-dp'
                           : idx === j ? 'highlight-dp-dependency'
                           : (el.state.startsWith('highlight-final') || el.state === 'highlight-impossible') ? el.state
                           : 'default',
                 }));
                 setDpElements([...currentDpElements]);
                 setStringChars(prev => prev.map((char, idx) => ({
                     ...char,
                     state: (idx >= j && idx < i) ? 'highlight-substring' : 'default'
                 })));

                 setMessage(`Inner loop (j=${j}): Check 1: Is dp[${j}] true? Check 2: Is substring s[${j}...${i-1}] ('${sub}') in dictionary?`);
                 await speak(`Checking from index ${j}. Substring is '${sub}'.`);
                 if (stopRef.current) break outerLoop;
                 await sleep(1000);

                 setMessage(`Checking if dp[${j}] (prefix s[0...${j-1}] segmentable) is true...`);
                 playCheckDpSound();
                 await speak(`Is dp of ${j} true?`);
                 if (stopRef.current) break outerLoop;
                 await sleep(800);

                 if (dp[j]) {
                     setMessage(`dp[${j}] is TRUE. Now checking dictionary for substring '${sub}'...`);
                     await speak(`Yes, dp of ${j} is true. Checking dictionary for '${sub}'.`);
                     playCheckDictSound();
                     if (stopRef.current) break outerLoop;
                     await sleep(1000);

                     if (wordSet.has(sub)) {
                         setSubstringFound(true);
                         dp[i] = true;
                         currentDpElements[i] = { ...currentDpElements[i], value: 'T', state: 'highlight-update' };
                         setDpElements([...currentDpElements]);

                         setMessage(`Substring '${sub}' FOUND in dictionary! Setting dp[${i}] = true.`);
                         playFoundWordSound();
                         await speak(`Found '${sub}'! Setting dp of ${i} to true.`);
                         if (stopRef.current) break outerLoop;
                         await sleep(1500);

                         currentDpElements[i].state = 'highlight-final';
                         setDpElements([...currentDpElements]);
                         setMessage(`dp[${i}] is now true. Breaking inner loop for i=${i} (optimization).`);
                         await speak(`Breaking inner loop.`);
                         if (stopRef.current) break outerLoop;
                         await sleep(800);
                         break;

                     } else {
                         setMessage(`Substring '${sub}' NOT found in dictionary.`);
                         await speak(`'${sub}' is not in the dictionary.`);
                         setSubstringFound(false);
                         if (stopRef.current) break outerLoop;
                         await sleep(800);
                     }
                 } else {
                     setMessage(`dp[${j}] is FALSE. Cannot use this split point (j=${j}). Continuing inner loop...`);
                     await speak(`dp of ${j} is false.`);
                     if (stopRef.current) break outerLoop;
                     await sleep(800);
                 }

                 setStringChars(prev => prev.map(char => ({ ...char, state: 'default' })));
                 currentDpElements = currentDpElements.map((el, idx) => ({
                    ...el,
                    state: idx === i ? 'highlight-current-dp'
                           : (el.state.startsWith('highlight-final') || el.state === 'highlight-impossible') ? el.state
                           : 'default',
                 }));
                 setDpElements([...currentDpElements]);
                 setCurrentIndexJ(null);
                 setCurrentSubstring("");
                 if (stopRef.current) break outerLoop;
                 await sleep(300);

             }

             if (stopRef.current) break;

             if (!dp[i]) {
                  currentDpElements[i].state = 'highlight-impossible';
                  setDpElements([...currentDpElements]);
                  setMessage(`Could not find a valid segmentation for prefix s[0...${i-1}]. dp[${i}] remains false.`);
                  await speak(`dp of ${i} remains false.`);
                  if (stopRef.current) break;
                  await sleep(600);
             } else {
             }

             setCurrentIndexI(null);
             setCurrentIndexJ(null);
             setCurrentSubstring("");
             setSubstringFound(false);
             setStringChars(prev => prev.map(char => ({ ...char, state: 'default' })));

             currentDpElements = currentDpElements.map((el, idx) => {
                 if (idx <= i && el.state !== 'highlight-final' && el.state !== 'highlight-impossible') {
                     return { ...el, state: el.value === 'T' ? 'highlight-final' : 'highlight-impossible' };
                 }
                 return el;
             });
             setDpElements([...currentDpElements]);

             if (stopRef.current) break;
             await sleep(500);

        }

        if (stopRef.current) {
            setMessage("Visualization stopped by user.");
            speak("Visualization stopped.");
            playStopSound();
        } else {
            const finalAnswer = dp[n];
            setFinalResult(finalAnswer);
            setMessage(`Finished Word Break check. Result for entire string s[0...${n-1}]: ${finalAnswer}.`);
            playEndSound(finalAnswer);
            await speak(`Finished. The string can ${finalAnswer ? '' : 'not '}be segmented.`);

            setDpElements(prev => prev.map((el, idx) => ({
                ...el,
                state: idx === n ? (finalAnswer ? 'highlight-final-result-success' : 'highlight-final-result-fail')
                       : (el.state === 'highlight-impossible' || el.state.startsWith('highlight-final')) ? el.state
                       : 'default'
            })));
        }

        setIsRunning(false);
        stopRef.current = false;
        setCurrentIndexI(null);
        setCurrentIndexJ(null);
        setCurrentSubstring("");
        setSubstringFound(false);
    };


    const stopVisualization = () => {
        stopRef.current = true;
        cancelSpeech();
        setMessage("Stopping visualization...");
    };

    const toggleAudio = () => {
        const newState = !isAudioEnabled;
        setIsAudioEnabled(newState);
        if (newState) {
            initAudioContext();
             setTimeout(() => playTone(500, 0.05, 'sine', 0.2), 50);
        } else {
            playTone(300, 0.05, 'square', 0.2);
            if (audioContextRef.current && audioContextRef.current.state === 'running') {
                audioContextRef.current.suspend().catch(e => console.error("Audio context suspend failed", e));
            }
        }
    };

    const toggleSpeech = () => {
        const newState = !isSpeechEnabled;
        if (newState && (typeof window === 'undefined' || !window.speechSynthesis)) {
            setErrorMessage("Speech synthesis not supported by your browser.");
            setTimeout(() => setErrorMessage(""), 3000);
            return;
        }
        setIsSpeechEnabled(newState);
        if (!newState) {
            cancelSpeech();
        } else {
            speak("Speech enabled.");
        }
    };

    // --- Render ---
    return (
        <>
            <BaseVisualizer
                problemSummary={
                    <>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                            <Typography variant="h4" component="h1">Word Break</Typography>
                            <Chip label="Medium" color="warning" size="small" variant="filled" />
                        </Box>
                        <Typography variant="body1" component="div" sx={{ mb: 2 }}>
                            Given a string <code>s</code> and a dictionary of strings <code>wordDict</code>, return <code>true</code> if <code>s</code> can be segmented into a space-separated sequence of one or more dictionary words.
                            <br/><br/>Note that the same word in the dictionary may be reused multiple times in the segmentation.
                        </Typography>
                        <Typography variant="h6" component="h3" sx={{ mt: 2, mb: 1 }}>Examples:</Typography>
                        <Box sx={{ bgcolor: 'action.hover', p: 1.5, borderRadius: 1, fontFamily: 'monospace', mb: 2, fontSize: '0.875rem' }}>
                            <strong>Input:</strong> s = "leetcode", wordDict = ["leet","code"]<br/><strong>Output:</strong> true<br/><strong>Explanation:</strong> "leet code".<br/><br/>
                            <strong>Input:</strong> s = "applepenapple", wordDict = ["apple","pen"]<br/><strong>Output:</strong> true<br/><strong>Explanation:</strong> "apple pen apple".<br/><br/>
                            <strong>Input:</strong> s = "catsandog", wordDict = ["cats","dog","sand","and","cat"]<br/><strong>Output:</strong> false
                        </Box>
                        <Typography variant="h6" component="h3" sx={{ mt: 2, mb: 1 }}>Constraints:</Typography>
                        <Box component="ul" sx={{ pl: 2, mb: 2 }}>
                             <li><code>1 &lt;= s.length &lt;= 300</code></li>
                             <li><code>1 &lt;= wordDict.length &lt;= 1000</code></li>
                             <li><code>1 &lt;= wordDict[i].length &lt;= 20</code></li>
                             <li><code>s</code> and <code>wordDict[i]</code> consist of only lowercase English letters.</li>
                             <li>All the strings of <code>wordDict</code> are <strong>unique</strong>.</li>
                        </Box>
                        <Divider sx={{ my: 3 }} />
                        <Typography variant="h6" sx={{ mt: 3, mb: 1 }}>Runnable Solution Code Examples (Dynamic Programming)</Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>Copy/paste these into the compiler below or an external editor.</Typography>
                        <Typography variant="subtitle2" sx={{ mb: 0.5 }}>JavaScript:</Typography><SolutionCodeDisplay codeString={wordBreakSolutionCodeJS} language="javascript"/>
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>Python:</Typography><SolutionCodeDisplay codeString={wordBreakSolutionCodePython} language="python" />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>Java:</Typography><SolutionCodeDisplay codeString={wordBreakSolutionCodeJava} language="java"/>
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>C++:</Typography><SolutionCodeDisplay codeString={wordBreakSolutionCodeCPP} language="cpp"/>
                        <Divider sx={{ my: 3 }} />
                        <Typography variant="subtitle1" gutterBottom>Algorithm Analysis (Dynamic Programming)</Typography>
                        <Typography variant="body2" color="text.secondary">
                             <strong>Time Complexity:</strong> <code>O(N^3)</code> in the worst case due to substring creation/hashing inside two nested loops (where N is the length of <code>s</code>). If substring operations are assumed O(1) on average (like Python slicing or optimized C++ `substr` with views), and hash lookups are O(1) on average, it approaches <code>O(N^2)</code>. Set creation takes O(L), where L is the total length of all words in the dictionary.
                        </Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
                             <strong>Space Complexity:</strong> <code>O(N + L)</code> for the DP array of size N+1 and the word set storing the dictionary words (total length L).
                        </Typography>
                    </>
                }
                controls={
                    <>
                        <Typography variant="subtitle1" sx={{ textAlign: 'center', fontWeight: 'bold', p: 0.75, mb: 2.5, borderRadius: '4px', color: 'common.white', background: 'linear-gradient(45deg, #1976D2 30%, #2196F3 90%)', boxShadow: 1 }}>
                             Word Break Visualizer Controls
                        </Typography>
                        <Grid container spacing={1.5} alignItems="center" mb={2}>
                            <Grid item xs={12} sm={6} md={4}>
                                <TextField fullWidth id="wb-s-input" label="Input String s" variant="outlined" size="small" value={sInput} onChange={(e) => setSInput(e.target.value)} placeholder="e.g., leetcode" disabled={isRunning} />
                            </Grid>
                            <Grid item xs={12} sm={6} md={4}>
                                 <TextField fullWidth id="wb-dict-input" label="Word Dict (comma-separated)" variant="outlined" size="small" value={dictInput} onChange={(e) => setDictInput(e.target.value)} placeholder="e.g., leet, code, sand, cat" disabled={isRunning} />
                            </Grid>
                            <Grid item xs={4} sm={2} md={1} sx={{ display: 'flex' }}>
                                <Tooltip title={isRunning ? "Stop Visualization" : "Run Visualization"}>
                                     <span>
                                        <Button
                                            fullWidth
                                            variant="contained"
                                            sx={{ height: '40px' }}
                                            startIcon={isRunning && !stopRef.current ? <CircularProgress size={20} color="inherit" /> : <PlayArrowIcon />}
                                            onClick={isRunning ? stopVisualization : runVisualization}
                                            color={isRunning ? "warning" : "primary"}
                                            disabled={isRunning && stopRef.current}
                                        >
                                            {isRunning && !stopRef.current ? 'Running' : (isRunning && stopRef.current ? 'Stopping' : 'Run')}
                                        </Button>
                                    </span>
                                </Tooltip>
                            </Grid>
                             <Grid item xs={4} sm={2} md={1} sx={{ display: 'flex' }}>
                                 <Tooltip title="Reset Visualization and Inputs">
                                     <span>
                                         <Button fullWidth variant="outlined" startIcon={<ReplayIcon />} onClick={() => reset(false)} disabled={isRunning} sx={{ height: '40px' }}>
                                             Reset
                                         </Button>
                                     </span>
                                </Tooltip>
                            </Grid>
                            <Grid item xs={4} sm={2} md={1} sx={{ display: 'flex' }}>
                                <Tooltip title={isAudioEnabled ? "Mute Tones" : "Unmute Tones"}>
                                    <Button fullWidth variant="outlined" onClick={toggleAudio} sx={{ height: '40px', minWidth: 'auto', p: 1 }}>
                                        {isAudioEnabled ? <VolumeUpIcon /> : <VolumeOffIcon />}
                                    </Button>
                                </Tooltip>
                            </Grid>
                            <Grid item xs={4} sm={2} md={1} sx={{ display: 'flex' }}>
                                <Tooltip title={isSpeechEnabled ? "Disable Speech" : "Enable Speech"}>
                                    <Button fullWidth variant="outlined" onClick={toggleSpeech} sx={{ height: '40px', minWidth: 'auto', p: 1 }}>
                                        {isSpeechEnabled ? <RecordVoiceOverIcon /> : <VoiceOverOffIcon />}
                                    </Button>
                                </Tooltip>
                            </Grid>
                        </Grid>
                        {errorMessage && <Alert severity="error" sx={{ mt: 1, mb:1 }}>{errorMessage}</Alert>}
                    </>
                }
                displayArea={
                    <>
                         <Box sx={{ mb: 3 }}>
                             <Typography variant="subtitle1" gutterBottom align="center">Input String (s)</Typography>
                             <Box sx={{ display: 'flex', justifyContent: 'center', flexWrap: 'wrap', gap: 0.5, alignItems: 'center', minHeight: '40px', p:1, border: '1px solid', borderColor: 'divider', borderRadius: 1 }}>
                                 {stringChars.length > 0 ? stringChars.map(char => (
                                     <Chip
                                         key={char.id}
                                         label={char.value}
                                         size="small"
                                         sx={{
                                             minWidth: '20px',
                                             fontWeight: 'medium',
                                             fontFamily: 'monospace',
                                             bgcolor: char.state === 'highlight-substring' ? 'warning.light' : 'background.paper',
                                             border: char.state === 'highlight-substring' ? 1.5 : 0,
                                             borderColor: 'warning.main',
                                             transition: 'background-color 0.3s ease, border 0.3s ease',
                                         }}
                                     />
                                 )) : (
                                     !errorMessage && <Typography variant="caption" color="text.secondary">Enter input string above</Typography>
                                 )}
                             </Box>
                         </Box>

                         <Box sx={{ mb: 2 }}>
                            <Typography variant="subtitle1" gutterBottom align="center">DP Array (dp[i]: can prefix s[0...i-1] be segmented?)</Typography>
                            <Box sx={{ display: 'flex', justifyContent: 'center', flexWrap: 'wrap', gap: 1, alignItems: 'flex-end', minHeight: '60px', position: 'relative', pt: 4, pb: 1, border: '1px dashed', borderColor: 'divider', borderRadius: 1 }}>
                                 {dpElements.length > 0 ? dpElements.map(el => (
                                     <ArrayElement
                                         key={el.id}
                                         value={el.value}
                                         index={el.index}
                                         state={el.state}
                                         type="box"
                                         showValue={true}
                                         showIndex={true}
                                     />
                                 )) : (
                                     !errorMessage && <Typography variant="caption" color="text.secondary">Enter inputs and click Run</Typography>
                                 )}
                                 {errorMessage && dpElements.length === 0 && <Typography variant="caption" color="error">Input Error - Cannot initialize DP array</Typography>}
                            </Box>
                         </Box>

                         <Grid container spacing={1} sx={{ mb: 2, textAlign: 'center', fontFamily: 'monospace', fontSize: '0.8rem', p:1, bgcolor:'action.hover', borderRadius: 1 }}>
                             <Grid item xs={6} sm={3}>
                                 <Typography variant="overline" display="block" color="text.secondary">Outer Loop (i)</Typography>
                                 <Chip label={currentIndexI ?? 'idle'} color={currentIndexI ? "primary": "default"} size="small" variant={currentIndexI ? "filled" : "outlined"}/>
                             </Grid>
                             <Grid item xs={6} sm={3}>
                                 <Typography variant="overline" display="block" color="text.secondary">Inner Loop (j)</Typography>
                                  <Chip label={currentIndexJ ?? 'idle'} color={currentIndexJ !== null ? "secondary" : "default"} size="small" variant={currentIndexJ !== null ? "filled" : "outlined"}/>
                             </Grid>
                             <Grid item xs={12} sm={6}>
                                 <Typography variant="overline" display="block" color="text.secondary">Checking Substring s[j...i-1]</Typography>
                                 <Tooltip title={currentSubstring || 'N/A'}>
                                     <Chip
                                         label={currentSubstring || 'N/A'}
                                         color={substringFound ? "success" : "default"}
                                         variant={currentSubstring ? "filled" : "outlined"}
                                         size="small"
                                         icon={substringFound ? <CheckCircleOutlineIcon fontSize='small' sx={{ color: 'success.dark' }}/> : undefined}
                                         sx={{
                                             width: '90%',
                                             maxWidth: '300px',
                                             overflow: 'hidden',
                                             textOverflow: 'ellipsis',
                                             justifyContent: 'flex-start',
                                             pl: 1,
                                             '.MuiChip-icon': { ml: 0.5 }
                                         }}
                                     />
                                 </Tooltip>
                             </Grid>
                         </Grid>

                        {finalResult !== null && !isRunning && !errorMessage && (
                             <Alert
                                icon={finalResult ? <CheckCircleOutlineIcon fontSize="inherit" /> : <HighlightOffIcon fontSize="inherit" />}
                                severity={finalResult ? "success" : "error"}
                                sx={{ mt: 3, justifyContent: 'center', textAlign: 'center', alignItems: 'center' }}
                            >
                                <Typography variant="h6">
                                    Final Result: {finalResult ? "String CAN be segmented" : "String CANNOT be segmented"}
                                </Typography>
                            </Alert>
                        )}
                    </>
                }
                message={message}
            />

            <Container maxWidth="xl" sx={{ mt: 4, mb: 4 }}>
                 {/* <Typography variant="h5" component="h2" gutterBottom>Test with Online Compiler</Typography> */}
                 <OnlineCompiler />
            </Container>
        </>
    );
};

export default WordBreakVisualizer;
