const solutionCodeJS = `
/**
 * Finds the longest palindromic substring in s.
 * Uses the "Expand Around Center" approach.
 * Time: O(N^2), Space: O(1)
 * @param {string} s The input string.
 * @return {string} The longest palindromic substring.
 */
const longestPalindrome = function(s) {
    if (!s || s.length < 1) return "";

    let start = 0; // Start index of the longest palindrome found
    let end = 0;   // End index of the longest palindrome found

    // Helper function to expand around a center
    const expandAroundCenter = (left, right) => {
        while (left >= 0 && right < s.length && s[left] === s[right]) {
            // Check if this palindrome is longer than the current longest
            if (right - left > end - start) {
                start = left;
                end = right;
            }
            left--;  // Expand outwards
            right++;
        }
    };

    for (let i = 0; i < s.length; i++) {
        // Expand around a single character center (odd length palindromes)
        expandAroundCenter(i, i);

        // Expand around the space between two characters (even length palindromes)
        expandAroundCenter(i, i + 1);
    }

    return s.substring(start, end + 1);
};
`;
const solutionCodePython = `
class Solution:
    """
    Finds the longest palindromic substring in s.
    Uses the "Expand Around Center" approach.
    Time: O(N^2), Space: O(1)
    """
    def longestPalindrome(self, s: str) -> str:
        if not s or len(s) < 1:
            return ""

        start, end = 0, 0 # Indices of the longest palindrome found

        def expand_around_center(left, right):
            nonlocal start, end # Allow modification of outer scope variables
            while left >= 0 and right < len(s) and s[left] == s[right]:
                # Check if current palindrome is longer
                if right - left > end - start:
                    start = left
                    end = right
                left -= 1
                right += 1

        for i in range(len(s)):
            # Odd length palindromes (center is i)
            expand_around_center(i, i)
            # Even length palindromes (center is between i and i+1)
            expand_around_center(i, i + 1)

        return s[start : end + 1]
`;
const solutionCodeJava = `
class Solution {
    private int start = 0;
    private int end = 0;

    /**
     * Finds the longest palindromic substring in s.
     * Uses the "Expand Around Center" approach.
     * Time: O(N^2), Space: O(1)
     * @param s The input string.
     * @return The longest palindromic substring.
     */
    public String longestPalindrome(String s) {
        if (s == null || s.length() < 1) return "";

        start = 0; // Reset instance variables if object is reused
        end = 0;

        for (int i = 0; i < s.length(); i++) {
            // Expand around single character center (odd length)
            expandAroundCenter(s, i, i);
            // Expand around space between characters (even length)
            expandAroundCenter(s, i, i + 1);
        }
        return s.substring(start, end + 1);
    }

    private void expandAroundCenter(String s, int left, int right) {
        while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
            // Check if this palindrome is longer
            if (right - left > end - start) {
                start = left;
                end = right;
            }
            left--;
            right++;
        }
    }
}
`;
const solutionCodeCPP = `
#include <string>
#include <algorithm> // For std::max (not strictly needed here)

using namespace std;

class Solution {
private:
    int start = 0;
    int maxLen = 0; // Store max length directly

    void expandAroundCenter(const string& s, int left, int right) {
        while (left >= 0 && right < s.length() && s[left] == s[right]) {
            int currentLen = right - left + 1;
            if (currentLen > maxLen) {
                maxLen = currentLen;
                start = left;
            }
            left--;
            right++;
        }
    }

public:
    /**
     * Finds the longest palindromic substring in s.
     * Uses the "Expand Around Center" approach.
     * Time: O(N^2), Space: O(1)
     * @param s The input string.
     * @return The longest palindromic substring.
     */
    string longestPalindrome(string s) {
        if (s.length() < 1) return "";

        start = 0; // Reset member variables
        maxLen = 0;

        for (int i = 0; i < s.length(); ++i) {
            // Odd length palindromes
            expandAroundCenter(s, i, i);
            // Even length palindromes
            expandAroundCenter(s, i, i + 1);
        }

        // Handle empty string case where maxLen might still be 0
        if (maxLen == 0 && s.length() > 0) {
             return s.substr(0, 1); // Return first char if no palindrome > 1 found
        }


        return s.substr(start, maxLen);
    }
};
`;

