// --- NumberOf1BitsVisualizer Component (Template Applied) ---
const NumberOf1BitsVisualizer = () => {
    // --- State Variables ---
    const [numberInput, setNumberInput] = useState("11"); // Input string for the number
    const [currentN, setCurrentN] = useState(null); // Current value of n during algorithm
    const [bitCount, setBitCount] = useState(0); // Hamming weight count
    const [binaryString, setBinaryString] = useState(""); // Binary representation for display
    const [message, setMessage] = useState("");
    const [errorMessage, setErrorMessage] = useState("");
    const [isRunning, setIsRunning] = useState(false);
    const [finalResult, setFinalResult] = useState(null);
    const stopRef = React.useRef(false);
    // Audio/Speech State
    const [isAudioEnabled, setIsAudioEnabled] = useState(true);
    const [isSpeechEnabled, setIsSpeechEnabled] = useState(true);

    // --- Web Audio API Setup ---
    const audioContextRef = useRef(null);
    const initAudioContext = useCallback(() => { /* ... (Template standard) ... */ if (!isAudioEnabled) return; if (audioContextRef.current === null && typeof window !== 'undefined' && (window.AudioContext || window.webkitAudioContext)) { try { audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { console.error("Web Audio API not supported.", e); setIsAudioEnabled(false); setMessage("Audio tones disabled: Not supported."); } } if (audioContextRef.current && audioContextRef.current.state === 'suspended') { audioContextRef.current.resume().catch(e => console.error("Audio resume failed", e)); } }, [isAudioEnabled]);
    const playTone = useCallback((frequency = 440, duration = 0.1, type = 'sine', volume = 0.3) => { /* ... (Template standard) ... */ if (!isAudioEnabled || !audioContextRef.current || audioContextRef.current.state !== 'running') return; try { const oscillator = audioContextRef.current.createOscillator(); const gainNode = audioContextRef.current.createGain(); oscillator.type = type; oscillator.frequency.setValueAtTime(frequency, audioContextRef.current.currentTime); gainNode.gain.setValueAtTime(volume, audioContextRef.current.currentTime); gainNode.gain.exponentialRampToValueAtTime(0.0001, audioContextRef.current.currentTime + duration); oscillator.connect(gainNode); gainNode.connect(audioContextRef.current.destination); oscillator.start(audioContextRef.current.currentTime); oscillator.stop(audioContextRef.current.currentTime + duration); } catch (e) { console.error("Error playing tone:", e); } }, [isAudioEnabled]);
    // Specific sounds
    const playBitCheckSound = useCallback(() => playTone(600, 0.05, 'square', 0.15), [playTone]); // Reusing sound
    const playIncrementCountSound = useCallback(() => playTone(800, 0.08, 'sine', 0.2), [playTone]);
    const playBitClearSound = useCallback(() => playTone(500, 0.07, 'triangle', 0.2), [playTone]);
    const playStartSound = useCallback(() => playTone(440, 0.1, 'sine', 0.3), [playTone]);
    const playEndSound = useCallback(() => playTone(330, 0.2, 'sine', 0.3), [playTone]);
    const playStopSound = useCallback(() => playTone(220, 0.15, 'square', 0.3), [playTone]);
    const playErrorSound = useCallback(() => playTone(150, 0.3, 'sawtooth', 0.3), [playTone]);

    // --- Web Speech API Setup (Promise-based - FIXED ERROR HANDLING) ---
    const speak = useCallback((text) => {
        return new Promise((resolve) => { // Always resolve
            if (!isSpeechEnabled || typeof window === 'undefined' || !window.speechSynthesis) {
                resolve(); // Resolve immediately if disabled or not supported
                return;
            }
            try {
                window.speechSynthesis.cancel(); // Cancel previous speech
                const utterance = new SpeechSynthesisUtterance(text);
                utterance.lang = 'en-US';
                utterance.rate = 1.0;
                utterance.pitch = 1.0;
                utterance.volume = 0.8;

                // Resolve the promise when speech ends
                utterance.onend = () => {
                    resolve();
                };

                // ALSO resolve the promise on error to prevent unhandled rejections
                utterance.onerror = (event) => {
                    console.error("Speech synthesis error:", event.error);
                    resolve(); // CHANGE: Resolve instead of reject
                };

                window.speechSynthesis.speak(utterance);

            } catch (e) {
                console.error("Error initiating speech synthesis:", e);
                resolve(); // Resolve if initiation fails
            }
        });
    }, [isSpeechEnabled]); // Dependency on isSpeechEnabled

    const cancelSpeech = useCallback(() => { if (typeof window !== 'undefined' && window.speechSynthesis) { window.speechSynthesis.cancel(); } }, []);

     // --- Helper to get Binary String ---
     const toBinary = (n, bits = 8) => { // Show 8 bits for simplicity, adjust if needed
        if (n === null || n === undefined || isNaN(n)) return '-'.repeat(bits);
        // Use >>> 0 for unsigned representation before converting
        return (n >>> 0).toString(2).padStart(bits, '0').slice(-bits); // Pad and take last bits
    };

    // --- Reset Function ---
    const reset = useCallback((initial = false) => {
        stopRef.current = true; cancelSpeech(); setIsRunning(false);
        setBitCount(0); setCurrentN(null); setBinaryString(""); setFinalResult(null);
        setErrorMessage("");
        try {
            // Validate input only if not initial load
            let numToShow = null;
            if (!initial || numberInput) { // Try to parse even on initial if input exists
                try {
                    numToShow = parseNumberInput(numberInput); // Validate it's a number
                } catch (e) {
                    if (!initial) throw e; // Rethrow if not initial load
                }
            }
            setCurrentN(numToShow); // Set initial n value for display
            setBinaryString(toBinary(numToShow));
            setMessage(initial ? "" : "Enter an integer (will be treated as unsigned).");
        } catch (e) {
            setErrorMessage(`Input Error: ${e.message}`); setMessage("");
            setCurrentN(null); setBinaryString("");
            if (!initial) playErrorSound();
        }
    }, [numberInput, cancelSpeech, parseNumberInput, playErrorSound]); // Added dependencies

    // --- Effects ---
    useEffect(() => { reset(true); return () => { stopRef.current = true; cancelSpeech(); if (audioContextRef.current) { audioContextRef.current.close().catch(e => console.error("Error closing AudioContext:", e)); audioContextRef.current = null; } }; }, [reset, cancelSpeech]);
    useEffect(() => { const handler = setTimeout(() => { reset(true); }, 500); return () => clearTimeout(handler); }, [numberInput, reset]);

    // --- Visualization Logic (Brian Kernighan's Algorithm) ---
    const runVisualization = async () => {
        initAudioContext(); cancelSpeech(); reset(false); await sleep(50);

        let n;
        try {
            if (errorMessage) { setIsRunning(false); return; }
            n = parseNumberInput(numberInput); // Parse validated input
             setErrorMessage("");
        } catch (e) {
            setErrorMessage(`Input Error: ${e.message}`); setIsRunning(false); playErrorSound(); return;
        }

        stopRef.current = false; setIsRunning(true);
        let count = 0;
        setCurrentN(n); setBitCount(count); setBinaryString(toBinary(n)); setFinalResult(null);
        setMessage(`Starting Hamming Weight calculation for n = ${n} (${toBinary(n)}). Count = ${count}.`);
        playStartSound(); await speak(`Starting calculation for ${n}. Initial count is ${count}.`);
        if (stopRef.current) { setIsRunning(false); return; }

        // Treat n as unsigned 32-bit for the loop condition in JS
        let currentN_algo = n >>> 0;
        await sleep(1000); // Pause after init speak

        while (currentN_algo !== 0) {
            if (stopRef.current) break;

            setMessage(`Current n = ${currentN_algo} (${toBinary(currentN_algo)}). Count = ${count}.`);
            await speak(`Current n is ${currentN_algo}, count is ${count}.`);
            if (stopRef.current) break;
            await sleep(800); // Pause after speak

            // Brian Kernighan's: n = n & (n - 1)
            let nMinus1 = (currentN_algo - 1) >>> 0;
            let nextN = (currentN_algo & nMinus1) >>> 0;

            setMessage(`Calculate n & (n - 1): ${currentN_algo} & ${nMinus1} = ${nextN} (${toBinary(nextN)}). This clears the lowest set bit.`);
            playBitClearSound();
            await speak(`Calculate n AND n minus 1. Result is ${nextN}. This clears the lowest set bit.`);
            currentN_algo = nextN; // Update n for the algorithm
            setCurrentN(currentN_algo); // Update display state
            setBinaryString(toBinary(currentN_algo));
            if (stopRef.current) break;
            await sleep(1200); // Pause after calculation speak

            count++;
            setBitCount(count);
            setMessage(`Increment count. Count = ${count}.`);
            playIncrementCountSound();
            await speak(`Increment count to ${count}.`);
            if (stopRef.current) break;
            await sleep(1000); // Pause after increment speak
        }

        // Final State
        if (stopRef.current) {
            setMessage("Visualization stopped by user."); speak("Visualization stopped."); playStopSound();
        } else {
            setFinalResult(count);
            setMessage(`Finished. n is 0. Final Hamming Weight (Number of 1 Bits) = ${count}.`);
            playEndSound();
            await speak(`Finished. The final count is ${count}.`);
        }
        setIsRunning(false); stopRef.current = false;
    };

    const stopVisualization = () => {
        stopRef.current = true; cancelSpeech(); setMessage("Stopping visualization...");
    };

    const toggleAudio = () => { /* ... (Template standard) ... */ const newState = !isAudioEnabled; setIsAudioEnabled(newState); if (newState) { initAudioContext(); playTone(500, 0.05, 'sine', 0.2); } else { playTone(300, 0.05, 'square', 0.2); if (audioContextRef.current && audioContextRef.current.state === 'running') { audioContextRef.current.suspend().catch(e => console.error("Audio suspend failed", e)); } } };
    const toggleSpeech = () => { /* ... (Template standard) ... */ const newState = !isSpeechEnabled; if (newState && (typeof window === 'undefined' || !window.speechSynthesis)) { setMessage("Speech synthesis not supported."); return; } setIsSpeechEnabled(newState); if (!newState) { cancelSpeech(); } else { speak("Speech enabled."); } };

    // --- Render ---
    return (
        <>
            <BaseVisualizer
                problemSummary={
                    <>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                            <Typography variant="h4" component="h1">Number of 1 Bits</Typography>
                            <Chip label="Easy" color="success" size="small" variant="filled" />
                        </Box>
                        <Typography variant="body1" component="div" sx={{ mb: 2 }}>
                            Write a function that takes the binary representation of an unsigned integer and returns the number of '1' bits it has (also known as the Hamming weight).
                            <br/><br/>
                            <strong>Note:</strong> In some languages like Java, the input parameter does not have an unsigned integer type. In this case, the input will be given as a signed integer type. It should not affect your implementation, as the integer's internal binary representation is the same, whether it is signed or unsigned.
                        </Typography>
                        <Typography variant="h6" component="h3" sx={{ mt: 2, mb: 1 }}>Examples:</Typography>
                        <Box sx={{ bgcolor: 'action.hover', p: 1.5, borderRadius: 1, fontFamily: 'monospace', mb: 2, fontSize: '0.875rem' }}>
                            <strong>Input:</strong> n = 00000000000000000000000000001011 (Decimal: 11)<br/><strong>Output:</strong> 3<br/><br/>
                            <strong>Input:</strong> n = 00000000000000000000000010000000 (Decimal: 128)<br/><strong>Output:</strong> 1<br/><br/>
                            <strong>Input:</strong> n = 11111111111111111111111111111101 (Signed Int: -3)<br/><strong>Output:</strong> 31
                        </Box>
                        <Typography variant="h6" component="h3" sx={{ mt: 2, mb: 1 }}>Constraints:</Typography>
                        <Box component="ul" sx={{ pl: 2, mb: 2 }}>
                            <li>The input must be a <strong>binary string</strong> of length 32 in some platform test cases, but we accept integers here.</li>
                        </Box>
                        <Divider sx={{ my: 3 }} />
                        <Typography variant="h6" sx={{ mt: 3, mb: 1 }}>Runnable Solution Code Examples (Bit Manipulation)</Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>Copy/paste these into the compiler below.</Typography>
                        <Typography variant="subtitle2" sx={{ mb: 0.5 }}>JavaScript:</Typography><SolutionCodeDisplay codeString={numberOf1BitsSolutionCodeJS} />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>Python:</Typography><SolutionCodeDisplay codeString={numberOf1BitsSolutionCodePython} />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>Java:</Typography><SolutionCodeDisplay codeString={numberOf1BitsSolutionCodeJava} />
                        <Typography variant="subtitle2" sx={{ mt: 2, mb: 0.5 }}>C++:</Typography><SolutionCodeDisplay codeString={numberOf1BitsSolutionCodeCPP} />
                        <Divider sx={{ my: 3 }} />
                        <Typography variant="subtitle1" gutterBottom>Algorithm Analysis (Brian Kernighan's)</Typography>
                        <Typography variant="body2" color="text.secondary"><strong>Time Complexity:</strong> <code>O(k)</code>, where k is the number of set bits (1s). In the worst case (all bits set), it's O(number of bits), e.g., O(32).</Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}><strong>Space Complexity:</strong> <code>O(1)</code>. Constant extra space is used.</Typography>
                    </>
                }
                controls={
                    <>
                        <Typography variant="subtitle1" sx={{ textAlign: 'center', fontWeight: 'bold', p: 0.75, mb: 2.5, borderRadius: '4px', color: 'common.white', background: 'linear-gradient(45deg, #00ACC1 30%, #4DD0E1 90%)', boxShadow: 1 }}>Algorithm Visualizer</Typography>
                        <Grid container spacing={1.5} alignItems="center" mb={2}>
                            <Grid item xs={12} sm={6} md={6}><TextField fullWidth id="n1b-input-n" label="Integer n" type="number" variant="outlined" size="small" value={numberInput} onChange={(e) => setNumberInput(e.target.value)} placeholder="e.g., 11" disabled={isRunning} /></Grid>
                            <Grid item xs={4} sm={2} md={1.5}><Tooltip title={isRunning ? "Stop Visualization" : "Run Visualization"}><span><Button fullWidth variant="contained" sx={{ height: '40px' }} startIcon={isRunning ? <CircularProgress size={20} color="inherit" /> : <LooksOneIcon />} onClick={isRunning ? stopVisualization : runVisualization} color={isRunning ? "warning" : "primary"} disabled={isRunning && stopRef.current}>{isRunning ? 'Stop' : 'Run'}</Button></span></Tooltip></Grid>
                            <Grid item xs={4} sm={2} md={1.5}><Tooltip title={isAudioEnabled ? "Mute Tones" : "Unmute Tones"}><Button fullWidth variant="outlined" onClick={toggleAudio} sx={{ height: '40px', minWidth: 'auto', p: 1 }}>{isAudioEnabled ? <VolumeUpIcon /> : <VolumeOffIcon />}</Button></Tooltip></Grid>
                            <Grid item xs={4} sm={2} md={1.5}><Tooltip title={isSpeechEnabled ? "Disable Speech" : "Enable Speech"}><Button fullWidth variant="outlined" onClick={toggleSpeech} sx={{ height: '40px', minWidth: 'auto', p: 1 }}>{isSpeechEnabled ? <RecordVoiceOverIcon /> : <VoiceOverOffIcon />}</Button></Tooltip></Grid>
                            <Grid item xs={12} sm={12} md={1.5} sx={{ display: 'flex', justifyContent: { xs: 'center', md: 'flex-start' } }}><Button variant="outlined" startIcon={<ReplayIcon />} onClick={() => reset(false)} disabled={isRunning} sx={{ height: '40px' }}>Reset</Button></Grid>
                        </Grid>
                        {errorMessage && <Alert severity="error" sx={{ mt: 2 }}>{errorMessage}</Alert>}
                    </>
                }
                displayArea={
                    <>
                        {/* Display current values */}
                        <Grid container spacing={2} sx={{ mb: 3, textAlign: 'center' }}>
                             <Grid item xs={12} sm={6}>
                                <Typography variant="overline" display="block" color="text.secondary">Current 'n' (Decimal)</Typography>
                                <Chip label={currentN ?? '-'} color="primary" sx={{ width: '80%', mb: 1 }} />
                                <Typography variant="caption" display="block" sx={{ fontFamily: 'monospace', wordBreak: 'break-all' }}>
                                    Binary: {binaryString || '-'.repeat(8)}
                                </Typography>
                             </Grid>
                             <Grid item xs={12} sm={6}>
                                <Typography variant="overline" display="block" color="text.secondary">Bit Count</Typography>
                                <Chip label={bitCount} color="success" variant='filled' sx={{ width: '80%' }}/>
                             </Grid>
                        </Grid>

                        {/* Final Result Display */}
                        {finalResult !== null && !isRunning && (
                            <Alert icon={<CheckCircleOutlineIcon fontSize="inherit" />} severity="success" sx={{ mt: 2, justifyContent: 'center' }}>
                                <Typography variant="h6">Final Count (Hamming Weight) = {finalResult}</Typography>
                            </Alert>
                        )}
                        {errorMessage && <Typography variant="caption" color="error" align="center" display="block">Input Error</Typography>}
                    </>
                }
                message={message}
            />
            {/* Render Imported Online Compiler */}
            <Container maxWidth="xl" sx={{ mt: 4, mb: 4 }}>
                <OnlineCompiler />
            </Container>
        </>
    );
};

export default NumberOf1BitsVisualizer;
