const cloneGraphSolutionCodeJS = `
${graphNodeDefinitionJS}
/**
 * Creates a deep copy (clone) of a graph.
 * Uses DFS and a map to track cloned nodes.
 * Time: O(V + E), Space: O(V + E) for map, recursion stack, new graph.
 * @param {Node} node - The starting node of the graph to clone.
 * @return {Node} The starting node of the deep copied graph, or null if input is null.
 */
const cloneGraph = function(node) {
    const oldToNew = new Map(); // Map original nodes to their clones

    const dfs = (originalNode) => {
        if (!originalNode) {
            return null;
        }
        // If already cloned, return the existing clone
        if (oldToNew.has(originalNode)) {
            return oldToNew.get(originalNode);
        }

        // Create the clone node
        const cloneNode = new Node(originalNode.val);
        oldToNew.set(originalNode, cloneNode); // Add to map *before* recursive calls

        // Recursively clone neighbors
        if (originalNode.neighbors) {
            for (const neighbor of originalNode.neighbors) {
                cloneNode.neighbors.push(dfs(neighbor));
            }
        }
        return cloneNode;
    };

    return dfs(node);
};
`;

