// --- Tree Node Class (Helper - Can be shared or redefined) ---
class TreeNode {
    constructor(val, left = null, right = null) {
        this.val = val;
        this.left = left;
        this.right = right;
        this.id = Math.random().toString(36).substring(2, 15); // Unique ID for visualization
        this.x = 0;
        this.y = 0;
        this.parentId = null;
        this.originalPosition = null; // Store original x for swap animation if needed
    }
}

// --- Tree Parsing Function (Assume exists or copy from MaxDepth) ---
const parseTreeString = (str) => {
    str = str.trim();
    if (!str.startsWith('[') || !str.endsWith(']')) {
        throw new Error("Invalid input format. Must be like '[1,2,null,3]'.");
    }
    str = str.substring(1, str.length - 1);
    if (!str) return null;
    const values = str.split(',').map(v => v.trim());
    if (values.length === 0 || values[0] === 'null') return null;

    const root = new TreeNode(parseInt(values[0], 10));
    const queue = [root];
    let i = 1;
    while (queue.length > 0 && i < values.length) {
        const currentNode = queue.shift();
        if (i < values.length) {
            if (values[i] !== 'null') {
                const leftVal = parseInt(values[i], 10);
                currentNode.left = new TreeNode(leftVal);
                currentNode.left.parentId = currentNode.id;
                queue.push(currentNode.left);
            }
            i++;
        }
        if (i < values.length) {
            if (values[i] !== 'null') {
                const rightVal = parseInt(values[i], 10);
                currentNode.right = new TreeNode(rightVal);
                 currentNode.right.parentId = currentNode.id;
                queue.push(currentNode.right);
            }
            i++;
        }
    }
    return root;
};


// --- Function to calculate node positions (Assume exists or copy from MaxDepth) ---
// Returns { nodes, nodeMap, height }
const calculateNodePositions = (root, isInitial = true) => { // Add flag for initial vs inverted
    if (!root) return { nodes: [], nodeMap: {}, height: 0 };
    const nodes = [];
    const nodeMap = {};
    let maxLevel = 0;

    // Use BFS to calculate positions level by level for better layout
    const queue = [{ node: root, level: 0, parentX: null, indexInLevel: 0 }];
    const levelWidths = {}; // Store nodes per level

    while(queue.length > 0) {
        const { node, level, parentX, indexInLevel } = queue.shift();
        if (!node) continue;

        maxLevel = Math.max(maxLevel, level);
        node.y = level * 80; // Vertical position based on level

        // Calculate horizontal position
        const nodesInLevel = Math.pow(2, level);
        const totalWidth = nodesInLevel * 60; // Estimated width needed for this level
        const startX = -totalWidth / 2;
        node.x = startX + indexInLevel * 60 + 30; // Distribute nodes

        // More robust positioning relative to parent (might still overlap)
         const horizontalSpread = 150 / (level + 1);
         if (parentX === null) { // Root
             node.x = 0;
         } else {
             const parentNode = nodeMap[node.parentId];
             if (parentNode) {
                 // Determine if it's left or right *based on current structure*
                 const isLeftChild = parentNode.left?.id === node.id;
                 node.x = parentX + (isLeftChild ? -horizontalSpread : horizontalSpread);
             } else { node.x = 0; } // Fallback
         }


        if (isInitial) {
            node.originalPosition = node.x; // Store initial position
        }

        nodes.push(node);
        nodeMap[node.id] = node;

        if (node.left) queue.push({ node: node.left, level: level + 1, parentX: node.x, indexInLevel: indexInLevel * 2 });
        if (node.right) queue.push({ node: node.right, level: level + 1, parentX: node.x, indexInLevel: indexInLevel * 2 + 1 });
    }


     // Center the tree horizontally
     if (nodes.length > 0) {
        let minX = Infinity, maxX = -Infinity;
        nodes.forEach(n => { minX = Math.min(minX, n.x); maxX = Math.max(maxX, n.x); });
        const width = maxX - minX;
        const offsetX = -minX - (width / 2);
        nodes.forEach(n => { n.x += offsetX; });
    }

    return { nodes, nodeMap, height: (maxLevel + 1) * 80 };
};


