const LEVEL_SPACING = 80;

// --- Tree Node Class (Helper - Reuse) ---
class TreeNode {
    constructor(val, left = null, right = null) {
        this.val = val; this.left = left; this.right = right;
        this.id = Math.random().toString(36).substring(2, 15);
        this.x = 0; this.y = 0; this.parentId = null;
    }
}

// --- Tree Parsing Function (Reuse - From MaxDepth) ---
const parseTreeString = (str) => {
    str = str.trim();
    if (!str.startsWith('[') || !str.endsWith(']')) {
        const num = parseInt(str, 10); if (!isNaN(num)) return new TreeNode(num);
        throw new Error("Invalid format. Use array like '[1,2,null,3]' or single number.");
    } str = str.substring(1, str.length - 1); if (!str) return null;
    const values = str.split(',').map(v => v.trim());
    if (values.length === 0 || values[0] === 'null') return null;
    const rootVal = parseInt(values[0], 10); if (isNaN(rootVal)) throw new Error(`Invalid root value: ${values[0]}`);
    const root = new TreeNode(rootVal); const queue = [root]; let i = 1;
    while (queue.length > 0 && i < values.length) {
        const currentNode = queue.shift();
        if (i < values.length) { if (values[i] !== 'null') { const leftVal = parseInt(values[i], 10); if (isNaN(leftVal)) throw new Error(`Invalid node value: ${values[i]}`); currentNode.left = new TreeNode(leftVal); currentNode.left.parentId = currentNode.id; queue.push(currentNode.left); } i++; }
        if (i < values.length) { if (values[i] !== 'null') { const rightVal = parseInt(values[i], 10); if (isNaN(rightVal)) throw new Error(`Invalid node value: ${values[i]}`); currentNode.right = new TreeNode(rightVal); currentNode.right.parentId = currentNode.id; queue.push(currentNode.right); } i++; }
    } return root;
};

// --- Calculate Node Positions (Reuse - From MaxDepth) ---
const calculateNodePositions = (root) => {
    if (!root) return { nodes: [], nodeMap: {}, height: 0 }; const nodes = []; const nodeMap = {}; let maxLevel = 0; const baseHorizontalSpacing = 150;
    const traverse = (node, level, x, parentId) => { if (!node) return; maxLevel = Math.max(maxLevel, level); node.y = level * LEVEL_SPACING; node.x = x; node.parentId = parentId; nodes.push(node); nodeMap[node.id] = node; const childrenHorizontalSpread = baseHorizontalSpacing / Math.pow(1.8, level + 1); traverse(node.left, level + 1, x - childrenHorizontalSpread, node.id); traverse(node.right, level + 1, x + childrenHorizontalSpread, node.id); };
    traverse(root, 0, 0, null);
    const nodesByLevel = {}; nodes.forEach(node => { if (!nodesByLevel[node.y]) nodesByLevel[node.y] = []; nodesByLevel[node.y].push(node); });
    Object.values(nodesByLevel).forEach(levelNodes => { levelNodes.sort((a, b) => a.x - b.x); for (let i = 1; i < levelNodes.length; i++) { const node1 = levelNodes[i - 1], node2 = levelNodes[i]; const minGap = NODE_RADIUS * 2 + 10; const currentGap = node2.x - node1.x; if (currentGap < minGap) node2.x += (minGap - currentGap); } });
    if (nodes.length > 0) { let minX = Infinity, maxX = -Infinity; nodes.forEach(n => { minX = Math.min(minX, n.x); maxX = Math.max(maxX, n.x); }); const treeWidth = maxX - minX; const centeringOffset = -minX - (treeWidth / 2); nodes.forEach(n => { n.x += centeringOffset; }); }
    const topPadding = NODE_RADIUS + 10; nodes.forEach(n => { n.y += topPadding; });
    return { nodes, nodeMap, height: (maxLevel * LEVEL_SPACING) + topPadding };
};

