/**
 * Performs level order traversal of a binary tree (BFS).
 * Time: O(N), visits each node once.
 * Space: O(W), where W is the maximum width of the tree (for the queue).
 * @param {TreeNode} root The root of the binary tree.
 * @return {number[][]} A 2D array where each inner array contains the node values at that level.
 */
const levelOrder = function(root) {
    if (!root) {
        return [];
    }

    const result = [];
    const queue = [root]; // Use array as a queue (shift/push)

    while (queue.length > 0) {
        const levelSize = queue.length; // Number of nodes at the current level
        const currentLevelValues = [];

        // Process all nodes at the current level
        for (let i = 0; i < levelSize; i++) {
            const node = queue.shift(); // Dequeue node
            currentLevelValues.push(node.val); // Add its value to the current level list

            // Enqueue children for the next level
            if (node.left) {
                queue.push(node.left);
            }
            if (node.right) {
                queue.push(node.right);
            }
        }
        result.push(currentLevelValues); // Add the completed level to the result
    }

    return result;
};
