const solutionCodeJava = `
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 * int val;
 * TreeNode left;
 * TreeNode right;
 * TreeNode() {}
 * TreeNode(int val) { this.val = val; }
 * TreeNode(int val, TreeNode left, TreeNode right) {
 * this.val = val;
 * this.left = left;
 * this.right = right;
 * }
 * }
 */
class Solution {
    /**
     * Performs level order traversal (BFS).
     * Time: O(N), Space: O(W) max width.
     * @param root The root of the binary tree.
     * @return A list of lists, where each inner list contains node values at that level.
     */
    public List<List<Integer>> levelOrder(TreeNode root) {
        List<List<Integer>> result = new ArrayList<>();
        if (root == null) {
            return result;
        }

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root); // Add root to the queue

        while (!queue.isEmpty()) {
            int levelSize = queue.size(); // Get the number of nodes at the current level
            List<Integer> currentLevelValues = new ArrayList<>();

            // Process all nodes at the current level
            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll(); // Dequeue node
                currentLevelValues.add(node.val); // Add its value

                // Enqueue children for the next level
                if (node.left != null) {
                    queue.offer(node.left);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                }
            }
            result.add(currentLevelValues); // Add the completed level list to the result
        }

        return result;
    }
}
`;
const solutionCodeCPP = `
#include <vector>
#include <queue>

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 * int val;
 * TreeNode *left;
 * TreeNode *right;
 * TreeNode() : val(0), left(nullptr), right(nullptr) {}
 * TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 * TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    /**
     * Performs level order traversal (BFS).
     * Time: O(N), Space: O(W) max width.
     * @param root The root of the binary tree.
     * @return A vector of vectors, where each inner vector contains node values at that level.
     */
    std::vector<std::vector<int>> levelOrder(TreeNode* root) {
        std::vector<std::vector<int>> result;
        if (root == nullptr) {
            return result;
        }

        std::queue<TreeNode*> q;
        q.push(root);

        while (!q.empty()) {
            int levelSize = q.size(); // Number of nodes at the current level
            std::vector<int> currentLevelValues;

            // Process all nodes at the current level
            for (int i = 0; i < levelSize; ++i) {
                TreeNode* node = q.front();
                q.pop(); // Dequeue
                currentLevelValues.push_back(node->val); // Add value

                // Enqueue children
                if (node->left != nullptr) {
                    q.push(node->left);
                }
                if (node->right != nullptr) {
                    q.push(node->right);
                }
            }
            result.push_back(currentLevelValues); // Add completed level
        }

        return result;
    }
};
`;

