const setZeroesSolutionCodeJS = `
/**
 * Sets entire row and column to 0 if an element is 0, in-place.
 * Uses O(m*n) time and O(1) extra space (using first row/col as markers).
 * @param {number[][]} matrix - The m x n matrix.
 * @modifies matrix in-place.
 */
const setZeroes = function(matrix) {
    if (!matrix || matrix.length === 0 || matrix[0].length === 0) {
        return;
    }
    const R = matrix.length;
    const C = matrix[0].length;
    let isColZero = false; // Marker for first column

    // 1. Check if first column needs to be zeroed
    for (let i = 0; i < R; i++) {
        if (matrix[i][0] === 0) {
            isColZero = true;
            break;
        }
    }

    // 2. Check if first row needs to be zeroed (use matrix[0][0] for this)
    // Note: matrix[0][0] also overlaps with first column check
    let isRowZero = matrix[0][0] === 0;
    for (let j = 1; j < C; j++) {
         if (matrix[0][j] === 0) {
             isRowZero = true;
             break;
         }
    }
     // If matrix[0][0] was 0, isColZero is true, isRowZero is true.
     // If another element in first row is 0, isRowZero becomes true.

    // 3. Use first row and first column to mark zero rows/cols
    // Start from (1, 1) to avoid overwriting markers prematurely
    for (let i = 1; i < R; i++) {
        for (let j = 1; j < C; j++) {
            if (matrix[i][j] === 0) {
                matrix[i][0] = 0; // Mark row i
                matrix[0][j] = 0; // Mark col j
            }
        }
    }

    // 4. Set cells to zero based on markers (excluding first row/col)
    for (let i = 1; i < R; i++) {
        for (let j = 1; j < C; j++) {
            if (matrix[i][0] === 0 || matrix[0][j] === 0) {
                matrix[i][j] = 0;
            }
        }
    }

    // 5. Set first row to zero if needed
    if (isRowZero) {
        for (let j = 0; j < C; j++) {
            matrix[0][j] = 0;
        }
    }

    // 6. Set first column to zero if needed
    if (isColZero) {
        for (let i = 0; i < R; i++) {
            matrix[i][0] = 0;
        }
    }
};

// Example Usage:
let matrix1 = [[1,1,1],[1,0,1],[1,1,1]];
setZeroes(matrix1);
console.log(matrix1); // Output: [[1,0,1],[0,0,0],[1,0,1]]

let matrix2 = [[0,1,2,0],[3,4,5,2],[1,3,1,5]];
setZeroes(matrix2);
console.log(matrix2); // Output: [[0,0,0,0],[0,4,5,0],[0,3,1,0]]
`;

const setZeroesSolutionCodePython = `
from typing import List

class Solution:
    """
    Sets rows and columns to 0 in-place if a cell contains 0.
    Uses O(m*n) time and O(1) extra space.
    """
    def setZeroes(self, matrix: List[List[int]]) -> None:
        if not matrix or not matrix[0]:
            return

        R, C = len(matrix), len(matrix[0])
        is_col_zero = False

        # 1. Check if the first column needs zeroing
        for r in range(R):
            if matrix[r][0] == 0:
                is_col_zero = True
                break

        # 2. Check if the first row needs zeroing (using matrix[0][0] as marker)
        is_row_zero = matrix[0][0] == 0
        for c in range(1, C):
            if matrix[0][c] == 0:
                is_row_zero = True
                break

        # 3. Use first row/col as markers for other cells
        for r in range(1, R):
            for c in range(1, C):
                if matrix[r][c] == 0:
                    matrix[r][0] = 0 # Mark row r
                    matrix[0][c] = 0 # Mark col c

        # 4. Zero out cells based on markers (skip first row/col)
        for r in range(1, R):
            for c in range(1, C):
                if matrix[r][0] == 0 or matrix[0][c] == 0:
                    matrix[r][c] = 0

        # 5. Zero out first row if needed
        if is_row_zero:
            for c in range(C):
                matrix[0][c] = 0

        # 6. Zero out first column if needed
        if is_col_zero:
            for r in range(R):
                matrix[r][0] = 0

# Example Usage:
if __name__ == "__main__":
    sol = Solution()
    matrix1 = [[1,1,1],[1,0,1],[1,1,1]]
    sol.setZeroes(matrix1)
    print(f"Matrix 1: {matrix1}") # Output: [[1, 0, 1], [0, 0, 0], [1, 0, 1]]

    matrix2 = [[0,1,2,0],[3,4,5,2],[1,3,1,5]]
    sol.setZeroes(matrix2)
    print(f"Matrix 2: {matrix2}") # Output: [[0, 0, 0, 0], [0, 4, 5, 0], [0, 3, 1, 0]]
`;

const setZeroesSolutionCodeJava = `
class Solution {
    /**
     * Sets rows and columns to 0 in-place if a cell contains 0.
     * Uses O(m*n) time and O(1) extra space.
     * Modifies the matrix directly.
     * @param matrix The m x n matrix.
     */
    public void setZeroes(int[][] matrix) {
        if (matrix == null || matrix.length == 0 || matrix[0].length == 0) {
            return;
        }
        int R = matrix.length;
        int C = matrix[0].length;
        boolean isColZero = false; // Marker for first column

        // 1. Check first column
        for (int i = 0; i < R; i++) {
            if (matrix[i][0] == 0) {
                isColZero = true;
                break;
            }
        }

        // 2. Check first row (use matrix[0][0] as marker)
        boolean isRowZero = matrix[0][0] == 0;
        for (int j = 1; j < C; j++) {
            if (matrix[0][j] == 0) {
                isRowZero = true;
                break;
            }
        }

        // 3. Mark first row/col based on inner cells
        for (int i = 1; i < R; i++) {
            for (int j = 1; j < C; j++) {
                if (matrix[i][j] == 0) {
                    matrix[i][0] = 0;
                    matrix[0][j] = 0;
                }
            }
        }

        // 4. Zero out inner cells based on markers
        for (int i = 1; i < R; i++) {
            for (int j = 1; j < C; j++) {
                if (matrix[i][0] == 0 || matrix[0][j] == 0) {
                    matrix[i][j] = 0;
                }
            }
        }

        // 5. Zero out first row
        if (isRowZero) {
            for (int j = 0; j < C; j++) {
                matrix[0][j] = 0;
            }
        }

        // 6. Zero out first column
        if (isColZero) {
            for (int i = 0; i < R; i++) {
                matrix[i][0] = 0;
            }
        }
    }

    // Example Usage (Helper to print matrix):
    private static void printMatrix(int[][] matrix) {
        System.out.print("[");
        for (int i = 0; i < matrix.length; i++) {
            System.out.print(i == 0 ? "[" : " [");
            for (int j = 0; j < matrix[0].length; j++) {
                System.out.print(matrix[i][j] + (j == matrix[0].length - 1 ? "" : ","));
            }
            System.out.print("]" + (i == matrix.length - 1 ? "" : ","));
        }
        System.out.println("]");
    }

    public static void main(String[] args) {
        Solution sol = new Solution();
        int[][] matrix1 = {{1,1,1},{1,0,1},{1,1,1}};
        sol.setZeroes(matrix1);
        System.out.print("Matrix 1: "); printMatrix(matrix1); // Output: [[1,0,1],[0,0,0],[1,0,1]]

        int[][] matrix2 = {{0,1,2,0},{3,4,5,2},{1,3,1,5}};
        sol.setZeroes(matrix2);
        System.out.print("Matrix 2: "); printMatrix(matrix2); // Output: [[0,0,0,0],[0,4,5,0],[0,3,1,0]]
    }
}
`;

const setZeroesSolutionCodeCPP = `
#include <vector>
#include <iostream>

class Solution {
public:
    /**
     * Sets rows and columns to 0 in-place if a cell contains 0.
     * Uses O(m*n) time and O(1) extra space.
     * Modifies the matrix directly.
     * @param matrix The m x n matrix passed by reference.
     */
    void setZeroes(std::vector<std::vector<int>>& matrix) {
        if (matrix.empty() || matrix[0].empty()) {
            return;
        }
        int R = matrix.size();
        int C = matrix[0].size();
        bool isColZero = false; // Marker for first column

        // 1. Check first column
        for (int i = 0; i < R; ++i) {
            if (matrix[i][0] == 0) {
                isColZero = true;
                break;
            }
        }

        // 2. Check first row (using matrix[0][0])
        bool isRowZero = matrix[0][0] == 0;
        for (int j = 1; j < C; ++j) {
            if (matrix[0][j] == 0) {
                isRowZero = true;
                break;
            }
        }

        // 3. Mark first row/col based on inner cells
        for (int i = 1; i < R; ++i) {
            for (int j = 1; j < C; ++j) {
                if (matrix[i][j] == 0) {
                    matrix[i][0] = 0;
                    matrix[0][j] = 0;
                }
            }
        }

        // 4. Zero out inner cells based on markers
        for (int i = 1; i < R; ++i) {
            for (int j = 1; j < C; ++j) {
                if (matrix[i][0] == 0 || matrix[0][j] == 0) {
                    matrix[i][j] = 0;
                }
            }
        }

        // 5. Zero out first row if needed
        if (isRowZero) {
            for (int j = 0; j < C; ++j) {
                matrix[0][j] = 0;
            }
        }

        // 6. Zero out first column if needed
        if (isColZero) {
            for (int i = 0; i < R; ++i) {
                matrix[i][0] = 0;
            }
        }
    }
};

// Example Usage (Helper to print matrix):
void printMatrix(const std::vector<std::vector<int>>& matrix) {
    std::cout << "[";
    for (size_t i = 0; i < matrix.size(); ++i) {
        std::cout << (i == 0 ? "[" : " [");
        for (size_t j = 0; j < matrix[0].size(); ++j) {
            std::cout << matrix[i][j] << (j == matrix[0].size() - 1 ? "" : ",");
        }
        std::cout << "]" << (i == matrix.size() - 1 ? "" : ",");
    }
    std::cout << "]" << std::endl;
}

int main() {
    Solution sol;
    std::vector<std::vector<int>> matrix1 = {{1,1,1},{1,0,1},{1,1,1}};
    sol.setZeroes(matrix1);
    std::cout << "Matrix 1: "; printMatrix(matrix1); // Output: [[1,0,1],[0,0,0],[1,0,1]]

    std::vector<std::vector<int>> matrix2 = {{0,1,2,0},{3,4,5,2},{1,3,1,5}};
    sol.setZeroes(matrix2);
    std::cout << "Matrix 2: "; printMatrix(matrix2); // Output: [[0,0,0,0],[0,4,5,0],[0,3,1,0]]
    return 0;
}
`;
